(window.CERTDATA = window.CERTDATA || {})["ml-associate"] = {"meta":{"id":"ml-associate","title":"Machine Learning Associate","level":"Associate","color":"#16a34a","examMinutes":90,"examSize":48,"lang":"en","lessonRoot":"certifications/ml-associate","questionCount":203,"lessonCount":16,"banks":[{"id":"praticas","label":"Questões práticas","kind":"practice","count":107},{"id":"simulado-1","label":"Simulado 1","kind":"mock","count":48},{"id":"simulado-2","label":"Simulado 2","kind":"mock","count":48}],"domains":[{"id":"databricks-ml","name":"Databricks ML: Runtimes, Compute & AutoML (Section 1)","nameEn":"Databricks ML: Runtimes, Compute & AutoML (Section 1)","weight":6.4,"official":false,"count":13},{"id":"ml-workflows","name":"MLflow Tracking & Experiments (Section 1)","nameEn":"MLflow Tracking & Experiments (Section 1)","weight":6.4,"official":false,"count":13},{"id":"feature-engineering","name":"Spark ML Pipelines, Tuning & Feature Tables (Sections 1 & 3)","nameEn":"Spark ML Pipelines, Tuning & Feature Tables (Sections 1 & 3)","weight":7.4,"official":false,"count":15},{"id":"mlflow-deployment","name":"Model Registry & Deployment (Sections 1 & 4)","nameEn":"Model Registry & Deployment (Sections 1 & 4)","weight":3.9,"official":false,"count":8},{"id":"unity-catalog-mlops","name":"Unity Catalog, MLOps & MLflow Client (Section 1)","nameEn":"Unity Catalog, MLOps & MLflow Client (Section 1)","weight":6.9,"official":false,"count":14},{"id":"data-processing","name":"Data Processing (Section 2)","nameEn":"Data Processing (Section 2)","weight":16.3,"official":false,"count":33},{"id":"model-development","name":"Model Development (Section 3)","nameEn":"Model Development (Section 3)","weight":23.6,"official":false,"count":48},{"id":"model-deployment","name":"Model Deployment (Section 4)","nameEn":"Model Deployment (Section 4)","weight":11.3,"official":false,"count":23},{"id":"databricks-machine-learning","name":"Databricks Machine Learning","nameEn":"Databricks Machine Learning","weight":17.7,"official":false,"count":36}],"officialWeights":false},"questions":[{"id":"01-databricks-ml-q001","bank":"praticas","n":1,"domain":"databricks-ml","title":"ML Runtime Pre-installed Libraries","difficulty":"easy","question":"Which of the following libraries is pre-installed in the Databricks Runtime for Machine Learning but NOT in the standard Databricks Runtime?","choices":{"A":"Apache Spark","B":"Delta Lake","C":"pandas","D":"MLflow"},"answer":"D","short":"The Databricks Runtime for ML adds a pre-installed, version-tested ML stack — MLflow, PyTorch, TensorFlow, scikit-learn, XGBoost, and more — on top of the standard Databricks Runtime. Apache Spark, pandas, and Delta Lake are already part of the standard runtime.","explanation":"","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"01-databricks-ml-q002","bank":"praticas","n":2,"domain":"databricks-ml","title":"Single-Node Cluster Use Case","difficulty":"medium","question":"A data scientist is training a scikit-learn model on a 500 MB dataset that fits entirely in memory. Which cluster type is most appropriate?","choices":{"A":"Multi-node cluster with 4 workers","B":"Multi-node cluster with autoscaling enabled","C":"High-concurrency cluster","D":"Single-node cluster"},"answer":"D","short":"Single-node clusters are ideal for workloads that use libraries without native Spark support, such as scikit-learn, and for datasets that fit in memory. Using a multi-node cluster adds distributed computing overhead with no benefit for non-distributed workloads.","explanation":"","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"01-databricks-ml-q003","bank":"praticas","n":3,"domain":"databricks-ml","title":"AutoML Task Types","difficulty":"easy","question":"A data scientist wants to use Databricks AutoML to predict customer churn (a binary yes/no outcome). Which AutoML task type should they select?","choices":{"A":"Regression","B":"Forecasting","C":"Classification","D":"Clustering"},"answer":"C","short":"Databricks AutoML supports three task types: classification (for categorical targets), regression (for continuous targets), and forecasting (for time series). Predicting a binary outcome like churn is a classification problem. Clustering is not an AutoML task type in Databricks.","explanation":"","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"01-databricks-ml-q004","bank":"praticas","n":4,"domain":"databricks-ml","title":"AutoML Output","difficulty":"easy","question":"After running a Databricks AutoML experiment, where are the results stored?","choices":{"A":"A Delta table in the default catalog","B":"A set of Python scripts in a Git folder","C":"An MLflow experiment with one run per trial","D":"A JSON configuration file in DBFS"},"answer":"C","short":"AutoML automatically creates and populates an MLflow experiment. Each trial is logged as a separate MLflow run with its parameters, metrics, and model artifact. For classification and regression, the best-trial notebook and a data exploration notebook are imported into the workspace as editable starting points.","explanation":"","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"01-databricks-ml-q005","bank":"praticas","n":5,"domain":"databricks-ml","title":"Cluster Policy Purpose","difficulty":"medium","question":"A platform engineer wants to prevent data science teams from launching GPU clusters without explicit approval. What is the best approach?","choices":{"A":"Document a policy in a wiki and ask teams to follow it","B":"Restrict Unity Catalog permissions for the data science teams","C":"Set up a budget alert that notifies the engineer when GPU spend exceeds a threshold","D":"Create a cluster policy that restricts node type to CPU instance types only"},"answer":"D","short":"Cluster policies allow administrators to enforce cluster configuration constraints, including restricting the allowed instance types to non-GPU options. Policies are enforced at the platform level and cannot be bypassed by regular users.","explanation":"","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"01-databricks-ml-q006","bank":"praticas","n":6,"domain":"databricks-ml","title":"ML Runtime Version Selection","difficulty":"medium","question":"A data scientist needs to train a deep learning model using PyTorch with GPU acceleration. Which Databricks Runtime variant should they select?","choices":{"A":"Databricks Runtime (standard)","B":"Databricks Runtime ML","C":"Databricks Runtime ML GPU","D":"Databricks Runtime Photon"},"answer":"C","short":"The GPU variant of the ML runtime (selected when you choose a GPU instance type with an ML runtime) includes the GPU drivers and GPU-enabled builds of deep learning libraries such as PyTorch and TensorFlow. The CPU ML runtime has no GPU drivers, and the standard runtime (with or without Photon) does not include the ML library stack.","explanation":"","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"01-databricks-ml-q007","bank":"praticas","n":7,"domain":"databricks-ml","title":"Notebook %run Directive","difficulty":"easy","question":"A team stores common data preprocessing utility functions in a notebook called `utils` in the same folder. What is the correct way to execute that notebook's code in another notebook so its functions become available?","choices":{"A":"`import utils`","B":"`spark.sql(\"RUN NOTEBOOK utils\")`","C":"`dbutils.notebook.run(\"utils\", 60)`","D":"`%run ./utils`"},"answer":"D","short":"The `%run` magic command executes another notebook in the context of the current notebook, making all defined functions and variables available in the current scope. `dbutils.notebook.run()` also executes a notebook but runs it in a separate context and only returns a string result, not the defined variables.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"01-databricks-ml-q008","bank":"praticas","n":8,"domain":"databricks-ml","title":"Git Folders Version Control","difficulty":"easy","question":"A data scientist wants to track changes to their model training notebooks using Git. What Databricks feature should they use?","choices":{"A":"Delta Lake change data feed","B":"MLflow run history","C":"Databricks Git folders (formerly Repos)","D":"Lakeflow Jobs"},"answer":"C","short":"Git folders (formerly called Databricks Repos) integrate with Git providers such as GitHub, GitLab, Bitbucket, and Azure DevOps, so notebooks and code can be version-controlled directly from the workspace — the foundation of a \"deploy code\" MLOps workflow.","explanation":"Delta Lake change data feed tracks table changes, MLflow run history tracks experiment results, and Lakeflow Jobs orchestrate workloads.","lesson":"01-databricks-machine-learning/01-databricks-ml-workspace","related":null},{"id":"01-databricks-ml-q009","bank":"praticas","n":9,"domain":"databricks-ml","title":"AutoML Forecasting Input","difficulty":"easy","question":"When configuring a Databricks AutoML forecasting experiment, which column is required in addition to the target variable?","choices":{"A":"A feature importance column","B":"A row ID column","C":"A grouping column","D":"A time column"},"answer":"D","short":"AutoML forecasting requires a time column that identifies the time step for each observation. The time column is mandatory because forecasting is inherently a time-series problem. A grouping column is optional (for multi-series forecasting). Feature importance and row ID columns are not required inputs.","explanation":"","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"01-databricks-ml-q010","bank":"praticas","n":10,"domain":"databricks-ml","title":"Standard vs ML Runtime","difficulty":"medium","question":"A data scientist expects every scikit-learn training call in their notebook to be tracked automatically, with no MLflow code, but no runs appear. Which cluster choice is the most likely cause?","choices":{"A":"The cluster is running the standard Databricks Runtime instead of Databricks Runtime ML","B":"The cluster has autoscaling disabled","C":"The cluster uses spot instances for workers","D":"The cluster has auto-termination set to 30 minutes"},"answer":"A","short":"Databricks Autologging is available on Databricks Runtime 10.4 LTS ML and above: on an ML runtime, supported frameworks such as scikit-learn are tracked automatically. On a standard runtime you would have to install MLflow yourself and call `mlflow.autolog()` explicitly.","explanation":"Autoscaling, spot instances, and auto-termination affect cost and capacity, not MLflow tracking.","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"01-databricks-ml-q011","bank":"praticas","n":11,"domain":"databricks-ml","title":"Multi-Node Cluster Benefit","difficulty":"medium","question":"Which of the following workloads benefits MOST from using a multi-node Spark cluster instead of a single-node cluster?","choices":{"A":"Training a logistic regression model with scikit-learn on a 1 GB CSV file","B":"Visualizing model performance with matplotlib","C":"Running a hyperparameter sweep with Optuna on a single machine","D":"Training a distributed gradient-boosted tree using Spark ML on a 500 GB Delta table"},"answer":"D","short":"Multi-node clusters are beneficial when the workload can be parallelized across workers. Training a Spark ML model on a large Delta table leverages distributed computation. scikit-learn, Optuna, and matplotlib do not distribute work across Spark workers, so they receive no benefit from additional nodes.","explanation":"","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"01-databricks-ml-q012","bank":"praticas","n":12,"domain":"databricks-ml","title":"AutoML Best Model","difficulty":"easy","question":"After completing an AutoML experiment, a data scientist wants to retrain and customize the best model. What does AutoML provide to enable this?","choices":{"A":"A compiled binary model file that can be fine-tuned","B":"A Delta table containing the best model's feature importances","C":"A REST API endpoint that exposes the best model's hyperparameters","D":"A generated Python notebook containing the training code for the best model"},"answer":"D","short":"Databricks AutoML generates an editable Python notebook for the best model. This notebook contains all the code to reproduce and customize the model, including feature engineering, training, and MLflow logging. The data scientist can clone and modify this notebook as a starting point.","explanation":"","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"01-databricks-ml-q013","bank":"praticas","n":13,"domain":"databricks-ml","title":"Cluster Termination Policy","difficulty":"easy","question":"A platform administrator wants to ensure that ML training clusters are automatically terminated after 30 minutes of inactivity to reduce costs. Where is this configured?","choices":{"A":"In the cluster policy definition","B":"In the MLflow experiment configuration","C":"In the Databricks workflow job settings","D":"In the cluster's auto-termination setting"},"answer":"D","short":"Each cluster has an auto-termination setting that specifies the number of minutes of inactivity before the cluster is shut down. This is configured directly on the cluster (or enforced via a cluster policy). It is independent of workflow job settings and MLflow configuration.","explanation":"","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"02-ml-workflows-q001","bank":"praticas","n":14,"domain":"ml-workflows","title":"Start Run Context Manager","difficulty":"easy","question":"A data scientist writes the following code. What happens when the `with` block exits normally?\n\n```python\nwith mlflow.start_run():\n    mlflow.log_param(\"alpha\", 0.5)\n    mlflow.log_metric(\"rmse\", 1.23)\n```","choices":{"A":"The run stays open until `mlflow.end_run()` is called manually","B":"The run parameters and metrics are discarded","C":"The run is automatically ended and its status is set to FAILED","D":"The run is automatically ended and its status is set to FINISHED"},"answer":"D","short":"When used as a context manager, `mlflow.start_run()` automatically calls `mlflow.end_run()` when the `with` block exits. If the block exits normally (no exception), the run status is set to FINISHED. If an exception is raised, the run status is set to FAILED.","explanation":"","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"02-ml-workflows-q002","bank":"praticas","n":15,"domain":"ml-workflows","title":"log_metric vs log_metrics","difficulty":"easy","question":"A data scientist wants to log three metrics at once — `accuracy`, `precision`, and `recall` — without writing three separate log calls. Which function signature is correct?","choices":{"A":"`mlflow.log_metric({\"accuracy\": 0.9, \"precision\": 0.85, \"recall\": 0.88})`","B":"`mlflow.log_metric(\"accuracy\", \"precision\", \"recall\", [0.9, 0.85, 0.88])`","C":"`mlflow.log_metrics(accuracy=0.9, precision=0.85, recall=0.88)`","D":"`mlflow.log_metrics({\"accuracy\": 0.9, \"precision\": 0.85, \"recall\": 0.88})`"},"answer":"D","short":"`mlflow.log_metrics()` (plural) accepts a dictionary of metric name to numeric value. `mlflow.log_metric()` (singular) accepts a single name-value pair. Neither function accepts keyword arguments or positional lists for multiple metrics.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"02-ml-workflows-q003","bank":"praticas","n":16,"domain":"ml-workflows","title":"Autolog Supported Frameworks","difficulty":"medium","question":"A data scientist calls `mlflow.autolog()` at the start of their notebook. Which of the following frameworks will have its parameters and metrics automatically logged?","choices":{"A":"scikit-learn only","B":"scikit-learn and XGBoost only","C":"scikit-learn, XGBoost, LightGBM, and PyTorch Lightning","D":"All Python libraries that call `fit()` on a model object"},"answer":"C","short":"`mlflow.autolog()` supports multiple frameworks including scikit-learn, XGBoost, LightGBM, PyTorch Lightning, TensorFlow/Keras, Spark ML, and statsmodels. It does not automatically log all Python libraries — only those with built-in MLflow integration. Calling `mlflow.autolog()` enables all supported integrations at once.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"02-ml-workflows-q004","bank":"praticas","n":17,"domain":"ml-workflows","title":"Autolog and Custom Metrics","difficulty":"medium","question":"A data scientist enables `mlflow.autolog()` and trains a scikit-learn model. They also compute a custom business metric called `revenue_impact`. Will `revenue_impact` be logged automatically?","choices":{"A":"Yes, autolog captures all variables assigned in the training script","B":"Yes, autolog logs all numeric values computed during training","C":"No, autolog only logs metrics defined by the framework (e.g., accuracy, loss); custom metrics must be logged with `mlflow.log_metric()`","D":"No, custom metrics cannot be logged in the same run as autolog metrics"},"answer":"C","short":"`mlflow.autolog()` only captures metrics, parameters, and artifacts that the underlying framework itself produces (e.g., sklearn's cross-validation scores). Custom business metrics like `revenue_impact` must be explicitly logged with `mlflow.log_metric(\"revenue_impact\", value)`. Both autolog and manual logging can coexist in the same run.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"02-ml-workflows-q005","bank":"praticas","n":18,"domain":"ml-workflows","title":"search_runs Filter Syntax","difficulty":"medium","question":"A data scientist wants to find all MLflow runs where the `test_accuracy` metric is greater than 0.90. Which `mlflow.search_runs()` call is correct?","choices":{"A":"`mlflow.search_runs(filter_string=\"metrics.test_accuracy > 0.90\")`","B":"`mlflow.search_runs(filter_string=\"metric.test_accuracy > 0.90\")`","C":"`mlflow.search_runs(filter=\"test_accuracy > 0.90\")`","D":"`mlflow.search_runs(metrics={\"test_accuracy\": \">0.90\"})`"},"answer":"A","short":"The correct filter string prefix for metrics is `metrics.` (plural). The filter string syntax uses dot notation: `metrics.<name>`, `params.<name>`, or `tags.<name>`. Using the singular `metric.` or passing a plain column name without the prefix will raise an error or return no results.","explanation":"","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"02-ml-workflows-q006","bank":"praticas","n":19,"domain":"ml-workflows","title":"log_artifact Usage","difficulty":"easy","question":"A data scientist wants to save a confusion matrix image file (`confusion_matrix.png`) as part of their MLflow run. Which code is correct?","choices":{"A":"`mlflow.log_metric(\"confusion_matrix\", \"confusion_matrix.png\")`","B":"`mlflow.save_artifact(\"confusion_matrix.png\")`","C":"`mlflow.log_param(\"confusion_matrix\", \"confusion_matrix.png\")`","D":"`mlflow.log_artifact(\"confusion_matrix.png\")`"},"answer":"D","short":"`mlflow.log_artifact(local_path)` uploads a local file to the run's artifact store. Metrics are numeric values, parameters are string key-value pairs, and `save_artifact` is not a valid MLflow function.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"02-ml-workflows-q007","bank":"praticas","n":20,"domain":"ml-workflows","title":"Experiment vs Run","difficulty":"easy","question":"What is the relationship between an MLflow experiment and an MLflow run?","choices":{"A":"An experiment is a single training attempt; a run is a collection of experiments","B":"A run contains multiple experiments, each representing a different dataset","C":"An experiment and a run are the same concept with different names","D":"An experiment is a logical container for runs; a run is a single training attempt with its own parameters, metrics, and artifacts"},"answer":"D","short":"In MLflow, an **experiment** is a named container that groups related runs. A **run** represents a single execution of training code, capturing parameters, metrics, artifacts, and metadata. One experiment can contain many runs, making it easy to compare different model configurations.","explanation":"","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"02-ml-workflows-q008","bank":"praticas","n":21,"domain":"ml-workflows","title":"Nested Runs","difficulty":"medium","question":"A data scientist is running a hyperparameter sweep and wants to create a parent run that tracks the sweep, with each individual trial as a child run. Which code correctly creates a child run inside an existing parent run?","choices":{"A":"`mlflow.start_run(parent=True)`","B":"`mlflow.start_run(run_type=\"child\")`","C":"`mlflow.start_child_run()`","D":"`mlflow.start_run(nested=True)`"},"answer":"D","short":"`mlflow.start_run(nested=True)` creates a child run within the currently active parent run. There is no `parent=True`, `start_child_run()`, or `run_type` parameter in the MLflow API.","explanation":"","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"02-ml-workflows-q009","bank":"praticas","n":22,"domain":"ml-workflows","title":"log_artifacts for a Directory","difficulty":"easy","question":"A data scientist generates multiple output files in a local directory called `./outputs/` and wants to log all of them as artifacts. Which function should they use?","choices":{"A":"`mlflow.log_artifact(\"./outputs/\")`","B":"`mlflow.log_model(\"./outputs/\")`","C":"`mlflow.log_artifact(\"./outputs/*\")`","D":"`mlflow.log_artifacts(\"./outputs/\")`"},"answer":"D","short":"`mlflow.log_artifacts(local_dir)` (plural) uploads all files in a local directory to the artifact store. `mlflow.log_artifact(local_path)` (singular) uploads a single file. Glob patterns are not supported, and `log_model` is for ML model objects, not arbitrary files.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"02-ml-workflows-q010","bank":"praticas","n":23,"domain":"ml-workflows","title":"Notebook vs Workspace Experiments","difficulty":"medium","question":"A data scientist runs `mlflow.start_run()` in a Databricks notebook without ever calling `mlflow.set_experiment()`. Where is the run logged?","choices":{"A":"To the notebook's own experiment, which Databricks associates with the notebook","B":"To a workspace experiment that an admin must create first","C":"To a registry experiment attached to the Unity Catalog schema","D":"Nowhere — the call fails until an experiment is set"},"answer":"A","short":"On Databricks, a notebook has a default **notebook experiment**; runs started without `set_experiment()` are logged there. **Workspace experiments** are created explicitly (UI or `mlflow.set_experiment(\"/path\")`) and can collect runs from many notebooks or jobs.","explanation":"There is no \"registry experiment\" type, and the call does not fail.","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"02-ml-workflows-q011","bank":"praticas","n":24,"domain":"ml-workflows","title":"Run Comparison in UI","difficulty":"easy","question":"A data scientist has run 10 experiments with different hyperparameters and wants to visually compare their metrics. Which MLflow UI feature enables this?","choices":{"A":"The artifact browser in each individual run","B":"The run tags section, which can be filtered by metric value","C":"The model registry page, which shows metric comparisons across versions","D":"The \"Compare\" feature on the Experiments page, which creates parallel coordinate plots and scatter plots"},"answer":"D","short":"The MLflow Experiments page allows you to select multiple runs and click \"Compare\" to view parallel coordinate plots, scatter plots, and metric comparison tables. This makes it straightforward to identify which hyperparameter combinations produced the best results. The artifact browser, model registry page, and run tags do not provide side-by-side metric comparison views.","explanation":"","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"02-ml-workflows-q012","bank":"praticas","n":25,"domain":"ml-workflows","title":"Setting the Active Experiment","difficulty":"easy","question":"A data scientist wants all MLflow runs in their notebook to be logged to an experiment named `fraud-detection-v2`. Which code sets the active experiment?","choices":{"A":"`mlflow.set_experiment(\"fraud-detection-v2\")`","B":"`mlflow.start_run(experiment_name=\"fraud-detection-v2\")`","C":"`mlflow.create_experiment(\"fraud-detection-v2\")`","D":"`mlflow.use_experiment(\"fraud-detection-v2\")`"},"answer":"A","short":"`mlflow.set_experiment(experiment_name)` sets the active experiment for the current session. Subsequent `mlflow.start_run()` calls will log to that experiment. `mlflow.create_experiment()` creates a new experiment but does not set it as active. `start_run()` does not accept an `experiment_name` parameter directly. `use_experiment()` does not exist.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"02-ml-workflows-q013","bank":"praticas","n":26,"domain":"ml-workflows","title":"Retrieving Run Data Programmatically","difficulty":"medium","question":"A data scientist wants to retrieve the `rmse` metric from a specific MLflow run by its `run_id`. Which approach is correct?","choices":{"A":"`mlflow.get_run(run_id).data.metrics[\"rmse\"]`","B":"`mlflow.load_run(run_id)[\"rmse\"]`","C":"`mlflow.search_runs(run_id=run_id)[\"metrics.rmse\"]`","D":"`MlflowClient().get_metric(run_id, \"rmse\")`"},"answer":"A","short":"`mlflow.get_run(run_id)` returns a `Run` object. The metrics are accessible via `.data.metrics`, which is a dictionary of metric names to their last logged values. `mlflow.load_run()` does not exist. `search_runs()` returns a pandas DataFrame; while you can filter by run ID, it is not the idiomatic way to retrieve a single run's metric. `MlflowClient().get_metric()` does not exist as a single-call API.","explanation":"","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"03-feature-engineering-q001","bank":"praticas","n":27,"domain":"feature-engineering","title":"VectorAssembler Required Parameters","difficulty":"easy","question":"A data scientist wants to use `VectorAssembler` to combine columns `age`, `income`, and `credit_score` into a single feature vector column called `features`. Which code is correct?","choices":{"A":"`VectorAssembler(inputCols=[\"age\", \"income\", \"credit_score\"], outputCol=\"features\")`","B":"`VectorAssembler(inputCol=[\"age\", \"income\", \"credit_score\"], outputCol=\"features\")`","C":"`VectorAssembler(columns=[\"age\", \"income\", \"credit_score\"], output=\"features\")`","D":"`VectorAssembler(features=[\"age\", \"income\", \"credit_score\"], label=\"features\")`"},"answer":"A","short":"`VectorAssembler` requires `inputCols` (plural, a list of column names) and `outputCol` (singular, the output column name). Using `inputCol` (singular) is the common mistake — `VectorAssembler` always takes a list, so the parameter is always plural. The other options use non-existent parameter names.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"03-feature-engineering-q002","bank":"praticas","n":28,"domain":"feature-engineering","title":"Pipeline Stage Ordering — StringIndexer and OneHotEncoder","difficulty":"medium","question":"A data scientist wants to one-hot encode a categorical column `color`. Which stage ordering in the Pipeline is correct?","choices":{"A":"`OneHotEncoder` → `StringIndexer`","B":"`OneHotEncoder` can be applied directly to a string column without `StringIndexer`","C":"`VectorAssembler` → `StringIndexer` → `OneHotEncoder`","D":"`StringIndexer` → `OneHotEncoder`"},"answer":"D","short":"`StringIndexer` must come before `OneHotEncoder`. `StringIndexer` converts string categories to numeric indices (e.g., \"red\" → 0, \"blue\" → 1). `OneHotEncoder` then converts those integer indices into sparse binary vectors. `OneHotEncoder` does not accept raw string columns — it requires numeric index input.","explanation":"","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"03-feature-engineering-q003","bank":"praticas","n":29,"domain":"feature-engineering","title":"Pipeline fit() vs transform()","difficulty":"medium","question":"A data scientist creates a `Pipeline` with a `StringIndexer` and a `LogisticRegression` estimator. They call `pipeline.fit(train_df)`. What is returned?","choices":{"A":"A `PipelineModel` object containing fitted stages","B":"A trained `LogisticRegressionModel` object","C":"The original `Pipeline` object with updated parameters","D":"A pandas DataFrame with predictions"},"answer":"A","short":"`Pipeline.fit(df)` returns a `PipelineModel`, not a single model object. The `PipelineModel` contains all the fitted stages — in this case, a fitted `StringIndexerModel` and a fitted `LogisticRegressionModel`. You then call `pipeline_model.transform(test_df)` to generate predictions.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"03-feature-engineering-q004","bank":"praticas","n":30,"domain":"feature-engineering","title":"PipelineModel transform()","difficulty":"easy","question":"After fitting a `Pipeline`, a data scientist calls `pipeline_model.transform(test_df)`. What does this return?","choices":{"A":"A new `Pipeline` object trained on `test_df`","B":"A `PipelineModel` with updated weights","C":"A Spark DataFrame with new columns added by each stage","D":"A Python dictionary of model metrics"},"answer":"C","short":"`PipelineModel.transform(df)` applies each stage's `transform()` method sequentially and returns a new Spark DataFrame. Each stage adds one or more columns. For example, a `VectorAssembler` adds a `features` column, and a fitted classifier adds a `prediction` column.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"03-feature-engineering-q005","bank":"praticas","n":31,"domain":"feature-engineering","title":"CrossValidator numFolds Default","difficulty":"easy","question":"A data scientist creates a `CrossValidator` without specifying `numFolds`. How many folds will be used by default?","choices":{"A":"5","B":"10","C":"3","D":"2"},"answer":"C","short":"The default value of `numFolds` in `CrossValidator` is 3. This means the data is split into 3 equal folds, and the model is trained and evaluated 3 times, each time using a different fold as the validation set. You can override this with `numFolds=5` or `numFolds=10` for more robust estimates.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"03-feature-engineering-q006","bank":"praticas","n":32,"domain":"feature-engineering","title":"ParamGridBuilder Syntax","difficulty":"medium","question":"A data scientist wants to search over two values of `regParam` (0.01 and 0.1) and two values of `maxIter` (10 and 100) for a `LogisticRegression` model. Which code correctly builds the parameter grid?","choices":{"A":"`ParamGridBuilder().addGrid(lr.regParam, [0.01, 0.1]).addGrid(lr.maxIter, [10, 100]).build()`","B":"`ParamGridBuilder().add(lr.regParam, [0.01, 0.1]).add(lr.maxIter, [10, 100])`","C":"`ParamGridBuilder(lr.regParam=[0.01, 0.1], lr.maxIter=[10, 100]).build()`","D":"`{\"regParam\": [0.01, 0.1], \"maxIter\": [10, 100]}` passed directly as `estimatorParamMaps`"},"answer":"A","short":"`ParamGridBuilder` uses a builder pattern with chained `.addGrid(param, values)` calls followed by `.build()`, which returns the list of param maps (here 2 × 2 = 4 combinations). The `param` argument must be the actual parameter object from the estimator (e.g., `lr.regParam`), not a string.","explanation":"There is no `.add()` method, the constructor does not accept keyword arguments, and a plain dictionary is not a valid `estimatorParamMaps` value.","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"03-feature-engineering-q007","bank":"praticas","n":33,"domain":"feature-engineering","title":"CrossValidator vs TrainValidationSplit","difficulty":"medium","question":"A data scientist has a small dataset of 5,000 rows. They want to select hyperparameters using the most statistically reliable method. Which Spark ML class should they use?","choices":{"A":"`TrainValidationSplit` — it is faster and more reliable on small datasets","B":"`Pipeline` — it automatically performs cross-validation when `numFolds` is set","C":"`ParamGridBuilder` — it directly selects the best hyperparameter combination","D":"`CrossValidator` — it performs k-fold cross-validation, providing more reliable estimates on small datasets"},"answer":"D","short":"`CrossValidator` performs k-fold cross-validation, which provides more reliable hyperparameter estimates because every data point is used for both training and validation across different folds. This is especially valuable on small datasets. `TrainValidationSplit` uses a single random split, which is faster but less reliable on small datasets. `ParamGridBuilder` and `Pipeline` do not perform cross-validation themselves.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"03-feature-engineering-q008","bank":"praticas","n":34,"domain":"feature-engineering","title":"Feature Table Primary Keys in Unity Catalog","difficulty":"easy","question":"A data scientist calls `FeatureEngineeringClient().create_table(name=\"ml.features.customers\", df=features_df)` without specifying `primary_keys`. What happens?","choices":{"A":"The call fails because `primary_keys` is a required argument","B":"The feature table is created with an auto-generated UUID as the primary key","C":"The feature table is created with no primary key, allowing duplicate rows","D":"The feature table is created using the first column as the default primary key"},"answer":"A","short":"`primary_keys` is a required argument of `FeatureEngineeringClient.create_table` (it has no default). In Unity Catalog a feature table *is* a Delta table with a primary key; the key is what lookups, training-set joins, `score_batch`, and online publishing use to find rows.","explanation":"No key is ever invented for you. The legacy workspace `FeatureStoreClient.create_table` also required primary keys.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"03-feature-engineering-q009","bank":"praticas","n":35,"domain":"feature-engineering","title":"Writing to a Feature Table","difficulty":"medium","question":"A data scientist wants to update an existing Unity Catalog feature table with new and changed rows while preserving existing rows that are not in the new DataFrame. Which `FeatureEngineeringClient.write_table()` call is correct?","choices":{"A":"`fe.write_table(name=..., df=new_df, mode=\"overwrite\")`","B":"`fe.write_table(name=..., df=new_df, mode=\"append\")`","C":"`fe.write_table(name=..., df=new_df, mode=\"merge\")`","D":"`fe.write_table(name=..., df=new_df, mode=\"update\")`"},"answer":"C","short":"`mode=\"merge\"` upserts by primary key: matching keys are updated, new keys are inserted, and rows whose key is not in the DataFrame stay unchanged. In `FeatureEngineeringClient` it is the only supported `write_table` mode (and the default).","explanation":"To fully replace the data you would delete rows or recreate the table first; `append` and `update` are not `write_table` modes.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"03-feature-engineering-q010","bank":"praticas","n":36,"domain":"feature-engineering","title":"Scoring with Feature Tables","difficulty":"medium","question":"A model was trained on Unity Catalog feature tables and logged with `fe.log_model(...)`. A data scientist has a DataFrame containing only `customer_id` values to score. Which call retrieves the features and scores the batch?","choices":{"A":"`fe.predict(model_uri, entities_df)`","B":"`mlflow.pyfunc.load_model(model_uri).transform(entities_df)`","C":"`fe.score_batch(model_uri=model_uri, df=entities_df)`","D":"`fe.read_table(name=feature_table_name).join(entities_df)`"},"answer":"C","short":"`FeatureEngineeringClient.score_batch(model_uri, df)` reads the feature-lookup metadata packaged by `fe.log_model`, joins the required features to the input keys, and applies the model — the same feature definitions as training, so no training-serving skew.","explanation":"There is no `fe.predict`, a pyfunc model has `predict` rather than `transform`, and `read_table(...).join(...)` only fetches features without scoring.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"03-feature-engineering-q011","bank":"praticas","n":37,"domain":"feature-engineering","title":"Point-in-Time Lookups","difficulty":"medium","question":"Why do feature tables in Unity Catalog support point-in-time lookups?","choices":{"A":"To ensure features are computed faster using parallel processing","B":"To automatically version all feature tables when new data is ingested","C":"To allow real-time feature updates without retraining the model","D":"To prevent data leakage by retrieving feature values as they existed at the time of each training label's event"},"answer":"D","short":"Point-in-time lookups (a `timestamp_lookup_key` on the `FeatureLookup`) retrieve the feature values that were available at the exact moment each training label was generated. This prevents data leakage, which occurs when future information is used to predict a past event. For example, when predicting a customer's purchase at time T, only features available before or at time T should be used.","explanation":"","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"03-feature-engineering-q012","bank":"praticas","n":38,"domain":"feature-engineering","title":"Train-Serve Skew Prevention","difficulty":"hard","question":"A data scientist trains a model using manually computed features in their notebook. In production, a different team recomputes those features. The model's production accuracy is lower than its training accuracy. What is the most likely cause?","choices":{"A":"The production cluster has fewer cores than the training cluster","B":"Train-serve skew — the feature computation logic differs between training and serving","C":"The MLflow model version in production is different from the one that was tested","D":"The production Delta table uses a different partition scheme"},"answer":"B","short":"Train-serve skew occurs when the features used at training time are computed differently from those computed at serving time. Even small differences in logic (e.g., different null handling, different aggregation windows) can cause significant accuracy degradation. Feature tables in Unity Catalog prevent this by centralizing feature definitions: a model logged with `fe.log_model` gets its features from the same tables at training, batch scoring, and serving time.","explanation":"","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"03-feature-engineering-q013","bank":"praticas","n":39,"domain":"feature-engineering","title":"Estimator vs Transformer in Pipeline","difficulty":"medium","question":"Which of the following Spark ML classes is an `Estimator` (requires `fit()`) rather than a `Transformer` (only requires `transform()`)?","choices":{"A":"`VectorAssembler`","B":"`Bucketizer`","C":"`StandardScaler`","D":"`SQLTransformer`"},"answer":"C","short":"`StandardScaler` is an `Estimator` because it must learn the mean and standard deviation of the training data during `fit()` before it can scale new data. `VectorAssembler`, `Bucketizer`, and `SQLTransformer` are all `Transformer` classes — they do not learn from data and can apply their transformations directly without fitting.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"03-feature-engineering-q014","bank":"praticas","n":40,"domain":"feature-engineering","title":"Feature Lookup in Feature Store","difficulty":"easy","question":"When building a training set from Unity Catalog feature tables, a data scientist specifies a `FeatureLookup`. What is the purpose of the `lookup_key` parameter?","choices":{"A":"It specifies the primary key column in the feature table to join on","B":"It specifies the MLflow run ID used to retrieve the feature values","C":"It specifies the encryption key for secure feature retrieval","D":"It specifies the maximum number of features to retrieve"},"answer":"A","short":"The `lookup_key` parameter in `FeatureLookup` specifies the column in the training dataset that maps to the primary key in the feature table. This enables `create_training_set` to join the training DataFrame with the feature table to retrieve the correct feature values for each entity.","explanation":"","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"03-feature-engineering-q015","bank":"praticas","n":41,"domain":"feature-engineering","title":"Pipeline with CrossValidator","difficulty":"hard","question":"A data scientist wraps a `Pipeline` inside a `CrossValidator`. When `CrossValidator.fit(train_df)` is called, what happens?","choices":{"A":"The Pipeline is fit once on the full training set, then evaluated on a held-out test set","B":"The Pipeline is fit and evaluated K times using K-fold splits, and the best hyperparameter combination is selected","C":"The Pipeline stages are fit independently, and CrossValidator only tunes the final estimator","D":"The Pipeline is converted to a single estimator before cross-validation begins"},"answer":"B","short":"When a `Pipeline` is used as the estimator inside `CrossValidator`, the entire pipeline (all stages) is fit and evaluated K times across K folds for each hyperparameter combination in the `ParamGrid`. This ensures that preprocessing stages like `StringIndexer` and `VectorAssembler` are fit only on training data in each fold, preventing data leakage from the validation fold.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"04-mlflow-deployment-q001","bank":"praticas","n":42,"domain":"mlflow-deployment","title":"register_model URI Format","difficulty":"easy","question":"A data scientist has trained a model and its `run_id` is `abc123`. The model was logged with `mlflow.sklearn.log_model(model, artifact_path=\"model\")`. With the registry URI set to `databricks-uc`, which call registers it as `ml.fraud.detector` in Unity Catalog?","choices":{"A":"`mlflow.register_model(\"model/abc123\", \"ml.fraud.detector\")`","B":"`mlflow.register_model(\"runs:/abc123/model\", \"ml.fraud.detector\")`","C":"`mlflow.register_model(\"mlflow:/abc123/model\", \"ml.fraud.detector\")`","D":"`mlflow.register_model(\"artifacts:/abc123/model\", \"ml.fraud.detector\")`"},"answer":"B","short":"The URI for a model logged in a run is `runs:/<run_id>/<artifact_path>` — here `runs:/abc123/model` — and Unity Catalog model names are three-level `catalog.schema.model`. The `mlflow:/` and `artifacts:/` schemes do not exist.","explanation":"In MLflow 3, `log_model` also returns a `models:/<model_id>` URI you can register directly.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"04-mlflow-deployment-q002","bank":"praticas","n":43,"domain":"mlflow-deployment","title":"Promoting a Version with an Alias","difficulty":"medium","question":"Version 3 of the Unity Catalog model `ml.churn.predictor` has passed validation. Production scoring code loads `models:/ml.churn.predictor@champion`. Which call makes production use version 3?","choices":{"A":"`MlflowClient().transition_model_version_stage(\"ml.churn.predictor\", 3, \"Production\")`","B":"`MlflowClient().set_registered_model_alias(\"ml.churn.predictor\", \"champion\", 3)`","C":"`MlflowClient().set_model_version_tag(\"ml.churn.predictor\", \"3\", \"champion\", \"true\")`","D":"`mlflow.register_model(\"models:/ml.churn.predictor/3\", \"ml.churn.predictor\")`"},"answer":"B","short":"In Unity Catalog, promotion means pointing an **alias** at a version: `set_registered_model_alias(name, \"champion\", 3)` moves `@champion` to version 3, and code that loads `models:/ml.churn.predictor@champion` picks it up without changes.","explanation":"Stage transitions are a legacy workspace-registry feature and are not supported in UC. A tag is descriptive metadata and changes nothing that is served. Re-registering creates yet another version.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"04-mlflow-deployment-q003","bank":"praticas","n":44,"domain":"mlflow-deployment","title":"Stages vs Aliases in Unity Catalog","difficulty":"easy","question":"A team migrating from the workspace model registry to Models in Unity Catalog asks which registry feature does **not** carry over. Which one is it?","choices":{"A":"Numbered model versions","B":"Model stages such as `Staging` and `Production`","C":"Tags on registered models and model versions","D":"Loading a specific version with `models:/<name>/<version>`"},"answer":"B","short":"\"Stages are not supported for models in Unity Catalog.\" UC uses **aliases** (for example `@champion` / `@challenger`) plus separate catalogs per environment instead.","explanation":"Versions, tags, and version-number URIs all work in UC.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"04-mlflow-deployment-q004","bank":"praticas","n":45,"domain":"mlflow-deployment","title":"Loading a Registered Model for Inference","difficulty":"medium","question":"A data scientist wants to load whichever version of the Unity Catalog model `ml.pricing.estimator` currently holds the `champion` alias, in a way that works for any model flavor. Which code is correct?","choices":{"A":"`model = mlflow.load_model(\"models:/ml.pricing.estimator@champion\")`","B":"`model = mlflow.pyfunc.load_model(\"models:/ml.pricing.estimator@champion\")`","C":"`model = MlflowClient().load_model(\"ml.pricing.estimator\", alias=\"champion\")`","D":"`model = mlflow.pyfunc.load_model(\"models:/ml.pricing.estimator/champion\")`"},"answer":"B","short":"`mlflow.pyfunc.load_model()` is the flavor-agnostic loader, and `models:/<name>@<alias>` resolves an alias. `mlflow.load_model()` and `MlflowClient().load_model()` do not exist.","explanation":"`models:/<name>/<x>` expects a version number (or, in the legacy workspace registry, a stage) — `@` is the alias syntax.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"04-mlflow-deployment-q005","bank":"praticas","n":46,"domain":"mlflow-deployment","title":"spark_udf for Batch Scoring","difficulty":"medium","question":"A data scientist wants to score a Spark DataFrame of 10 million customer records using a registered MLflow model. Which approach is most appropriate for distributed batch scoring?","choices":{"A":"Load the model with `mlflow.pyfunc.load_model()` and call `model.predict(df.toPandas())`","B":"Use `mlflow.pyfunc.spark_udf()` to create a UDF and apply it to the Spark DataFrame","C":"Deploy the model to a serving endpoint and send the DataFrame as a single HTTP request","D":"Use `fe.score_batch()` without any model URI"},"answer":"B","short":"`mlflow.pyfunc.spark_udf(spark, model_uri)` creates a Spark UDF that wraps the model, enabling distributed batch scoring across all Spark workers. Calling `.toPandas()` on 10 million rows collects all data to the driver, which can cause out-of-memory errors. Sending 10 million rows in a single HTTP request to a serving endpoint is not feasible. `fe.score_batch()` needs a model URI and a model logged with `fe.log_model`.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"04-mlflow-deployment-q006","bank":"praticas","n":47,"domain":"mlflow-deployment","title":"spark_udf Usage Pattern","difficulty":"medium","question":"A data scientist creates a `spark_udf` from a registered model. Which option correctly creates and applies the UDF to a DataFrame `df` that has a `features` column?","choices":{"A":"`predict_udf = mlflow.pyfunc.spark_udf(spark, \"models:/ml.demo.mymodel@champion\")`, then `df.withColumn(\"prediction\", predict_udf(\"features\"))`","B":"`predict_udf = mlflow.pyfunc.spark_udf(\"models:/ml.demo.mymodel@champion\")`, then `predict_udf.transform(df)`","C":"`predict_udf = mlflow.pyfunc.spark_udf(spark, \"models:/ml.demo.mymodel@champion\")`, then `spark.sql(\"SELECT predict_udf(features) FROM df\")` with no registration","D":"`predict_udf = mlflow.load_model(\"models:/ml.demo.mymodel@champion\")`, then `df.withColumn(\"prediction\", predict_udf(df[\"features\"]))`"},"answer":"A","short":"`mlflow.pyfunc.spark_udf(spark, model_uri)` takes the `spark` session as its first argument and returns a Spark UDF, applied with `df.withColumn(\"prediction\", predict_udf(\"features\"))` (column names as strings or `Column` objects).","explanation":"A Python UDF object is not visible to SQL until it is registered (`spark.udf.register`), `mlflow.load_model()` does not exist, and a UDF has no `transform()` method.","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"04-mlflow-deployment-q007","bank":"praticas","n":48,"domain":"mlflow-deployment","title":"log_model vs register_model","difficulty":"medium","question":"What is the key difference between `mlflow.sklearn.log_model()` and `mlflow.register_model()`?","choices":{"A":"`log_model()` saves the model to the Model Registry; `register_model()` saves it as a run artifact","B":"`log_model()` saves the model as a run artifact inside an MLflow run; `register_model()` registers a previously logged artifact to the Model Registry under a named version","C":"`log_model()` and `register_model()` are interchangeable — both register a model to the registry","D":"`register_model()` can only be called immediately after `log_model()` in the same code block"},"answer":"B","short":"`mlflow.sklearn.log_model()` (and other flavor-specific `log_model` functions) saves a model as an artifact within the current MLflow run. The model is associated with that specific run. `mlflow.register_model()` takes a `runs:/` or `models:/` URI and creates a numbered version of a registered model (in Unity Catalog, `catalog.schema.model`), making it discoverable, governed, and promotable with aliases. These are two separate steps, and `register_model()` can be called at any time after the model is logged.","explanation":"","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"04-mlflow-deployment-q008","bank":"praticas","n":49,"domain":"mlflow-deployment","title":"Model Serving Endpoint Invocation","difficulty":"easy","question":"A data scientist has deployed a model to a Databricks Model Serving endpoint. Which format is used to send prediction requests to the endpoint?","choices":{"A":"A Spark DataFrame serialized as a Parquet file","B":"A JSON payload with a `dataframe_records` or `dataframe_split` key","C":"A Python pickle of the input DataFrame","D":"A CSV file uploaded to DBFS and referenced by path"},"answer":"B","short":"Databricks Model Serving endpoints accept JSON payloads via HTTP POST requests. The standard input format uses either `dataframe_records` (list of row dictionaries) or `dataframe_split` (columnar format with `columns` and `data` keys). Parquet, pickle, and DBFS file references are not supported input formats for real-time serving endpoints.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"05-unity-catalog-mlops-q001","bank":"praticas","n":50,"domain":"unity-catalog-mlops","title":"MLOps Environment Best Practice *(2026 guide)*","difficulty":"medium","question":"A team is formalising its MLOps process on Databricks. Which setup follows the recommended best practices?","choices":{"A":"One shared catalog for all work, with production jobs running notebooks straight from each data scientist's home folder","B":"Separate development, staging, and production environments, each with its own Unity Catalog catalog, and ML pipeline code in Git promoted through branches with CI tests","C":"Training only in the development workspace and emailing the model file to the platform team for production","D":"A single production catalog where data scientists experiment directly so models always see live data"},"answer":"B","short":"Databricks recommends separate environments for development, staging, and production — each backed by its own Unity Catalog catalog — with ML pipelines kept as code in Git, tested in CI, and promoted from branch to branch.","explanation":"Running production from personal folders, sending model files around by hand, or experimenting directly on production data all skip review, testing, and governance.","lesson":"01-databricks-machine-learning/08-mlops-strategy","related":null},{"id":"05-unity-catalog-mlops-q002","bank":"praticas","n":51,"domain":"unity-catalog-mlops","title":"Deploy Code When Production Data Is Restricted *(2026 guide)*","difficulty":"medium","question":"Data scientists at a bank cannot read production customer data from the development workspace. The company has a CI/CD process and wants automated monthly retraining. Which deployment pattern fits best?","choices":{"A":"Deploy models — train in development and copy the model version to production","B":"Deploy models — train in staging on a sample and promote the artifact","C":"Deploy code — promote the reviewed training code so the model is trained in production on production data","D":"Neither — retraining must be done manually in a notebook each month"},"answer":"C","short":"With **deploy code**, the training code moves through dev → staging → production and the model is trained in production, where the data lives. The docs list restricted production data access and safer automated retraining as advantages of this pattern, and recommend it in most situations.","explanation":"Deploy models may not be viable when production data is not accessible from development, and automated retraining is harder in that pattern.","lesson":"01-databricks-machine-learning/08-mlops-strategy","related":null},{"id":"05-unity-catalog-mlops-q003","bank":"praticas","n":52,"domain":"unity-catalog-mlops","title":"Deploy Models for Expensive Training *(2026 guide)*","difficulty":"medium","question":"A team fine-tunes a large vision model for three days on many GPUs. All of its work happens in a single Databricks workspace and it has no external CI/CD pipeline. Which approach is most appropriate?","choices":{"A":"Deploy models — train once, validate the artifact, then promote that model version","B":"Deploy code — retrain the model from scratch in staging and again in production","C":"Deploy code — retrain in production every night to keep the model fresh","D":"Avoid the model registry and serve the model file from a volume"},"answer":"A","short":"The docs suggest **deploy models** when training is very expensive or hard to reproduce, when all work is in a single workspace, or when there is no external repo / CI/CD process. Training once and promoting the validated artifact avoids repeating a multi-day GPU job in every environment.","explanation":"Retraining in each environment multiplies the cost, and bypassing the registry loses versioning and governance.","lesson":"01-databricks-machine-learning/08-mlops-strategy","related":null},{"id":"05-unity-catalog-mlops-q004","bank":"praticas","n":53,"domain":"unity-catalog-mlops","title":"Account-Level Feature Tables *(2026 guide)*","difficulty":"easy","question":"Teams in two workspaces attached to the same Unity Catalog metastore want to reuse one set of customer features. What is the main benefit of keeping these feature tables in Unity Catalog rather than in a legacy workspace feature store?","choices":{"A":"Unity Catalog feature tables refresh themselves automatically every hour","B":"Unity Catalog feature tables can be shared and discovered across workspaces, with centralised access control and lineage","C":"Unity Catalog feature tables do not need a primary key","D":"Unity Catalog feature tables can only be read by the workspace that created them, which improves security"},"answer":"B","short":"Unity Catalog is account-level: any workspace on the metastore can discover and use the table, governed by UC privileges, with lineage to the models that use it. The docs describe \"built-in governance, lineage, point-in-time joins, and cross-workspace feature sharing and discovery.\"","explanation":"Refresh is still your pipeline's job, a primary key is required, and per-workspace isolation is what the legacy store had.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"05-unity-catalog-mlops-q005","bank":"praticas","n":54,"domain":"unity-catalog-mlops","title":"Turning an Existing Delta Table into a Feature Table *(2026 guide)*","difficulty":"medium","question":"The Unity Catalog Delta table `ml.features.store_sales` already contains one row per `store_id`. What makes it usable as a feature table?","choices":{"A":"`ALTER TABLE ml.features.store_sales SET AS FEATURE STORE`","B":"`fe.register_table(delta_table=\"ml.features.store_sales\")`","C":"`CREATE FEATURE TABLE ml.features.store_sales AS SELECT * FROM ml.features.store_sales`","D":"Make `store_id` `NOT NULL`, then `ALTER TABLE ml.features.store_sales ADD CONSTRAINT store_sales_pk PRIMARY KEY (store_id)`"},"answer":"D","short":"In Unity Catalog, any Delta table with a **primary key constraint** is a feature table. For an existing table, set the key column(s) to `NOT NULL` and add the `PRIMARY KEY` constraint.","explanation":"There is no `SET AS FEATURE STORE` or `CREATE FEATURE TABLE` syntax, and `register_table` is not the Unity Catalog path.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"05-unity-catalog-mlops-q006","bank":"praticas","n":55,"domain":"unity-catalog-mlops","title":"Online vs Offline Feature Tables *(2026 guide)*","difficulty":"medium","question":"A fraud model served on a real-time endpoint must fetch a customer's latest aggregates within milliseconds using only `customer_id`. The same features are used for nightly retraining. How should the features be organised?","choices":{"A":"Keep the offline Delta feature table for training and batch scoring, and publish it to an online store for low-latency lookups at serving time","B":"Query the offline Delta table with a full scan for each request","C":"Store the features only in the online store and train from there","D":"Copy the features into the model artifact at training time"},"answer":"A","short":"The **offline** feature table (a Delta table in Unity Catalog) is optimised for large scans and joins — training sets and batch scoring. An **online store** holds a published copy optimised for key-based millisecond lookups; a model logged with `fe.log_model` and deployed to Model Serving can look features up automatically.","explanation":"Scanning Delta per request is too slow, the online store is not the training source, and baking features into the artifact makes them stale.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"05-unity-catalog-mlops-q007","bank":"praticas","n":56,"domain":"unity-catalog-mlops","title":"Building a Training Set from Feature Tables *(2026 guide)*","difficulty":"medium","question":"A label DataFrame has `customer_id` and `churned`. Which sequence produces a training DataFrame that joins features from `ml.features.customer_features`?","choices":{"A":"`fe.read_table(...)` then `labels_df.union(...)`","B":"Define `FeatureLookup(table_name=\"ml.features.customer_features\", lookup_key=\"customer_id\")`, call `fe.create_training_set(df=labels_df, feature_lookups=[...], label=\"churned\")`, then `.load_df()`","C":"`fe.score_batch(model_uri, labels_df)` to add the features","D":"`fe.write_table(name=\"ml.features.customer_features\", df=labels_df, mode=\"merge\")`"},"answer":"B","short":"`FeatureLookup` says which table to join on which key; `create_training_set` combines the label DataFrame with the looked-up features, and `load_df()` returns the joined DataFrame. Logging the model later with `fe.log_model(..., training_set=training_set)` records the lookups for scoring.","explanation":"A union does not join on keys, `score_batch` needs a trained model, and `write_table` would write labels into the feature table.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"05-unity-catalog-mlops-q008","bank":"praticas","n":57,"domain":"unity-catalog-mlops","title":"Best Run with the MLflow Client API *(2026 guide)*","difficulty":"medium","question":"An experiment holds 60 runs, each logging `val_auc`. Which MLflow Client API call returns the single run with the **highest** `val_auc`?","choices":{"A":"`MlflowClient().search_runs([exp_id], order_by=[\"metrics.val_auc ASC\"], max_results=1)[0]`","B":"`MlflowClient().get_run(exp_id)`","C":"`MlflowClient().search_runs([exp_id], order_by=[\"metrics.val_auc DESC\"], max_results=1)[0]`","D":"`MlflowClient().search_experiments(order_by=[\"metrics.val_auc DESC\"])[0]`"},"answer":"C","short":"`search_runs` ranks runs server-side: for a score where higher is better, order by `metrics.val_auc DESC` and take the first result.","explanation":"`ASC` would return the *worst* AUC, `get_run` needs a run ID and does not rank, and `search_experiments` returns experiments, not runs.","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"05-unity-catalog-mlops-q009","bank":"praticas","n":58,"domain":"unity-catalog-mlops","title":"Unity Catalog Registry vs Workspace Registry *(2026 guide)*","difficulty":"easy","question":"Which is a benefit of registering models in Unity Catalog instead of the legacy workspace model registry?","choices":{"A":"Models are automatically promoted to `Production` when their metrics improve","B":"Model versions no longer need a signature","C":"Models get centralised access control, auditing, lineage, and discovery across workspaces","D":"Model serving endpoints respond faster for UC models"},"answer":"C","short":"The docs state that Models in Unity Catalog extend \"centralized access control, auditing, lineage, and model discovery across workspaces\" to ML models.","explanation":"UC does not auto-promote (and has no stages), new UC versions *must* have a signature, and the registry choice does not change endpoint latency.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"05-unity-catalog-mlops-q010","bank":"praticas","n":59,"domain":"unity-catalog-mlops","title":"Registering a Model with the MLflow Client API *(2026 guide)*","difficulty":"medium","question":"With the registry URI set to `databricks-uc`, a data scientist wants to use the **MLflow Client API** (not the fluent API) to create the registered model `ml.churn.clf` and add the model from run `r42` as a version. Which calls are correct?","choices":{"A":"`client.create_registered_model(\"ml.churn.clf\")` then `client.create_model_version(name=\"ml.churn.clf\", source=\"runs:/r42/model\", run_id=\"r42\")`","B":"`client.register_model(\"runs:/r42/model\")` with no name","C":"`client.create_model_version(name=\"ml.churn.clf\")` with no source","D":"`client.log_model(\"ml.churn.clf\", \"runs:/r42/model\")`"},"answer":"A","short":"`MlflowClient.create_registered_model(name)` creates the registered model (three-level name in UC), and `create_model_version(name, source, run_id)` adds a numbered version pointing at the logged model. The fluent shortcut for the same thing is `mlflow.register_model(\"runs:/r42/model\", \"ml.churn.clf\")`.","explanation":"A version needs a source; `MlflowClient` has no `log_model` method.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"05-unity-catalog-mlops-q011","bank":"praticas","n":60,"domain":"unity-catalog-mlops","title":"Removing a Model Version Tag *(2026 guide)*","difficulty":"easy","question":"Version 4 of `ml.churn.clf` carries the tag `validation_status=pending`. Validation was rerun, and the tag should be removed from that version only. Which call does this?","choices":{"A":"`client.delete_registered_model_tag(\"ml.churn.clf\", \"validation_status\")`","B":"`client.set_model_version_tag(\"ml.churn.clf\", \"4\", \"validation_status\", None)`","C":"`client.delete_registered_model_alias(\"ml.churn.clf\", \"validation_status\")`","D":"`client.delete_model_version_tag(\"ml.churn.clf\", \"4\", \"validation_status\")`"},"answer":"D","short":"`delete_model_version_tag(name, version, key)` removes a tag from one version; `set_model_version_tag(name, version, key, value)` sets it.","explanation":"`delete_registered_model_tag` removes a **model-level** tag, an alias is not a tag, and setting a value is not the same as removing the key.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"05-unity-catalog-mlops-q012","bank":"praticas","n":61,"domain":"unity-catalog-mlops","title":"Rolling Back a Champion *(2026 guide)*","difficulty":"hard","question":"Yesterday the team moved the `champion` alias of `ml.churn.clf` from version 4 to version 5. Batch and serving code load `models:/ml.churn.clf@champion`. Version 5 is now misbehaving. What is the fastest rollback that needs no code change?","choices":{"A":"`client.set_registered_model_alias(\"ml.churn.clf\", \"champion\", 4)`","B":"Delete version 5 so the registry falls back automatically","C":"`client.transition_model_version_stage(\"ml.churn.clf\", 4, \"Production\")`","D":"Edit every job to load `models:/ml.churn.clf/4`"},"answer":"A","short":"Aliases are movable pointers: reassigning `champion` to version 4 makes every consumer of `@champion` use version 4 on its next load. Deployment is decoupled from inference code.","explanation":"Deleting versions is destructive and does not move an alias for you, stages are not supported in Unity Catalog, and hard-coding versions is exactly what aliases avoid.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"05-unity-catalog-mlops-q013","bank":"praticas","n":62,"domain":"unity-catalog-mlops","title":"AutoML Feature Importance *(2026 guide)*","difficulty":"medium","question":"After an AutoML classification run, a data scientist wants to see which features drive the best model's predictions. What should they do?","choices":{"A":"Read the `feature_importance` Delta table that AutoML writes","B":"Open the best-trial notebook and enable the SHAP-based feature importance section (`shap_enabled = True`), then rerun it","C":"Query the `summary.best_trial.shap_values` attribute","D":"AutoML does not support any form of feature importance"},"answer":"B","short":"AutoML's generated notebooks include a **Feature importance** section that computes Shapley values with the SHAP package. Because it is memory-intensive it is **off by default**; set `shap_enabled = True` and rerun the notebook.","explanation":"AutoML writes no feature-importance Delta table, and `TrialInfo` has no `shap_values` attribute.","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"05-unity-catalog-mlops-q014","bank":"praticas","n":63,"domain":"unity-catalog-mlops","title":"Advantage of the ML Runtime *(2026 guide)*","difficulty":"easy","question":"Why would a team choose the Databricks Runtime for Machine Learning over the standard runtime for model development?","choices":{"A":"It is the only runtime that can read Delta tables","B":"It runs Spark SQL queries on GPUs automatically","C":"It provides pre-installed, version-compatible ML and deep-learning libraries plus MLflow and AutoML, so no environment assembly is needed","D":"It removes the need for Unity Catalog permissions"},"answer":"C","short":"The ML runtime \"automates the creation of a compute resource with pre-built machine learning and deep learning infrastructure\": popular libraries (scikit-learn, PyTorch, TensorFlow, XGBoost, …) and MLflow are installed and tested together, and AutoML is available.","explanation":"Every runtime reads Delta, Spark SQL is not automatically GPU-accelerated, and Unity Catalog permissions still apply.","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"06-data-processing-q001","bank":"praticas","n":64,"domain":"data-processing","title":"summary() vs describe() *(2026 guide)*","difficulty":"easy","question":"Which statistics does `df.summary()` return by default that `df.describe()` does not?","choices":{"A":"Approximate 25 %, 50 %, and 75 % percentiles","B":"The number of null values per column","C":"The mode of each column","D":"The skewness and kurtosis of each column"},"answer":"A","short":"With no arguments, `summary()` computes count, mean, stddev, min, approximate quartiles (25 %, 50 %, 75 %), and max; `describe()` returns count, mean, stddev, min, and max only.","explanation":"Neither returns null counts, mode, skewness, or kurtosis by default; `summary()` also accepts arbitrary percentiles such as `\"10%\"`.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"06-data-processing-q002","bank":"praticas","n":65,"domain":"data-processing","title":"Databricks Data Summaries *(2026 guide)*","difficulty":"easy","question":"In a Databricks notebook, which call displays summary statistics (including histograms for numeric columns) for a Spark DataFrame `df`?","choices":{"A":"`dbutils.fs.summarize(df)`","B":"`df.profile()`","C":"`dbutils.data.summarize(df)`","D":"`spark.summary(df)`"},"answer":"C","short":"`dbutils.data.summarize(df)` \"calculates and displays summary statistics of an Apache Spark DataFrame or pandas DataFrame.\" It is the \"dbutils data summaries\" named in the exam guide.","explanation":"`dbutils.fs` is for files, and `df.profile()` and `spark.summary()` do not exist.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"06-data-processing-q003","bank":"praticas","n":66,"domain":"data-processing","title":"The precise Parameter *(2026 guide)*","difficulty":"medium","question":"What does `dbutils.data.summarize(df, precise=True)` change compared with the default?","choices":{"A":"It samples 1 % of the rows to run faster","B":"Statistics are computed with higher precision; with the default (`False`) some statistics are approximations","C":"It writes the summary to a Delta table","D":"It only summarises numeric columns"},"answer":"B","short":"The default `precise=False` uses approximations for some statistics to reduce run time; `precise=True` computes them with higher precision (all except histograms and percentiles for numeric columns become exact).","explanation":"The command still analyses the complete DataFrame, writes nothing to a table, and covers all column types.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"06-data-processing-q004","bank":"praticas","n":67,"domain":"data-processing","title":"IQR Fences *(2026 guide)*","difficulty":"medium","question":"For a feature, Q1 = 20 and Q3 = 50. Using the 1.5 × IQR rule, what are the lower and upper fences outside which values are treated as outliers?","choices":{"A":"5 and 65","B":"20 and 50","C":"−10 and 80","D":"−25 and 95"},"answer":"D","short":"IQR = Q3 − Q1 = 30, so the fences are Q1 − 1.5 × 30 = −25 and Q3 + 1.5 × 30 = 95. Rows outside [−25, 95] are removed (or capped).","explanation":"In Spark: `q1, q3 = df.approxQuantile(\"x\", [0.25, 0.75], 0.01)` and then `df.filter(F.col(\"x\").between(lower, upper))`.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"06-data-processing-q005","bank":"praticas","n":68,"domain":"data-processing","title":"Standard-Deviation Rule *(2026 guide)*","difficulty":"medium","question":"A roughly normal feature `x` has mean `mu` and standard deviation `sigma`. Which filter keeps only values within three standard deviations of the mean?","choices":{"A":"`df.filter(F.abs(F.col(\"x\") - mu) <= 3 * sigma)`","B":"`df.filter(F.col(\"x\") <= mu + 3)`","C":"`df.filter(F.col(\"x\") / sigma <= 3)`","D":"`df.filter(F.abs(F.col(\"x\")) <= 3 * mu)`"},"answer":"A","short":"The z-score rule keeps rows where |x − μ| ≤ k·σ (k = 3 here), i.e. values in [μ − 3σ, μ + 3σ].","explanation":"The other filters ignore the mean, the standard deviation, or both.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"06-data-processing-q006","bank":"praticas","n":69,"domain":"data-processing","title":"Choosing an Outlier Rule for Skewed Data *(2026 guide)*","difficulty":"hard","question":"A `price` column is strongly right-skewed with a few extreme listings. Why are IQR fences usually preferred over a 3-standard-deviation rule here?","choices":{"A":"The IQR rule removes more rows, which always improves models","B":"Standard deviation cannot be computed in Spark","C":"Quartiles barely move when extreme values are present, while the mean and standard deviation are inflated by the very outliers being detected","D":"The IQR rule only works on normally distributed data"},"answer":"C","short":"The z-score rule assumes a roughly symmetric distribution; extreme values pull the mean and inflate σ, widening the bounds so outliers can hide. Quartiles are robust to extremes, so IQR fences suit skewed features.","explanation":"Removing more rows is not automatically better, Spark computes stddev easily, and IQR is the rule that does *not* need normality.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"06-data-processing-q007","bank":"praticas","n":70,"domain":"data-processing","title":"Visualising a Categorical Feature *(2026 guide)*","difficulty":"easy","question":"A data scientist wants to see how often each of the 6 values of `payment_method` occurs. Which visualisation is most appropriate?","choices":{"A":"A scatter plot","B":"A bar chart of counts per category","C":"A line chart over row index","D":"A histogram with 50 numeric bins"},"answer":"B","short":"Categorical features are summarised by frequency per level — a bar (count) chart. Histograms, box plots, and density plots are for **continuous** features; scatter plots compare two continuous features.","explanation":"","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"06-data-processing-q008","bank":"praticas","n":71,"domain":"data-processing","title":"Comparing Two Continuous Features *(2026 guide)*","difficulty":"medium","question":"What is the appropriate way to examine the relationship between two continuous features, `sqft` and `price`?","choices":{"A":"A scatter plot plus a correlation coefficient (Pearson, or Spearman for monotonic/skewed relationships)","B":"A contingency table and a chi-square test","C":"A bar chart of the counts of each `sqft` value","D":"One-hot encode both features and compare the vectors"},"answer":"A","short":"Two continuous features are compared with a scatter plot and a correlation measure — `df.stat.corr(\"sqft\", \"price\")` (Pearson) or `pyspark.ml.stat.Correlation.corr(..., method=\"spearman\")`.","explanation":"Contingency tables and chi-square tests are for two **categorical** features.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"06-data-processing-q009","bank":"praticas","n":72,"domain":"data-processing","title":"Comparing Two Categorical Features *(2026 guide)*","difficulty":"medium","question":"A data scientist wants to know whether `plan_type` and `region` (both categorical) are related. Which method is appropriate?","choices":{"A":"Pearson correlation of the raw strings","B":"A scatter plot of the two columns","C":"A box plot of `plan_type` per `region`","D":"A contingency table (`df.stat.crosstab(\"plan_type\", \"region\")`) and a chi-square test of independence"},"answer":"D","short":"For two categorical variables, a cross-tabulation of counts shows the joint distribution, and a chi-square test (e.g. `pyspark.ml.stat.ChiSquareTest` on indexed columns) tests whether they are independent. A grouped/stacked bar chart visualises it.","explanation":"Correlation and scatter plots need numeric values; box plots compare a continuous feature across categories.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"06-data-processing-q010","bank":"praticas","n":73,"domain":"data-processing","title":"Mean vs Median Imputation *(2026 guide)*","difficulty":"medium","question":"`annual_income` is right-skewed with a handful of extremely high earners, and 8 % of its values are missing. Which imputation is most appropriate?","choices":{"A":"Mean, because it uses every value","B":"Median, because it is robust to the skew and outliers","C":"Mode, because income is continuous","D":"Zero, because missing income means no income"},"answer":"B","short":"Extreme earners pull the mean upward, so mean imputation would assign unrealistically high incomes. The median is robust to skew and outliers. Mean suits roughly symmetric continuous data; mode suits categorical or discrete data.","explanation":"Filling zero invents information that is probably wrong. In Spark: `Imputer(strategy=\"median\")`, fitted on the training split.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"06-data-processing-q011","bank":"praticas","n":74,"domain":"data-processing","title":"Imputing a String Category *(2026 guide)*","difficulty":"easy","question":"The string column `preferred_channel` (email / sms / app) has missing values. Which imputation strategy fits this feature?","choices":{"A":"Mode — fill with the most frequent category","B":"Mean of the column","C":"Median of the column","D":"Linear interpolation between neighbouring rows"},"answer":"A","short":"For a categorical feature, the most frequent value (mode) is the standard simple imputation; mean and median are undefined for strings.","explanation":"Note that Spark's `Imputer` only accepts numeric columns, so for a string column compute the most frequent value and use `fillna({\"preferred_channel\": value})` (or add an explicit \"unknown\" level).","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"06-data-processing-q012","bank":"praticas","n":75,"domain":"data-processing","title":"Spark Imputer Strategies *(2026 guide)*","difficulty":"easy","question":"Which values does `pyspark.ml.feature.Imputer` accept for `strategy`?","choices":{"A":"`\"mean\"` and `\"median\"` only","B":"`\"mean\"`, `\"median\"`, and `\"constant\"`","C":"`\"mean\"` (default), `\"median\"`, and `\"mode\"`","D":"`\"ffill\"` and `\"bfill\"`"},"answer":"C","short":"`Imputer` supports `mean` (the default), `median`, and `mode`, computed after filtering out missing values; nulls (and `NaN` by default) are treated as missing. Input columns must be numeric.","explanation":"`constant` is a scikit-learn `SimpleImputer` strategy; forward/backward fill are pandas methods.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"06-data-processing-q013","bank":"praticas","n":76,"domain":"data-processing","title":"One-Hot Encoding a High-Cardinality Feature *(2026 guide)*","difficulty":"medium","question":"A logistic regression model will use `zip_code`, which has about 40,000 distinct values. Why is one-hot encoding a poor choice here?","choices":{"A":"`OneHotEncoder` cannot process more than 100 categories","B":"It creates a huge, very sparse feature space that adds memory cost and overfitting risk; target/frequency encoding or hashing is usually better","C":"Logistic regression cannot use binary features","D":"One-hot encoding makes `zip_code` ordinal"},"answer":"B","short":"One column per level means ~40,000 sparse columns with few observations each — expensive and prone to overfitting. High-cardinality features are better handled with target or frequency encoding (fitted on training data only), hashing, or grouping rare levels.","explanation":"There is no 100-category limit, linear models use binary indicators routinely, and one-hot encoding removes order rather than adding it.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"06-data-processing-q014","bank":"praticas","n":77,"domain":"data-processing","title":"When One-Hot Encoding Is Appropriate *(2026 guide)*","difficulty":"medium","question":"In which situation is one-hot encoding most appropriate?","choices":{"A":"A nominal feature with 5 unordered levels feeding a linear regression model","B":"An ordinal feature (`small` < `medium` < `large`) whose order matters","C":"A `user_id` column with 2 million distinct values","D":"A continuous `temperature` feature"},"answer":"A","short":"Linear and distance-based models treat numbers as magnitudes, so a nominal feature with a few levels should become indicator columns (`StringIndexer` → `OneHotEncoder`).","explanation":"Ordinal features keep their order with an ordinal mapping, very high-cardinality IDs need other encodings, and continuous features are not one-hot encoded. Tree-based models often do not need one-hot encoding at all.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"06-data-processing-q015","bank":"praticas","n":78,"domain":"data-processing","title":"Log Transform with Zeros *(2026 guide)*","difficulty":"medium","question":"`num_reviews` is right-skewed, spans several orders of magnitude, and contains many zeros. Which transformation compresses the tail without failing on zeros?","choices":{"A":"`F.log(\"num_reviews\")`","B":"`F.sqrt(F.col(\"num_reviews\") * -1)`","C":"`F.log1p(\"num_reviews\")`, i.e. log(1 + x)","D":"Min-max scaling to [0, 1]"},"answer":"C","short":"A log transform suits positive, right-skewed values spanning orders of magnitude, but log(0) is undefined. `log1p` computes log(1 + x), so zeros map to 0 while large values are still compressed.","explanation":"The square root of a negative number is invalid, and min-max scaling rescales the range without reducing skew. If you log-transform a **target**, exponentiate the predictions (`expm1` after `log1p`) before reporting metrics.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"07-model-development-q001","bank":"praticas","n":79,"domain":"model-development","title":"Interpretable Algorithm Choice *(2026 guide)*","difficulty":"medium","question":"A lender must explain to a regulator how each input affects every approve/decline decision. Which algorithm is the most appropriate starting point?","choices":{"A":"Logistic regression","B":"k-means clustering","C":"A deep neural network with many hidden layers","D":"Linear regression on the approve/decline label"},"answer":"A","short":"Approve/decline is binary classification, and logistic regression's coefficients explain each feature's effect on the log-odds — ideal when interpretability is required.","explanation":"k-means is unsupervised, a deep network is hard to explain, and linear regression is meant for continuous targets.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"07-model-development-q002","bank":"praticas","n":80,"domain":"model-development","title":"Non-Linear Tabular Regression *(2026 guide)*","difficulty":"medium","question":"A team predicts delivery time (minutes) from tabular features with strong non-linear effects and interactions. Interpretability is secondary. Which algorithm family is the best first choice?","choices":{"A":"Logistic regression","B":"Gradient-boosted tree regression (e.g. `GBTRegressor`, XGBoost, LightGBM)","C":"k-means clustering","D":"Naive Bayes"},"answer":"B","short":"The target is continuous (regression), and tree ensembles capture non-linear effects and interactions without manual feature crosses.","explanation":"Logistic regression and Naive Bayes are classifiers, and k-means is unsupervised.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"07-model-development-q003","bank":"praticas","n":81,"domain":"model-development","title":"Where to Oversample *(2026 guide)*","difficulty":"hard","question":"Only 5 % of rows are fraud. A data scientist plans to oversample the fraud class. At which point should oversampling be applied?","choices":{"A":"Before splitting, to the whole dataset, so every split is balanced","B":"To the test set only, so evaluation is fair","C":"To the training split only, after splitting; validation and test keep the real class distribution","D":"To the validation set only, so tuning sees more fraud"},"answer":"C","short":"Resampling changes the data the model **learns** from; evaluation must reflect reality. Oversampling before the split leaks duplicated minority rows into validation/test and inflates metrics. (AutoML follows the same rule: it balances only the training split.)","explanation":"","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"07-model-development-q004","bank":"praticas","n":82,"domain":"model-development","title":"Class Weights in Spark ML *(2026 guide)*","difficulty":"medium","question":"How do you make a Spark ML `LogisticRegression` penalise errors on the minority class more heavily?","choices":{"A":"Add a weight column (higher for minority rows) and set `weightCol` on the estimator","B":"Set `classWeight=\"balanced\"` on `LogisticRegression`","C":"Add a `StandardScaler` stage before the model","D":"Increase `maxIter`"},"answer":"A","short":"Spark ML estimators such as `LogisticRegression` accept `weightCol`; giving minority rows a larger weight is cost-sensitive learning. `class_weight=\"balanced\"` is the scikit-learn equivalent — Spark's `LogisticRegression` has no `classWeight` parameter.","explanation":"Scaling and more iterations do not address imbalance.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"07-model-development-q005","bank":"praticas","n":83,"domain":"model-development","title":"Is Imputer an Estimator? *(2026 guide)*","difficulty":"easy","question":"In Spark ML, what kind of pipeline stage is `Imputer`?","choices":{"A":"A Transformer — it only has `transform()`","B":"An Evaluator","C":"An Estimator — `fit()` learns the fill values and returns an `ImputerModel`","D":"It cannot be used inside a `Pipeline`"},"answer":"C","short":"Anything that must learn from data is an Estimator. `Imputer.fit(df)` computes the mean/median/mode and returns an `ImputerModel` (a Transformer). `StringIndexer`, `OneHotEncoder`, `StandardScaler`, and every learning algorithm are Estimators too; `VectorAssembler`, `Bucketizer`, and `SQLTransformer` are Transformers.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"07-model-development-q006","bank":"praticas","n":84,"domain":"model-development","title":"Leakage in a Training Pipeline *(2026 guide)*","difficulty":"medium","question":"A data scientist fits `StandardScaler` on the full dataset, then splits into train and test and trains a model. What is wrong, and what is the fix?","choices":{"A":"Nothing — scaling statistics are harmless","B":"Test-set statistics leak into training; split first, then fit a `Pipeline` (scaler + model) on the training data and only `transform` the test data","C":"The scaler should be fitted on the test set only","D":"`StandardScaler` must always come after the model in a `Pipeline`"},"answer":"B","short":"Fitting any Estimator (scaler, imputer, encoder) on data that includes the test set leaks information into training. Split first, fit the whole `Pipeline` on the training split, and apply the fitted `PipelineModel` to validation/test data.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"07-model-development-q007","bank":"praticas","n":85,"domain":"model-development","title":"What fmin Optimises *(2026 guide)*","difficulty":"medium","question":"A Hyperopt objective returns validation accuracy, and `fmin` keeps choosing the *worst* hyperparameters. What should the objective return instead?","choices":{"A":"`{\"loss\": accuracy, \"status\": STATUS_OK}`","B":"`{\"accuracy\": accuracy}`","C":"`{\"loss\": -accuracy, \"status\": STATUS_OK}` (or `1 - accuracy`)","D":"Nothing — `fmin` reads metrics from MLflow"},"answer":"C","short":"`fmin` **minimises** the `loss` returned by the objective. To maximise a score, return its negative (or 1 − score). Loss-type metrics such as RMSE or log loss can be returned as-is.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"07-model-development-q008","bank":"praticas","n":86,"domain":"model-development","title":"Bayesian Search in Hyperopt *(2026 guide)*","difficulty":"easy","question":"Which Hyperopt `algo` performs Bayesian (adaptive) optimisation, choosing each trial based on earlier results?","choices":{"A":"`rand.suggest`","B":"`grid.suggest`","C":"`SparkTrials`","D":"`tpe.suggest`"},"answer":"D","short":"`tpe.suggest` (Tree-structured Parzen Estimator) uses completed trials to propose promising regions — Bayesian search. `rand.suggest` is random search; Hyperopt has no `grid.suggest`. `SparkTrials` controls *where* trials run, not *how* they are chosen.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"07-model-development-q009","bank":"praticas","n":87,"domain":"model-development","title":"Parallelising Single-Node Tuning *(2026 guide)*","difficulty":"medium","question":"A scikit-learn random forest trains on a single machine. The team wants Hyperopt to run eight trials at a time across an eight-worker cluster. What should they pass to `fmin`?","choices":{"A":"`trials=SparkTrials(parallelism=8)`","B":"`trials=Trials()`","C":"`algo=rand.suggest` with `max_evals=8`","D":"Wrap the model in Spark ML `CrossValidator(parallelism=8)`"},"answer":"A","short":"`SparkTrials` \"is designed to parallelize computations for single-machine ML models such as scikit-learn\": each trial runs on a worker, up to `parallelism` at once. `Trials()` runs sequentially on the driver, the algorithm choice does not add parallelism, and `CrossValidator` tunes Spark ML estimators, not scikit-learn models.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"07-model-development-q010","bank":"praticas","n":88,"domain":"model-development","title":"SparkTrials with Spark MLlib *(2026 guide)*","difficulty":"hard","question":"A data scientist uses Hyperopt to tune a Spark ML `GBTClassifier` on a 500 GB table. Which `trials` object is recommended?","choices":{"A":"`SparkTrials`, because the data is large","B":"The default `Trials`, because MLlib already distributes model training across the cluster","C":"`SparkTrials(parallelism=1)` only","D":"Hyperopt cannot tune MLlib models"},"answer":"B","short":"For distributed algorithms such as Spark MLlib, use the default `Trials` class: each trial is already a distributed Spark job. `SparkTrials` is for single-machine models. (Platform note: Hyperopt is no longer included in Databricks Runtime ML after 16.4 LTS ML; the docs recommend Optuna or Ray Tune for new work.)","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"07-model-development-q011","bank":"praticas","n":89,"domain":"model-development","title":"Cost of Grid Search *(2026 guide)*","difficulty":"medium","question":"Which statement about grid search is true?","choices":{"A":"Its cost grows with the **product** of the number of values per hyperparameter, so adding parameters quickly multiplies the number of models","B":"It learns from previous trials to choose the next combination","C":"It always finds a better optimum than random search for the same budget","D":"It samples a fixed number of random combinations"},"answer":"A","short":"Grid search is exhaustive: 4 values × 4 values × 5 values = 80 combinations, multiplied again by the number of CV folds. Bayesian search learns from previous trials, random search samples a fixed number of combinations, and random search often matches grid search with far fewer trials when only some parameters matter.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"07-model-development-q012","bank":"praticas","n":90,"domain":"model-development","title":"Counting Models in a Cross-Validated Grid *(2026 guide)*","difficulty":"medium","question":"A `ParamGridBuilder` has `regParam` = [0.01, 0.1, 1.0], `elasticNetParam` = [0.0, 0.5], and `maxIter` = [50, 100]. It is used with `CrossValidator(numFolds=4)`. How many models are fitted **during the search** (not counting the final refit)?","choices":{"A":"12","B":"16","C":"48","D":"19"},"answer":"C","short":"The grid has 3 × 2 × 2 = 12 combinations, and 4-fold CV fits 4 models per combination: 12 × 4 = 48. `CrossValidator` then refits the best combination once on the full training data (49 in total).","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"07-model-development-q013","bank":"praticas","n":91,"domain":"model-development","title":"Downside of Cross-Validation *(2026 guide)*","difficulty":"easy","question":"Compared with a single train-validation split, what is the main downside of k-fold cross-validation?","choices":{"A":"It uses less of the data for validation","B":"It trains k times as many models, so it costs more time and compute","C":"It cannot be used with Spark ML pipelines","D":"It produces higher-variance estimates"},"answer":"B","short":"k-fold CV trains and evaluates k models per combination, giving a lower-variance, more reliable estimate (every row is validated once) at roughly k times the cost. `TrainValidationSplit` is cheaper but noisier. CV works with Spark ML via `CrossValidator`.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"07-model-development-q014","bank":"praticas","n":92,"domain":"model-development","title":"Metric for Costly False Negatives *(2026 guide)*","difficulty":"medium","question":"In a disease-screening model, missing a sick patient is far worse than flagging a healthy one for a follow-up test. Which metric should drive model selection?","choices":{"A":"Precision","B":"Accuracy","C":"R²","D":"Recall"},"answer":"D","short":"Recall = TP / (TP + FN) measures how many actual positives are found, so it directly penalises missed patients. Precision matters when false positives are costly, accuracy misleads on imbalanced data, and R² is a regression metric.","explanation":"","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"07-model-development-q015","bank":"praticas","n":93,"domain":"model-development","title":"RMSE vs MAE *(2026 guide)*","difficulty":"medium","question":"A forecasting team wants an error metric in dollars that is **not** dominated by a few very large misses. Which metric should they use?","choices":{"A":"RMSE","B":"MAE","C":"MSE","D":"ROC AUC"},"answer":"B","short":"MAE averages absolute errors, so every dollar of error counts equally and outliers do not dominate. RMSE and MSE square errors, which emphasises large misses (useful when big misses are especially costly). ROC AUC is a classification metric.","explanation":"","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"07-model-development-q016","bank":"praticas","n":94,"domain":"model-development","title":"Evaluating a Log-Transformed Target *(2026 guide)*","difficulty":"medium","question":"A model was trained on `log(price)`. The team reports an RMSE of 0.21 computed on the model's raw predictions and the log labels. Management wants the error in dollars. What should be done?","choices":{"A":"Report 0.21 dollars — RMSE is unit-free","B":"Multiply 0.21 by the mean price","C":"Retrain on raw price, because log targets cannot be evaluated","D":"Exponentiate the predictions (e.g. `F.exp(\"prediction\")`) and compute RMSE against the original `price` column"},"answer":"D","short":"Predictions from a log-target model are in log space. Convert them back with `exp` (or `expm1` after `log1p`) and compute metrics against the original labels so the numbers mean something in dollars. RMSE is in the target's units, so 0.21 is in log units. Log targets are fine to use; they just have to be undone before evaluation and interpretation.","explanation":"","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"07-model-development-q017","bank":"praticas","n":95,"domain":"model-development","title":"Diagnosing Underfitting *(2026 guide)*","difficulty":"medium","question":"A model's error is high on **both** the training and validation sets, and the two are similar. What is happening, and what should the data scientist try?","choices":{"A":"High variance — reduce model complexity","B":"High bias (underfitting) — increase model complexity or add more informative features","C":"Data leakage — remove the validation set","D":"The model is well fitted — deploy it"},"answer":"B","short":"High error everywhere means the model is too simple to capture the pattern (high bias). Increase capacity (deeper trees, more features, less regularisation). High variance would show **low** training error with much higher validation error.","explanation":"","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"07-model-development-q018","bank":"praticas","n":96,"domain":"model-development","title":"Choosing Tree Depth *(2026 guide)*","difficulty":"hard","question":"As `maxDepth` increases from 2 to 20, training error falls steadily. Validation error falls until depth 8, then rises. Which conclusion is correct?","choices":{"A":"Depth 20 is best because training error is lowest","B":"Depth 2 is best because the model is simplest","C":"Depth around 8 balances bias and variance; deeper trees overfit (high variance)","D":"The validation set is broken because its error should keep falling"},"answer":"C","short":"More complexity lowers bias but raises variance. The best setting minimises **validation** error (here around depth 8). Beyond that, the model memorises training noise: training error keeps falling while validation error rises — classic overfitting.","explanation":"","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"08-model-deployment-q001","bank":"praticas","n":97,"domain":"model-deployment","title":"Choosing Streaming Inference *(2026 guide)*","difficulty":"medium","question":"Sensor readings arrive continuously from thousands of machines. Each reading must be scored for anomalies within seconds and the result written to a Delta table for an operations dashboard. No application waits for an individual prediction. Which serving approach fits best?","choices":{"A":"Nightly batch inference","B":"A real-time Model Serving endpoint called once per reading","C":"Streaming inference on the incoming data","D":"Manual scoring in a notebook when the dashboard is opened"},"answer":"C","short":"Continuously arriving data that must be scored within seconds and stored is the streaming use case — apply the model as a Spark UDF to a stream (for example in a Delta Live Tables pipeline).","explanation":"Nightly batch is too slow, and a request/response endpoint adds per-call overhead when no caller is waiting.","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"08-model-deployment-q002","bank":"praticas","n":98,"domain":"model-deployment","title":"Choosing Real-Time Inference *(2026 guide)*","difficulty":"easy","question":"A mobile app shows a personalised price quote while the user waits on the checkout screen. Which serving approach is required?","choices":{"A":"Real-time inference behind a Model Serving REST endpoint","B":"Weekly batch inference","C":"Streaming inference into a Delta table","D":"Exporting predictions to a CSV file each night"},"answer":"A","short":"When a caller needs the prediction inside the request (milliseconds), use a real-time endpoint. Batch and file exports cannot react to a new request, and streaming writes results to tables rather than answering a caller.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"08-model-deployment-q003","bank":"praticas","n":99,"domain":"model-deployment","title":"Choosing Batch Inference *(2026 guide)*","difficulty":"easy","question":"Every Monday a retention team needs a churn-risk list for 2 million customers. Nobody needs individual predictions in real time. Which approach is most appropriate and cost-effective?","choices":{"A":"An always-on GPU serving endpoint queried once per customer","B":"A scheduled batch inference job that scores all customers and writes a table","C":"A continuously running streaming pipeline","D":"A real-time endpoint with scale-to-zero disabled"},"answer":"B","short":"Scheduled scoring of a whole population with no latency requirement is batch inference — the simplest and cheapest option. Endpoints and streaming pipelines add always-on infrastructure for latency the workload does not need.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"08-model-deployment-q004","bank":"praticas","n":100,"domain":"model-deployment","title":"Batch Inference with pandas *(2026 guide)*","difficulty":"medium","question":"A model registered as `ml.sales.forecaster` must score a 40,000-row table once a day; the data easily fits on the driver. What is the simplest correct approach?","choices":{"A":"Create a serving endpoint and send one HTTP request per row","B":"Build a streaming pipeline over the table","C":"`model = mlflow.pyfunc.load_model(\"models:/ml.sales.forecaster@champion\")`, then `model.predict(df.toPandas()[features])`","D":"`mlflow.pyfunc.spark_udf(...)` is mandatory for any registered model"},"answer":"C","short":"For small data, load the model as a generic `pyfunc` and call `predict` on a pandas DataFrame. Endpoints and streaming add unnecessary infrastructure, and `spark_udf` is the tool for data too large for one machine, not a requirement.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"08-model-deployment-q005","bank":"praticas","n":101,"domain":"model-deployment","title":"Why spark_udf Scales *(2026 guide)*","difficulty":"medium","question":"Why does `mlflow.pyfunc.spark_udf` handle 300 million rows when `load_model(...).predict(df.toPandas())` fails?","choices":{"A":"`spark_udf` uses a GPU automatically","B":"`spark_udf` sends rows to a serving endpoint","C":"`spark_udf` samples 1 % of the rows","D":"`spark_udf` ships the model to the workers and scores partitions in parallel as pandas batches, while `toPandas()` collects every row to the driver"},"answer":"D","short":"`spark_udf` wraps the model as a Spark UDF, so each worker loads the model once and scores its partitions in pandas batches. `toPandas()` pulls the entire dataset into driver memory and can run out of memory. It neither uses GPUs automatically, calls endpoints, nor samples.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"08-model-deployment-q006","bank":"praticas","n":102,"domain":"model-deployment","title":"Deploying a Custom Model *(2026 guide)*","difficulty":"medium","question":"An endpoint must return a churn probability **and** a yes/no flag based on a business threshold, using preprocessing that is not part of the scikit-learn model. How should this be deployed?","choices":{"A":"Subclass `mlflow.pyfunc.PythonModel` with a `predict` method that applies the preprocessing and threshold, log it with `mlflow.pyfunc.log_model` (with an input example), register it in Unity Catalog, and serve that version from a Model Serving endpoint","B":"Deploy the raw scikit-learn model and ask every client to apply the threshold","C":"Write the logic in a SQL view and point the endpoint at the view","D":"Upload the notebook directly to Model Serving"},"answer":"A","short":"A custom `pyfunc` model packages arbitrary Python logic with the model so the endpoint returns exactly what clients need. Unity Catalog requires a signature (inferred from the input example). Pushing logic to clients duplicates it, and endpoints serve registered MLflow models, not views or notebooks.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"08-model-deployment-q007","bank":"praticas","n":103,"domain":"model-deployment","title":"Request Format *(2026 guide)*","difficulty":"easy","question":"Which JSON key is the recommended way to send tabular input to a custom model serving endpoint?","choices":{"A":"`\"rows\"`","B":"`\"spark_dataframe\"`","C":"`\"dataframe_split\"` (with `columns` and `data`)","D":"`\"csv\"`"},"answer":"C","short":"Endpoints accept `dataframe_split` (recommended, pandas split orientation), `dataframe_records`, and the tensor formats `instances` / `inputs`. `rows`, `spark_dataframe`, and `csv` are not accepted keys.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"08-model-deployment-q008","bank":"praticas","n":104,"domain":"model-deployment","title":"Endpoint URL *(2026 guide)*","difficulty":"easy","question":"A Model Serving endpoint is named `churn-model`. Which URL is used to query it over REST?","choices":{"A":"`https://<workspace>/api/2.0/mlflow/predict/churn-model`","B":"`https://<workspace>/serving-endpoints/churn-model/invocations`","C":"`https://<workspace>/models/churn-model/score`","D":"`https://<workspace>/serving/churn-model/predict`"},"answer":"B","short":"The invocation URL is `https://<databricks-instance>/serving-endpoints/<endpoint-name>/invocations`, called with a POST and a JSON body. From Python, `mlflow.deployments.get_deploy_client(\"databricks\").predict(endpoint=..., inputs=...)` wraps the same call.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"08-model-deployment-q009","bank":"praticas","n":105,"domain":"model-deployment","title":"Splitting Traffic Between Versions *(2026 guide)*","difficulty":"medium","question":"The team wants 80 % of real-time requests to keep going to version 7 and 20 % to go to version 8 for an A/B comparison. What is the recommended setup?","choices":{"A":"Create two endpoints and have each client pick one at random","B":"Give version 8 the `challenger` alias; Model Serving then routes 20 % automatically","C":"Tag version 8 with `traffic=20`","D":"Serve both versions as served entities on one endpoint and set `traffic_config` routes of 80 and 20"},"answer":"D","short":"One endpoint can host several served entities, and `traffic_config.routes` assigns each a `traffic_percentage` (summing to 100). Aliases and tags are registry metadata; they do not route traffic. Two endpoints push routing logic onto every client.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"08-model-deployment-q010","bank":"praticas","n":106,"domain":"model-deployment","title":"Streaming Inference with Delta Live Tables *(2026 guide)*","difficulty":"medium","question":"How is streaming inference performed with Delta Live Tables?","choices":{"A":"Delta Live Tables has a built-in `MODEL` table type that trains and scores automatically","B":"Load the registered model as a Spark UDF with `mlflow.pyfunc.spark_udf` and apply it to the streaming input inside a Delta Live Tables table definition","C":"Delta Live Tables can only run batch pipelines, so streaming inference is impossible","D":"Delta Live Tables forwards every row to the workspace's default serving endpoint"},"answer":"B","short":"The model is loaded once as a Spark UDF and applied to `spark.readStream` data in a pipeline table; the pipeline manages checkpoints, retries, and autoscaling. There is no `MODEL` table type, pipelines support streaming tables, and nothing forwards rows to an endpoint automatically.","explanation":"Platform note: Delta Live Tables is now called Lakeflow Spark Declarative Pipelines (`from pyspark import pipelines as dp`; `import dlt` still works).","lesson":"04-model-deployment/02-streaming-inference","related":null},{"id":"08-model-deployment-q011","bank":"praticas","n":107,"domain":"model-deployment","title":"Scale to Zero *(2026 guide)*","difficulty":"easy","question":"A development endpoint has `scale_to_zero_enabled=True`. What trade-off does this create?","choices":{"A":"Lower cost when idle, but the first request after an idle period has cold-start latency","B":"Higher accuracy, but lower throughput","C":"The endpoint cannot be queried from Python","D":"Requests are dropped while the endpoint is idle"},"answer":"A","short":"Scaling to zero releases compute when there is no traffic, saving cost, but the next request waits while compute starts again. It has no effect on accuracy or client libraries, and requests are served once compute is back. Latency-critical production endpoints usually disable it.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-1-q001","bank":"simulado-1","n":1,"domain":"databricks-machine-learning","title":"Which pre-installed library distinguishes Databricks Runtime for Machine Learning from…","difficulty":"easy","question":"Which pre-installed library distinguishes Databricks Runtime for Machine Learning from the standard Databricks Runtime?","choices":{"A":"Apache Spark","B":"Delta Lake connector","C":"MLflow","D":"JDBC driver"},"answer":"C","short":"Databricks Runtime for ML pre-installs ML-specific libraries including MLflow, TensorFlow, PyTorch, and scikit-learn. Apache Spark and Delta Lake are included in the standard runtime. JDBC drivers are available in both runtimes.","explanation":"","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"ml-associate-mock-1-q002","bank":"simulado-1","n":2,"domain":"databricks-machine-learning","title":"What does Databricks AutoML produce after completing a classification experiment?","difficulty":"easy","question":"What does Databricks AutoML produce after completing a classification experiment?","choices":{"A":"A single deployable model binary","B":"An MLflow experiment with one run per algorithm trial, plus a generated best-model notebook","C":"A Delta table of feature importances","D":"A REST endpoint ready for production traffic"},"answer":"B","short":"AutoML creates an MLflow experiment and logs each algorithm trial as a separate run. It also generates an editable Python notebook for the best-performing model that the data scientist can customize. It does not automatically deploy the model or create Delta tables.","explanation":"","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"ml-associate-mock-1-q003","bank":"simulado-1","n":3,"domain":"databricks-machine-learning","title":"A data scientist wants to use AutoML to forecast future sales. Which AutoML task type…","difficulty":"easy","question":"A data scientist wants to use AutoML to forecast future sales. Which AutoML task type should they select?","choices":{"A":"Regression","B":"Classification","C":"Forecasting","D":"Time Series"},"answer":"C","short":"Databricks AutoML supports three task types: classification, regression, and forecasting. Forecasting is specifically designed for time-series prediction problems. \"Time Series\" is not a separate AutoML task type.","explanation":"","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"ml-associate-mock-1-q004","bank":"simulado-1","n":4,"domain":"databricks-machine-learning","title":"Which Databricks Runtime is required to use GPU-accelerated deep learning with CUDA?","difficulty":"easy","question":"Which Databricks Runtime is required to use GPU-accelerated deep learning with CUDA?","choices":{"A":"Databricks Runtime (standard)","B":"Databricks Runtime ML","C":"Databricks Runtime ML GPU","D":"Databricks Runtime Photon"},"answer":"C","short":"Databricks Runtime ML GPU includes CUDA, cuDNN, NCCL, and GPU-optimized versions of PyTorch and TensorFlow. The standard ML Runtime does not include GPU drivers or CUDA libraries.","explanation":"","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"ml-associate-mock-1-q005","bank":"simulado-1","n":5,"domain":"databricks-machine-learning","title":"A data scientist runs AutoML on a regression problem and wants to understand which…","difficulty":"medium","question":"A data scientist runs AutoML on a regression problem and wants to understand which features drive the best model's predictions. What does AutoML provide for this purpose?","choices":{"A":"A Shapley value table written automatically to Unity Catalog","B":"A generated best-trial notebook with a SHAP feature-importance section that can be enabled (it is off by default)","C":"A PDF report summarizing the model's performance","D":"An automatic A/B test comparing the best model to the baseline"},"answer":"B","short":"AutoML's generated notebooks include a Feature importance section that computes Shapley values with SHAP. Because it is memory-intensive it is off by default — set `shap_enabled = True` and rerun the notebook.","explanation":"AutoML writes no SHAP table, produces no PDF report, and does not run A/B tests.","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"ml-associate-mock-1-q006","bank":"simulado-1","n":6,"domain":"databricks-machine-learning","title":"What is the primary benefit of using Databricks AutoML over manually training multiple…","difficulty":"medium","question":"What is the primary benefit of using Databricks AutoML over manually training multiple models?","choices":{"A":"AutoML models cannot be overfitted because they use ensemble methods","B":"AutoML eliminates the need to write any Python code for the entire ML workflow","C":"AutoML reduces the time to a baseline model by automatically trying multiple algorithms and hyperparameters","D":"AutoML automatically deploys models to production without human review"},"answer":"C","short":"AutoML accelerates the path to a baseline model by systematically trying multiple algorithms and hyperparameter combinations, logging all results to MLflow. It does not eliminate coding entirely (data scientists still customize the generated notebooks), it can overfit on small datasets, and it does not automatically deploy to production.","explanation":"","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"ml-associate-mock-1-q007","bank":"simulado-1","n":7,"domain":"databricks-machine-learning","title":"What is the correct way to log a hyperparameter called learning_rate with value 0.01…","difficulty":"easy","question":"What is the correct way to log a hyperparameter called `learning_rate` with value `0.01` to the current MLflow run?","choices":{"A":"`mlflow.log_metric(\"learning_rate\", 0.01)`","B":"`mlflow.log_param(\"learning_rate\", 0.01)`","C":"`mlflow.log_artifact(\"learning_rate\", 0.01)`","D":"`mlflow.set_tag(\"learning_rate\", 0.01)`"},"answer":"B","short":"`mlflow.log_param()` is used for hyperparameters and configuration values (typically strings or numbers that describe how the model was configured). `mlflow.log_metric()` is for numeric performance measurements that can be tracked over time. `log_artifact()` saves files. `set_tag()` logs string metadata.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"ml-associate-mock-1-q008","bank":"simulado-1","n":8,"domain":"databricks-machine-learning","title":"A data scientist calls mlflow.autolog() at the start of a notebook and then trains a…","difficulty":"easy","question":"A data scientist calls `mlflow.autolog()` at the start of a notebook and then trains a scikit-learn `RandomForestClassifier`. What is automatically logged?","choices":{"A":"Only the trained model artifact","B":"The model's feature importances as a custom metric","C":"Parameters (n_estimators, max_depth, etc.), metrics (accuracy, f1, etc.), and the model artifact","D":"Parameters only — metrics must still be logged manually"},"answer":"C","short":"`mlflow.autolog()` with scikit-learn automatically captures estimator parameters (from `get_params()`), training metrics (via cross-validation if applicable), and logs the trained model as an artifact. Feature importances are sometimes logged as artifacts depending on the estimator type.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"ml-associate-mock-1-q009","bank":"simulado-1","n":9,"domain":"databricks-machine-learning","title":"A data scientist wants to find all runs in experiment ID 123 where val_loss is less…","difficulty":"medium","question":"A data scientist wants to find all runs in experiment ID `123` where `val_loss` is less than `0.5`. Which `search_runs` call is correct?","choices":{"A":"`mlflow.search_runs(experiment_ids=[\"123\"], filter_string=\"metrics.val_loss < 0.5\")`","B":"`mlflow.search_runs(experiment_id=\"123\", filter=\"val_loss < 0.5\")`","C":"`mlflow.search_runs(\"123\", metrics={\"val_loss\": \"<0.5\"})`","D":"`mlflow.find_runs(experiment_ids=[\"123\"], filter_string=\"metric.val_loss < 0.5\")`"},"answer":"A","short":"`mlflow.search_runs()` accepts `experiment_ids` (a list) and `filter_string` using `metrics.` prefix. `experiment_id` (singular) is not a valid parameter. `metrics` as a dictionary and `find_runs` do not exist in the MLflow Python API. The prefix must be `metrics.` (plural), not `metric.`.","explanation":"","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"ml-associate-mock-1-q010","bank":"simulado-1","n":10,"domain":"databricks-machine-learning","title":"A data scientist logs a metric accuracy at step 1 (0.72), step 2 (0.85), and step 3…","difficulty":"medium","question":"A data scientist logs a metric `accuracy` at step 1 (0.72), step 2 (0.85), and step 3 (0.91) within a single run. What does `mlflow.get_run(run_id).data.metrics[\"accuracy\"]` return?","choices":{"A":"0.72 (first logged value)","B":"A list of all three values: [0.72, 0.85, 0.91]","C":"0.91 (last logged value)","D":"The average: 0.827"},"answer":"C","short":"`run.data.metrics` returns a dictionary with the **last logged value** for each metric. To retrieve the full metric history, use `MlflowClient().get_metric_history(run_id, metric_key)`, which returns all logged values with their steps and timestamps.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"ml-associate-mock-1-q011","bank":"simulado-1","n":11,"domain":"databricks-machine-learning","title":"What is the best way to compare the val_accuracy of 20 MLflow runs from the same…","difficulty":"easy","question":"What is the best way to compare the `val_accuracy` of 20 MLflow runs from the same experiment in the Databricks UI?","choices":{"A":"Open each run individually and note the metric value","B":"Export all runs to a CSV and sort in Excel","C":"On the Experiments page, select all runs and click \"Compare\" to view parallel coordinates and scatter plots","D":"Use the Model Registry to compare version metrics"},"answer":"C","short":"The MLflow Experiments page allows selecting multiple runs and clicking \"Compare\" to generate visualizations including parallel coordinate plots, scatter plots, contour plots, and metric comparison tables. This is the intended workflow for comparing runs within an experiment.","explanation":"","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"ml-associate-mock-1-q012","bank":"simulado-1","n":12,"domain":"databricks-machine-learning","title":"A data scientist calls…","difficulty":"easy","question":"A data scientist calls `FeatureEngineeringClient().create_table(name=\"ml.features.users\", df=users_df)` without `primary_keys`. What happens?","choices":{"A":"The table is created with a default UUID primary key","B":"The call fails because `primary_keys` is a required argument","C":"The table is created successfully with no primary key","D":"A deprecation warning is shown but the table is still created"},"answer":"B","short":"`primary_keys` has no default in `FeatureEngineeringClient.create_table`. In Unity Catalog a feature table is a Delta table with a primary key; lookups, training sets, `score_batch`, and online publishing all rely on it.","explanation":"","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"ml-associate-mock-1-q013","bank":"simulado-1","n":13,"domain":"databricks-machine-learning","title":"A data engineer wants to add new rows and update existing rows of a Unity Catalog…","difficulty":"medium","question":"A data engineer wants to add new rows and update existing rows of a Unity Catalog feature table by primary key, leaving other rows unchanged. Which `FeatureEngineeringClient.write_table()` mode should they use?","choices":{"A":"`mode=\"append\"`","B":"`mode=\"overwrite\"`","C":"`mode=\"merge\"`","D":"`mode=\"upsert\"`"},"answer":"C","short":"`mode=\"merge\"` upserts by primary key: matching keys are updated, new keys inserted, and rows not in the DataFrame stay unchanged. It is the only (and default) `write_table` mode of `FeatureEngineeringClient`.","explanation":"To replace all data you would delete rows or recreate the table; `append` and `upsert` are not modes.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"ml-associate-mock-1-q014","bank":"simulado-1","n":14,"domain":"databricks-machine-learning","title":"A model trained on Unity Catalog feature tables was logged with fe.log_model(...). A…","difficulty":"medium","question":"A model trained on Unity Catalog feature tables was logged with `fe.log_model(...)`. A new DataFrame contains only `customer_id`. Which call retrieves the features and scores the batch?","choices":{"A":"`mlflow.pyfunc.load_model(model_uri).predict(entity_df)`","B":"`fe.score_batch(model_uri=model_uri, df=entity_df)`","C":"`fe.read_table(name=table_name).join(entity_df)`","D":"`mlflow.pyfunc.spark_udf(spark, model_uri)(entity_df)`"},"answer":"B","short":"`FeatureEngineeringClient.score_batch` reads the feature metadata packaged by `fe.log_model`, joins the features to the keys, and applies the model — identical feature definitions to training.","explanation":"A plain pyfunc model does not know how to fetch features, `read_table(...).join(...)` only fetches features, and a UDF is applied to columns, not to a whole DataFrame.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"ml-associate-mock-1-q015","bank":"simulado-1","n":15,"domain":"databricks-machine-learning","title":"A data scientist has run_id xyz789 and logged a model with artifact_path=\"classifier\".…","difficulty":"easy","question":"A data scientist has run_id `xyz789` and logged a model with `artifact_path=\"classifier\"`. With the registry URI set to `databricks-uc`, which call registers it as `ml.sales.purchase_predictor`?","choices":{"A":"`mlflow.register_model(\"classifier/xyz789\", \"ml.sales.purchase_predictor\")`","B":"`mlflow.register_model(\"runs:/xyz789/classifier\", \"ml.sales.purchase_predictor\")`","C":"`mlflow.register_model(\"artifacts:/xyz789/classifier\", \"ml.sales.purchase_predictor\")`","D":"`mlflow.register_model(\"runs:/xyz789/classifier\", \"purchase_predictor\")` with no catalog or schema"},"answer":"B","short":"A logged model is referenced as `runs:/<run_id>/<artifact_path>`, and Unity Catalog names are three-level `catalog.schema.model`.","explanation":"`artifacts:/` is not a valid scheme and a one-part name is not a Unity Catalog model name.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"ml-associate-mock-1-q016","bank":"simulado-1","n":16,"domain":"databricks-machine-learning","title":"Version 5 of the Unity Catalog model ml.finance.revenue_predictor has beaten the…","difficulty":"medium","question":"Version 5 of the Unity Catalog model `ml.finance.revenue_predictor` has beaten the current production version. Scoring jobs load `models:/ml.finance.revenue_predictor@champion`. What is the recommended way to promote version 5?","choices":{"A":"`MlflowClient().transition_model_version_stage(\"ml.finance.revenue_predictor\", 5, \"Production\")`","B":"Delete the old champion version so version 5 is the only one left","C":"`MlflowClient().set_registered_model_alias(\"ml.finance.revenue_predictor\", \"champion\", 5)`","D":"`MlflowClient().set_model_version_tag(\"ml.finance.revenue_predictor\", \"5\", \"champion\", \"true\")`"},"answer":"C","short":"In Unity Catalog, promotion moves an alias: pointing `champion` at version 5 makes every consumer of `@champion` use it without code changes.","explanation":"Stages belong to the legacy workspace registry and are not supported in UC; deleting versions is destructive; a tag is only metadata.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"ml-associate-mock-1-q017","bank":"simulado-1","n":17,"domain":"databricks-machine-learning","title":"A team's model training takes 20 minutes, and its data scientists cannot read…","difficulty":"medium","question":"A team's model training takes 20 minutes, and its data scientists cannot read production data from the development workspace. The company uses Git and CI/CD. Which deployment pattern does Databricks recommend here?","choices":{"A":"Deploy models: train in dev and copy the model version to production","B":"Deploy code: promote the reviewed training code so the model is retrained in production","C":"Train in staging on a sample and promote that artifact","D":"Skip staging and register directly into the production catalog from dev"},"answer":"B","short":"Databricks recommends **deploy code** in most situations, and it is the pattern that works when production data is restricted: the training code moves through dev → staging → prod and trains where the data lives.","explanation":"Deploy models fits very expensive or hard-to-reproduce training, a single workspace, or no CI/CD — none of which applies here.","lesson":"01-databricks-machine-learning/08-mlops-strategy","related":null},{"id":"ml-associate-mock-1-q018","bank":"simulado-1","n":18,"domain":"databricks-machine-learning","title":"A recommendation endpoint must fetch a user's latest features in milliseconds by…","difficulty":"medium","question":"A recommendation endpoint must fetch a user's latest features in milliseconds by `user_id`, and the same features feed weekly retraining. Which design fits?","choices":{"A":"Read the offline Delta feature table with a full scan on every request","B":"Use the offline feature table for training and batch scoring, and publish it to an online store for low-latency lookups at serving time","C":"Keep the features only in an online store and train from it","D":"Hard-code the features into the model artifact"},"answer":"B","short":"Offline feature tables (Delta tables in Unity Catalog) serve training and batch scoring; an online store serves key-based millisecond lookups to real-time endpoints, where a model logged with `fe.log_model` can look features up automatically.","explanation":"","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"ml-associate-mock-1-q019","bank":"simulado-1","n":19,"domain":"data-processing","title":"A data scientist uses StringIndexer with handleInvalid=\"keep\". What happens when the…","difficulty":"medium","question":"A data scientist uses `StringIndexer` with `handleInvalid=\"keep\"`. What happens when the transformer encounters a category during test inference that was not seen during training?","choices":{"A":"An exception is raised and the pipeline halts","B":"The unseen category is mapped to index 0 (the most frequent category)","C":"The unseen category is assigned a new index at the end of the index range","D":"The row containing the unseen category is dropped from the output"},"answer":"C","short":"`handleInvalid=\"keep\"` instructs `StringIndexer` to assign unseen categories a reserved index equal to the number of distinct training categories (i.e., one beyond the existing range). This allows inference to continue without errors. The alternative `handleInvalid=\"error\"` raises an exception, and `handleInvalid=\"skip\"` drops the row.","explanation":"","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-1-q020","bank":"simulado-1","n":20,"domain":"data-processing","title":"Which call shows count, mean, stddev, min, the 25 %/50 %/75 % percentiles, and max for…","difficulty":"easy","question":"Which call shows count, mean, stddev, min, the 25 %/50 %/75 % percentiles, and max for every column of a Spark DataFrame `df`?","choices":{"A":"`df.describe()`","B":"`df.summary()`","C":"`df.stats()`","D":"`df.agg(\"*\")`"},"answer":"B","short":"`summary()` with no arguments returns count, mean, stddev, min, approximate quartiles, and max; `describe()` omits the percentiles.","explanation":"`df.stats()` does not exist and `agg(\"*\")` is invalid.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"ml-associate-mock-1-q021","bank":"simulado-1","n":21,"domain":"data-processing","title":"For session_minutes, Q1 = 10 and Q3 = 30. Using the 1.5 × IQR rule, which filter…","difficulty":"medium","question":"For `session_minutes`, Q1 = 10 and Q3 = 30. Using the 1.5 × IQR rule, which filter removes outliers?","choices":{"A":"`df.filter(F.col(\"session_minutes\").between(-20, 60))`","B":"`df.filter(F.col(\"session_minutes\").between(10, 30))`","C":"`df.filter(F.col(\"session_minutes\") <= 45)`","D":"`df.filter(F.col(\"session_minutes\").between(-5, 45))`"},"answer":"A","short":"IQR = 30 − 10 = 20, so the fences are 10 − 30 = −20 and 30 + 30 = 60.","explanation":"Keeping only Q1–Q3 would drop half the data; the other bounds use the wrong multiple.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"ml-associate-mock-1-q022","bank":"simulado-1","n":22,"domain":"data-processing","title":"A roughly normal feature should be cleaned of extreme values using its mean and…","difficulty":"medium","question":"A roughly normal feature should be cleaned of extreme values using its mean and standard deviation. Which rule is the standard choice?","choices":{"A":"Keep values within the 5th–95th percentiles","B":"Keep values within μ ± 3σ","C":"Keep values within Q1 − 1.5·IQR and Q3 + 1.5·IQR","D":"Remove all values above the mean"},"answer":"B","short":"The standard-deviation (z-score) rule keeps values within k standard deviations of the mean, commonly k = 3, and suits roughly symmetric data.","explanation":"The IQR rule is the alternative for skewed data; percentile trimming and removing everything above the mean are not the standard-deviation method.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"ml-associate-mock-1-q023","bank":"simulado-1","n":23,"domain":"data-processing","title":"A data scientist wants to see the distribution shape (skew, multiple peaks) of the…","difficulty":"easy","question":"A data scientist wants to see the distribution shape (skew, multiple peaks) of the continuous feature `trip_distance`. Which plot is most appropriate?","choices":{"A":"A bar chart of counts per distinct value","B":"A pie chart","C":"A histogram or density plot","D":"A contingency table"},"answer":"C","short":"Histograms and density (KDE) plots show the distribution of a continuous feature; box plots add outliers and quartiles.","explanation":"Bar and pie charts suit categorical frequencies, and contingency tables compare two categorical variables.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"ml-associate-mock-1-q024","bank":"simulado-1","n":24,"domain":"data-processing","title":"Which method is appropriate for checking whether two categorical features, device_type…","difficulty":"medium","question":"Which method is appropriate for checking whether two categorical features, `device_type` and `subscription_tier`, are associated?","choices":{"A":"Pearson correlation of the string values","B":"A cross-tabulation of counts with a chi-square test of independence","C":"A scatter plot","D":"Computing the mean of each column"},"answer":"B","short":"A contingency table (`df.stat.crosstab`) shows the joint counts, and a chi-square test checks independence.","explanation":"Correlation, scatter plots, and means need numeric data.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"ml-associate-mock-1-q025","bank":"simulado-1","n":25,"domain":"data-processing","title":"house_price is right-skewed with a few very expensive properties, and some values are…","difficulty":"medium","question":"`house_price` is right-skewed with a few very expensive properties, and some values are missing. Which imputation is most appropriate?","choices":{"A":"Mean","B":"Median","C":"Mode","D":"The maximum value"},"answer":"B","short":"The median is robust to skew and outliers; the mean is pulled upward by the expensive properties.","explanation":"Mode suits categorical data, and the maximum would distort the feature.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-1-q026","bank":"simulado-1","n":26,"domain":"data-processing","title":"Which imputation strategy is appropriate for missing values in a categorical feature…","difficulty":"easy","question":"Which imputation strategy is appropriate for missing values in a categorical feature such as `browser`?","choices":{"A":"Mean","B":"Median","C":"Mode (most frequent value)","D":"Standard deviation"},"answer":"C","short":"Mean and median are undefined for categories; the most frequent value (or an explicit \"unknown\" level) is used.","explanation":"Spark's `Imputer` handles numeric columns only, so fill string columns with `fillna`.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-1-q027","bank":"simulado-1","n":27,"domain":"data-processing","title":"For which model is one-hot encoding a nominal feature with 4 levels most clearly…","difficulty":"medium","question":"For which model is one-hot encoding a nominal feature with 4 levels most clearly appropriate?","choices":{"A":"A random forest, which can split on indexed categories directly","B":"A linear regression, which would otherwise treat the index 0–3 as an ordered magnitude","C":"Any model, for a feature with 100,000 levels","D":"An ordinal feature whose order matters"},"answer":"B","short":"Linear and distance-based models interpret numeric codes as magnitudes, so nominal levels should become indicator columns.","explanation":"Trees often do not need one-hot encoding, very high-cardinality features need other encodings, and ordinal features should keep their order.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-1-q028","bank":"simulado-1","n":28,"domain":"model-development","title":"Which VectorAssembler parameter specifies the list of input columns to combine into a…","difficulty":"easy","question":"Which `VectorAssembler` parameter specifies the list of input columns to combine into a single feature vector?","choices":{"A":"`inputCol`","B":"`inputCols`","C":"`featureCols`","D":"`columns`"},"answer":"B","short":"`VectorAssembler` uses `inputCols` (plural) because it accepts a list of column names. Using `inputCol` (singular) will raise a `TypeError` because `inputCol` is a single-value parameter used by transformers like `StringIndexer` that operate on one column at a time.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-1-q029","bank":"simulado-1","n":29,"domain":"model-development","title":"A data scientist has a Pipeline with stages: StringIndexer, VectorAssembler,…","difficulty":"medium","question":"A data scientist has a `Pipeline` with stages: `StringIndexer`, `VectorAssembler`, `RandomForestClassifier`. They call `pipeline.fit(train_df)`. In what order do the stages execute?","choices":{"A":"`RandomForestClassifier` → `VectorAssembler` → `StringIndexer`","B":"All stages execute simultaneously in parallel","C":"`StringIndexer` → `VectorAssembler` → `RandomForestClassifier`","D":"The order depends on which stages are `Estimator` vs `Transformer`"},"answer":"C","short":"A `Pipeline` executes stages sequentially in the order they are listed. During `fit()`, each stage's `fit()` (for Estimators) or `transform()` (for Transformers) is called in order, passing the transformed DataFrame to the next stage.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-1-q030","bank":"simulado-1","n":30,"domain":"model-development","title":"After calling pipeline_model = pipeline.fit(train_df), a data scientist calls…","difficulty":"easy","question":"After calling `pipeline_model = pipeline.fit(train_df)`, a data scientist calls `predictions = pipeline_model.transform(test_df)`. What does `predictions` contain?","choices":{"A":"A trained `PipelineModel` object","B":"The `test_df` with new columns added by each stage's transformation","C":"Only the final model's predictions column","D":"A dictionary of metric values from the model evaluation"},"answer":"B","short":"`PipelineModel.transform(df)` passes the DataFrame through each stage's `transform()` method sequentially. The result is the input DataFrame with additional columns appended by each stage (e.g., `StringIndexer` adds an index column, `VectorAssembler` adds a features column, and the classifier adds `rawPrediction`, `probability`, and `prediction` columns).","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-1-q031","bank":"simulado-1","n":31,"domain":"model-development","title":"What is the default number of folds used by CrossValidator if numFolds is not specified?","difficulty":"easy","question":"What is the default number of folds used by `CrossValidator` if `numFolds` is not specified?","choices":{"A":"5","B":"10","C":"2","D":"3"},"answer":"D","short":"`CrossValidator` defaults to `numFolds=3`. This means the training data is split into 3 equal folds, and for each hyperparameter combination in the grid, the model is trained on 2 folds and evaluated on the remaining 1 fold, repeating 3 times.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-1-q032","bank":"simulado-1","n":32,"domain":"model-development","title":"A data scientist wants to search over maxDepth values of 5 and 10 for a…","difficulty":"medium","question":"A data scientist wants to search over `maxDepth` values of 5 and 10 for a `DecisionTreeClassifier` named `dt`. Which code correctly adds this to the parameter grid?","choices":{"A":"`ParamGridBuilder().addGrid(\"maxDepth\", [5, 10]).build()`","B":"`ParamGridBuilder().addGrid(dt.maxDepth, [5, 10]).build()`","C":"`ParamGridBuilder(dt.maxDepth=[5, 10]).build()`","D":"`ParamGridBuilder().add(dt, \"maxDepth\", [5, 10]).build()`"},"answer":"B","short":"`ParamGridBuilder().addGrid(estimator.param, [values]).build()` is the correct syntax. The first argument to `addGrid` must be the actual `Param` object from the estimator (e.g., `dt.maxDepth`), not a string. The constructor does not accept keyword arguments.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-1-q033","bank":"simulado-1","n":33,"domain":"model-development","title":"What is the key advantage of CrossValidator over TrainValidationSplit for…","difficulty":"medium","question":"What is the key advantage of `CrossValidator` over `TrainValidationSplit` for hyperparameter tuning?","choices":{"A":"`CrossValidator` is always faster because it uses more CPU cores","B":"`CrossValidator` provides more reliable performance estimates by using all data for both training and validation across multiple folds","C":"`CrossValidator` automatically selects the best algorithm, not just the best hyperparameters","D":"`CrossValidator` requires less memory because it processes one fold at a time"},"answer":"B","short":"`CrossValidator` uses k-fold cross-validation, ensuring every data point is used for validation exactly once across k experiments. This produces more reliable performance estimates than `TrainValidationSplit`, which uses a single random split and may produce high-variance estimates on small datasets.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-1-q034","bank":"simulado-1","n":34,"domain":"model-development","title":"Which class is an Estimator in Spark ML (requiring fit() to produce a fitted object)?","difficulty":"medium","question":"Which class is an `Estimator` in Spark ML (requiring `fit()` to produce a fitted object)?","choices":{"A":"`VectorAssembler`","B":"`Bucketizer`","C":"`Normalizer`","D":"`MinMaxScaler`"},"answer":"D","short":"`MinMaxScaler` is an `Estimator` that learns the minimum and maximum values of each feature during `fit()`. `VectorAssembler`, `Bucketizer`, and `Normalizer` are `Transformer` classes that apply deterministic transformations without learning from data.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-1-q035","bank":"simulado-1","n":35,"domain":"model-development","title":"A Pipeline contains a CrossValidator as its last stage. Which statement is true?","difficulty":"hard","question":"A Pipeline contains a `CrossValidator` as its last stage. Which statement is true?","choices":{"A":"`CrossValidator` cannot be used inside a `Pipeline`","B":"The `CrossValidator` is only applied to the last stage's estimator","C":"The entire preceding pipeline (all stages) is treated as the estimator inside `CrossValidator`","D":"`CrossValidator` automatically wraps all prior pipeline stages"},"answer":"C","short":"When the estimator passed to `CrossValidator` is a `Pipeline`, the entire pipeline (all stages) is fit and evaluated for each hyperparameter combination in each fold. This ensures that preprocessing stages fit only on training data within each fold, preventing data leakage.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-1-q036","bank":"simulado-1","n":36,"domain":"model-development","title":"A data scientist wants to apply feature scaling so that each numerical feature has…","difficulty":"easy","question":"A data scientist wants to apply feature scaling so that each numerical feature has zero mean and unit variance. Which Spark ML feature stage should they use?","choices":{"A":"`Normalizer`","B":"`StandardScaler`","C":"`MinMaxScaler`","D":"`MaxAbsScaler`"},"answer":"B","short":"`StandardScaler` standardizes features by removing the mean and scaling to unit variance (z-score normalization). `Normalizer` scales rows to unit norm (not column-wise). `MinMaxScaler` scales to a [0, 1] range. `MaxAbsScaler` scales by the maximum absolute value.","explanation":"","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-1-q037","bank":"simulado-1","n":37,"domain":"model-development","title":"A data scientist uses Hyperopt to tune a scikit-learn GradientBoostingClassifier and…","difficulty":"medium","question":"A data scientist uses Hyperopt to tune a scikit-learn `GradientBoostingClassifier` and wants up to 6 trials to run at once on the cluster's workers. Which `fmin` call is appropriate?","choices":{"A":"`fmin(fn=objective, space=space, algo=tpe.suggest, max_evals=60, trials=Trials())`","B":"`fmin(fn=objective, space=space, algo=tpe.suggest, max_evals=60, trials=SparkTrials(parallelism=6))`","C":"`fmin(fn=objective, space=space, algo=rand.suggest, max_evals=6)`","D":"`CrossValidator(estimator=objective, parallelism=6)`"},"answer":"B","short":"`SparkTrials` parallelises single-machine models such as scikit-learn across Spark workers; `parallelism` caps concurrent trials.","explanation":"`Trials()` runs sequentially on the driver, and `CrossValidator` tunes Spark ML estimators, not Python objective functions.","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-1-q038","bank":"simulado-1","n":38,"domain":"model-development","title":"A GridSearchCV uses {\"max_depth\": [3, 5, 7, 9], \"min_samples_leaf\": [1, 5, 10]} with…","difficulty":"medium","question":"A `GridSearchCV` uses `{\"max_depth\": [3, 5, 7, 9], \"min_samples_leaf\": [1, 5, 10]}` with `cv=3`. How many models are trained during the grid search, not counting the final refit?","choices":{"A":"7","B":"12","C":"21","D":"36"},"answer":"D","short":"The grid has 4 × 3 = 12 combinations and 3-fold CV trains 3 models per combination: 12 × 3 = 36.","explanation":"With `refit=True` (the default) one more model is then trained on all the data.","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-1-q039","bank":"simulado-1","n":39,"domain":"model-development","title":"Only 8 % of training rows belong to the positive class. Which technique directly…","difficulty":"medium","question":"Only 8 % of training rows belong to the positive class. Which technique directly counters the model's bias toward the majority class?","choices":{"A":"Standardise all features","B":"Collect more majority-class rows","C":"Assign a higher weight to minority-class rows during training (cost-sensitive learning)","D":"Shuffle the rows before training"},"answer":"C","short":"Class weights or cost-sensitive learning make minority-class errors more expensive; resampling the training split is the alternative.","explanation":"Scaling, more majority data, and shuffling do not change the class balance the model optimises for.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-1-q040","bank":"simulado-1","n":40,"domain":"model-development","title":"A spam filter sends messages it flags to a hidden folder, and users are very unhappy…","difficulty":"medium","question":"A spam filter sends messages it flags to a hidden folder, and users are very unhappy when legitimate mail is hidden. Which metric best reflects this concern?","choices":{"A":"Recall","B":"Precision","C":"RMSE","D":"R²"},"answer":"B","short":"Precision = TP / (TP + FP) measures how many flagged messages really are spam, so it penalises hiding legitimate mail.","explanation":"Recall focuses on missed spam; RMSE and R² are regression metrics.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-1-q041","bank":"simulado-1","n":41,"domain":"model-development","title":"A model was trained on log1p(sales). Before reporting MAE in units of sales, what must…","difficulty":"medium","question":"A model was trained on `log1p(sales)`. Before reporting MAE in units of sales, what must be done?","choices":{"A":"Nothing — MAE is scale-free","B":"Apply `expm1` to the predictions and compare them with the original `sales` values","C":"Apply `log1p` to the predictions again","D":"Divide the MAE by the mean of `sales`"},"answer":"B","short":"Predictions are in log space; invert the transform (`expm1` for `log1p`, `exp` for `log`) and evaluate against the original labels.","explanation":"MAE is in the target's units, so log-space MAE is not in sales units.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-1-q042","bank":"simulado-1","n":42,"domain":"model-development","title":"A model shows 2 % training error and 25 % validation error. Which change is most…","difficulty":"hard","question":"A model shows 2 % training error and 25 % validation error. Which change is most likely to help?","choices":{"A":"Increase model complexity","B":"Train for more epochs without other changes","C":"Reduce model complexity or add regularization (or more training data)","D":"Remove the validation set"},"answer":"C","short":"Low training error with much higher validation error is high variance (overfitting); simplify the model, regularise, or add data.","explanation":"Adding complexity or training longer worsens overfitting; removing validation hides the problem.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-1-q043","bank":"simulado-1","n":43,"domain":"model-deployment","title":"A data scientist must score 50 million rows in a Spark DataFrame with the registered…","difficulty":"medium","question":"A data scientist must score 50 million rows in a Spark DataFrame with the registered model `ml.retail.mymodel`. Which approach is correct?","choices":{"A":"`mlflow.pyfunc.load_model(\"models:/ml.retail.mymodel@champion\").predict(spark_df.toPandas())`","B":"`predict_udf = mlflow.pyfunc.spark_udf(spark, \"models:/ml.retail.mymodel@champion\")`, then `spark_df.withColumn(\"prediction\", predict_udf(*feature_cols))`","C":"POST `spark_df.toPandas().to_dict()` to a serving endpoint in one request","D":"`spark_df.rdd.map(model.predict).collect()` with a scikit-learn model loaded on the driver"},"answer":"B","short":"`spark_udf` distributes the model to the workers and scores partitions in parallel pandas batches.","explanation":"`toPandas()` on 50 million rows collects everything to the driver (out-of-memory risk), one HTTP request with 50 million rows is not feasible, and mapping a driver-side model over an RDD and collecting the results does not scale.","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-1-q044","bank":"simulado-1","n":44,"domain":"model-deployment","title":"Card transactions arrive continuously and each must be scored for fraud within…","difficulty":"medium","question":"Card transactions arrive continuously and each must be scored for fraud within seconds, with the score written to a Delta table for investigators. Which serving approach fits best?","choices":{"A":"A nightly batch job","B":"Streaming inference with the model applied to the incoming stream","C":"A real-time endpoint called by investigators on demand","D":"Weekly retraining only"},"answer":"B","short":"Continuously arriving events scored within seconds and stored in a table is the streaming pattern (for example a Delta Live Tables pipeline with the model as a Spark UDF).","explanation":"Nightly batch is too late, and an on-demand endpoint does not score every transaction as it arrives.","lesson":"04-model-deployment/02-streaming-inference","related":null},{"id":"ml-associate-mock-1-q045","bank":"simulado-1","n":45,"domain":"model-deployment","title":"How is streaming inference typically implemented in a Delta Live Tables pipeline?","difficulty":"medium","question":"How is streaming inference typically implemented in a Delta Live Tables pipeline?","choices":{"A":"Delta Live Tables calls the workspace's default serving endpoint for each row","B":"Load the registered model with `mlflow.pyfunc.spark_udf` and apply it to `spark.readStream` data in a pipeline table definition","C":"Delta Live Tables trains a new model on every micro-batch","D":"Delta Live Tables only supports batch, so a separate tool is required"},"answer":"B","short":"The model runs in-process as a Spark UDF inside a streaming table; the pipeline handles checkpoints, retries, and autoscaling.","explanation":"Delta Live Tables is now called Lakeflow Spark Declarative Pipelines; the pattern is unchanged.","lesson":"04-model-deployment/02-streaming-inference","related":null},{"id":"ml-associate-mock-1-q046","bank":"simulado-1","n":46,"domain":"model-deployment","title":"A team needs an endpoint that returns a fraud probability plus a decision string…","difficulty":"medium","question":"A team needs an endpoint that returns a fraud probability plus a decision string computed from business rules that are not part of the trained model. What should they deploy?","choices":{"A":"The raw scikit-learn model, with rules implemented in every client","B":"A custom `mlflow.pyfunc.PythonModel` that wraps the model and the rules, logged with `mlflow.pyfunc.log_model`, registered in Unity Catalog, and served from a Model Serving endpoint","C":"A SQL view containing the rules","D":"A notebook uploaded to Model Serving"},"answer":"B","short":"Custom pyfunc models package arbitrary Python logic with the model so the endpoint returns exactly what callers need.","explanation":"Endpoints serve registered MLflow models, not views or notebooks.","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-1-q047","bank":"simulado-1","n":47,"domain":"model-deployment","title":"Which request body is valid for querying a custom model endpoint with two rows of…","difficulty":"easy","question":"Which request body is valid for querying a custom model endpoint with two rows of tabular data?","choices":{"A":"`{\"dataframe_split\": {\"columns\": [\"a\", \"b\"], \"data\": [[1, 2], [3, 4]]}}`","B":"`{\"rows\": [[1, 2], [3, 4]]}`","C":"`{\"spark_df\": \"a,b\\n1,2\\n3,4\"}`","D":"`{\"predict\": [1, 2, 3, 4]}`"},"answer":"A","short":"`dataframe_split` (recommended) and `dataframe_records` are the tabular formats; `instances` and `inputs` are tensor formats.","explanation":"The other keys are not accepted.","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-1-q048","bank":"simulado-1","n":48,"domain":"model-deployment","title":"A team wants 10 % of live requests to go to a new model version while 90 % stay on the…","difficulty":"medium","question":"A team wants 10 % of live requests to go to a new model version while 90 % stay on the current one, on the same endpoint. What should they configure?","choices":{"A":"Give the new version the `challenger` alias","B":"Two served entities on the endpoint with `traffic_config` routes of 90 and 10","C":"A tag `traffic=10` on the new version","D":"A second workspace"},"answer":"B","short":"An endpoint can serve several versions, and `traffic_config.routes` sets each one's `traffic_percentage` (summing to 100).","explanation":"Aliases and tags are registry metadata and do not route traffic.","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-2-q001","bank":"simulado-2","n":1,"domain":"databricks-machine-learning","title":"A data scientist is debugging a scikit-learn pipeline on a small sample of data…","difficulty":"medium","question":"A data scientist is debugging a scikit-learn pipeline on a small sample of data locally in a Databricks notebook. The full training dataset is 2 TB in Delta Lake. Which cluster type should they use for the debugging phase?","choices":{"A":"Multi-node cluster with 20 workers to match the production environment","B":"Single-node cluster to minimize cost during the debugging phase","C":"GPU cluster to ensure the code runs correctly before moving to GPU production","D":"High-concurrency cluster shared with the rest of the team"},"answer":"B","short":"During debugging with a small data sample using scikit-learn (which does not distribute), a single-node cluster minimizes cost. Multi-node clusters add overhead with no benefit for non-distributed code. GPU and high-concurrency clusters are not needed for debugging scikit-learn logic.","explanation":"","lesson":"01-databricks-machine-learning/02-compute-clusters-ml","related":null},{"id":"ml-associate-mock-2-q002","bank":"simulado-2","n":2,"domain":"databricks-machine-learning","title":"A data scientist runs AutoML for classification. The resulting experiment shows 20…","difficulty":"medium","question":"A data scientist runs AutoML for classification. The resulting experiment shows 20 trial runs. They want to use the best model's code as a starting point for further tuning. Where is this code located?","choices":{"A":"In the DBFS path `/ml/automl/best_model.py`","B":"In a generated notebook linked from the best run in the AutoML experiment","C":"In the MLflow model artifact under `source_code/`","D":"In a Delta table named `automl_best_model_code`"},"answer":"B","short":"AutoML generates a Python notebook containing the complete training code for the best-performing trial. This notebook is linked directly from the best run in the MLflow experiment UI. Data scientists can clone and modify it to customize the training approach.","explanation":"","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"ml-associate-mock-2-q003","bank":"simulado-2","n":3,"domain":"databricks-machine-learning","title":"An organization uses AutoML for initial model prototyping. A data scientist notices…","difficulty":"hard","question":"An organization uses AutoML for initial model prototyping. A data scientist notices that the AutoML experiment uses different feature transformations than their production preprocessing pipeline. What is the risk?","choices":{"A":"The AutoML model may perform better than expected in production due to more optimized preprocessing","B":"The AutoML model may perform worse in production due to train-serve skew from different feature transformations","C":"AutoML preprocessing is always identical to production because it uses the Databricks Feature Store","D":"There is no risk because AutoML models are never used directly in production"},"answer":"B","short":"If AutoML's internal feature transformations differ from the production preprocessing pipeline, the model will experience train-serve skew — it will be evaluated in production on differently transformed features than it was trained on. This can significantly degrade prediction quality. Integrating the Feature Store with AutoML or carefully replicating feature logic mitigates this risk.","explanation":"","lesson":"01-databricks-machine-learning/03-databricks-automl","related":null},{"id":"ml-associate-mock-2-q004","bank":"simulado-2","n":4,"domain":"databricks-machine-learning","title":"A data scientist enables mlflow.autolog() and then manually logs…","difficulty":"medium","question":"A data scientist enables `mlflow.autolog()` and then manually logs `mlflow.log_metric(\"custom_f1\", 0.88)` within the same run. What is the result?","choices":{"A":"An error is raised because manual and automatic logging cannot coexist","B":"The `custom_f1` metric is logged alongside the automatically captured metrics","C":"Autolog is disabled after the first manual logging call","D":"The manual log overwrites all autolog metrics with the same name"},"answer":"B","short":"`mlflow.autolog()` and manual logging calls are fully compatible. Autolog captures framework-generated metrics, while manual calls add supplementary data. All logged values coexist in the same run record. Autolog is not disabled by manual logging.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"ml-associate-mock-2-q005","bank":"simulado-2","n":5,"domain":"databricks-machine-learning","title":"A parent run is active. A data scientist calls mlflow.start_run(nested=True) inside a…","difficulty":"hard","question":"A parent run is active. A data scientist calls `mlflow.start_run(nested=True)` inside a loop to create child runs. When does the parent run end?","choices":{"A":"After the first child run ends","B":"After all child runs in the loop have ended","C":"Only when the parent run's context manager or `mlflow.end_run()` is explicitly called","D":"Automatically after 60 minutes of inactivity"},"answer":"C","short":"The parent run's lifecycle is independent of its child runs. The parent run ends when its `with` block exits (if using a context manager) or when `mlflow.end_run()` is explicitly called. Child runs ending does not affect the parent run's status.","explanation":"","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"ml-associate-mock-2-q006","bank":"simulado-2","n":6,"domain":"databricks-machine-learning","title":"A data scientist wants the top 3 runs of experiment 123 ordered by val_accuracy,…","difficulty":"medium","question":"A data scientist wants the top 3 runs of experiment `123` ordered by `val_accuracy`, highest first. Which call is correct?","choices":{"A":"`mlflow.search_runs(experiment_ids=[\"123\"], order_by=[\"metrics.val_accuracy DESC\"], max_results=3)`","B":"`mlflow.search_runs(experiment_ids=[\"123\"], sort_by=\"val_accuracy\", limit=3)`","C":"`mlflow.get_experiment(\"123\").runs[:3]`","D":"`mlflow.search_runs(experiment_ids=[\"123\"], order_by=[\"metrics.val_accuracy ASC\"], max_results=3)`"},"answer":"A","short":"`search_runs` takes `order_by` strings such as `\"metrics.val_accuracy DESC\"` and `max_results` to limit the result.","explanation":"`sort_by` and `limit` are not parameters, an `Experiment` object has no `.runs`, and `ASC` would return the lowest accuracies.","lesson":"01-databricks-machine-learning/06-experiments-runs","related":null},{"id":"ml-associate-mock-2-q007","bank":"simulado-2","n":7,"domain":"databricks-machine-learning","title":"A data scientist logged a model in run r9 (artifact path model) but forgot to register…","difficulty":"medium","question":"A data scientist logged a model in run `r9` (artifact path `model`) but forgot to register it. How can they register it as `ml.churn.clf` in Unity Catalog without retraining?","choices":{"A":"Retrain the model and pass `registered_model_name` this time","B":"`mlflow.register_model(\"runs:/r9/model\", \"ml.churn.clf\")`","C":"Delete the run and start over","D":"Copy the artifact files into the catalog with `dbutils.fs.cp`"},"answer":"B","short":"`mlflow.register_model()` can be called any time after logging, using the `runs:/<run_id>/<artifact_path>` URI and a three-level Unity Catalog name.","explanation":"The run must still exist, and the model version must have a signature for Unity Catalog.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"ml-associate-mock-2-q008","bank":"simulado-2","n":8,"domain":"databricks-machine-learning","title":"Which MLflow tag is automatically set to identify the notebook path where a run was…","difficulty":"medium","question":"Which MLflow tag is automatically set to identify the notebook path where a run was started in Databricks?","choices":{"A":"`mlflow.source.name`","B":"`mlflow.databricks.notebookPath`","C":"`mlflow.notebook.path`","D":"`databricks.notebook.id`"},"answer":"A","short":"MLflow automatically sets the `mlflow.source.name` tag to the notebook path when runs are started from a Databricks notebook. Other Databricks-specific tags such as `mlflow.databricks.notebookRevisionID` and `mlflow.databricks.cluster.id` are also set automatically.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"ml-associate-mock-2-q009","bank":"simulado-2","n":9,"domain":"databricks-machine-learning","title":"A data scientist calls mlflow.log_metric(\"accuracy\", 0.92) multiple times in a run…","difficulty":"medium","question":"A data scientist calls `mlflow.log_metric(\"accuracy\", 0.92)` multiple times in a run without specifying a `step`. What happens?","choices":{"A":"Only the first value is retained; subsequent calls are ignored","B":"The last logged value overwrites the previous values","C":"All values are retained in the metric history and the last value is shown in the run summary","D":"An error is raised because a metric can only be logged once per run"},"answer":"C","short":"MLflow stores the complete history for each metric, including all values and their timestamps. When you call `log_metric()` without a `step`, MLflow uses an auto-incrementing step. The run summary (`run.data.metrics`) shows the last logged value, but the full history is accessible via `MlflowClient().get_metric_history()`.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"ml-associate-mock-2-q010","bank":"simulado-2","n":10,"domain":"databricks-machine-learning","title":"A data scientist sets mlflow.autolog(log_models=False). What is the effect?","difficulty":"medium","question":"A data scientist sets `mlflow.autolog(log_models=False)`. What is the effect?","choices":{"A":"Autolog is completely disabled","B":"Autolog captures parameters and metrics but does NOT log the model artifact","C":"Autolog logs the model artifact but not parameters or metrics","D":"Autolog raises a deprecation warning and falls back to default behavior"},"answer":"B","short":"`log_models=False` disables automatic model artifact logging within autolog, but parameters and metrics are still captured. This is useful when you want to log the model manually with custom metadata or a different artifact path, while still benefiting from automatic metric and parameter capture.","explanation":"","lesson":"01-databricks-machine-learning/05-mlflow-tracking","related":null},{"id":"ml-associate-mock-2-q011","bank":"simulado-2","n":11,"domain":"databricks-machine-learning","title":"Features are computed daily into a time-series feature table. Training must use, for…","difficulty":"medium","question":"Features are computed daily into a time-series feature table. Training must use, for each label, the feature values as of the label's event time. Which capability provides this?","choices":{"A":"`fe.write_table(..., mode=\"merge\")` every day","B":"A point-in-time lookup: `FeatureLookup(..., timestamp_lookup_key=\"event_ts\")`","C":"Delta time travel to the latest table version","D":"Calling `fe.score_batch()` on historical entities"},"answer":"B","short":"Point-in-time lookups use the label's timestamp to fetch the feature values as they existed at that moment, preventing future data leaking into training rows.","explanation":"Merging and time travel to the latest version do not align features with each label's time, and `score_batch` scores rather than building training sets.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"ml-associate-mock-2-q012","bank":"simulado-2","n":12,"domain":"databricks-machine-learning","title":"A model logged with fe.log_model was trained on three features of…","difficulty":"medium","question":"A model logged with `fe.log_model` was trained on three features of `ml.features.customers`. Later two new columns are added to that feature table. How are the model's scoring calls affected?","choices":{"A":"The model automatically starts using the new columns","B":"They are unaffected — the model looks up only the features recorded in its training set","C":"Scoring fails because the table schema changed","D":"The new columns are passed in but given zero weight"},"answer":"B","short":"`fe.log_model` stores the feature lookups used at training; `score_batch` and online lookups fetch exactly those features. New columns are used only if the model is retrained with them.","explanation":"","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"ml-associate-mock-2-q013","bank":"simulado-2","n":13,"domain":"databricks-machine-learning","title":"Why log a feature-table-trained model with fe.log_model(...) instead of…","difficulty":"medium","question":"Why log a feature-table-trained model with `fe.log_model(...)` instead of `mlflow.sklearn.log_model(...)`?","choices":{"A":"It deploys the model to a serving endpoint automatically","B":"It packages the feature lookup metadata, so `fe.score_batch` (and online lookups) can fetch the features automatically at inference","C":"It stores the model in a Delta table instead of MLflow","D":"It skips signature inference"},"answer":"B","short":"`FeatureEngineeringClient.log_model(model, artifact_path, flavor, training_set, ...)` records which feature tables and keys the model needs; inference then needs only the keys.","explanation":"It does not deploy anything or replace MLflow storage, and Unity Catalog still requires a signature.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"ml-associate-mock-2-q014","bank":"simulado-2","n":14,"domain":"databricks-machine-learning","title":"A data scientist needs a DataFrame of feature values for a list of customer_ids to…","difficulty":"medium","question":"A data scientist needs a DataFrame of feature values for a list of `customer_id`s to inspect before scoring, without running a model. Which call fits?","choices":{"A":"`fe.score_batch(model_uri, ids_df)`","B":"`fe.create_training_set(df=ids_df, feature_lookups=lookups, label=None).load_df()`","C":"`fe.publish_table(...)`","D":"`fe.create_table(name, primary_keys=[\"customer_id\"])`"},"answer":"B","short":"`create_training_set` joins the requested features onto the key DataFrame; `label=None` builds a feature set without a target column, and `load_df()` returns it.","explanation":"`score_batch` runs inference, `publish_table` copies to an online store, and `create_table` creates a new table.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"ml-associate-mock-2-q015","bank":"simulado-2","n":15,"domain":"databricks-machine-learning","title":"Version 5 of ml.ads.ctr_model should replace version 4 in production. Consumers load…","difficulty":"hard","question":"Version 5 of `ml.ads.ctr_model` should replace version 4 in production. Consumers load `@champion`, and the team also wants to keep a pointer to the previous model for quick rollback. Which sequence is correct?","choices":{"A":"`transition_model_version_stage(version=5, stage=\"Production\", archive_existing_versions=True)`","B":"`set_registered_model_alias(name, \"previous\", 4)` then `set_registered_model_alias(name, \"champion\", 5)`","C":"`delete_model_version(name, 4)` then `set_registered_model_alias(name, \"champion\", 5)`","D":"`set_model_version_tag(name, \"5\", \"stage\", \"Production\")`"},"answer":"B","short":"Aliases are named pointers you control: keep `previous` on version 4 for rollback, then move `champion` to version 5. Rolling back is just moving `champion` back.","explanation":"Stages (and `archive_existing_versions`) are not supported in Unity Catalog, deleting version 4 removes the rollback target, and a tag does not change what consumers load.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"ml-associate-mock-2-q016","bank":"simulado-2","n":16,"domain":"databricks-machine-learning","title":"A data scientist registers the same logged model runs:/abc123/model under two Unity…","difficulty":"medium","question":"A data scientist registers the same logged model `runs:/abc123/model` under two Unity Catalog names: `ml.team_a.model` and `ml.team_b.model`. What happens?","choices":{"A":"An error — a run's model can only be registered once","B":"Both succeed, each creating version 1 of its own registered model","C":"Only the first succeeds","D":"The second call adds version 2 to `ml.team_a.model`"},"answer":"B","short":"Registration creates a version under the target name; the same source can back versions in different registered models, each starting at version 1.","explanation":"","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"ml-associate-mock-2-q017","bank":"simulado-2","n":17,"domain":"databricks-machine-learning","title":"Version 6 of ml.churn.clf should carry validation_status=approved. Which call adds…","difficulty":"easy","question":"Version 6 of `ml.churn.clf` should carry `validation_status=approved`. Which call adds that tag to the version?","choices":{"A":"`client.set_registered_model_alias(\"ml.churn.clf\", \"approved\", 6)`","B":"`client.set_model_version_tag(\"ml.churn.clf\", \"6\", \"validation_status\", \"approved\")`","C":"`client.set_registered_model_tag(\"ml.churn.clf\", \"validation_status\", \"approved\")`","D":"`client.update_model_version(\"ml.churn.clf\", 6, tag=\"approved\")`"},"answer":"B","short":"`set_model_version_tag(name, version, key, value)` tags one version; `delete_model_version_tag(name, version, key)` removes it.","explanation":"A model-level tag applies to the registered model, an alias is a pointer rather than a tag, and `update_model_version` changes the description.","lesson":"01-databricks-machine-learning/07-model-registry","related":null},{"id":"ml-associate-mock-2-q018","bank":"simulado-2","n":18,"domain":"databricks-machine-learning","title":"Why might an organisation keep feature tables in Unity Catalog rather than in a legacy…","difficulty":"medium","question":"Why might an organisation keep feature tables in Unity Catalog rather than in a legacy workspace feature store?","choices":{"A":"Unity Catalog feature tables don't need primary keys","B":"Feature tables registered in Unity Catalog can be discovered and reused from any workspace on the metastore, with centralised governance and lineage","C":"Unity Catalog feature tables are refreshed automatically","D":"Workspace feature stores support online serving but Unity Catalog does not"},"answer":"B","short":"Unity Catalog is account-level, giving cross-workspace sharing and discovery, UC access control, and lineage to models.","explanation":"Primary keys are required, refresh is your pipeline's job, and UC feature tables publish to online stores.","lesson":"01-databricks-machine-learning/04-feature-store","related":null},{"id":"ml-associate-mock-2-q019","bank":"simulado-2","n":19,"domain":"data-processing","title":"A data scientist accidentally passes a string column directly to OneHotEncoder…","difficulty":"medium","question":"A data scientist accidentally passes a string column directly to `OneHotEncoder` (skipping `StringIndexer`). What happens?","choices":{"A":"`OneHotEncoder` automatically converts strings to integer indices internally","B":"An error is raised because `OneHotEncoder` expects numeric input","C":"The string column is encoded as binary using ASCII values","D":"`OneHotEncoder` silently ignores the column and produces a zero vector"},"answer":"B","short":"`OneHotEncoder` requires numeric input (specifically, integer indices produced by `StringIndexer`). Passing a string column directly raises a `SparkException` at runtime because the transformer cannot process string data. `StringIndexer` must always precede `OneHotEncoder` in the pipeline.","explanation":"","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-2-q020","bank":"simulado-2","n":20,"domain":"data-processing","title":"A data scientist applies Normalizer(p=2.0) to a feature vector. What transformation is…","difficulty":"medium","question":"A data scientist applies `Normalizer(p=2.0)` to a feature vector. What transformation is applied?","choices":{"A":"Each feature value is divided by the maximum value in the column","B":"Each row vector is scaled to have unit L2 norm","C":"Each feature value is transformed to have zero mean and unit variance","D":"Each feature value is scaled to the range [0, 1]"},"answer":"B","short":"`Normalizer` with `p=2.0` scales each **row** vector to unit L2 norm (Euclidean norm). This is row-wise normalization, not column-wise. `MinMaxScaler` scales to [0, 1], `StandardScaler` applies z-score normalization, and neither is `Normalizer`.","explanation":"","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-2-q021","bank":"simulado-2","n":21,"domain":"data-processing","title":"Which Databricks utility renders summary statistics for a Spark or pandas DataFrame in…","difficulty":"easy","question":"Which Databricks utility renders summary statistics for a Spark or pandas DataFrame in a notebook?","choices":{"A":"`dbutils.data.summarize(df)`","B":"`dbutils.notebook.summarize(df)`","C":"`dbutils.fs.describe(df)`","D":"`dbutils.widgets.summary(df)`"},"answer":"A","short":"`dbutils.data.summarize(df)` calculates and displays summary statistics; `precise=True` trades speed for precision.","explanation":"The other utilities handle notebooks, files, and widgets.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"ml-associate-mock-2-q022","bank":"simulado-2","n":22,"domain":"data-processing","title":"Which approach removes rows whose amount lies more than 3 standard deviations from the…","difficulty":"medium","question":"Which approach removes rows whose `amount` lies more than 3 standard deviations from the mean?","choices":{"A":"Compute `mu` and `sigma` with `F.mean`/`F.stddev`, then `df.filter(F.abs(F.col(\"amount\") - mu) <= 3 * sigma)`","B":"`df.filter(F.col(\"amount\") <= 3)`","C":"`df.dropna(subset=[\"amount\"])`","D":"`df.orderBy(\"amount\").limit(int(df.count() * 0.97))`"},"answer":"A","short":"The z-score rule keeps |x − μ| ≤ 3σ.","explanation":"Filtering a raw value of 3, dropping nulls, or trimming the top 3 % are different operations.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"ml-associate-mock-2-q023","bank":"simulado-2","n":23,"domain":"data-processing","title":"What is the most appropriate way to examine the relationship between two continuous…","difficulty":"medium","question":"What is the most appropriate way to examine the relationship between two continuous features, `age` and `annual_spend`?","choices":{"A":"A contingency table with a chi-square test","B":"A scatter plot with a correlation coefficient","C":"A bar chart of distinct ages","D":"One-hot encoding both columns"},"answer":"B","short":"Scatter plots and Pearson/Spearman correlation describe two continuous features; Spearman is preferable for monotonic or skewed relationships.","explanation":"Contingency tables and chi-square tests are for categorical pairs.","lesson":"02-data-processing/01-exploratory-data-analysis","related":null},{"id":"ml-associate-mock-2-q024","bank":"simulado-2","n":24,"domain":"data-processing","title":"A data scientist must impute missing delivery_days (a numeric feature that is roughly…","difficulty":"medium","question":"A data scientist must impute missing `delivery_days` (a numeric feature that is roughly symmetric, with no strong outliers). Which strategy is reasonable?","choices":{"A":"Mean","B":"Mode of a string column","C":"Always zero","D":"Drop the column"},"answer":"A","short":"For symmetric continuous data without strong outliers, the mean is a reasonable estimate (median for skewed data, mode for categorical).","explanation":"Zero-filling invents values, and dropping a mostly complete column throws away signal.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-2-q025","bank":"simulado-2","n":25,"domain":"data-processing","title":"Which Spark code imputes missing numeric age with its median, learned from the…","difficulty":"medium","question":"Which Spark code imputes missing numeric `age` with its median, learned from the training data?","choices":{"A":"`Imputer(inputCols=[\"age\"], outputCols=[\"age_imp\"], strategy=\"median\").fit(train_df)`","B":"`train_df.fillna(\"median\")`","C":"`Imputer(strategy=\"median\").transform(train_df)` with no fit","D":"`train_df.na.drop(subset=[\"age\"])`"},"answer":"A","short":"`Imputer` is an Estimator: `fit` learns the median on training data, and the resulting `ImputerModel` transforms train, validation, and test data.","explanation":"`fillna(\"median\")` fills the literal string, an unfitted `Imputer` cannot transform, and dropping rows is not imputation.","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-2-q026","bank":"simulado-2","n":26,"domain":"data-processing","title":"Which feature is a poor candidate for one-hot encoding?","difficulty":"medium","question":"Which feature is a poor candidate for one-hot encoding?","choices":{"A":"`payment_type` with 4 nominal levels for a logistic regression","B":"`customer_id` with 3 million distinct values","C":"`day_of_week` for a linear model","D":"`region` with 6 levels for k-nearest neighbours"},"answer":"B","short":"Millions of levels would create millions of sparse columns; identifiers like this are usually dropped or replaced by aggregate or encoded features.","explanation":"Low-cardinality nominal features for linear or distance-based models are classic one-hot candidates.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-2-q027","bank":"simulado-2","n":27,"domain":"data-processing","title":"When is a log transformation of a feature most appropriate?","difficulty":"medium","question":"When is a log transformation of a feature most appropriate?","choices":{"A":"The feature is already normally distributed around zero","B":"The feature is positive, right-skewed, and spans several orders of magnitude","C":"The feature contains many negative values","D":"The feature is a high-cardinality categorical column"},"answer":"B","short":"A log compresses large values and makes right-skewed positive data more symmetric.","explanation":"It adds nothing for normal data, is undefined for zero or negative values (use `log1p` for zeros), and is not a cardinality-reduction technique.","lesson":"02-data-processing/02-feature-engineering-techniques","related":null},{"id":"ml-associate-mock-2-q028","bank":"simulado-2","n":28,"domain":"model-development","title":"A data scientist wants to create a reproducible experiment where the same random split…","difficulty":"easy","question":"A data scientist wants to create a reproducible experiment where the same random split is used every time the notebook runs. Which parameter in `train_test_split` (sklearn) or `randomSplit` (Spark) controls this?","choices":{"A":"`reproducible=True`","B":"`random_state` (sklearn) or `seed` (Spark)","C":"`deterministic=True`","D":"`fixed_split=True`"},"answer":"B","short":"In scikit-learn, `train_test_split(df, random_state=42)` sets the random seed. In Spark, `df.randomSplit([0.8, 0.2], seed=42)` sets the split seed. The parameter is `random_state` in sklearn and `seed` in Spark. `reproducible`, `deterministic`, and `fixed_split` are not valid parameters.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-2-q029","bank":"simulado-2","n":29,"domain":"model-development","title":"A data scientist creates a Pipeline with a VectorAssembler and LogisticRegression. The…","difficulty":"hard","question":"A data scientist creates a `Pipeline` with a `VectorAssembler` and `LogisticRegression`. The `VectorAssembler` uses `inputCols=[\"age\", \"income\"]` and `outputCol=\"features\"`. `LogisticRegression` uses `featuresCol=\"features\"`. What happens if the test DataFrame is missing the `income` column?","choices":{"A":"The pipeline silently ignores the missing column and uses only `age`","B":"An exception is raised when `transform()` is called on the missing column","C":"The `VectorAssembler` fills missing values with 0 by default","D":"The pipeline adds a null `income` column automatically"},"answer":"B","short":"`VectorAssembler` raises an exception if any column specified in `inputCols` is missing from the input DataFrame at transform time. There is no automatic null-filling or column creation behavior unless `handleInvalid=\"keep\"` is set, which handles null values in existing columns but not entirely absent columns.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-2-q030","bank":"simulado-2","n":30,"domain":"model-development","title":"A pipeline must one-hot encode city and category. Which stage ordering is invalid?","difficulty":"medium","question":"A pipeline must one-hot encode `city` and `category`. Which stage ordering is **invalid**?","choices":{"A":"`SI(city)` → `SI(category)` → `OHE(city_idx, category_idx)` → `VectorAssembler`","B":"`SI(city)` → `OHE(city_idx)` → `SI(category)` → `OHE(category_idx)` → `VectorAssembler`","C":"`OHE(city)` → `SI(city)` → `OHE(category)` → `SI(category)` → `VectorAssembler`","D":"`SI(city, category)` (multi-column) → `OHE(city_idx, category_idx)` → `VectorAssembler`"},"answer":"C","short":"Each `OneHotEncoder` needs the numeric index produced by its `StringIndexer`, so every indexer must come before the encoder that uses its output.","explanation":"Grouping all indexers first, interleaving index/encode pairs, or using multi-column stages are all valid.","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-2-q031","bank":"simulado-2","n":31,"domain":"model-development","title":"A CrossValidator with numFolds=5 is used to tune a model with a ParamGrid containing 6…","difficulty":"hard","question":"A `CrossValidator` with `numFolds=5` is used to tune a model with a `ParamGrid` containing 6 hyperparameter combinations. How many total model training runs occur?","choices":{"A":"6 (one per hyperparameter combination)","B":"5 (one per fold)","C":"30 (6 combinations × 5 folds)","D":"11 (6 combinations + 5 folds)"},"answer":"C","short":"`CrossValidator` trains a model for every combination of hyperparameters and every fold. With 6 parameter combinations and 5 folds, the total is 6 × 5 = 30 training runs. After selecting the best combination, a final model is optionally retrained on the full dataset.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-2-q032","bank":"simulado-2","n":32,"domain":"model-development","title":"A data scientist fits a Pipeline on training data and saves it with…","difficulty":"medium","question":"A data scientist fits a `Pipeline` on training data and saves it with `pipeline_model.save(\"/Volumes/ml/churn/models/pipeline\")`. Later, they load it with `PipelineModel.load(\"/Volumes/ml/churn/models/pipeline\")`. Which statement is true?","choices":{"A":"The loaded model needs to be re-fitted on new data before it can transform","B":"The loaded model contains all fitted stage parameters and can transform new data immediately","C":"Only the final estimator stage is saved; preprocessing stages must be re-fitted","D":"The `save()` method does not persist the fitted parameters, only the stage configuration"},"answer":"B","short":"`PipelineModel.save()` persists all fitted stage parameters (e.g., `StringIndexerModel`'s index mapping, `StandardScalerModel`'s mean and variance, `LogisticRegressionModel`'s coefficients). When loaded, the model is fully ready to call `transform()` without any re-fitting.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-2-q033","bank":"simulado-2","n":33,"domain":"model-development","title":"Which Spark ML evaluator class should be used with CrossValidator for a binary…","difficulty":"easy","question":"Which Spark ML evaluator class should be used with `CrossValidator` for a binary classification problem?","choices":{"A":"`RegressionEvaluator`","B":"`MulticlassClassificationEvaluator`","C":"`BinaryClassificationEvaluator`","D":"`ClusteringEvaluator`"},"answer":"C","short":"`BinaryClassificationEvaluator` is used for binary classification problems. It supports metrics such as `areaUnderROC` (AUC) and `areaUnderPR`. `MulticlassClassificationEvaluator` supports more than two classes with metrics like accuracy and F1. `RegressionEvaluator` is for regression tasks.","explanation":"","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-2-q034","bank":"simulado-2","n":34,"domain":"model-development","title":"A data scientist's CrossValidator is running slowly because the parameter grid has 100…","difficulty":"medium","question":"A data scientist's `CrossValidator` is running slowly because the parameter grid has 100 combinations and 5 folds (500 total training runs). Which `CrossValidator` parameter reduces wall-clock time by training multiple combinations simultaneously?","choices":{"A":"`numFolds=2` — reduces the number of folds","B":"`parallelism=8` — trains up to 8 combinations concurrently","C":"`seed=42` — enables deterministic caching","D":"`collectSubModels=True` — reduces memory overhead"},"answer":"B","short":"`parallelism` controls how many (hyperparameter combination, fold) pairs are trained concurrently. Setting `parallelism=8` can reduce wall-clock time by up to 8×. Reducing `numFolds` also reduces training runs but decreases estimate reliability. `seed` and `collectSubModels` do not affect parallelism.","explanation":"","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-2-q035","bank":"simulado-2","n":35,"domain":"model-development","title":"A data scientist uses Pipeline with stages [indexer, encoder, assembler, classifier].…","difficulty":"hard","question":"A data scientist uses `Pipeline` with stages `[indexer, encoder, assembler, classifier]`. During `pipeline.fit(train_df)`, which stages call `.fit()` vs `.transform()`?","choices":{"A":"All stages call `.fit()` then `.transform()` sequentially","B":"Only the classifier (last stage) calls `.fit()`; all others call only `.transform()`","C":"`Estimator` stages (e.g., indexer, classifier) call `.fit()` then `.transform()`; `Transformer` stages call only `.transform()`","D":"All stages call `.transform()` only; `.fit()` is called once at the pipeline level"},"answer":"C","short":"During `Pipeline.fit()`, each stage is processed in order. `Estimator` stages (like `StringIndexer` and `RandomForestClassifier`) call `.fit(df)` to learn parameters, then `.transform(df)` to produce the output DataFrame for the next stage. `Transformer` stages (like `VectorAssembler` and `OneHotEncoderModel`) call only `.transform(df)` since they have no parameters to learn.","explanation":"","lesson":"03-model-development/01-spark-ml-pipelines","related":null},{"id":"ml-associate-mock-2-q036","bank":"simulado-2","n":36,"domain":"model-development","title":"Which Hyperopt setting performs random search instead of Bayesian search?","difficulty":"easy","question":"Which Hyperopt setting performs random search instead of Bayesian search?","choices":{"A":"`algo=tpe.suggest`","B":"`algo=rand.suggest`","C":"`trials=SparkTrials()`","D":"`max_evals=1`"},"answer":"B","short":"`rand.suggest` samples hyperparameters at random; `tpe.suggest` is the Bayesian (TPE) algorithm.","explanation":"`SparkTrials` controls parallel execution, not the search strategy.","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-2-q037","bank":"simulado-2","n":37,"domain":"model-development","title":"A data scientist tunes a Spark ML RandomForestClassifier on a large table with…","difficulty":"hard","question":"A data scientist tunes a Spark ML `RandomForestClassifier` on a large table with Hyperopt. Which `trials` setting is recommended?","choices":{"A":"`SparkTrials(parallelism=16)`","B":"The default `Trials()`, because each MLlib fit is already distributed across the cluster","C":"`SparkTrials(parallelism=1)`","D":"No trials object; Hyperopt cannot tune MLlib"},"answer":"B","short":"`SparkTrials` is for single-machine models; distributed MLlib training should use `Trials`.","explanation":"Note: Hyperopt is not included in Databricks Runtime ML after 16.4 LTS ML; the docs now recommend Optuna or Ray Tune.","lesson":"03-model-development/02-hyperparameter-tuning","related":null},{"id":"ml-associate-mock-2-q038","bank":"simulado-2","n":38,"domain":"model-development","title":"A marketing team needs to explain to stakeholders how each attribute influences a…","difficulty":"medium","question":"A marketing team needs to explain to stakeholders how each attribute influences a customer's predicted spend (a continuous value). Which model is the best starting point?","choices":{"A":"Linear regression (with regularisation if needed)","B":"Logistic regression","C":"k-means","D":"A 500-tree gradient-boosted ensemble"},"answer":"A","short":"Linear regression predicts a continuous target and its coefficients explain each feature's effect.","explanation":"Logistic regression is for classification, k-means is unsupervised, and large ensembles are harder to explain.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-2-q039","bank":"simulado-2","n":39,"domain":"model-development","title":"Which is a valid way to mitigate class imbalance in training data?","difficulty":"medium","question":"Which is a valid way to mitigate class imbalance in training data?","choices":{"A":"Oversample the minority class in the training split only","B":"Oversample the minority class in the test split","C":"Remove the minority class","D":"Evaluate only with accuracy"},"answer":"A","short":"Resampling the training split (or class weights) helps the model learn the minority class; evaluation data must keep the real distribution.","explanation":"Evaluating only with accuracy hides poor minority-class performance.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-2-q040","bank":"simulado-2","n":40,"domain":"model-development","title":"Revenue forecasts must heavily penalise occasional very large misses. Which metric fits?","difficulty":"medium","question":"Revenue forecasts must heavily penalise occasional very large misses. Which metric fits?","choices":{"A":"MAE","B":"RMSE","C":"Accuracy","D":"F1"},"answer":"B","short":"RMSE squares errors before averaging, so large misses dominate — useful when big errors are especially costly.","explanation":"MAE treats all errors linearly; accuracy and F1 are classification metrics.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-2-q041","bank":"simulado-2","n":41,"domain":"model-development","title":"A regression model trained on log(price) reports RMSE = 0.18 on the validation set. A…","difficulty":"medium","question":"A regression model trained on `log(price)` reports RMSE = 0.18 on the validation set. A stakeholder asks for the typical error in dollars. What is the correct next step?","choices":{"A":"Report $0.18","B":"Exponentiate the predictions and compute RMSE against the original prices","C":"Report e^0.18 dollars","D":"Retrain without the log transform"},"answer":"B","short":"Convert predictions back to dollars (exp) and evaluate them against the dollar labels; a log-space RMSE cannot be converted to dollars by a simple formula.","explanation":"There is no need to abandon the log target — just invert it before evaluation.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-2-q042","bank":"simulado-2","n":42,"domain":"model-development","title":"Increasing a tree's maxDepth from 3 to 6 lowers both training and validation error.…","difficulty":"medium","question":"Increasing a tree's `maxDepth` from 3 to 6 lowers both training and validation error. What does this suggest about the depth-3 model?","choices":{"A":"It was overfitting (high variance)","B":"It was underfitting (high bias), so extra complexity helped","C":"It had data leakage","D":"Nothing — validation error is irrelevant"},"answer":"B","short":"When added complexity lowers validation error too, the simpler model was too biased. Keep increasing complexity only while validation error keeps improving.","explanation":"Overfitting would show validation error rising as training error falls.","lesson":"03-model-development/03-model-evaluation","related":null},{"id":"ml-associate-mock-2-q043","bank":"simulado-2","n":43,"domain":"model-deployment","title":"A data scientist wants to create a custom MLflow model that wraps a proprietary…","difficulty":"medium","question":"A data scientist wants to create a custom MLflow model that wraps a proprietary scoring library. Which MLflow class should they subclass?","choices":{"A":"`mlflow.pyfunc.BaseModel`","B":"`mlflow.pyfunc.PythonModel`","C":"`mlflow.sklearn.SklearnModel`","D":"`mlflow.models.CustomModel`"},"answer":"B","short":"`mlflow.pyfunc.PythonModel` is the base class for custom MLflow models. By subclassing it and implementing the `predict(context, model_input)` method, data scientists can wrap any arbitrary Python logic, including proprietary libraries, as a deployable MLflow model. `BaseModel`, `SklearnModel`, and `CustomModel` do not exist in the MLflow API.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-2-q044","bank":"simulado-2","n":44,"domain":"model-deployment","title":"A data scientist loads mlflow.pyfunc.load_model(\"models:/ml.retail.mymodel@champion\")…","difficulty":"medium","question":"A data scientist loads `mlflow.pyfunc.load_model(\"models:/ml.retail.mymodel@champion\")` for a scikit-learn model and calls `model.predict(data)`. What should `data` be?","choices":{"A":"A Spark DataFrame","B":"A pandas DataFrame (or array) compatible with the model's signature","C":"A Delta table path string","D":"A list of SQL statements"},"answer":"B","short":"A `PyFuncModel.predict` takes pandas DataFrames (or NumPy arrays) matching the model signature — batch inference with pandas.","explanation":"For Spark DataFrames, use `mlflow.pyfunc.spark_udf` instead.","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-2-q045","bank":"simulado-2","n":45,"domain":"model-deployment","title":"A retailer scores 5 million customers each night for the next day's email campaign. No…","difficulty":"easy","question":"A retailer scores 5 million customers each night for the next day's email campaign. No one needs a prediction in real time. Which approach is most cost-effective?","choices":{"A":"An always-on real-time endpoint","B":"A scheduled batch inference job","C":"A continuously running streaming pipeline","D":"A GPU endpoint with provisioned concurrency"},"answer":"B","short":"Scheduled scoring of a full population with no latency requirement is batch inference — the simplest and cheapest option.","explanation":"","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-2-q046","bank":"simulado-2","n":46,"domain":"model-deployment","title":"Which Databricks SDK call shape creates a Model Serving endpoint for version 2 of…","difficulty":"medium","question":"Which Databricks SDK call shape creates a Model Serving endpoint for version 2 of `ml.fraud.clf`?","choices":{"A":"`w.serving_endpoints.create(name=\"fraud\", config=EndpointCoreConfigInput(served_entities=[ServedEntityInput(entity_name=\"ml.fraud.clf\", entity_version=\"2\", workload_size=\"Small\", scale_to_zero_enabled=True)]))`","B":"`w.clusters.create(model=\"ml.fraud.clf\", version=2)`","C":"`mlflow.register_model(\"ml.fraud.clf/2\", \"fraud\")`","D":"`w.jobs.create(name=\"fraud\", endpoint=True)`"},"answer":"A","short":"Endpoints are created with `served_entities` naming the Unity Catalog model, version, workload size, and scale-to-zero setting (or the same payload through the MLflow Deployments client or the UI).","explanation":"Clusters, registration, and jobs do not create serving endpoints.","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-2-q047","bank":"simulado-2","n":47,"domain":"model-deployment","title":"An endpoint serves champion-v7 and challenger-v8. Which traffic_config sends a quarter…","difficulty":"medium","question":"An endpoint serves `champion-v7` and `challenger-v8`. Which `traffic_config` sends a quarter of requests to the challenger?","choices":{"A":"`{\"routes\": [{\"served_model_name\": \"champion-v7\", \"traffic_percentage\": 75}, {\"served_model_name\": \"challenger-v8\", \"traffic_percentage\": 25}]}`","B":"`{\"routes\": [{\"served_model_name\": \"challenger-v8\", \"traffic_percentage\": 25}]}`","C":"`{\"alias\": \"challenger\", \"share\": 0.25}`","D":"`{\"routes\": [{\"served_model_name\": \"champion-v7\", \"traffic_percentage\": 100}, {\"served_model_name\": \"challenger-v8\", \"traffic_percentage\": 25}]}`"},"answer":"A","short":"Each served entity gets a route, and the percentages must add up to 100.","explanation":"A single 25 % route or routes summing to 125 % are invalid, and aliases do not route traffic.","lesson":"04-model-deployment/01-model-deployment-serving","related":null},{"id":"ml-associate-mock-2-q048","bank":"simulado-2","n":48,"domain":"model-deployment","title":"Listening events must be scored for low engagement as they arrive, at tens of…","difficulty":"medium","question":"Listening events must be scored for low engagement as they arrive, at tens of thousands of events per second, with compute that grows and shrinks with traffic. Which design fits best?","choices":{"A":"A Delta Live Tables pipeline that applies the model as a Spark UDF to the streaming events","B":"A notebook that a person reruns every hour","C":"A serving endpoint called once per event from a Python loop on the driver","D":"A weekly batch job"},"answer":"A","short":"A pipeline keeps the model in-process (Spark UDF) for throughput and manages streaming state, checkpoints, and enhanced autoscaling.","explanation":"Per-event endpoint calls from the driver add overhead and do not scale; manual or weekly runs miss the latency requirement.","lesson":"04-model-deployment/02-streaming-inference","related":null}],"lessons":[{"id":"01-databricks-machine-learning/01-databricks-ml-workspace","folder":"01-databricks-machine-learning","group":"modulo","order":1,"isIndex":false,"title":"Databricks ML Workspace & Notebooks","md":"# Databricks ML Workspace & Notebooks\n\n## Overview\n\nThe Databricks workspace is a collaborative environment where data scientists and ML engineers develop, test, and collaborate on machine learning models. It provides unified access to notebooks, compute, and data.\n\n> [!abstract]\n>\n> - Notebooks are multi-language (Python, SQL, Scala, R) with magic commands and `display()` for rich output\n> - Widgets parameterise notebooks so the same code runs in dev, staging, and prod\n> - **Git folders** (formerly Databricks Repos) bring Git-based version control into the workspace\n> - Unity Catalog governs the data and ML assets (tables, volumes, feature tables, registered models) that notebooks use\n\n> [!tip] What the Exam Tests\n>\n> - The workspace is the *surface*; the exam's Section 1 bullets focus on what you do from it — ML runtimes, AutoML, feature tables, MLflow, and the UC registry\n> - Recognise Git folders as the version-control mechanism behind \"promote code\" MLOps workflows\n> - Know that DBFS mounts are a legacy pattern — Unity Catalog governs data access\n\n---\n\n## Workspace Architecture\n\n```mermaid\nflowchart TB\n    subgraph Users[\"Users & Access\"]\n        U1[\"Data Scientist\"]\n        U2[\"ML Engineer\"]\n        U3[\"Data Engineer\"]\n    end\n\n    subgraph Workspace[\"Databricks Workspace\"]\n        NB[\"Notebooks\"]\n        Repos[\"Git folders\"]\n        Secrets[\"Secrets\"]\n        Jobs[\"Jobs\"]\n    end\n\n    subgraph Compute[\"Compute Resources\"]\n        Clusters[\"Clusters\"]\n        Pools[\"Instance Pools\"]\n    end\n\n    subgraph Storage[\"Storage & Catalog\"]\n        Unity[\"Unity Catalog\"]\n        Tables[\"Tables\"]\n        Data[\"Data Files\"]\n    end\n\n    Users --> Workspace\n    Workspace --> Compute\n    Compute --> Storage\n```\n\n## Workspace Components\n\n### **Notebooks**\n\nInteractive development environment supporting multiple languages:\n\n```python\n# Python notebook with Databricks magic commands\n\n%md\n# Machine Learning Experiment\n\nThis is a Markdown cell for documentation\n\n%python\nfrom pyspark.ml import Pipeline\nimport pandas as pd\n\n# Load data from Unity Catalog\n\ndf = spark.read.table(\"catalog.schema.dataset\")\ndisplay(df)\n\n%sql\n-- SQL cells for data exploration\nSELECT * FROM catalog.schema.dataset LIMIT 10\n\n%scala\n// Scala cells for Spark operations\nval df = spark.read.table(\"catalog.schema.dataset\")\ndf.show()\n```\n\n**Key Features:**\n\n- **Multiple Languages**: Python, SQL, Scala, R\n- **Magic Commands**: `%md`, `%python`, `%sql`, `%scala`, `%sh`\n- **Widgets**: Interactive parameters for notebooks\n- **Rich Output**: Display tables, plots, graphs\n\n### **Widgets for Parameterization**\n\n```python\n# Create text widget\n\ndbutils.widgets.text(\"model_name\", \"baseline_model\")\nmodel_name = dbutils.widgets.get(\"model_name\")\n\n# Create dropdown\n\ndbutils.widgets.dropdown(\"environment\", \"dev\", [\"dev\", \"staging\", \"prod\"])\nenvironment = dbutils.widgets.get(\"environment\")\n\n# Create multi-select\n\ndbutils.widgets.multiselect(\"features\", \"feat1\", [\"feat1\", \"feat2\", \"feat3\"])\nselected_features = dbutils.widgets.get(\"features\").split(\",\")\n\n# Remove all widgets\n\ndbutils.widgets.removeAll()\n```\n\n### **File System Access**\n\n```python\n# Files governed by Unity Catalog live in volumes:\n# /Volumes/<catalog>/<schema>/<volume>/<path>\n\n# List files\n\ndbutils.fs.ls(\"/Volumes/ml_dev/churn/raw_files\")\n\n# Create directory\n\ndbutils.fs.mkdirs(\"/Volumes/ml_dev/churn/raw_files/models\")\n\n# Remove files\n\ndbutils.fs.rm(\"/Volumes/ml_dev/churn/raw_files/old_data\", recurse=True)\n```\n\n> [!note] Platform update (Oct 2026)\n> Older study material shows `dbutils.fs.mount(...)` with storage keys. Databricks now documents **DBFS mounts as a deprecated pattern** that is not compatible with serverless compute, and recommends Unity Catalog external locations instead ([Mounting cloud object storage](https://docs.databricks.com/aws/en/dbfs/mounts)).\n\n## Collaboration Features\n\n### **Git Folders for Version Control**\n\n```mermaid\nflowchart LR\n    GitHub[\"GitHub/GitLab\"]\n    Repos[\"Databricks Git folder\"]\n    Notebooks[\"Notebooks\"]\n\n    GitHub <-->|Clone/Push/Pull| Repos\n    Repos --> Notebooks\n```\n\n**Git Operations (UI):**\n\n```text\nWorkspace → Create → Git folder → paste repository URL\nGit folder menu → branch selector → create / switch branch\nGit dialog → review diff → commit & push → open a pull request in your Git provider\n```\n\n> [!note] Platform update (Oct 2026)\n> Databricks **Repos** is now called **Git folders** in the docs ([Git folders](https://docs.databricks.com/aws/en/repos/)). Questions or older notes that say \"Repos\" mean the same feature.\n\n### **Shared Notebooks & Folders**\n\n```python\n# Access shared data\n\nimport pandas as pd\ndf = pd.read_csv(\"/Workspace/Shared/datasets/training_data.csv\")\n\n# Write results to shared location\n\nresults_df.to_csv(\"/Workspace/Shared/results/model_metrics.csv\", index=False)\n```\n\n## Notebook Best Practices for ML\n\n### **Initialization Cell**\n\n```python\n# Cell 1: Setup and imports\n\n%python\nimport warnings\nwarnings.filterwarnings(\"ignore\")\n\nimport pandas as pd\nimport numpy as np\nfrom pyspark.sql import functions as F\nfrom pyspark.ml import Pipeline\nfrom sklearn.preprocessing import StandardScaler\nimport mlflow\n\n# Set seed for reproducibility\n\nnp.random.seed(42)\nspark.sparkContext.setCheckpointDir(\"/tmp/checkpoints\")\n\n# Configure display\n\npd.set_option(\"display.max_columns\", None)\n```\n\n### **Data Loading Pattern**\n\n```python\n# Load from Unity Catalog\n\ndf = spark.read.table(\"ml_catalog.training.customer_data\")\n\n# Convert to Pandas for small datasets\n\npdf = df.toPandas()\n\n# Print schema and sample\n\ndf.printSchema()\ndisplay(df.limit(5))\n```\n\n### **Visualization**\n\n```python\n# Using Databricks display() function\n\nimport matplotlib.pyplot as plt\n\nfig, ax = plt.subplots(figsize=(10, 6))\nax.scatter(X[\"feature1\"], X[\"feature2\"], alpha=0.6)\nax.set_xlabel(\"Feature 1\")\nax.set_ylabel(\"Feature 2\")\nplt.title(\"Feature Distribution\")\ndisplay(fig)\n\n# Direct display of DataFrames\n\ndisplay_df = spark.read.table(\"my_table\")\ndisplay(display_df)\n```\n\n## Access Control & Security\n\n### **Workspace Access Levels**\n\n| Role | Permissions | Use Case |\n|------|---|---|\n| **Viewer** | Read-only access | Stakeholders reviewing results |\n| **Editor** | Create/modify notebooks | Data scientists, engineers |\n| **Admin** | Full workspace management | Workspace administrators |\n\n### **Managing Permissions**\n\nNotebook permissions are set from the notebook's **Share** dialog (or the Permissions API). The levels are cumulative ([Access control lists](https://docs.databricks.com/aws/en/security/auth/access-control/)):\n\n| Level | Adds |\n| :--- | :--- |\n| **CAN VIEW** (API: `CAN_READ`) | View cells, comment, run via `%run` |\n| **CAN RUN** | Attach/detach compute and run commands |\n| **CAN EDIT** | Edit cells |\n| **CAN MANAGE** | Change permissions |\n\n## Comparison: Databricks Notebooks vs Jupyter\n\n| Aspect | Databricks Notebooks | Jupyter |\n|--------|---|---|\n| **Collaboration** | Real-time, built-in | Limited (requires third-party) |\n| **Compute** | Integrated clusters | Manual kernel management |\n| **Version Control** | Git folders (native Git integration) | External git only |\n| **UI/UX** | Cloud-native interface | Browser-based |\n| **Secrets Management** | Built-in secrets store | Manual/external |\n| **Multi-language** | Python, SQL, Scala, R | Kernels only |\n| **Debugging** | Full debugger support | Basic debugging |\n\n## Real-World Scenario\n\n**Building a Customer Churn Model:**\n\n```python\n%md\n# Customer Churn Prediction Model\n\nTeam: Data Science\nDate: 2025-02-20\n\n%python\n# Load data\n\ndf = spark.read.table(\"production.customer_analytics.customer_data\")\n\n# Explore & prepare\n\ndf.groupBy(\"churn\").count().show()\n\n# Build model\n\nfrom pyspark.ml import Pipeline\nfrom pyspark.ml.feature import VectorAssembler\nfrom pyspark.ml.classification import LogisticRegression\n\npipeline = Pipeline(stages=[\n    VectorAssembler(inputCols=[\"age\", \"balance\", \"tenure\"], outputCol=\"features\"),\n    LogisticRegression(labelCol=\"churn\")\n])\n\n# Share with team\n\ndisplay(df.limit(10))\n\n# Save to shared location\n\ndf.write.mode(\"overwrite\").saveAsTable(\"ml_staging.churn_model_data\")\n```\n\n## Use Cases\n\n- **Databricks ML Workspace & Notebooks Implementation**: Incorporating Databricks ML Workspace & Notebooks principles to build scalable and maintainable solutions in Databricks environments.\n- **Shared Notebook Environment for Team Collaboration**: Multiple data scientists working in the same workspace, using shared folders and Git folders to collaboratively develop and review ML experiments.\n\n## Common Issues & Errors\n\n### Notebook Cannot Read a Unity Catalog Table\n\n**Scenario:** `spark.read.table(\"ml_dev.churn.customers\")` fails with a permission error from a notebook.\n**Fix:** Check `USE CATALOG`, `USE SCHEMA`, and `SELECT` grants for your identity, and attach the notebook to compute whose access mode supports Unity Catalog (Dedicated for ML runtimes).\n\n### Notebook Cannot Access MLflow Experiment\n\n**Scenario:** `mlflow.start_run()` fails because the experiment doesn't exist or the user lacks permissions.\n**Fix:** Create the experiment first with `mlflow.create_experiment()` or verify workspace permissions on the experiment folder.\n\n## Exam Tips\n\n- ✅ Understand workspace hierarchy: workspace → folders → notebooks\n- ✅ Know magic commands and their uses (`%python`, `%sql`, `%md`, `%sh`)\n- ✅ Recognize the difference between Unity Catalog volumes, legacy DBFS paths, and workspace folders\n- ✅ Understand access controls and sharing notebooks\n- ✅ Remember widgets for parameterizing notebooks\n- ✅ Understand the purpose of Git folders (formerly Repos) for version control\n\n## Key Takeaways\n\n- Databricks notebooks provide interactive, multi-language development environment\n- Collaboration is built-in with real-time editing and comment support\n- Git integration via Git folders (formerly Repos) enables version control\n- Fine-grained access control supports team workflows\n- Unity Catalog volumes (not legacy DBFS mounts) are the governed place for files\n- Widgets enable notebook parameterization for reusability\n\n## Related Topics\n\n- [Compute Clusters for ML](./02-compute-clusters-ml.md)\n- [Databricks AutoML](./03-databricks-automl.md)\n- [MLflow Tracking](./05-mlflow-tracking.md)\n- [MLOps Strategy](./08-mlops-strategy.md)\n\n## Official Documentation\n\n- [Databricks Workspace](https://docs.databricks.com/aws/en/workspace/)\n- [Notebooks Guide](https://docs.databricks.com/aws/en/notebooks/)\n- [Git folders](https://docs.databricks.com/aws/en/repos/)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Compute Clusters for ML →](./02-compute-clusters-ml.md)**\n"},{"id":"01-databricks-machine-learning/02-compute-clusters-ml","folder":"01-databricks-machine-learning","group":"modulo","order":2,"isIndex":false,"title":"Compute Clusters for ML","md":"# Compute Clusters for ML\n\n## Overview\n\nClusters are the compute backbone for machine learning workloads. Databricks provides flexible, auto-scaling clusters optimized for different ML workflows — and the **Databricks Runtime for Machine Learning** (ML runtime) that the exam guide asks you to justify.\n\n> [!abstract]\n>\n> - The **ML runtime** ships a pre-built, version-tested ML stack (popular ML/DL libraries, MLflow, AutoML) on top of the standard Databricks Runtime\n> - GPU ML runtimes add GPU drivers and GPU-enabled deep-learning libraries for GPU instance types\n> - Single-node compute suits pandas / scikit-learn work; multi-node compute suits distributed Spark ML and distributed tuning\n> - To read Unity Catalog data from an ML runtime cluster, use **Dedicated** access mode\n\n> [!tip] What the Exam Tests\n>\n> - *Identify the advantages of using ML runtimes* — no manual library installs, compatible versions, MLflow + AutoML ready, GPU variants\n> - Choosing single-node vs multi-node vs GPU compute for a described workload\n> - Cost levers: autoscaling, auto-termination, job compute vs all-purpose compute\n\n---\n\n## Advantages of the Databricks Runtime for ML\n\n| Advantage | What it means in practice |\n| :--- | :--- |\n| **Pre-built ML infrastructure** | The ML runtime \"automates the creation of a compute resource with pre-built machine learning and deep learning infrastructure\" — no init scripts to assemble a stack |\n| **Popular libraries pre-installed and version-tested** | ML and deep-learning libraries plus MLflow are included — e.g. Databricks Runtime 17.3 LTS ML lists scikit-learn, PyTorch, TensorFlow, transformers, and MLflow as top-tier libraries, with XGBoost, LightGBM, Optuna, Ray, and the Feature Engineering client in its library tables |\n| **MLflow + Databricks Autologging ready** | Databricks Autologging is available on Databricks Runtime 10.4 LTS ML and above, capturing params, metrics, and models for supported frameworks |\n| **AutoML entry point** | AutoML runs on ML-runtime compute (see the platform note in [Databricks AutoML](./03-databricks-automl.md) for newer runtimes) |\n| **GPU variants** | Selecting a GPU instance type gives a GPU-enabled ML runtime with the drivers and GPU builds of deep-learning libraries |\n| **Performance options** | Photon and Graviton instances can speed up Spark DataFrame feature engineering and libraries such as XGBoost/LightGBM |\n\nSources: [Databricks Runtime for Machine Learning](https://docs.databricks.com/aws/en/machine-learning/databricks-runtime-ml), [Databricks Runtime 17.3 LTS ML release notes](https://docs.databricks.com/aws/en/release-notes/runtime/17.3lts-ml), [Databricks Autologging](https://docs.databricks.com/aws/en/mlflow/databricks-autologging).\n\n> [!note] Platform update (Oct 2026)\n> To access Unity Catalog data from ML-runtime compute, the docs require **Dedicated** access mode (formerly called single-user; it can be assigned to a user or a group). For GPU deep learning, the docs now also point to **AI Runtime**, a serverless GPU compute offering ([Databricks Runtime for Machine Learning](https://docs.databricks.com/aws/en/machine-learning/databricks-runtime-ml)).\n\n## Cluster Architecture\n\n```mermaid\nflowchart TB\n    subgraph Driver[\"Driver Node\"]\n        Coord[\"Coordinator\"]\n        Scheduler[\"Task Scheduler\"]\n    end\n\n    subgraph Workers[\"Worker Nodes\"]\n        W1[\"Worker 1\"]\n        W2[\"Worker 2\"]\n        W3[\"Worker 3\"]\n    end\n\n    subgraph Storage[\"Storage\"]\n        Delta[\"Delta Lake\"]\n        Cache[\"Cache\"]\n    end\n\n    Coord --> W1\n    Coord --> W2\n    Coord --> W3\n    Scheduler --> W1\n    Scheduler --> W2\n    Scheduler --> W3\n    Workers --> Storage\n\n    style Driver fill:#e1f5ff\n    style Workers fill:#f3e5f5\n```\n\n## Cluster Types\n\n### **All-Purpose Clusters**\n\nUsed for interactive development and shared workloads.\n\n```python\n# Create all-purpose cluster via API\n\ncluster_config = {\n    \"cluster_name\": \"ml-dev-cluster\",\n    \"spark_version\": \"14.3.x-scala2.12\",\n    \"node_type_id\": \"i3.xlarge\",\n    \"driver_node_type_id\": \"i3.xlarge\",\n    \"num_workers\": 4,\n    \"aws_attributes\": {\n        \"availability\": \"SPOT\",\n        \"zone_id\": \"us-west-2a\"\n    },\n    \"autoscale\": {\n        \"min_workers\": 2,\n        \"max_workers\": 8\n    }\n}\n\n# Features\n# - Supports multiple users\n# - Long-running sessions\n# - Supports all Spark workloads\n# - Good for development\n\n```\n\n**Use Cases:**\n\n- Interactive development\n- Data exploration\n- Ad-hoc analysis\n- Shared team work\n\n### **Job Clusters**\n\nDedicated clusters for scheduled jobs, automatically terminated after job completion.\n\n```python\n# Job cluster configuration\n\njob_config = {\n    \"name\": \"model_training_job\",\n    \"new_cluster\": {\n        \"spark_version\": \"14.3.x-scala2.12\",\n        \"node_type_id\": \"i3.xlarge\",\n        \"num_workers\": 8,\n        \"aws_attributes\": {\n            \"availability\": \"SPOT\"\n        }\n    },\n    \"spark_python_task\": {\n        \"python_file\": \"dbfs:/ml/train_model.py\",\n        \"parameters\": [\"--epochs=100\", \"--batch_size=32\"]\n    },\n    \"timeout_seconds\": 3600,\n    \"max_concurrent_runs\": 1\n}\n\n# Benefits\n# - Cost-effective (auto-terminate)\n# - Isolated environments\n# - Consistent infrastructure\n# - Better for production jobs\n\n```\n\n**Use Cases:**\n\n- Model training pipelines\n- Batch processing\n- Scheduled experiments\n- Production inference\n\n### **SQL Warehouses**\n\nSpecialized compute for SQL queries without creating clusters.\n\n```sql\n-- SQL Warehouse configuration\n-- Type: Pro or Serverless\n-- Auto-scaling: 2-4 endpoints\n-- Query timeout: 60 minutes\n-- Use for: BI, analytics, dashboards\n\nSELECT * FROM ml_catalog.models.predictions\nWHERE prediction_date = CURRENT_DATE()\nORDER BY confidence DESC\nLIMIT 100;\n```\n\n**Characteristics:**\n\n- Optimized for SQL workloads\n- No cluster management\n- Automatic scaling\n- Cost per DBU used\n\n## Cluster Configuration for ML\n\n### **Optimal Settings for Machine Learning**\n\n```python\nml_cluster_config = {\n    # Compute sizing\n    \"num_workers\": 4,  # or use autoscale\n    \"node_type_id\": \"i3.xlarge\",  # Memory-optimized for ML\n    \"driver_node_type_id\": \"i3.xlarge\",  # Same as workers\n\n    # Runtime\n    \"spark_version\": \"14.3.x-cpu-ml-scala2.12\",  # ML runtime (CPU); GPU variant: 14.3.x-gpu-ml-scala2.12\n    \"runtime_engine\": \"PHOTON\",  # Photon = vectorized query engine on CPU (not GPU acceleration)\n\n    # Autoscaling\n    \"autoscale\": {\n        \"min_workers\": 2,\n        \"max_workers\": 16\n    },\n\n    # Spot instances for cost savings\n    \"aws_attributes\": {\n        \"availability\": \"SPOT\",\n        \"zone_id\": \"us-west-2a\"\n    },\n\n    # Performance tuning\n    \"spark_conf\": {\n        \"spark.databricks.adaptive.execution.enabled\": \"true\",\n        \"spark.sql.adaptive.skewJoin.enabled\": \"true\",\n        \"spark.databricks.delta.optimizeWrite.enabled\": \"true\"\n    }\n}\n```\n\n## Instance Types for ML\n\n| Instance Type | Memory | Use Case | Cost |\n|---|---|---|---|\n| **i3.xlarge** | 30.5 GB | General ML | Medium |\n| **i3.2xlarge** | 61 GB | Large models | Medium-High |\n| **i3en.3xlarge** | 96 GB | Memory/storage-heavy ML (no GPU) | High |\n| **g4dn.xlarge** | 16 GB + 1 GPU | Deep Learning | Very High |\n| **p3.2xlarge** | 61 GB + V100 | Large-scale DL | Very High |\n\n**Selection Guide:**\n\n- Small experiments: `i3.xlarge`\n- Large datasets: `i3.2xlarge` or `i3en.3xlarge` (CPU only)\n- GPU-based ML: `g4dn` or `p3` series\n- Budget-conscious: Use SPOT instances (up to 90% savings)\n\n## Cluster Lifecycle Management\n\n### **Initialization Scripts**\n\n```python\n# Install custom libraries on cluster startup\n\ninit_script = \"\"\"\n#!/bin/bash\n/databricks/python/bin/pip install --upgrade xgboost lightgbm\n/databricks/python/bin/pip install optuna hyperopt\n\"\"\"\n\n# Configuration\n\ninit_config = {\n    \"init_scripts\": [{\n        \"dbfs\": {\n            \"destination\": \"dbfs:/init-scripts/ml-setup.sh\"\n        }\n    }]\n}\n```\n\n### **Auto-Termination**\n\n```python\ncluster_config = {\n    \"autotermination_minutes\": 30,  # Auto-stop after 30 mins idle\n    \"enable_elastic_disk\": True,  # Dynamically resize storage\n    \"cluster_log_conf\": {\n        \"dbfs\": {\n            \"destination\": \"dbfs:/logs/ml-cluster/\"\n        }\n    }\n}\n```\n\n## Scaling Strategy for ML\n\n### **Manual vs Auto-Scaling**\n\n```python\n# MANUAL SCALING\n\nmanual_config = {\n    \"num_workers\": 8,  # Fixed\n    \"autoscale\": None\n}\n\n# AUTOSCALING\n\nauto_config = {\n    \"autoscale\": {\n        \"min_workers\": 2,\n        \"max_workers\": 16\n    },\n    \"aws_attributes\": {\n        \"availability\": \"SPOT\"\n    }\n}\n\n# When to use MANUAL:\n# - Predictable workloads\n# - Cost control needed\n# - Long-running processes\n\n# When to use AUTOSCALING:\n# - Variable workload sizes\n# - Handle traffic spikes\n# - Optimize cost with SPOT instances\n\n```\n\n## Performance Tuning Parameters\n\n```python\nspark_configs = {\n    # Adaptive Query Execution\n    \"spark.databricks.adaptive.execution.enabled\": \"true\",\n    \"spark.sql.adaptive.skewJoin.enabled\": \"true\",\n    \"spark.sql.adaptive.coalescePartitions.enabled\": \"true\",\n\n    # Memory Management\n    \"spark.memory.fraction\": 0.6,  # 60% for execution\n    \"spark.memory.storageFraction\": 0.5,  # 50% for cache\n\n    # Shuffle Optimization\n    \"spark.shuffle.partitions\": 200,  # Based on data size\n    \"spark.sql.shuffle.partitions\": 200,\n\n    # Delta Optimization\n    \"spark.databricks.delta.optimizeWrite.enabled\": \"true\",\n    \"spark.databricks.delta.autoCompact.enabled\": \"true\",\n}\n\n# MLflow autologging is not a Spark conf: Databricks Autologging is available on\n# Databricks Runtime 10.4 LTS ML and above, and an admin can switch it on/off\n# for the workspace. In a notebook, opt out with mlflow.autolog(disable=True).\n```\n\n## Cost Optimization Strategies\n\n### **Tier-Down Approach**\n\n```mermaid\nflowchart TD\n    Dev[\"Development<br/>All-Purpose<br/>1-2 Workers<br/>SPOT\"] --> Test[\"Testing<br/>All-Purpose<br/>4 Workers<br/>SPOT\"]\n    Test --> Prod[\"Production<br/>Job Cluster<br/>8-16 Workers<br/>ON-DEMAND\"]\n\n    style Dev fill:#c8e6c9\n    style Test fill:#fff9c4\n    style Prod fill:#ffccbc\n```\n\n### **Cost Calculation**\n\n```python\n\n# Cost = DBU/hour × hours used × node count\n# Example:\n# - Cluster: 4 workers @ i3.xlarge (8 DBU/hour each)\n# - Usage: 2 hours\n# - Total: 8 × 2 × 4 = 64 DBUs\n# - Cost: 64 × $0.40 = $25.60\n\ndef calculate_cluster_cost(num_workers, hours, price_per_dbu):\n    dbu_per_worker = 8  # i3.xlarge\n    total_dbu = num_workers * dbu_per_worker * hours\n    return total_dbu * price_per_dbu\n```\n\n## Real-World Example: ML Training Cluster\n\n```python\n%python\nfrom databricks.sdk import WorkspaceClient\n\n# Initialize client\n\nw = WorkspaceClient()\n\n# Create optimized ML training cluster\n\ncluster_create_request = {\n    \"cluster_name\": \"ml_training_prod\",\n    \"spark_version\": \"14.3.x-cpu-ml-scala2.12\",\n    \"num_workers\": 8,\n    \"node_type_id\": \"i3.2xlarge\",\n    \"driver_node_type_id\": \"i3.2xlarge\",\n    \"spark_conf\": {\n        \"spark.databricks.adaptive.execution.enabled\": \"true\",\n        \"spark.databricks.delta.optimizeWrite.enabled\": \"true\"\n    },\n    \"aws_attributes\": {\n        \"availability\": \"SPOT_WITH_FALLBACK\",\n        \"zone_id\": \"us-west-2a\"\n    },\n    \"autotermination_minutes\": 30,\n    \"enable_elastic_disk\": True,\n    \"data_security_mode\": \"SINGLE_USER\",  # Dedicated access mode for UC data on an ML runtime\n    \"single_user_name\": \"ml-team@company.com\",\n    \"init_scripts\": [{\n        \"workspace\": {\n            \"destination\": \"/Workspace/Shared/init-scripts/ml-requirements.sh\"\n        }\n    }]\n}\n\n# Create cluster through the Clusters REST API (raw JSON body)\n\nresp = w.api_client.do(\"POST\", \"/api/2.1/clusters/create\", body=cluster_create_request)\nprint(f\"Created cluster: {resp['cluster_id']}\")\n```\n\n## Comparison: Cluster Types for ML\n\n| Aspect | All-Purpose | Job Cluster | SQL Warehouse |\n|--------|---|---|---|\n| **Cost** | Medium | Low | High |\n| **Startup Time** | 5-10 min | ~5 min | Immediate |\n| **Users** | Multiple | Single/Batch | Multiple |\n| **Auto-termination** | Manual | Automatic | N/A |\n| **Python Support** | ✓ | ✓ | Limited |\n| **SQL Support** | ✓ | ✓ | ✓ |\n| **Best For** | Development | Production | Analytics |\n\n## Use Cases\n\n- **Compute Clusters for ML Implementation**: Incorporating Compute Clusters for ML principles to build scalable and maintainable solutions in Databricks environments.\n- **Cost-Optimized Training with Spot Instances**: Using autoscaling clusters with SPOT instances to run large-scale hyperparameter sweeps while minimizing cloud compute costs.\n\n## Common Issues & Errors\n\n### ML Libraries Missing on the Cluster\n\n**Scenario:** `import xgboost` or `from databricks import automl` fails in a notebook.\n**Fix:** The cluster is on the standard runtime. Switch to a Databricks Runtime ML version (AutoML is not built in from Databricks Runtime 18.0 ML), rather than installing a stack by hand with init scripts.\n\n### GPU Cluster Out of Memory\n\n**Scenario:** Training job crashes with `CUDA out of memory` on a GPU cluster.\n**Fix:** Reduce batch size, use gradient accumulation, or select a node type with more GPU memory (e.g., A10G to A100).\n\n## Exam Tips\n\n- ✅ Name the advantages of the ML runtime: pre-installed, version-compatible ML libraries + MLflow + AutoML, GPU variants\n- ✅ Know cluster vs job cluster trade-offs\n- ✅ Understand auto-scaling configuration\n- ✅ Recognize instance types and their use cases\n- ✅ Know how to optimize costs with SPOT instances\n- ✅ Understand initialization scripts for dependencies\n- ✅ Remember idle timeout for cost control\n\n## Key Takeaways\n\n- The ML runtime removes environment setup: ML/DL libraries, MLflow, and AutoML come pre-installed and tested together\n- All-purpose clusters for development, job clusters for production\n- Autoscaling enables cost-effective handling of variable workloads\n- Instance type selection depends on workload (CPU, memory, GPU)\n- SPOT instances can reduce costs by up to 90%\n- Initialization scripts automate dependency management\n- Proper configurations optimize both performance and cost\n\n## Related Topics\n\n- [Databricks ML Workspace](./01-databricks-ml-workspace.md)\n- [Databricks AutoML](./03-databricks-automl.md)\n- [Hyperparameter Tuning](../03-model-development/02-hyperparameter-tuning.md) — parallelising single-node models across a cluster\n\n## Official Documentation\n\n- [Databricks Runtime for Machine Learning](https://docs.databricks.com/aws/en/machine-learning/databricks-runtime-ml)\n- [Compute Configuration](https://docs.databricks.com/aws/en/compute/configure)\n- [Databricks Autologging](https://docs.databricks.com/aws/en/mlflow/databricks-autologging)\n\n---\n\n**[← Previous: Databricks ML Workspace & Notebooks](./01-databricks-ml-workspace.md) | [↑ Back to Section](./README.md) | [Next: Databricks AutoML →](./03-databricks-automl.md)**\n"},{"id":"01-databricks-machine-learning/03-databricks-automl","folder":"01-databricks-machine-learning","group":"modulo","order":3,"isIndex":false,"title":"Databricks AutoML","md":"# Databricks AutoML\n\n## Overview\n\nDatabricks AutoML takes a dataset and a target column, then prepares the data, trains and tunes a set of candidate models, and logs every trial to MLflow. Its output is a **glass-box** baseline: real, editable notebooks that you can read, reproduce, and modify — not a black-box endpoint.\n\n> [!abstract]\n>\n> - Supports **classification**, **regression**, and **forecasting**, from a low-code UI or the Python API (`databricks.automl`)\n> - Each trial is an MLflow run; the **best-trial notebook** and a **data exploration notebook** are imported into the workspace\n> - Classification / regression try decision trees, random forests, linear/logistic regression, XGBoost, and LightGBM; forecasting uses Prophet and Auto-ARIMA\n> - Handles train/validation/test splitting, imputation, and class-imbalance balancing for you\n\n> [!tip] What the Exam Tests\n>\n> - *How AutoML facilitates model / feature selection* — many algorithms + hyperparameters compared on one primary metric; SHAP feature importance in generated notebooks\n> - *The advantages AutoML brings to model development* — fast, reproducible baseline; editable code; everything tracked in MLflow\n> - What AutoML produces and where it lives (MLflow experiment, trial runs, notebooks)\n\n---\n\n## AutoML Workflow\n\n```mermaid\nflowchart TB\n    Start[\"Start AutoML Experiment\"] --> Upload[\"1. Select a Unity Catalog table<br/>(or a DataFrame via the API)\"]\n    Upload --> Target[\"2. Pick the problem type + target<br/>Classification / Regression / Forecasting\"]\n    Target --> Config[\"3. Configure: primary metric,<br/>timeout, excluded columns / frameworks\"]\n    Config --> Auto[\"4. AutoML run\"]\n\n    Auto --> Prep[\"Data prep<br/>split, imputation, balancing\"]\n    Auto --> Trials[\"Trials<br/>algorithms x hyperparameters\"]\n\n    Prep --> Results[\"MLflow experiment<br/>one run per trial\"]\n    Trials --> Results\n\n    Results --> NB[\"Best-trial notebook +<br/>data exploration notebook\"]\n    NB --> Next[\"Register, deploy, or iterate\"]\n\n    style Auto fill:#e3f2fd\n    style Results fill:#c8e6c9\n```\n\n## What AutoML Automates\n\n### **Data preparation**\n\n| Step | Default behaviour (classification / regression) |\n| :--- | :--- |\n| **Split** | Random 60 % train / 20 % validation / 20 % test (stratified for classification) |\n| **Missing values** | Imputation method chosen per column based on type and content; overridable per column |\n| **Imbalanced classes** | Balances **only the training split** — downsamples the majority class and applies class weights; validation/test keep the original distribution |\n| **Large datasets** | Estimates memory and samples the dataset if needed (each trial trains on a single worker node) |\n| **Semantic types** | Best-effort detection (e.g. numeric strings, dates); override with column annotations |\n| **Columns** | All columns included by default; exclude with `exclude_cols` (not the target or time column) |\n\nSource: [Data preparation for classification](https://docs.databricks.com/aws/en/machine-learning/automl/classification-data-prep).\n\n### **Algorithms tried**\n\n| Problem type | Algorithms |\n| :--- | :--- |\n| **Classification** | Decision trees, random forests, logistic regression, XGBoost, LightGBM (scikit-learn / XGBoost / LightGBM implementations) |\n| **Regression** | Decision trees, random forests, linear regression with SGD, XGBoost, LightGBM |\n| **Forecasting** | Prophet, Auto-ARIMA (serverless forecasting also lists DeepAR) |\n\nSource: [What is AutoML?](https://docs.databricks.com/aws/en/machine-learning/automl/).\n\n### **Default primary metrics**\n\n| API | Default `primary_metric` |\n| :--- | :--- |\n| `automl.classify` | `f1` |\n| `automl.regress` | `r2` |\n| `automl.forecast` | `smape` |\n\nSource: [AutoML Python API reference](https://docs.databricks.com/aws/en/machine-learning/automl/automl-api-reference).\n\n## How AutoML Facilitates Model and Feature Selection\n\n- **Model selection** — every algorithm/hyperparameter combination is a trial scored on the *same* primary metric and validation split, so the leaderboard (the MLflow experiment, sorted by metric) shows directly which model family wins\n- **Feature selection** — the trial notebooks include a **Feature importance** section that computes **Shapley (SHAP) values**; it is off by default because it is memory-intensive — set `shap_enabled = True` and re-run the notebook\n- **Feature reuse** — `feature_store_lookups` lets AutoML join Unity Catalog feature tables into the training data, so the baseline uses governed features\n\nSource: [How Databricks AutoML works](https://docs.databricks.com/aws/en/machine-learning/automl/how-automl-works).\n\n## Advantages AutoML Brings to Model Development\n\n| Advantage | Why it matters |\n| :--- | :--- |\n| **Fast baseline** | Minutes to a tuned benchmark instead of days of manual sweeps |\n| **Glass-box code** | Generated notebooks are ordinary Python you can edit, rerun, and productionise |\n| **Reproducible + tracked** | Every trial is an MLflow run with params, metrics, and a logged model |\n| **Sensible defaults** | Splitting, imputation, balancing, and sampling handled consistently |\n| **Low-code access** | Domain experts can produce a baseline from the UI; data scientists refine it |\n\n## Using AutoML via the UI\n\n1. **Create experiment** — from **Experiments** in the sidebar, start a new AutoML experiment and choose the problem type\n2. **Configure** — compute (ML runtime), problem type, input table, prediction target; optionally evaluation metric, excluded frameworks/columns, imputation per column, timeout\n3. **Start** — AutoML runs the trials and shows them in the MLflow experiment\n4. **Review** — sort runs by the primary metric, open the **best-trial notebook** or the **data exploration notebook**, register the best model\n\n## Programmatic AutoML\n\n```python\nfrom databricks import automl\n\ndf = spark.read.table(\"ml_dev.churn.customer_features\")\n\nsummary = automl.classify(\n    dataset=df,\n    target_col=\"churned\",\n    primary_metric=\"f1\",          # default for classify\n    timeout_minutes=30,           # default 120, minimum 5\n    exclude_cols=[\"customer_id\"],\n)\n\nbest = summary.best_trial\nprint(best.metrics)               # validation/test metrics of the best trial\nprint(best.mlflow_run_id)         # MLflow run that holds the model\nprint(best.notebook_url)          # generated notebook for the best trial\n\nmodel = best.load_model()         # load the trial's logged MLflow model\n```\n\n```python\n# Regression and forecasting follow the same pattern\nreg_summary = automl.regress(dataset=housing_df, target_col=\"price\", timeout_minutes=60)\n\nfc_summary = automl.forecast(\n    dataset=sales_df,\n    target_col=\"units\",\n    time_col=\"date\",              # required for forecasting\n    horizon=30,\n    frequency=\"D\",\n)\n```\n\n### **AutoMLSummary and TrialInfo**\n\n| Object | Useful attributes |\n| :--- | :--- |\n| `AutoMLSummary` | `experiment`, `trials`, `best_trial` |\n| `TrialInfo` | `mlflow_run_id`, `metrics`, `params`, `model_path`, `notebook_path` / `notebook_url` (best trial only for classification/regression), `load_model()` |\n\n## AutoML Output & Artifacts\n\n```text\nMLflow experiment (default dir /Users/<you>/databricks_automl/)\n├── Run: trial 1 (e.g. LightGBM)  → params, metrics, model, trial notebook as artifact\n├── Run: trial 2 (e.g. XGBoost)\n├── ...\n├── Best-trial notebook           → imported into the workspace\n└── Data exploration notebook     → imported into the workspace\n```\n\nRegistering the best model is a separate, explicit step:\n\n```python\nimport mlflow\n\nmlflow.set_registry_uri(\"databricks-uc\")\nmlflow.register_model(\n    f\"runs:/{summary.best_trial.mlflow_run_id}/model\",\n    \"ml_dev.churn.churn_classifier\",\n)\n```\n\n> [!note] Platform update (Oct 2026)\n> The AutoML docs now state: \"In Databricks Runtime 18.0 ML or above, AutoML is not included as a built-in library,\" and AutoML depends on the `databricks-automl-runtime` package. The exam guide (Mar 1, 2025 exam version) still tests AutoML — learn the concepts above; when practising, use an ML runtime where AutoML is available ([What is AutoML?](https://docs.databricks.com/aws/en/machine-learning/automl/)).\n\n## Best Practices for AutoML\n\n- Start from a clean Unity Catalog table; drop leakage columns (IDs, post-outcome fields) with `exclude_cols`\n- Pick the **primary metric that matches the business goal** (e.g. `f1` or `log_loss` for imbalanced classes, not accuracy)\n- Treat the output as a **baseline** — validate the best model on held-out data and review the generated notebook before production\n- Enable SHAP in the best-trial notebook to check that the most important features make domain sense\n- Use `feature_store_lookups` instead of ad-hoc joins so training and serving share feature definitions\n\n## Comparison: AutoML vs Manual ML\n\n| Aspect | AutoML | Manual |\n| :--- | :--- | :--- |\n| **Time to baseline** | Minutes–hours | Days–weeks |\n| **Algorithm + hyperparameter search** | Automated, logged to MLflow | Hand-written sweeps |\n| **Code visibility** | Generated, editable notebooks | Your own code |\n| **Customisation** | Limited to API/UI options, then edit notebooks | Full control |\n| **Best for** | Baselines, benchmarking, citizen data science | Complex, domain-specific pipelines |\n\n## Use Cases\n\n- **Rapid Baseline Model Generation**: Running AutoML on a new churn table to establish an F1 benchmark before investing in custom feature engineering.\n- **Feature Triage**: Using SHAP values in the best-trial notebook to decide which engineered features are worth keeping.\n\n## Common Issues & Errors\n\n### AutoML Not Available on the Cluster\n\n**Scenario:** `from databricks import automl` fails or the AutoML UI is unavailable.\n**Fix:** Use an ML runtime cluster with a supported access mode (Dedicated supports AutoML + Unity Catalog; Standard does not support AutoML). On Databricks Runtime 18.0 ML and above, AutoML is no longer built in.\n\n### AutoML Run Produces Poor Results\n\n**Scenario:** The best model's metric is low compared with expectations.\n**Fix:** Check data quality and leakage, choose a metric suited to the class balance, increase `timeout_minutes` so more trials run, or add better features via `feature_store_lookups`.\n\n## Exam Tips\n\n- ✅ Three problem types only: classification, regression, forecasting (no clustering)\n- ✅ Every trial = an MLflow run; best-trial + data exploration notebooks are imported into the workspace\n- ✅ SHAP feature importance is in the generated notebook but **off by default**\n- ✅ AutoML balances only the **training** split; validation/test keep the real distribution\n- ✅ AutoML does **not** auto-register or auto-deploy the model\n- ✅ Forecasting needs a `time_col`\n\n## Key Takeaways\n\n- AutoML is a glass-box accelerator: it produces editable code, not a sealed model\n- It automates splitting, imputation, balancing, algorithm choice, and hyperparameter search\n- Model selection happens by comparing trials on one primary metric in MLflow\n- Feature selection is supported through SHAP importance in the generated notebooks\n- Registration and deployment remain explicit, governed steps\n\n## Related Topics\n\n- [Compute Clusters for ML](./02-compute-clusters-ml.md)\n- [MLflow Tracking](./05-mlflow-tracking.md)\n- [Model Registry in Unity Catalog](./07-model-registry.md)\n- [Hyperparameter Tuning](../03-model-development/02-hyperparameter-tuning.md)\n\n## Official Documentation\n\n- [What is AutoML?](https://docs.databricks.com/aws/en/machine-learning/automl/)\n- [How Databricks AutoML works](https://docs.databricks.com/aws/en/machine-learning/automl/how-automl-works)\n- [Data preparation for classification](https://docs.databricks.com/aws/en/machine-learning/automl/classification-data-prep)\n- [AutoML Python API reference](https://docs.databricks.com/aws/en/machine-learning/automl/automl-api-reference)\n\n---\n\n**[← Previous: Compute Clusters for ML](./02-compute-clusters-ml.md) | [↑ Back to Section](./README.md) | [Next: Feature Store in Unity Catalog →](./04-feature-store.md)**\n"},{"id":"01-databricks-machine-learning/04-feature-store","folder":"01-databricks-machine-learning","group":"modulo","order":4,"isIndex":false,"title":"Feature Store in Unity Catalog","md":"# Feature Store in Unity Catalog\n\n## Overview\n\nIn a Unity Catalog-enabled workspace, the Databricks Feature Store *is* **Feature Engineering in Unity Catalog**: any Delta table with a primary key can be a feature table, governed by Unity Catalog and used through the `FeatureEngineeringClient`. The exam guide places every feature-table skill in Section 1 (Databricks Machine Learning, 38 %).\n\n> [!abstract]\n>\n> - A **feature table** is a Unity Catalog Delta table with a **primary key** (plus an optional time-series key for point-in-time joins)\n> - Create with `FeatureEngineeringClient.create_table(...)` or SQL `CREATE TABLE ... CONSTRAINT ... PRIMARY KEY`; write with `write_table(..., mode=\"merge\")`\n> - Train with `FeatureLookup` + `create_training_set` + `fe.log_model`; score with `fe.score_batch`\n> - **Offline** feature tables serve training and batch scoring; an **online store** serves low-latency lookups to real-time endpoints\n\n> [!tip] What the Exam Tests\n>\n> - The benefits of account-level (Unity Catalog) feature tables over legacy workspace-level ones\n> - The *correct creation path* in UC — `FeatureEngineeringClient.create_table`, not `FeatureStoreClient` or an invented SQL clause\n> - Writing, training, and scoring with feature tables, and the difference between online and offline feature tables\n\n---\n\n## Unity Catalog vs Workspace Feature Store\n\nUnity Catalog's metastore is attached at the **account** level, so feature tables registered there are shared by every workspace attached to that metastore. The legacy **Workspace Feature Store** kept feature tables inside a single workspace.\n\n| Aspect | Feature tables in Unity Catalog (account level) | Workspace Feature Store (legacy) |\n| :--- | :--- | :--- |\n| **Scope** | Any workspace attached to the metastore — cross-workspace feature sharing and discovery | One workspace |\n| **Governance** | Unity Catalog privileges (`SELECT`, `MODIFY`, ownership) on `catalog.schema.table` | Workspace ACLs |\n| **Lineage** | Lineage between feature tables, models, and functions in Unity Catalog | Limited |\n| **Naming** | Three-level `catalog.schema.table` | `database.table` |\n| **Python client** | `databricks.feature_engineering.FeatureEngineeringClient` | `databricks.feature_store.FeatureStoreClient` |\n| **Status** | Current | Docs label it \"Workspace Feature Store (deprecated)\" |\n\nSource: [Feature management](https://docs.databricks.com/aws/en/machine-learning/feature-store/) — registering features and models in Unity Catalog gives \"built-in governance, lineage, point-in-time joins, and cross-workspace feature sharing and discovery.\"\n\n```mermaid\nflowchart LR\n    subgraph Account[\"Databricks account\"]\n        UC[(\"Unity Catalog metastore<br/>ml_prod.features.customer_features\")]\n    end\n    W1[\"Workspace A<br/>(training)\"] --> UC\n    W2[\"Workspace B<br/>(batch scoring)\"] --> UC\n    UC --> OS[\"Online store<br/>(real-time lookups)\"]\n```\n\n## Creating a Feature Table\n\n### **Python: `FeatureEngineeringClient.create_table`**\n\n```python\nfrom databricks.feature_engineering import FeatureEngineeringClient\nfrom pyspark.sql import functions as F\n\nfe = FeatureEngineeringClient()\n\ncustomer_features_df = (spark.read.table(\"ml_dev.raw.transactions\")\n    .groupBy(\"customer_id\")\n    .agg(\n        F.count(\"*\").alias(\"txn_count_90d\"),\n        F.sum(\"amount\").alias(\"spend_90d\"),\n        F.avg(\"amount\").alias(\"avg_txn_amount\"),\n    ))\n\n# Passing df= creates the table AND writes the data\nfe.create_table(\n    name=\"ml_dev.features.customer_features\",\n    primary_keys=[\"customer_id\"],          # required\n    df=customer_features_df,\n    description=\"Customer spend aggregates (90-day window)\",\n)\n```\n\n- `primary_keys` is required; you must pass **either** `df` (create + populate) **or** `schema` (create empty)\n- The Python client is pre-installed on Databricks Runtime 13.3 LTS ML and above\n\n### **SQL: any Delta table with a primary key**\n\n```sql\nCREATE TABLE ml_dev.features.customer_features (\n  customer_id INT NOT NULL,\n  txn_count_90d BIGINT,\n  spend_90d DOUBLE,\n  CONSTRAINT customer_features_pk PRIMARY KEY (customer_id)\n);\n\n-- An existing table: make the key NOT NULL, then add the constraint\nALTER TABLE ml_dev.features.store_features ALTER COLUMN store_id SET NOT NULL;\nALTER TABLE ml_dev.features.store_features\n  ADD CONSTRAINT store_features_pk PRIMARY KEY (store_id);\n```\n\n> [!warning] Common Mistake\n> There is **no** `AS FEATURE STORE` or `SET AS FEATURE STORE` SQL clause, and `FeatureStoreClient.register_table` is not the Unity Catalog creation path. In UC, a feature table is simply a Delta table with a primary key constraint, created in SQL or with `FeatureEngineeringClient.create_table`.\n\nSource: [Work with feature tables in Unity Catalog](https://docs.databricks.com/aws/en/machine-learning/feature-store/uc/feature-tables-uc).\n\n## Writing Data to a Feature Table\n\n```python\n# Upsert new / changed rows by primary key\nfe.write_table(\n    name=\"ml_dev.features.customer_features\",\n    df=updated_features_df,\n    mode=\"merge\",        # the only supported mode\n)\n```\n\n| Behaviour | Detail |\n| :--- | :--- |\n| `mode=\"merge\"` | Upserts rows by primary key; rows whose key is **not** in the DataFrame stay unchanged |\n| Overwrite | Not a `write_table` mode in `FeatureEngineeringClient` — delete rows (`DELETE FROM`) or drop/recreate the table first |\n| Streaming | `write_table` accepts a streaming DataFrame (with `checkpoint_location` / `trigger`) |\n| Plain Delta writes | Because it is a Delta table, `MERGE INTO` or a Lakeflow pipeline can also maintain it |\n\nSources: [Work with feature tables in Unity Catalog](https://docs.databricks.com/aws/en/machine-learning/feature-store/uc/feature-tables-uc), [Feature Engineering Python API](https://api-docs.databricks.com/python/feature-engineering/latest/feature_engineering.client.html).\n\n## Training a Model with Feature Table Features\n\n```python\nimport mlflow\nfrom databricks.feature_engineering import FeatureEngineeringClient, FeatureLookup\nfrom sklearn.ensemble import RandomForestClassifier\n\nfe = FeatureEngineeringClient()\nmlflow.set_registry_uri(\"databricks-uc\")\n\n# Label table: keys + label (+ optional event timestamp)\nlabels_df = spark.read.table(\"ml_dev.churn.labels\")   # customer_id, churned\n\nfeature_lookups = [\n    FeatureLookup(\n        table_name=\"ml_dev.features.customer_features\",\n        lookup_key=\"customer_id\",                     # column in labels_df that matches the PK\n        feature_names=[\"txn_count_90d\", \"spend_90d\", \"avg_txn_amount\"],\n    ),\n]\n\ntraining_set = fe.create_training_set(\n    df=labels_df,\n    feature_lookups=feature_lookups,\n    label=\"churned\",\n    exclude_columns=[\"customer_id\"],\n)\ntrain_pdf = training_set.load_df().toPandas()\n\nX, y = train_pdf.drop(\"churned\", axis=1), train_pdf[\"churned\"]\nmodel = RandomForestClassifier(n_estimators=200).fit(X, y)\n\n# Log WITH feature metadata so scoring can look features up automatically\nfe.log_model(\n    model=model,\n    artifact_path=\"model\",\n    flavor=mlflow.sklearn,\n    training_set=training_set,\n    registered_model_name=\"ml_dev.churn.churn_classifier\",\n)\n```\n\n### **Point-in-time lookups**\n\nWhen a feature table has a time-series key, pass `timestamp_lookup_key` in the `FeatureLookup`. Each label row then gets the feature values **as of its event timestamp**, which prevents leakage of future information. A timestamp column must not be used as a plain `lookup_key`. See [Point-in-time feature joins](https://docs.databricks.com/aws/en/machine-learning/feature-store/time-series).\n\n```python\nFeatureLookup(\n    table_name=\"ml_dev.features.customer_daily_features\",\n    lookup_key=\"customer_id\",\n    timestamp_lookup_key=\"event_ts\",   # column in the label DataFrame\n)\n```\n\nSource: [Use features to train models](https://docs.databricks.com/aws/en/machine-learning/feature-store/train-models-with-feature-store).\n\n## Scoring a Model with Feature Table Features\n\n```python\n# The scoring DataFrame only needs the lookup keys (+ any non-feature-table inputs)\nbatch_df = spark.read.table(\"ml_dev.churn.customers_to_score\")   # customer_id\n\npredictions = fe.score_batch(\n    model_uri=\"models:/ml_dev.churn.churn_classifier@champion\",\n    df=batch_df,\n)\n(predictions.select(\"customer_id\", \"prediction\")\n    .write.mode(\"overwrite\")\n    .saveAsTable(\"ml_dev.churn.daily_predictions\"))\n```\n\n- `score_batch` reads the feature metadata packaged by `fe.log_model`, **joins the features automatically**, and applies the model — the same feature definitions as training, so no training-serving skew\n- Plain MLflow `pyfunc` batch inference does not support time-series feature tables; use `score_batch` for those\n\n## Online vs Offline Feature Tables\n\n| | Offline feature table | Online store |\n| :--- | :--- | :--- |\n| **What it is** | The Unity Catalog Delta table you created | A low-latency copy published from the offline table |\n| **Used for** | Training sets, batch scoring (`create_training_set`, `score_batch`) | Real-time model serving endpoints and online applications |\n| **Access pattern** | Large scans and joins | Key-based lookups in milliseconds |\n| **Freshness** | Whenever the table is written | Published `SNAPSHOT`, `TRIGGERED` (default), or `CONTINUOUS` |\n| **Backed by** | Delta Lake | Databricks Lakebase (Online Feature Stores) |\n\n```python\nfe.create_online_store(name=\"churn-online-store\", capacity=\"CU_2\")\nonline_store = fe.get_online_store(name=\"churn-online-store\")\n\nfe.publish_table(\n    online_store=online_store,\n    source_table_name=\"ml_dev.features.customer_features\",\n    online_table_name=\"ml_dev.features.customer_features_online\",\n    # publish_mode defaults to \"TRIGGERED\"; \"CONTINUOUS\" and \"SNAPSHOT\" also exist\n)\n```\n\nA model logged with `fe.log_model` and deployed to Model Serving can then **look up features automatically** from the online store using only the primary key in the request.\n\n> [!note] Platform update (Oct 2026)\n>\n> - **Online stores:** the docs describe Online Feature Stores \"powered by Databricks Lakebase\"; stores created with `fe.create_online_store` after March 23, 2026 use Lakebase Autoscaling. The older product appears as **Databricks online tables (legacy)** with a migration guide ([Online Feature Stores](https://docs.databricks.com/aws/en/machine-learning/feature-store/online-feature-store), [Migrate from legacy online tables](https://docs.databricks.com/aws/en/machine-learning/feature-store/migrate-from-online-tables)). Free Edition lists online tables as unsupported ([Free Edition limitations](https://docs.databricks.com/aws/en/getting-started/free-edition-limitations)).\n> - **Feature Views:** \"Feature Views are now generally available for batch, streaming, and request-time data\" ([October 2026 release notes](https://docs.databricks.com/aws/en/release-notes/product/2026/october), entry dated October 12, 2026), and the feature-management overview says \"For new use cases, Databricks recommends Feature Views\" ([Feature management](https://docs.databricks.com/aws/en/machine-learning/feature-store/)). The exam guide still tests **feature tables** — learn the APIs on this page.\n\n## Feature Store Best Practices\n\n- Keep feature tables in a dedicated schema per environment (`ml_dev.features`, `ml_prod.features`)\n- Always log models with `fe.log_model` when they use feature tables — it is what makes `score_batch` and online lookups work\n- Use point-in-time lookups for any time-dependent feature\n- Add descriptions and tags (`fe.set_feature_table_tag(name=..., key=..., value=...)`) so features are discoverable in Catalog Explorer\n- Refresh features with a scheduled Lakeflow Job or a pipeline rather than ad-hoc notebook runs\n\n## Comparison: Feature Store vs Manual Feature Management\n\n| Aspect | Feature tables in UC | Manual (copy features into every training table) |\n| :--- | :--- | :--- |\n| **Consistency** | Same definitions for training, batch, and online | Risk of training-serving skew |\n| **Reuse** | Discoverable across workspaces | Copies per project |\n| **Lineage** | Tracked in Unity Catalog | Manual |\n| **Inference** | `score_batch` / automatic online lookup | Re-implement joins at scoring time |\n\n## Use Cases\n\n- **Eliminating Training-Serving Skew**: A churn model logged with `fe.log_model` is scored nightly with `fe.score_batch`, which joins the exact same feature definitions used in training.\n- **Cross-Workspace Feature Reuse**: A fraud team in one workspace reuses the `customer_features` table that the marketing team maintains in another workspace on the same metastore.\n\n## Common Issues & Errors\n\n### Feature Lookup Returns NULL Values\n\n**Scenario:** Some rows have null features after `create_training_set` or `score_batch`.\n**Fix:** The lookup key values have no matching primary key in the feature table, or the key types differ. Check key types and coverage; use `default_values` in `FeatureLookup` if a default is acceptable.\n\n### Error Using a DATE/TIMESTAMP Primary Key\n\n**Scenario:** `create_training_set()` fails on a feature table whose primary key includes a `DATE` or `TIMESTAMP` column.\n**Fix:** Declare that column as the table's time-series key (and use `timestamp_lookup_key`), or change it to `STRING` for exact-match lookups.\n\n## Exam Tips\n\n- ✅ UC creation path: `FeatureEngineeringClient().create_table(name=\"cat.schema.table\", primary_keys=[...], df=...)`\n- ✅ Any Delta table with a `PRIMARY KEY` constraint is a feature table — there is no `AS FEATURE STORE` clause\n- ✅ `write_table` uses `mode=\"merge\"` (upsert by key)\n- ✅ Train: `FeatureLookup` → `create_training_set` → `fe.log_model`; score: `fe.score_batch(model_uri, df)`\n- ✅ Offline = Delta table for training/batch; online = low-latency store for real-time serving\n- ✅ UC (account-level) benefits: cross-workspace sharing/discovery, centralised governance, lineage\n\n## Key Takeaways\n\n- Feature Engineering in Unity Catalog replaces the deprecated Workspace Feature Store\n- A feature table is a governed Delta table keyed by a primary key\n- `fe.log_model` packages feature metadata so batch and real-time inference retrieve features automatically\n- Point-in-time lookups prevent future data leaking into training rows\n- Online stores serve features to real-time endpoints; offline tables serve training and batch scoring\n\n## Related Topics\n\n- [Feature Engineering Techniques](../02-data-processing/02-feature-engineering-techniques.md)\n- [MLflow Tracking](./05-mlflow-tracking.md)\n- [Model Registry in Unity Catalog](./07-model-registry.md)\n- [Model Deployment & Serving](../04-model-deployment/01-model-deployment-serving.md)\n- [Feature Engineering Basics (shared)](../../../shared/fundamentals/feature-engineering-basics.md)\n\n## Official Documentation\n\n- [Feature management on Databricks](https://docs.databricks.com/aws/en/machine-learning/feature-store/)\n- [Work with feature tables in Unity Catalog](https://docs.databricks.com/aws/en/machine-learning/feature-store/uc/feature-tables-uc)\n- [Use features to train models](https://docs.databricks.com/aws/en/machine-learning/feature-store/train-models-with-feature-store)\n- [Online Feature Stores](https://docs.databricks.com/aws/en/machine-learning/feature-store/online-feature-store)\n- [Feature Engineering Python API](https://api-docs.databricks.com/python/feature-engineering/latest/feature_engineering.client.html)\n\n---\n\n**[← Previous: Databricks AutoML](./03-databricks-automl.md) | [↑ Back to Section](./README.md) | [Next: MLflow Tracking →](./05-mlflow-tracking.md)**\n"},{"id":"01-databricks-machine-learning/05-mlflow-tracking","folder":"01-databricks-machine-learning","group":"modulo","order":5,"isIndex":false,"title":"MLflow Tracking","md":"# MLflow Tracking\n\n## Overview\n\nMLflow Tracking is the core component for logging, storing, and querying machine learning experiments. It captures parameters, metrics, artifacts, and models to enable reproducibility and comparison. The exam guide lists the MLflow skills under **Section 1: Databricks Machine Learning**.\n\n> [!abstract]\n>\n> - A **run** records params (`log_param`), metrics (`log_metric`, optional `step`), artifacts (`log_artifact` / `log_artifacts`), tags, and models (`<flavor>.log_model`)\n> - `mlflow.autolog()` captures framework params/metrics/models automatically; manual logging adds anything custom\n> - Runs from a Databricks notebook land in the notebook's experiment unless `mlflow.set_experiment()` points elsewhere\n> - `MlflowClient` is the lower-level Client API for runs, experiments, and registered models\n\n> [!tip] What the Exam Tests\n>\n> - *Manually log metrics, artifacts, and models in an MLflow run* — know the exact function names and argument shapes\n> - The difference between params (config), metrics (numbers over steps), tags (metadata), and artifacts (files)\n> - What autolog does and does not capture (custom business metrics need `log_metric`)\n\n---\n\n## MLflow Architecture\n\n```mermaid\nflowchart TB\n    subgraph Training[\"Training Code\"]\n        Code[\"ML Code\"]\n    end\n\n    subgraph Tracking[\"MLflow Tracking Server\"]\n        Logger[\"MLflow Logger\"]\n        Backend[\"Backend Store\"]\n        Artifact[\"Artifact Store\"]\n    end\n\n    subgraph Storage[\"Storage\"]\n        DB[\"Metadata DB\"]\n        S3[\"Object Storage<br/>S3, GCS, ADLS\"]\n    end\n\n    subgraph UI[\"MLflow UI\"]\n        Browser[\"Web Interface\"]\n    end\n\n    Code -->|log| Logger\n    Logger -->|metadata| Backend\n    Logger -->|files| Artifact\n    Backend --> DB\n    Artifact --> S3\n    DB --> Browser\n    S3 --> Browser\n```\n\n## Core Concepts\n\n### **Tracking APIs**\n\n```python\n# Initialize MLflow\n\nimport mlflow\nimport mlflow.sklearn\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.metrics import accuracy_score, roc_auc_score\n\n# Start a run\n\nmlflow.start_run(run_name=\"rf_baseline\")\n\n# Log parameters (hyperparameters)\n\nmlflow.log_param(\"n_estimators\", 100)\nmlflow.log_param(\"max_depth\", 10)\nmlflow.log_param(\"min_samples_split\", 2)\n\n# Log metrics (performance measurements)\n\nmlflow.log_metric(\"accuracy\", 0.92)\nmlflow.log_metric(\"auc\", 0.95)\nmlflow.log_metric(\"precision\", 0.91)\nmlflow.log_metric(\"recall\", 0.93)\n\n# Log model\n\nmodel = RandomForestClassifier(n_estimators=100, max_depth=10)\nmodel.fit(X_train, y_train)\nmlflow.sklearn.log_model(model, \"model\")\n\n# End run\n\nmlflow.end_run()\n```\n\n### **Logging Parameters**\n\n```python\n# Log single parameter\n\nmlflow.log_param(\"learning_rate\", 0.01)\n\n# Log multiple parameters\n\nparams = {\n    \"optimizer\": \"adam\",\n    \"batch_size\": 32,\n    \"epochs\": 100,\n    \"dropout\": 0.5,\n    \"l2_reg\": 0.001\n}\nmlflow.log_params(params)\n```\n\n### **Logging Metrics**\n\n```python\n# Single metric\n\nmlflow.log_metric(\"loss\", 0.456)\n\n# Multiple metrics\n\nmetrics = {\n    \"train_accuracy\": 0.89,\n    \"val_accuracy\": 0.87,\n    \"test_accuracy\": 0.86,\n    \"f1_score\": 0.88,\n    \"auc\": 0.91\n}\nmlflow.log_metrics(metrics)\n\n# Track metric over time (epochs)\n\nfor epoch in range(1, 101):\n    train_loss = train_model(epoch)\n    val_loss = validate_model(epoch)\n\n    mlflow.log_metric(\"train_loss\", train_loss, step=epoch)\n    mlflow.log_metric(\"val_loss\", val_loss, step=epoch)\n```\n\n### **Logging Artifacts**\n\n```python\nimport json\nimport matplotlib.pyplot as plt\nimport pickle\n\n# Log text files\n\nwith open(\"training_log.txt\", \"w\") as f:\n    f.write(\"Training completed successfully\")\nmlflow.log_artifact(\"training_log.txt\")\n\n# Log plots\n\nfig, ax = plt.subplots()\nax.plot([1, 2, 3], [1, 4, 9])\nplt.savefig(\"learning_curve.png\")\nmlflow.log_artifact(\"learning_curve.png\")\n\n# Log model data\n\nmodel_dict = {\"model\": model, \"scaler\": scaler}\nwith open(\"artifacts.pkl\", \"wb\") as f:\n    pickle.dump(model_dict, f)\nmlflow.log_artifact(\"artifacts.pkl\")\n\n# Log entire directory (plural function)\n\nmlflow.log_artifacts(\"config/\")\n\n# Log in-memory objects without writing a file first\nmlflow.log_dict({\"threshold\": 0.42}, \"config/threshold.json\")\nmlflow.log_figure(fig, \"plots/learning_curve.png\")\n```\n\n## MLflow Tracking UI\n\n### **Viewing Experiments**\n\n```python\n\n# Access MLflow UI\n# Databricks: Workspace → Experiments\n# Local: http://localhost:5000 after running mlflow ui\n\n# Create experiment\n\nmlflow.set_experiment(\"/Users/user@company.com/churn_model\")\n\n# Get experiment ID\n\nexp = mlflow.get_experiment_by_name(\"/Users/user@company.com/churn_model\")\nprint(f\"Experiment ID: {exp.experiment_id}\")\n\n# List all runs in experiment\n\nfrom mlflow.tracking import MlflowClient\nclient = MlflowClient()\nruns = client.search_runs(exp.experiment_id)\nfor run in runs:\n    print(f\"Run: {run.info.run_name}, Status: {run.info.status}\")\n```\n\n## Databricks Integration\n\n### **Automatic Tracking**\n\n```python\n\n# In a Databricks notebook with no set_experiment() call, runs are logged to the\n# *notebook experiment* (same path as the notebook). Calling a fluent logging\n# function with no active run starts a run automatically.\n\n%python\nimport mlflow\n\nmlflow.log_param(\"model_type\", \"gradient_boosting\")   # auto-starts a run in the notebook experiment\nmlflow.log_metric(\"accuracy\", 0.95)\nmlflow.end_run()\n\n# Check which experiment the run went to\nrun = mlflow.last_active_run()\nexp = mlflow.get_experiment(run.info.experiment_id)\nprint(f\"Experiment: {exp.name}\")\n```\n\n### **Unity Catalog Integration**\n\n```python\n# Store models in Unity Catalog (default registry URI in MLflow 3)\n\nmlflow.set_registry_uri(\"databricks-uc\")\n\n# Log model and register it in UC in one call (UC requires a signature —\n# passing input_example lets MLflow infer it)\n\nmlflow.sklearn.log_model(\n    model,\n    artifact_path=\"model\",\n    input_example=X_train.head(5),\n    registered_model_name=\"catalog.schema.model_name\"\n)\n\n# Load from UC by alias or by version number (UC has no stages)\n\nmodel = mlflow.sklearn.load_model(\"models:/catalog.schema.model_name@champion\")\nmodel_v1 = mlflow.sklearn.load_model(\"models:/catalog.schema.model_name/1\")\n```\n\n## Advanced Tracking Features\n\n### **Custom Tags**\n\n```python\n# Tag runs for organization\n\nmlflow.set_tag(\"project\", \"customer_churn\")\nmlflow.set_tag(\"team\", \"data_science\")\nmlflow.set_tag(\"environment\", \"production\")\nmlflow.set_tag(\"algorithm_type\", \"tree_based\")\n\n# Set multiple tags\n\ntags = {\n    \"experiment_type\": \"hyperparameter_tuning\",\n    \"baseline\": \"yes\",\n    \"model_complexity\": \"high\"\n}\nmlflow.set_tags(tags)\n```\n\n### **Run Management**\n\n```python\nfrom mlflow.tracking import MlflowClient\n\nclient = MlflowClient()\n\n# Get current run\n\nactive_run = mlflow.active_run()\nrun_id = active_run.info.run_id\n\n# Update run metadata\n\nclient.set_tag(run_id, \"status\", \"production_ready\")\n\n# Get run details\n\nrun = client.get_run(run_id)\nprint(f\"Duration: {run.info.end_time - run.info.start_time} ms\")\n\n# Delete run\n\nclient.delete_run(run_id)\n\n# Restore run\n\nclient.restore_run(run_id)\n```\n\n### **Searching Experiments**\n\n```python\n# Search runs by metrics\n\ntop_runs = client.search_runs(\n    experiment_ids=[\"1\"],\n    filter_string=\"metrics.accuracy > 0.90 and params.model_type = 'rf'\",\n    order_by=[\"metrics.accuracy DESC\"],\n    max_results=10\n)\n\nfor run in top_runs:\n    print(f\"{run.info.run_name}: {run.data.metrics['accuracy']}\")\n```\n\n## Logging Models\n\n### **Framework-Specific Logging**\n\n```python\nimport mlflow.sklearn\nimport mlflow.spark\nimport mlflow.xgboost\nimport mlflow.lightgbm\n\n# Scikit-learn\n\nfrom sklearn.ensemble import RandomForestClassifier\nmodel = RandomForestClassifier()\nmlflow.sklearn.log_model(model, \"sklearn_model\")\n\n# Spark ML\n\nfrom pyspark.ml import Pipeline\npipeline = Pipeline(stages=[...])\nmlflow.spark.log_model(pipeline, \"spark_model\")\n\n# XGBoost\n\nimport xgboost as xgb\nxgb_model = xgb.XGBClassifier()\nmlflow.xgboost.log_model(xgb_model, \"xgb_model\")\n\n# LightGBM\n\nimport lightgbm as lgb\nlgb_model = lgb.LGBMClassifier()\nmlflow.lightgbm.log_model(lgb_model, \"lgb_model\")\n\n# Custom Python logic: subclass mlflow.pyfunc.PythonModel\n\nclass Doubler(mlflow.pyfunc.PythonModel):\n    def predict(self, context, model_input):\n        return model_input * 2\n\nmlflow.pyfunc.log_model(artifact_path=\"custom_model\", python_model=Doubler())\n```\n\n> [!note] Platform update (Oct 2026)\n> With MLflow 3 on Databricks, `log_model(..., artifact_path=...)` \"is still supported but has been deprecated\" in favour of `name=`, and `log_model` returns a `models:/<model_id>` URI (rather than `runs:/<run_id>/<artifact_path>` as in MLflow 2.x). The default registry URI is now `databricks-uc`. Exam questions are written with MLflow 2-style `artifact_path` / `runs:/` URIs, so recognise both ([Get started with MLflow 3](https://docs.databricks.com/aws/en/mlflow/mlflow-3-install)).\n\n## Real-World Example\n\n### **Full Experiment Tracking**\n\n```python\n%python\nimport mlflow\nimport mlflow.sklearn\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score\nimport pandas as pd\nimport json\n\n# Load data\n\ndf = spark.read.table(\"ml_catalog.data.customer_data\").toPandas()\n\n# Split data\n\nX = df.drop(\"churn\", axis=1)\ny = df[\"churn\"]\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2)\n\n# Create experiment\n\nmlflow.set_experiment(\"/Users/user@company.com/churn_model_v2\")\n\n# Hyperparameters to test\n\nhyperparameters = [\n    {\"n_estimators\": 50, \"max_depth\": 5},\n    {\"n_estimators\": 100, \"max_depth\": 10},\n    {\"n_estimators\": 200, \"max_depth\": 15},\n]\n\nbest_f1 = 0\nbest_run_id = None\n\nfor params in hyperparameters:\n    with mlflow.start_run(run_name=f\"rf_{params['n_estimators']}_{params['max_depth']}\"):\n        # Log parameters\n        mlflow.log_params(params)\n\n        # Train model\n        scaler = StandardScaler()\n        X_train_scaled = scaler.fit_transform(X_train)\n        X_test_scaled = scaler.transform(X_test)\n\n        model = RandomForestClassifier(**params)\n        model.fit(X_train_scaled, y_train)\n\n        # Predictions\n        y_pred = model.predict(X_test_scaled)\n\n        # Calculate metrics\n        accuracy = accuracy_score(y_test, y_pred)\n        precision = precision_score(y_test, y_pred)\n        recall = recall_score(y_test, y_pred)\n        f1 = f1_score(y_test, y_pred)\n\n        # Log metrics\n        mlflow.log_metrics({\n            \"accuracy\": accuracy,\n            \"precision\": precision,\n            \"recall\": recall,\n            \"f1\": f1\n        })\n\n        # Log model\n        mlflow.sklearn.log_model(model, \"model\")\n\n        # Log feature importance\n        feature_importance = {\n            col: float(imp)\n            for col, imp in zip(X.columns, model.feature_importances_)\n        }\n        with open(\"feature_importance.json\", \"w\") as f:\n            json.dump(feature_importance, f)\n        mlflow.log_artifact(\"feature_importance.json\")\n\n        # Track best model\n        if f1 > best_f1:\n            best_f1 = f1\n            best_run_id = mlflow.active_run().info.run_id\n\n        mlflow.set_tag(\"best_model\", best_run_id == mlflow.active_run().info.run_id)\n\nprint(f\"Best run: {best_run_id} with F1: {best_f1}\")\n```\n\n## Comparison: MLflow vs Alternatives\n\n| Aspect | MLflow | Weights & Biases | Neptune | DVC |\n|--------|--------|---|---|---|\n| **Ease of Use** | Very easy | Easy | Moderate | Complex |\n| **Tracking** | ✓ | ✓ | ✓ | Limited |\n| **Model Registry** | ✓ | ✓ | ✓ | ✓ |\n| **Experiment Management** | ✓ | ✓ | ✓ | ✓ |\n| **UI Quality** | Good | Excellent | Good | CLI-only |\n| **Cost** | Free (open source) | Paid | Paid | Free |\n| **Databricks Native** | ✓ | ✗ | ✗ | ✗ |\n\n## Use Cases\n\n- **Hyperparameter Sweep with Experiment Comparison**: Logging parameters and metrics for multiple model configurations (e.g., Random Forest with different `n_estimators` and `max_depth` values) in the same experiment, then using `client.search_runs()` to find the best run by F1 score.\n- **Reproducible Model Artifacts**: Logging the trained model, scaler, feature importance JSON, and learning curve plots as artifacts so any team member can reproduce or inspect the exact model version that was promoted to production.\n\n## Common Issues & Errors\n\n### Metrics Not Logged to Experiment\n\n**Scenario:** `mlflow.log_metric()` calls succeed but metrics don't appear in the experiment UI.\n**Fix:** Ensure `mlflow.start_run()` was called and the run is active. Metrics logged outside an active run context are silently dropped. Use the `with mlflow.start_run():` context manager to guarantee the run is properly opened and closed.\n\n### Duplicate Runs Created in Databricks Notebooks\n\n**Scenario:** Re-running a notebook cell creates a new MLflow run each time, cluttering the experiment with incomplete runs.\n**Fix:** Use `mlflow.start_run()` with an explicit `run_name` and wrap training logic in a `with` block. Call `mlflow.end_run()` if using the imperative API to ensure the previous run is closed before starting a new one.\n\n## Exam Tips\n\n- `log_param()` stores a single string value (hyperparameter); `log_metric()` stores a numeric value (performance measure) and supports a `step` argument for epoch tracking\n- `log_params()` and `log_metrics()` accept dictionaries for batch logging -- know the plural forms\n- Logging from a notebook without `set_experiment()` uses the **notebook experiment** automatically\n- Custom business metrics are never captured by `autolog()` -- log them with `mlflow.log_metric()`\n- `mlflow.sklearn.log_model()` vs `mlflow.spark.log_model()` -- know which flavor matches which framework (sklearn, xgboost, lightgbm, spark)\n- `client.search_runs(filter_string=\"metrics.accuracy > 0.9\")` uses a SQL-like filter syntax with `metrics.` and `params.` prefixes\n- Artifacts (plots, JSON files, pickled objects) are stored in the artifact store (object storage), not the backend metadata store\n\n## Key Takeaways\n\n- MLflow Tracking captures all experiment data (parameters, metrics, artifacts)\n- Metrics can be logged with steps for tracking over time\n- Artifacts enable reproducibility by capturing models and data\n- Databricks provides native MLflow integration with automatic experiment creation\n- Search functionality enables finding best runs across experiments\n- Tags enable organization and filtering of runs\n\n## Related Topics\n\n- [Experiments & Runs](./06-experiments-runs.md)\n- [Model Registry in Unity Catalog](./07-model-registry.md)\n- [ML Experimentation Workflow](../03-model-development/04-ml-experimentation-workflow.md)\n- [MLflow cheat sheet (shared)](../../../shared/cheat-sheets/mlflow-quick-ref.md)\n\n## Official Documentation\n\n- [MLflow Tracking](https://mlflow.org/docs/latest/ml/tracking/)\n- [MLflow on Databricks](https://docs.databricks.com/aws/en/mlflow/)\n- [Databricks Autologging](https://docs.databricks.com/aws/en/mlflow/databricks-autologging)\n\n---\n\n**[← Previous: Feature Store in Unity Catalog](./04-feature-store.md) | [↑ Back to Section](./README.md) | [Next: Experiments & Runs →](./06-experiments-runs.md)**\n"},{"id":"01-databricks-machine-learning/06-experiments-runs","folder":"01-databricks-machine-learning","group":"modulo","order":6,"isIndex":false,"title":"Experiments & Runs","md":"# Experiments & Runs\n\n## Overview\n\nExperiments and runs are the organizational structure for machine learning tracking. Experiments group related runs, and runs represent individual model training executions. This file covers two Section 1 bullets directly: finding the **best run with the MLflow Client API** and knowing **what the MLflow UI shows**.\n\n> [!abstract]\n>\n> - Experiment = container of runs; run = one execution with params, metrics, tags, artifacts, and models\n> - `MlflowClient().search_runs(experiment_ids=[...], filter_string=..., order_by=[...], max_results=...)` ranks runs server-side\n> - `mlflow.search_runs(...)` is the fluent equivalent and returns a pandas DataFrame\n> - The UI shows run details (params, metrics, tags, artifacts, source notebook version, datasets) and compares runs within or across experiments\n\n> [!tip] What the Exam Tests\n>\n> - Retrieving the single best run programmatically — `order_by=[\"metrics.<m> ASC|DESC\"]` and take the first result\n> - Filter syntax: `metrics.`, `params.`, `tags.` prefixes; `get_run` needs a run ID and does not rank runs\n> - Which information you can read in the MLflow UI vs which needs the API\n\n---\n\n## Concept Hierarchy\n\n```mermaid\nflowchart TD\n    DB[\"MLflow Backend\"] --> Exp1[\"Experiment 1:<br/>Churn Model\"]\n    DB --> Exp2[\"Experiment 2:<br/>Revenue Model\"]\n\n    Exp1 --> Run1[\"Run 1: Baseline\"]\n    Exp1 --> Run2[\"Run 2: Feature Eng v1\"]\n    Exp1 --> Run3[\"Run 3: Hyperparameter Tuning\"]\n\n    Exp2 --> Run4[\"Run 4: Linear Model\"]\n    Exp2 --> Run5[\"Run 5: XGBoost\"]\n\n    Run1 --> Meta1[\"Params, Metrics, Artifacts\"]\n    Run2 --> Meta2[\"Params, Metrics, Artifacts\"]\n    Run3 --> Meta3[\"Params, Metrics, Artifacts\"]\n```\n\n## Experiment Management\n\n![MLflow Experiment Runs](../../../images/databricks-ui/mlflow/mlflow_experiment_runs.png)\n\n*MLflow Experiments UI listing runs with logged metrics and parameters.*\n\n### **Creating Experiments**\n\n```python\nimport mlflow\n\n# Set (and create if missing) the active experiment; on Databricks use a workspace path\n\nexp = mlflow.set_experiment(\"/Users/user@company.com/churn_prediction_v1\")\n\n# Create with full path (in notebooks, creates under user)\n\nmlflow.set_experiment(\"/Users/user@company.com/projects/churn_prediction\")\n\n# Get experiment info\n\nactive_exp = mlflow.get_experiment_by_name(\"/Users/user@company.com/churn_prediction_v1\")\nprint(f\"Experiment ID: {active_exp.experiment_id}\")\nprint(f\"Artifact location: {active_exp.artifact_location}\")\nprint(f\"Created: {active_exp.creation_time}\")\n\n# Working with multiple experiments\n\nfrom mlflow.tracking import MlflowClient\nclient = MlflowClient()\n\n# List all experiments\n\nexperiments = client.search_experiments()\nfor exp in experiments:\n    print(f\"{exp.name}: {len(client.search_runs([exp.experiment_id]))} runs\")\n```\n\n### **Experiment Organization Strategies**\n\n**Strategy 1: By Model Type**\n\n```text\n/Projects/\n├── /Projects/RandomForest/\n├── /Projects/GradientBoosting/\n├── /Projects/NeuralNetworks/\n```\n\n**Strategy 2: By Business Domain**\n\n```text\n/Business/\n├── /Business/CustomerAnalytics/\n├── /Business/Pricing/\n├── /Business/Marketing/\n```\n\n**Strategy 3: By Lifecycle**\n\n```text\n/Models/\n├── /Models/Development/\n├── /Models/Staging/\n├── /Models/Production/\n```\n\n**Best Practice: Hierarchical**\n\n```python\n# Organize by project/model/version\n\nbase_path = \"/Users/user@company.com/projects\"\nproject = \"churn_prediction\"\niteration = \"v2\"\n\nexp_name = f\"{base_path}/{project}/{iteration}\"\nmlflow.set_experiment(exp_name)\n```\n\n## Run Management\n\n![MLflow Run Details](../../../images/databricks-ui/mlflow/mlflow_run_details.png)\n\n*MLflow Run detail view showing logged parameters, metrics, and artifacts.*\n\n### **Creating & Managing Runs**\n\n```python\nimport mlflow\nfrom mlflow.tracking import MlflowClient\n\n# Start run with context manager (recommended)\n\nwith mlflow.start_run(run_name=\"rf_baseline_v1\") as run:\n    run_id = run.info.run_id\n    print(f\"Started run: {run_id}\")\n\n    # Log parameters and metrics\n    mlflow.log_param(\"n_estimators\", 100)\n    mlflow.log_metric(\"accuracy\", 0.92)\n\n    # Run info automatically available\n    print(f\"Run name: {run.info.run_name}\")\n    print(f\"Status: {run.info.status}\")\n\n# Run automatically ends\n\n# Manual run management\n\nmlflow.start_run(run_name=\"xgboost_v1\")\ntry:\n    mlflow.log_param(\"eta\", 0.3)\n    mlflow.log_metric(\"auc\", 0.95)\nfinally:\n    mlflow.end_run()\n```\n\n### **Run Status Tracking**\n\n```python\nfrom mlflow.tracking import MlflowClient\n\nclient = MlflowClient()\n\n# Run status lifecycle\n\nstatus_values = [\"RUNNING\", \"SCHEDULED\", \"FINISHED\", \"FAILED\"]\n\nrun_id = mlflow.active_run().info.run_id\n\n# Get run status\n\nrun = client.get_run(run_id)\nprint(f\"Status: {run.info.status}\")\nprint(f\"Start time: {run.info.start_time}\")\nprint(f\"End time: {run.info.end_time}\")\n\n# Duration calculation\n\nduration_ms = run.info.end_time - run.info.start_time\nduration_sec = duration_ms / 1000\nprint(f\"Duration: {duration_sec:.2f} seconds\")\n\n# Set status manually\n\nif error_occurred:\n    client.set_terminated(run_id, status=\"FAILED\")\nelse:\n    client.set_terminated(run_id, status=\"FINISHED\")\n```\n\n### **Nested Runs**\n\n```python\n# Parent run\n\nwith mlflow.start_run(run_name=\"hyperparameter_sweep\") as parent_run:\n    mlflow.set_tag(\"type\", \"sweep\")\n\n    # Child runs for each parameter set\n    for n_est in [50, 100, 200]:\n        with mlflow.start_run(run_name=f\"n_est_{n_est}\", nested=True):\n            mlflow.log_param(\"n_estimators\", n_est)\n            mlflow.log_metric(\"accuracy\", 0.90 + n_est/1000)\n            mlflow.set_tag(\"parent_run\", parent_run.info.run_id)\n\n# View parent-child relationship in UI\n# Parent run shows all nested child runs\n\n```\n\n## Comparing Runs\n\n### **Programmatic Comparison**\n\n```python\nfrom mlflow.tracking import MlflowClient\nimport pandas as pd\n\nclient = MlflowClient()\n\n# Get multiple runs\n\nexp_id = mlflow.get_experiment_by_name(\"/Users/user@company.com/churn_model\").experiment_id\nruns = client.search_runs([exp_id])\n\n# Extract data for comparison\n\ncomparison_data = []\nfor run in runs:\n    comparison_data.append({\n        \"run_name\": run.info.run_name,\n        \"accuracy\": run.data.metrics.get(\"accuracy\"),\n        \"precision\": run.data.metrics.get(\"precision\"),\n        \"recall\": run.data.metrics.get(\"recall\"),\n        \"n_estimators\": run.data.params.get(\"n_estimators\"),\n        \"max_depth\": run.data.params.get(\"max_depth\"),\n    })\n\n# Create comparison dataframe\n\ncomparison_df = pd.DataFrame(comparison_data)\nprint(comparison_df.to_string())\n\n# Find best run (client-side) — works, but the server-side order_by below is the idiomatic way\n\nbest_run = comparison_df.loc[comparison_df[\"accuracy\"].idxmax()]\nprint(f\"Best run: {best_run['run_name']} with accuracy {best_run['accuracy']}\")\n```\n\n### **Identify the Best Run with the MLflow Client API**\n\n```python\nfrom mlflow import MlflowClient\n\nclient = MlflowClient()\nexp = client.get_experiment_by_name(\"/Users/user@company.com/churn_model\")\n\nbest = client.search_runs(\n    experiment_ids=[exp.experiment_id],\n    filter_string=\"attributes.status = 'FINISHED'\",\n    order_by=[\"metrics.validation_rmse ASC\"],   # lower RMSE is better\n    max_results=1,\n)[0]\n\nprint(best.info.run_id, best.data.metrics[\"validation_rmse\"])\nbest_model_uri = f\"runs:/{best.info.run_id}/model\"\n```\n\n| Need | Call |\n| :--- | :--- |\n| Best run by a metric | `client.search_runs([exp_id], order_by=[\"metrics.m DESC\"], max_results=1)[0]` |\n| Same, as a DataFrame | `mlflow.search_runs(experiment_ids=[exp_id], order_by=[\"metrics.m DESC\"]).iloc[0]` |\n| One known run | `client.get_run(run_id)` — needs the run ID, does **not** rank |\n| Full history of a metric | `client.get_metric_history(run_id, \"loss\")` |\n\n> [!warning] Common Mistake\n> The most *recent* run is not the *best* run, and opening the UI to sort a column is not \"using the Client API\". For loss-type metrics (RMSE, log loss) sort **ascending**; for score-type metrics (AUC, F1, R²) sort **descending**.\n\n### **Information Available in the MLflow UI**\n\n| UI area | What you can see / do |\n| :--- | :--- |\n| **Experiment runs table** | Every run with start time, duration, user, source, status, params, metrics; sort, filter, search; export to CSV |\n| **Run details page** | Run ID and name, parameters, metrics (with step charts), tags (editable), source notebook and its version |\n| **Artifacts tab** | Logged files and models, including generated code snippets to load the model for predictions |\n| **Datasets** | Datasets logged with the run (usable as a filter) |\n| **Compare** | Select 2+ runs → **Compare** for side-by-side params/metrics with a *show diff only* toggle; select several experiments → **Compare (n)** to compare runs **across experiments** |\n| **Charts** | Visualise metrics across runs (see *Compare MLflow runs and models using graphs and charts*) |\n\nSource: [Manage training code with MLflow runs](https://docs.databricks.com/aws/en/mlflow/runs).\n\n### **Advanced Filtering & Search**\n\n```python\nfrom mlflow.tracking import MlflowClient\n\nclient = MlflowClient()\nexp_id = mlflow.get_experiment_by_name(\"/Users/user@company.com/churn_model\").experiment_id\n\n# Filter by metrics\n\nhigh_accuracy_runs = client.search_runs(\n    experiment_ids=[exp_id],\n    filter_string=\"metrics.accuracy > 0.90 AND metrics.auc > 0.92\"\n)\n\n# Filter by parameters\n\nrf_runs = client.search_runs(\n    experiment_ids=[exp_id],\n    filter_string=\"params.model_type = 'random_forest'\"\n)\n\n# Filter by tags\n\nproduction_runs = client.search_runs(\n    experiment_ids=[exp_id],\n    filter_string=\"tags.status = 'production'\"\n)\n\n# Order by metrics\n\nbest_runs = client.search_runs(\n    experiment_ids=[exp_id],\n    order_by=[\"metrics.f1_score DESC\"],\n    max_results=5\n)\n\nfor run in best_runs:\n    print(f\"{run.info.run_name}: F1={run.data.metrics['f1_score']:.3f}\")\n```\n\n## Real-World Experiment Structure\n\n### **Customer Churn Model - Full Lifecycle**\n\n```python\n%python\nimport mlflow\nfrom mlflow.tracking import MlflowClient\n\nclient = MlflowClient()\n\n# EXPLORATION PHASE\n\nmlflow.set_experiment(\"/Projects/ChurnModel/Exploration\")\nwith mlflow.start_run(run_name=\"baseline_lr\"):\n    mlflow.log_param(\"model\", \"logistic_regression\")\n    mlflow.log_metric(\"accuracy\", 0.75)\n    mlflow.log_metric(\"auc\", 0.82)\n    mlflow.set_tag(\"phase\", \"exploration\")\n\n# HYPERPARAMETER TUNING PHASE\n\nmlflow.set_experiment(\"/Projects/ChurnModel/Tuning\")\nfor max_depth in [5, 10, 15]:\n    for n_est in [50, 100]:\n        with mlflow.start_run(run_name=f\"rf_d{max_depth}_e{n_est}\"):\n            mlflow.log_param(\"max_depth\", max_depth)\n            mlflow.log_param(\"n_estimators\", n_est)\n            metrics = train_and_evaluate(max_depth, n_est)\n            mlflow.log_metrics(metrics)\n            mlflow.set_tag(\"phase\", \"tuning\")\n\n# VALIDATION PHASE\n\nmlflow.set_experiment(\"/Projects/ChurnModel/Validation\")\nbest_params = {\"max_depth\": 10, \"n_estimators\": 100}\nwith mlflow.start_run(run_name=\"final_validation\"):\n    mlflow.log_params(best_params)\n    validation_metrics = cross_validate_model(best_params)\n    mlflow.log_metrics(validation_metrics)\n    mlflow.sklearn.log_model(model, \"model\")\n    mlflow.set_tag(\"phase\", \"validation\")\n    mlflow.set_tag(\"status\", \"ready_for_production\")\n\n# COMPARE PHASES\n\nexp_names = [\n    \"/Projects/ChurnModel/Exploration\",\n    \"/Projects/ChurnModel/Tuning\",\n    \"/Projects/ChurnModel/Validation\"\n]\n\nfor exp_name in exp_names:\n    exp = mlflow.get_experiment_by_name(exp_name)\n    runs = client.search_runs([exp.experiment_id])\n    best_in_phase = max(runs, key=lambda r: r.data.metrics.get(\"auc\", 0))\n    print(f\"{exp_name}: Best AUC = {best_in_phase.data.metrics['auc']}\")\n```\n\n## Naming, Tagging & Cleanup Practices\n\n### **Naming Conventions**\n\n```python\n# ✓ Good: Descriptive, easy to identify\n\nrun_names = [\n    \"baseline_no_features\",\n    \"with_derived_features\",\n    \"after_feature_selection\",\n    \"with_hyperparameter_tuning\",\n    \"ensemble_with_calibration\"\n]\n\n# ✗ Poor: Generic, unclear\n\nbad_names = [\n    \"test1\",\n    \"v2\",\n    \"new_model\",\n    \"final\"\n]\n\n# Best practice: Include key differentiator\n\nmlflow.start_run(run_name=f\"rf_depth{max_depth}_n_est{n_estimators}\")\n```\n\n### **Tagging Strategy**\n\n```python\n# Standardized tags for filtering\n\nstandard_tags = {\n    \"project\": \"customer_churn\",\n    \"team\": \"data_science\",\n    \"phase\": \"exploration\",  # or tuning, validation, production\n    \"model_type\": \"classification\",\n    \"baseline\": \"no\",  # first run = yes\n    \"production_ready\": \"no\"  # yes only for deployment candidates\n}\n\nmlflow.set_tags(standard_tags)\n```\n\n### **Experiment Cleanup**\n\n```python\n# Archive old experiments\n\nfrom mlflow.tracking import MlflowClient\n\nclient = MlflowClient()\nold_exp = client.get_experiment(\"1\")\nclient.delete_experiment(old_exp.experiment_id)\n\n# Or rename for archiving\n# experiments should have clear retention policy\n\n```\n\n## Comparison: Run Organization Patterns\n\n| Pattern | Use Case | Pros | Cons |\n|---------|----------|------|------|\n| **Single Large Experiment** | Early exploration | Simple | Hard to navigate |\n| **Experiment per Model Type** | Multiple algorithms | Organized | Many experiments |\n| **Experiment per Phase** | Development lifecycle | Clear progression | Complex hierarchy |\n| **Experiment per Data Version** | Data pipeline changes | Reproducibility focus | Hard to compare models |\n| **Hybrid (Recommended)** | Everything | Flexible & organized | Requires discipline |\n\n## Use Cases\n\n- **Experiments & Runs Implementation**: Incorporating Experiments & Runs principles to build scalable and maintainable solutions in Databricks environments.\n- **Hyperparameter Sweep Organization**: Using nested runs to structure a parent sweep run with child runs for each parameter combination, making it easy to navigate and compare results.\n\n## Common Issues & Errors\n\n### Best Run Query Returns the Worst Run\n\n**Scenario:** `search_runs(..., order_by=[\"metrics.rmse DESC\"], max_results=1)` returns the run with the highest error.\n**Fix:** Sort loss metrics (RMSE, log loss) ascending and score metrics (AUC, F1) descending.\n\n### Runs Spread Across Several Experiments\n\n**Scenario:** Two candidate runs were logged to different experiments and need to be compared side-by-side.\n**Fix:** On the Experiments page, select both experiments, click **Compare (n)**, select the runs, and click **Compare** — or query both with `mlflow.search_runs(experiment_ids=[id1, id2])`.\n\n## Exam Tips\n\n- ✅ Best run via Client API: `search_runs(..., order_by=[\"metrics.x ASC\"], max_results=1)[0]`\n- ✅ Understand hierarchy: Backend → Experiments → Runs\n- ✅ Know difference between status values (RUNNING, FINISHED, FAILED)\n- ✅ Recognize nested runs for hyperparameter sweeps\n- ✅ Understand search/filter operations for finding runs\n- ✅ Know tagging strategy for organization\n- ✅ Understand run metadata (start_time, end_time, duration)\n\n## Key Takeaways\n\n- Experiments group related runs for organization\n- Runs represent individual training executions with full metadata\n- Status tracking enables monitoring of long-running experiments\n- Nested runs support hierarchical organization (parent-child)\n- Search and filtering enable finding best runs across experiments\n- Proper naming and tagging strategy essential for team collaboration\n\n## Related Topics\n\n- [MLflow Tracking](./05-mlflow-tracking.md)\n- [Model Registry in Unity Catalog](./07-model-registry.md)\n- [ML Experimentation Workflow](../03-model-development/04-ml-experimentation-workflow.md)\n\n## Official Documentation\n\n- [Manage training code with MLflow runs](https://docs.databricks.com/aws/en/mlflow/runs)\n- [Organize training runs with MLflow experiments](https://docs.databricks.com/aws/en/mlflow/experiments)\n- [MlflowClient.search_runs API](https://mlflow.org/docs/latest/api_reference/python_api/mlflow.client.html)\n\n---\n\n**[← Previous: MLflow Tracking](./05-mlflow-tracking.md) | [↑ Back to Section](./README.md) | [Next: Model Registry in Unity Catalog →](./07-model-registry.md)**\n"},{"id":"01-databricks-machine-learning/07-model-registry","folder":"01-databricks-machine-learning","group":"modulo","order":7,"isIndex":false,"title":"Model Registry in Unity Catalog","md":"# Model Registry in Unity Catalog\n\n## Overview\n\n**Models in Unity Catalog** is the MLflow Model Registry hosted in Unity Catalog. Registered models live at `catalog.schema.model`, every registration creates a numbered **model version**, and **aliases** such as `champion` / `challenger` mark which version a workload should use. The exam guide puts all registry skills in Section 1 (Databricks Machine Learning).\n\n> [!abstract]\n>\n> - Point MLflow at the UC registry with `mlflow.set_registry_uri(\"databricks-uc\")` (the default in MLflow 3) and use three-level names\n> - Register with `mlflow.register_model(...)`, `registered_model_name=` at log time, or the Client API (`MlflowClient().create_registered_model` / `create_model_version`)\n> - Promote with **aliases** (`set_registered_model_alias`) — UC does **not** support stages\n> - Tags (`set_*_tag` / `delete_*_tag`) are descriptive metadata; they do not change which version is served\n\n> [!tip] What the Exam Tests\n>\n> - *Register a model using the MLflow Client API in the Unity Catalog registry*\n> - *Benefits of the UC registry over the workspace registry* — centralised access control, auditing, lineage, cross-workspace discovery\n> - *Set or remove a tag for a model* and *promote a challenger to champion using aliases*\n\n---\n\n## Unity Catalog Registry vs Workspace Model Registry\n\n| Aspect | Models in Unity Catalog | Workspace Model Registry (legacy) |\n| :--- | :--- | :--- |\n| **Scope** | Account-level metastore — **discoverable and usable across workspaces** | One workspace |\n| **Access control** | Unity Catalog privileges (`EXECUTE`, `CREATE MODEL`, ownership) | Workspace registry ACLs |\n| **Auditing & lineage** | UC audit logs; lineage from model to the tables/feature tables it was trained on | Limited |\n| **Naming** | `catalog.schema.model` — environment can be encoded in the catalog (`dev` / `staging` / `prod`) | Flat model name |\n| **Promotion** | **Aliases** (`@champion`, `@challenger`) | Stages (`None` → `Staging` → `Production` → `Archived`) |\n| **Signature** | **Required** for new versions | Optional |\n\nDocs: Unity Catalog \"extends the benefits of Unity Catalog to ML models, including centralized access control, auditing, lineage, and model discovery across workspaces\" and \"Stages are not supported for models in Unity Catalog\" ([Manage model lifecycle in Unity Catalog](https://docs.databricks.com/aws/en/machine-learning/manage-model-lifecycle/)).\n\n```mermaid\nflowchart LR\n    Run[\"MLflow run<br/>logged model\"] -->|register| V3[\"Version 3\"]\n    subgraph RM[\"ml_prod.churn.churn_classifier\"]\n        V1[\"Version 1\"]\n        V2[\"Version 2\"]\n        V3\n    end\n    Champ([\"@champion\"]) -.-> V2\n    Chall([\"@challenger\"]) -.-> V3\n    Batch[\"Batch / serving code<br/>models:/...@champion\"] --> Champ\n```\n\n## Registering a Model\n\n### **Fluent API**\n\n```python\nimport mlflow\n\nmlflow.set_registry_uri(\"databricks-uc\")   # default in MLflow 3; harmless to set explicitly\n\n# Option 1 — register while logging (input_example lets MLflow infer the required signature)\nwith mlflow.start_run() as run:\n    mlflow.sklearn.log_model(\n        model,\n        artifact_path=\"model\",\n        input_example=X_train.head(5),\n        registered_model_name=\"ml_dev.churn.churn_classifier\",\n    )\n\n# Option 2 — register an already-logged model later\nmv = mlflow.register_model(f\"runs:/{run.info.run_id}/model\", \"ml_dev.churn.churn_classifier\")\nprint(mv.version)\n```\n\n![Run artifacts panel with a registered model version](../../../images/databricks-ui/mlflow/model_registry_versions.png)\n\n*A run's Artifacts panel: the logged `sklearn-model` and the registered model version it produced (older workspace-registry UI; in UC the version belongs to `catalog.schema.model`).*\n\n### **MLflow Client API**\n\n```python\nfrom mlflow import MlflowClient\n\nmlflow.set_registry_uri(\"databricks-uc\")\nclient = MlflowClient()\n\nname = \"ml_dev.churn.churn_classifier\"\n\n# Create the registered model once (raises if it already exists)\nclient.create_registered_model(name, description=\"Churn classifier (gradient boosting)\")\n\n# Each create_model_version call adds a new numbered version\nmv = client.create_model_version(\n    name=name,\n    source=f\"runs:/{run_id}/model\",\n    run_id=run_id,\n)\nprint(mv.version, mv.status)\n```\n\nPrivileges: registering needs `USE CATALOG` + `USE SCHEMA` and `CREATE MODEL` on the schema; loading a model needs `EXECUTE` on the registered model.\n\n> [!warning] Common Mistake\n> New model versions in Unity Catalog **must have a signature**. Pass an `input_example` (or an explicit `signature`) to `log_model`, or use autologging, otherwise registration in UC fails.\n\n## Model Versions and URIs\n\n| URI | Resolves to |\n| :--- | :--- |\n| `models:/ml_prod.churn.churn_classifier/3` | Version 3 (immutable) |\n| `models:/ml_prod.churn.churn_classifier@champion` | Whatever version the `champion` alias points to right now |\n| `runs:/<run_id>/model` | The model logged in a specific run (not a registry reference) |\n\n```python\nimport mlflow\n\nchampion = mlflow.pyfunc.load_model(\"models:/ml_prod.churn.churn_classifier@champion\")\nv3 = mlflow.pyfunc.load_model(\"models:/ml_prod.churn.churn_classifier/3\")\n```\n\n## Promoting a Challenger to Champion with Aliases\n\n```python\nfrom mlflow import MlflowClient\n\nclient = MlflowClient()\nname = \"ml_prod.churn.churn_classifier\"\n\n# 1. New version passes offline validation -> mark it as the challenger\nclient.set_registered_model_alias(name, \"challenger\", 4)\n\n# 2. Compare challenger vs current champion (offline metrics, A/B traffic split, etc.)\nchamp = client.get_model_version_by_alias(name, \"champion\")\nchall = client.get_model_version_by_alias(name, \"challenger\")\n\n# 3. Challenger wins -> move the champion alias (aliases are unique per model,\n#    so assigning \"champion\" to v4 removes it from the old version)\nclient.set_registered_model_alias(name, \"champion\", chall.version)\nclient.delete_registered_model_alias(name, \"challenger\")\n```\n\nInference code that loads `models:/<name>@champion` picks up the new version **without any code change** — deployment is decoupled from inference.\n\n> [!warning] Common Mistake\n> `transition_model_version_stage(...)` belongs to the legacy workspace registry; deleting the old version is destructive and unnecessary; setting a tag like `champion=true` is only metadata. The recommended promotion in UC is **moving an alias**.\n\n## Tags and Descriptions\n\n```python\nclient = MlflowClient()\nname = \"ml_prod.churn.churn_classifier\"\n\n# Registered-model-level tag\nclient.set_registered_model_tag(name, \"task\", \"classification\")\nclient.delete_registered_model_tag(name, \"task\")\n\n# Model-version-level tag\nclient.set_model_version_tag(name, \"4\", \"validation_status\", \"approved\")\nclient.delete_model_version_tag(name, \"4\", \"validation_status\")\n\n# Descriptions\nclient.update_registered_model(name=name, description=\"Predicts 30-day churn\")\nclient.update_model_version(name=name, version=4, description=\"LightGBM, F1 0.81 on holdout\")\n```\n\n| Operation | Model level | Version level |\n| :--- | :--- | :--- |\n| Set tag | `set_registered_model_tag(name, key, value)` | `set_model_version_tag(name, version, key, value)` |\n| Remove tag | `delete_registered_model_tag(name, key)` | `delete_model_version_tag(name, version, key)` |\n| Alias | — | `set_registered_model_alias(name, alias, version)` / `delete_registered_model_alias(name, alias)` |\n\nTags can also be set or removed in Catalog Explorer on the model or version page.\n\n## Promoting Across Environments\n\nWith one catalog per environment, a validated version can be **copied** from the staging catalog into the production catalog and then given the production alias:\n\n```python\nclient = MlflowClient()\nsrc_uri = \"models:/staging.ml_team.fraud_detection/1\"\n\ncopied = client.copy_model_version(src_uri, \"prod.ml_team.fraud_detection\")\nclient.set_registered_model_alias(\"prod.ml_team.fraud_detection\", \"champion\", copied.version)\n```\n\nThis is the *deploy models* pattern; the *deploy code* pattern instead retrains in each environment — see [MLOps Strategy](./08-mlops-strategy.md).\n\n## Legacy: Workspace Model Registry Stages\n\nYou may still see stage-based questions in older material. Recognise them, but answer UC questions with aliases.\n\n| Legacy concept | UC equivalent |\n| :--- | :--- |\n| Stages `None`, `Staging`, `Production`, `Archived` | Aliases you name yourself (`challenger`, `champion`) + environment catalogs |\n| `transition_model_version_stage(name, version, stage)` | `set_registered_model_alias(name, alias, version)` |\n| `models:/name/Production` | `models:/catalog.schema.name@champion` |\n| `get_latest_versions(name, stages=[...])` | `get_model_version_by_alias(name, alias)` |\n\n> [!note] Platform update (Oct 2026)\n> The docs title this registry **\"Workspace Model Registry (legacy)\"**: since April 2024 it is disabled for workspaces in new accounts whose default catalog is in Unity Catalog, and since May 2024 it imposes quota limits. It \"continues to be supported in MLflow 3\", but for UC-enabled workspaces the docs say to use Models in Unity Catalog instead ([Workspace Model Registry](https://docs.databricks.com/aws/en/machine-learning/manage-model-lifecycle/workspace-model-registry)).\n\n## Use Cases\n\n- **Champion/Challenger Rollout**: A retrained model is registered as version 7, tagged `validation_status=approved`, given the `challenger` alias, compared against the champion, then promoted by moving the `champion` alias — the nightly scoring job reads `@champion` and needs no change.\n- **Cross-Workspace Model Reuse**: A model registered in `ml_prod` from the training workspace is loaded by a serving workspace attached to the same metastore, governed by `EXECUTE` grants.\n\n## Common Issues & Errors\n\n### Model Registration Fails in Unity Catalog\n\n**Scenario:** `mlflow.register_model()` fails with a permissions or `RESOURCE_DOES_NOT_EXIST` error.\n**Fix:** Make sure the registry URI is `databricks-uc`, the catalog and schema exist, the name is three-level, and you have `USE CATALOG`, `USE SCHEMA`, and `CREATE MODEL`.\n\n### Registration Fails Because the Model Has No Signature\n\n**Scenario:** Logging worked but registering in UC is rejected.\n**Fix:** Re-log the model with an `input_example` or `signature` (or use autologging), then register the new run's model.\n\n## Exam Tips\n\n- ✅ Client API registration: `create_registered_model(name)` then `create_model_version(name, source, run_id)`\n- ✅ UC registry benefits: centralised access control, auditing, lineage, discovery **across workspaces**\n- ✅ Promotion = `set_registered_model_alias(name, \"champion\", version)`; load with `models:/name@champion`\n- ✅ Tags: `set_/delete_registered_model_tag` and `set_/delete_model_version_tag` — metadata only\n- ✅ Stages and `transition_model_version_stage` are legacy workspace-registry concepts\n\n## Key Takeaways\n\n- Models in Unity Catalog is the current registry; names are `catalog.schema.model`\n- Versions are immutable; aliases are movable pointers that decouple deployment from inference code\n- Tags and descriptions document versions but never decide what is served\n- UC governance (privileges, audit, lineage) applies to models exactly as it does to tables\n\n## Related Topics\n\n- [MLflow Tracking](./05-mlflow-tracking.md)\n- [Experiments & Runs](./06-experiments-runs.md)\n- [MLOps Strategy](./08-mlops-strategy.md)\n- [Model Deployment & Serving](../04-model-deployment/01-model-deployment-serving.md)\n- [MLflow cheat sheet (shared)](../../../shared/cheat-sheets/mlflow-quick-ref.md)\n\n## Official Documentation\n\n- [Manage model lifecycle in Unity Catalog](https://docs.databricks.com/aws/en/machine-learning/manage-model-lifecycle/)\n- [Workspace Model Registry (legacy)](https://docs.databricks.com/aws/en/machine-learning/manage-model-lifecycle/workspace-model-registry)\n- [MlflowClient API](https://mlflow.org/docs/latest/api_reference/python_api/mlflow.client.html)\n\n---\n\n**[← Previous: Experiments & Runs](./06-experiments-runs.md) | [↑ Back to Section](./README.md) | [Next: MLOps Strategy →](./08-mlops-strategy.md)**\n"},{"id":"01-databricks-machine-learning/08-mlops-strategy","folder":"01-databricks-machine-learning","group":"modulo","order":8,"isIndex":false,"title":"MLOps Strategy on Databricks","md":"# MLOps Strategy on Databricks\n\n## Overview\n\nMLOps is the set of practices that moves ML work from a notebook to a reliable production system: separate environments, version-controlled pipeline code, tracked experiments, a governed registry, CI/CD, and monitoring. The exam guide opens Section 1 with *\"Identify the best practices of an MLOps strategy\"* and later asks when to **promote code** versus **promote models**.\n\n> [!abstract]\n>\n> - Use **separate dev, staging, and prod environments**, each with its own Unity Catalog catalog\n> - Keep ML pipelines as **code in Git**; track runs with **MLflow**; manage models with **Models in Unity Catalog**\n> - Databricks recommends the **deploy code** pattern in most situations; **deploy models** fits expensive or hard-to-reproduce training\n> - Inference reads a **champion alias**, so promotion never requires an inference-code change\n\n> [!tip] What the Exam Tests\n>\n> - Recognising the recommended MLOps best practices (environment separation, Git, UC registry, CI/CD, monitoring)\n> - *Scenarios where promoting code is preferred over promoting models and vice versa*\n> - How aliases (`challenger` → `champion`) decouple deployment from inference\n\n---\n\n## Recommended MLOps Workflow\n\n```mermaid\nflowchart LR\n    subgraph Dev[\"Development — dev catalog\"]\n        D1[\"EDA + feature code\"] --> D2[\"Training code<br/>MLflow tracking\"]\n    end\n    subgraph Staging[\"Staging — staging catalog\"]\n        S1[\"CI: unit tests on PR\"] --> S2[\"Integration tests<br/>run all pipelines\"]\n    end\n    subgraph Prod[\"Production — prod catalog\"]\n        P1[\"Train on prod data\"] --> P2[\"Validate → @challenger\"]\n        P2 --> P3[\"Compare → @champion\"]\n        P3 --> P4[\"Batch / streaming / real-time inference\"]\n        P4 --> P5[\"Monitoring → retrain\"]\n    end\n    Dev -->|\"Git: feature → main\"| Staging\n    Staging -->|\"Git: release branch\"| Prod\n```\n\n## MLOps Best Practices\n\n| Practice | What Databricks recommends |\n| :--- | :--- |\n| **Separate environments** | \"Databricks recommends creating separate environments for the different stages of ML code and model development\" — dev, staging, prod, each with its own UC catalog |\n| **Pipelines as code** | \"The output of the development process is ML pipeline code\" — kept in Git (Git folders) and promoted through dev → staging → release branches |\n| **Data in Delta + UC** | Raw data and feature tables are Delta tables with Unity Catalog access controls |\n| **Experiment tracking** | MLflow records code snapshots, parameters, metrics, and artifacts for every run |\n| **Model lifecycle in UC** | \"Use Models in Unity Catalog to manage the model lifecycle\" — versioning, governance, deployment status |\n| **CI/CD** | Pull requests trigger unit tests; integration tests run the pipelines in staging; merging to the release branch updates production jobs |\n| **Champion / challenger** | A newly validated model gets the `Challenger` alias; after comparison it can take the `Champion` alias, which inference pipelines reference |\n| **Orchestration** | Training, validation, and deployment as tasks in a multitask job; scheduled retraining on the latest data |\n| **Monitoring** | \"Data profiling monitors statistical properties, such as data drift and model performance\"; alerts can trigger retraining |\n\nSource: [MLOps workflows on Databricks](https://docs.databricks.com/aws/en/machine-learning/mlops/mlops-workflow).\n\n> [!note] Platform update (Oct 2026)\n> Infrastructure-as-code for these jobs and pipelines used to be called **Databricks Asset Bundles**. The bundles release notes record that on March 16, 2026 \"Databricks Asset Bundles has been renamed to Declarative Automation Bundles\" ([Bundles release notes](https://docs.databricks.com/aws/en/release-notes/dev-tools/bundles)). Older MLOps material and questions may still say Asset Bundles.\n\n## Deploy Code vs Deploy Models\n\n| | **Deploy code** (promote code) | **Deploy models** (promote models) |\n| :--- | :--- | :--- |\n| **What moves between environments** | The training (and inference) **code** | The trained **model artifact** |\n| **Where the production model is trained** | In **production**, on production data, by reviewed code | In **development**; the artifact is tested in staging, then copied to production |\n| **Databricks recommendation** | \"In most situations, Databricks recommends the 'deploy code' approach.\" | Use when the conditions below apply |\n| **Advantages (docs)** | Works where access to production data is restricted; automated retraining is safer because training code is reviewed, tested, and approved; supporting code follows the same path through staging | A simpler handoff for data scientists; when training is expensive, the model is trained only once |\n| **Disadvantages (docs)** | The learning curve for data scientists to hand off code to collaborators can be steep | May not be viable if production data is not accessible from dev; automated retraining is tricky; supporting code (feature engineering, inference, monitoring pipelines) must be deployed to production separately |\n\n### **When to prefer deploy models**\n\nThe docs say to consider deploy models when one or more of these apply:\n\n- Model training is **very expensive or hard to reproduce** (e.g. a large deep-learning or fine-tuning job)\n- **All work is done in a single Databricks workspace**\n- You are **not working with external repos or a CI/CD process**\n\n### **When to prefer deploy code**\n\n- The default for most teams\n- **Access to production data is restricted** — deploy models may not be viable \"if production data is not accessible from the development environment,\" while deploy code trains where the data lives\n- You want automated retraining in production that goes through the same code review and testing as everything else\n\nSource: [Model deployment patterns](https://docs.databricks.com/aws/en/machine-learning/mlops/deployment-patterns).\n\n```python\n# Deploy models: copy a validated version from the staging catalog to prod, then alias it\nfrom mlflow import MlflowClient\n\nclient = MlflowClient()\ncopied = client.copy_model_version(\n    \"models:/staging.ml_team.fraud_detection/1\",\n    \"prod.ml_team.fraud_detection\",\n)\nclient.set_registered_model_alias(\"prod.ml_team.fraud_detection\", \"champion\", copied.version)\n```\n\n```text\n# Deploy code: no model copy — the release branch's training job runs in prod\nrelease branch merged\n  → CI/CD updates the prod training job\n  → job trains on prod.ml_team.* data, registers prod.ml_team.fraud_detection vN\n  → validation task sets @challenger; comparison task moves @champion\n```\n\n## Decoupling Deployment from Inference\n\nInference code should reference an alias, not a version number:\n\n```python\nimport mlflow\n\npredict = mlflow.pyfunc.spark_udf(spark, \"models:/prod.ml_team.fraud_detection@champion\")\nscored = spark.read.table(\"prod.ml_team.transactions\").withColumn(\n    \"fraud_score\", predict(\"amount\", \"merchant_id\", \"hour\"))\n```\n\nWhen a challenger wins, moving the `champion` alias is the whole deployment — the scoring job is untouched.\n\n## Use Cases\n\n- **Regulated Data, Deploy Code**: A bank's data scientists cannot read production customer data from the dev workspace, so the reviewed training code is promoted and the model is trained in production.\n- **Expensive Training, Deploy Models**: A team fine-tunes a large vision model for days on GPUs; they train once in dev, validate the artifact in staging, and copy the version into the prod catalog.\n\n## Common Issues & Errors\n\n### Model Trained in Dev Fails on Production Data\n\n**Scenario:** A model promoted with *deploy models* underperforms because dev data was a stale sample.\n**Fix:** Switch to *deploy code* so the model trains on production data, or ensure dev has read access to production-quality data before training.\n\n### Inference Job Breaks After Every Release\n\n**Scenario:** Scoring jobs hard-code `models:/name/5`, so each new version needs a code change.\n**Fix:** Load `models:/name@champion` and promote by moving the alias.\n\n## Exam Tips\n\n- ✅ Default answer: **deploy code** + separate dev/staging/prod catalogs + Git + CI/CD + UC registry\n- ✅ Pick **deploy models** when training is very expensive/hard to reproduce, everything is in one workspace, or there is no CI/CD/external repo\n- ✅ Restricted production data access favours **deploy code**, not deploy models\n- ✅ Champion/challenger is implemented with **aliases**, not stages\n\n## Key Takeaways\n\n- MLOps on Databricks = environments as UC catalogs + code in Git + MLflow + Models in UC + CI/CD + monitoring\n- Promote code by default; promote models only when retraining is impractical\n- Aliases make promotion a metadata change rather than a code change\n- Monitoring closes the loop by triggering retraining\n\n## Related Topics\n\n- [Model Registry in Unity Catalog](./07-model-registry.md)\n- [Databricks ML Workspace](./01-databricks-ml-workspace.md) — Git folders\n- [Model Deployment & Serving](../04-model-deployment/01-model-deployment-serving.md)\n- [ML Experimentation Workflow](../03-model-development/04-ml-experimentation-workflow.md)\n\n## Official Documentation\n\n- [MLOps workflows on Databricks](https://docs.databricks.com/aws/en/machine-learning/mlops/mlops-workflow)\n- [Model deployment patterns](https://docs.databricks.com/aws/en/machine-learning/mlops/deployment-patterns)\n- [Manage model lifecycle in Unity Catalog](https://docs.databricks.com/aws/en/machine-learning/manage-model-lifecycle/)\n\n---\n\n**[← Previous: Model Registry in Unity Catalog](./07-model-registry.md) | [↑ Back to Section](./README.md)**\n"},{"id":"01-databricks-machine-learning/README","folder":"01-databricks-machine-learning","group":"modulo","order":0,"isIndex":true,"title":"Databricks Machine Learning","md":"# Databricks Machine Learning (38 % of Exam)\n\nSection 1 of the exam guide and the largest domain. It covers the Databricks-specific ML surface: MLOps strategy, ML runtimes, AutoML, feature tables in Unity Catalog, MLflow tracking, and the Unity Catalog model registry (aliases, tags, champion/challenger promotion).\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    DML[Databricks ML] --> Plat[Workspace + ML runtimes]\n    DML --> AML[AutoML]\n    DML --> FS[Feature tables in UC]\n    DML --> MLF[MLflow tracking + runs]\n    DML --> Reg[UC model registry]\n    DML --> Ops[MLOps strategy]\n```\n\n## Section Contents\n\n| File | Topic | Exam-guide bullets covered | Priority |\n| :--- | :--- | :--- | :--- |\n| [01-databricks-ml-workspace.md](./01-databricks-ml-workspace.md) | Notebooks, widgets, Git folders, permissions | Context for every Section 1 bullet | Medium |\n| [02-compute-clusters-ml.md](./02-compute-clusters-ml.md) | ML runtime advantages, compute choices | Advantages of ML runtimes | High |\n| [03-databricks-automl.md](./03-databricks-automl.md) | AutoML for classification / regression / forecasting | AutoML model/feature selection; advantages of AutoML | High |\n| [04-feature-store.md](./04-feature-store.md) | Feature Engineering in Unity Catalog | UC vs workspace feature tables; create, write, train, score; online vs offline | High |\n| [05-mlflow-tracking.md](./05-mlflow-tracking.md) | Manual logging, autolog, log models | Manually log metrics, artifacts, and models | High |\n| [06-experiments-runs.md](./06-experiments-runs.md) | Experiments, run search, MLflow UI | Best run via MLflow Client API; information in the MLflow UI | High |\n| [07-model-registry.md](./07-model-registry.md) | Models in Unity Catalog | Register via Client API; UC vs workspace registry; tags; champion/challenger aliases | High |\n| [08-mlops-strategy.md](./08-mlops-strategy.md) | Environments, CI/CD, deploy code vs deploy models | MLOps best practices; promote code vs promote models | High |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **Databricks Runtime for ML** | Pre-installed, version-tested ML/DL libraries + MLflow + AutoML; GPU variants |\n| **AutoML** | Glass-box baselines: one MLflow run per trial, editable best-trial notebook, SHAP importance |\n| **Feature tables in UC** | `FeatureEngineeringClient.create_table` / `write_table(mode=\"merge\")`; `fe.log_model` + `fe.score_batch` |\n| **MLflow Client API** | `MlflowClient().search_runs(..., order_by=[...])` to find the best run |\n| **Models in Unity Catalog** | `catalog.schema.model`; aliases (`@champion`) instead of stages; governed by UC privileges |\n| **Deploy code vs deploy models** | Databricks recommends deploy code in most situations |\n\n## Related Resources\n\n- [MLflow Basics (shared)](../../../shared/fundamentals/mlflow-basics.md)\n- [Feature Engineering Basics (shared)](../../../shared/fundamentals/feature-engineering-basics.md)\n- [MLflow cheat sheet (shared)](../../../shared/cheat-sheets/mlflow-quick-ref.md)\n- [Hands-on Lab 04 — MLflow tracking and Model Registry in UC](../../../labs/04-mlflow-tracking.md)\n- [Databricks machine learning documentation](https://docs.databricks.com/aws/en/machine-learning/)\n\n---\n\n**[↑ Back to ML Associate](../README.md) | [Next: Data Processing →](../02-data-processing/README.md)** *(first domain — no previous)*\n"},{"id":"02-data-processing/01-exploratory-data-analysis","folder":"02-data-processing","group":"modulo","order":1,"isIndex":false,"title":"Exploratory Data Analysis for ML","md":"# Exploratory Data Analysis for ML\n\n## Overview\n\nBefore a single feature is encoded, you need to know what the data looks like: its distributions, its gaps, its extreme values, and how features relate to each other. Section 2 of the exam guide (**Data Processing, 19 %**) starts with exactly these skills — summary statistics, outlier removal, visualising features, and comparing pairs of features.\n\n> [!abstract]\n>\n> - `df.summary()` / `df.describe()` give count, mean, stddev, min/max (and quartiles for `summary`); `dbutils.data.summarize(df)` renders an interactive profile\n> - Outliers are removed by **standard deviation** (e.g. beyond ±3σ) or **IQR** fences (Q1 − 1.5·IQR, Q3 + 1.5·IQR)\n> - Categorical features → bar/count charts; continuous features → histograms, box plots, density plots\n> - Two continuous features → scatter plot + correlation; two categorical features → contingency table + chi-square test\n\n> [!tip] What the Exam Tests\n>\n> - *Compute summary statistics on a Spark DataFrame using `.summary()` or dbutils data summaries*\n> - *Remove outliers based on standard deviation or IQR* — know the formulas and the Spark calls\n> - *Create visualizations for categorical or continuous features* and *compare two categorical or two continuous features using the appropriate method*\n\n---\n\n## Summary Statistics\n\n### **`DataFrame.summary()` and `describe()`**\n\n```python\ndf = spark.read.table(\"ml_dev.housing.listings\")\n\n# Default: count, mean, stddev, min, 25%, 50%, 75%, max (approximate percentiles)\ndisplay(df.summary())\n\n# Pick specific statistics, including arbitrary percentiles\ndisplay(df.select(\"price\", \"sqft\").summary(\"count\", \"min\", \"10%\", \"50%\", \"90%\", \"max\"))\n\n# describe(): count, mean, stddev, min, max — no percentiles\ndisplay(df.describe(\"price\", \"sqft\"))\n```\n\n| Method | Statistics | Notes |\n| :--- | :--- | :--- |\n| `df.summary()` | count, mean, stddev, min, **25 % / 50 % / 75 %**, max | Pass names (`\"count\"`, `\"10%\"`, …) to choose; percentiles are approximate |\n| `df.describe()` | count, mean, stddev, min, max | Quick numeric overview without quartiles |\n| `dbutils.data.summarize(df)` | Per-column summary statistics, including histograms and percentiles for numeric columns | Rendered output in the notebook; works on Spark or pandas DataFrames |\n\nSource: [PySpark `DataFrame.summary`](https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.summary.html).\n\n### **`dbutils.data.summarize`**\n\n```python\ndbutils.data.summarize(df)                 # approximate statistics (default, faster)\ndbutils.data.summarize(df, precise=True)   # exact statistics except histograms/percentiles\n```\n\n- \"Calculates and displays summary statistics of an Apache Spark DataFrame or pandas DataFrame\"\n- It \"analyzes the complete contents of the DataFrame,\" so it can be expensive on very large data\n- `precise` (Databricks Runtime 10.4 LTS and above) trades speed for precision; with `precise=False` some statistics are approximations\n- The data utility is documented as **Public Preview**\n\nSource: [Databricks Utilities — data utility](https://docs.databricks.com/aws/en/dev-tools/databricks-utils).\n\n### **Missing values at a glance**\n\n```python\nfrom pyspark.sql import functions as F\n\nnull_counts = df.select([\n    F.sum(F.col(c).isNull().cast(\"int\")).alias(c) for c in df.columns\n])\ndisplay(null_counts)\n```\n\n## Removing Outliers\n\n### **Standard-deviation (z-score) rule**\n\nKeep values within *k* standard deviations of the mean (k = 3 is common; 2 is stricter). Best when the feature is roughly **normal** — the mean and stddev are themselves pulled by extreme values.\n\n```python\nfrom pyspark.sql import functions as F\n\nstats = df.select(F.mean(\"price\").alias(\"mu\"), F.stddev(\"price\").alias(\"sigma\")).first()\nk = 3\nlower, upper = stats[\"mu\"] - k * stats[\"sigma\"], stats[\"mu\"] + k * stats[\"sigma\"]\n\ndf_no_outliers = df.filter((F.col(\"price\") >= lower) & (F.col(\"price\") <= upper))\n```\n\n### **IQR (Tukey fences) rule**\n\nKeep values inside **[Q1 − 1.5·IQR, Q3 + 1.5·IQR]**, where IQR = Q3 − Q1. Robust for **skewed** data because quartiles barely move when extremes are present.\n\n```python\nq1, q3 = df.approxQuantile(\"price\", [0.25, 0.75], 0.01)   # relativeError=0.01\niqr = q3 - q1\nlower, upper = q1 - 1.5 * iqr, q3 + 1.5 * iqr\n\ndf_no_outliers = df.filter(F.col(\"price\").between(lower, upper))\n```\n\n| Rule | Bounds | Use when | Watch out |\n| :--- | :--- | :--- | :--- |\n| **Std-dev (z-score)** | μ ± k·σ | Roughly symmetric / normal features | Outliers inflate σ and can hide themselves |\n| **IQR** | Q1 − 1.5·IQR … Q3 + 1.5·IQR | Skewed features, unknown distribution | Very long tails can still flag many valid points |\n\n> [!warning] Common Mistake\n> Compute the bounds on the **training** split only, then apply the same bounds to validation/test data. Also decide whether an extreme value is an *error* (remove or fix) or a *rare but real* case (keep, cap, or log-transform).\n\n## Visualising Features\n\n| Feature type | Good plots | What you look for |\n| :--- | :--- | :--- |\n| **Categorical** | Bar chart / count plot of value frequencies | Rare levels, dominant levels, cardinality, class imbalance in the label |\n| **Continuous** | Histogram, density (KDE), box plot | Skew, multiple modes, outliers, impossible values |\n| **Continuous by category** | Box plot or violin plot per category | Whether the distribution shifts between groups |\n\n```python\n# Built-in: display(df) → \"+\" → Visualization (bar, histogram, box, scatter, ...)\ndisplay(df.groupBy(\"property_type\").count().orderBy(\"count\", ascending=False))\n\n# matplotlib / seaborn on a pandas sample\nimport matplotlib.pyplot as plt\nimport seaborn as sns\n\npdf = df.select(\"price\", \"sqft\", \"property_type\").sample(fraction=0.1, seed=42).toPandas()\n\nfig, axes = plt.subplots(1, 3, figsize=(15, 4))\nsns.histplot(pdf[\"price\"], bins=50, ax=axes[0])          # continuous: histogram\nsns.boxplot(x=pdf[\"sqft\"], ax=axes[1])                   # continuous: box plot (outliers)\nsns.countplot(x=pdf[\"property_type\"], ax=axes[2])        # categorical: counts\ndisplay(fig)\n```\n\n## Comparing Two Features\n\n### **Two continuous features → scatter plot + correlation**\n\n```python\n# Pearson correlation between two columns\nprint(df.stat.corr(\"sqft\", \"price\"))          # DataFrame.stat.corr supports Pearson\n\n# Correlation matrix (Pearson or Spearman) over a vector column\nfrom pyspark.ml.feature import VectorAssembler\nfrom pyspark.ml.stat import Correlation\n\nvec = VectorAssembler(inputCols=[\"sqft\", \"bedrooms\", \"price\"], outputCol=\"v\").transform(df)\nspearman = Correlation.corr(vec, \"v\", method=\"spearman\").head()[0]\nprint(spearman.toArray())\n\nsns.scatterplot(data=pdf, x=\"sqft\", y=\"price\")\n```\n\n- **Pearson** measures *linear* association; **Spearman** measures *monotonic* (rank) association and is less sensitive to outliers and skew\n- Correlation near ±1 between two *features* signals redundancy (multicollinearity) for linear models\n\n### **Two categorical features → contingency table + chi-square**\n\n```python\n# Contingency (cross) table of counts\ndisplay(df.stat.crosstab(\"property_type\", \"neighbourhood_group\"))\n\n# Chi-square test of independence of indexed categorical features vs a categorical label\nfrom pyspark.ml.feature import StringIndexer\nfrom pyspark.ml.stat import ChiSquareTest\n\nidx = StringIndexer(inputCols=[\"property_type\", \"room_type\"],\n                    outputCols=[\"property_type_idx\", \"room_type_idx\"]).fit(df).transform(df)\nvec = VectorAssembler(inputCols=[\"property_type_idx\"], outputCol=\"cat_features\").transform(idx)\n\nresult = ChiSquareTest.test(vec, \"cat_features\", \"room_type_idx\").head()\nprint(result.pValues, result.statistics)\n```\n\n- A small p-value means the two categorical variables are **not independent**\n- Visualise with a stacked/grouped bar chart or a heat map of the cross-tab\n\n| Pair of features | Numeric summary | Plot |\n| :--- | :--- | :--- |\n| Continuous × continuous | Pearson / Spearman correlation | Scatter plot |\n| Categorical × categorical | Contingency table, chi-square test (or Cramér's V) | Grouped / stacked bar chart, heat map |\n| Categorical × continuous | Group means/medians | Box plot per category |\n\n## Use Cases\n\n- **Data Quality Gate Before Training**: Running `df.summary()` and null counts on a new Unity Catalog table to catch impossible values (negative prices) before feature engineering.\n- **Choosing an Outlier Strategy**: A right-skewed `price` column is filtered with IQR fences instead of a 3σ rule because the extreme listings inflate the standard deviation.\n\n## Common Issues & Errors\n\n### `dbutils.data.summarize` Is Slow on a Large Table\n\n**Scenario:** The summary of a multi-billion-row table takes a long time.\n**Fix:** It scans the complete DataFrame — summarise a sample (`df.sample(0.01)`), keep `precise=False`, or use `df.summary()` on selected columns.\n\n### Outlier Filter Removes Too Many Rows\n\n**Scenario:** A z-score filter on a heavily skewed feature drops a large share of valid rows.\n**Fix:** Inspect the histogram first; for skewed data use IQR fences or log-transform before applying a z-score rule.\n\n## Exam Tips\n\n- ✅ `summary()` adds quartiles (25 %/50 %/75 %) that `describe()` does not show\n- ✅ `dbutils.data.summarize(df)` is the \"dbutils data summaries\" in the exam guide\n- ✅ Std-dev rule: μ ± 3σ (assumes roughly normal); IQR rule: Q1 − 1.5·IQR to Q3 + 1.5·IQR (robust to skew)\n- ✅ Two continuous → correlation + scatter; two categorical → cross-tab + chi-square\n- ✅ Bar charts for categorical frequencies; histograms/box plots for continuous distributions\n\n## Key Takeaways\n\n- EDA decides every later choice: imputation strategy, outlier handling, encoding, and transformations\n- `summary()` and `dbutils.data.summarize()` are the fastest way to profile a Spark DataFrame\n- Choose the outlier rule that matches the distribution: z-score for symmetric, IQR for skewed\n- Match the comparison method to the feature types\n\n## Related Topics\n\n- [Feature Engineering Techniques](./02-feature-engineering-techniques.md) — imputation, one-hot encoding, log transforms\n- [Model Evaluation & Metrics](../03-model-development/03-model-evaluation.md)\n- [Feature Engineering Basics (shared)](../../../shared/fundamentals/feature-engineering-basics.md)\n- [PySpark API cheat sheet (shared)](../../../shared/cheat-sheets/pyspark-api-quick-ref.md)\n\n## Official Documentation\n\n- [Databricks Utilities — data utility (`dbutils.data`)](https://docs.databricks.com/aws/en/dev-tools/databricks-utils)\n- [PySpark `DataFrame.summary`](https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.summary.html)\n- [Spark ML basic statistics (Correlation, ChiSquareTest)](https://spark.apache.org/docs/latest/ml-statistics.html)\n- [Visualizations in Databricks notebooks](https://docs.databricks.com/aws/en/visualizations/)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Feature Engineering Techniques →](./02-feature-engineering-techniques.md)**\n"},{"id":"02-data-processing/02-feature-engineering-techniques","folder":"02-data-processing","group":"modulo","order":2,"isIndex":false,"title":"Feature Engineering Techniques","md":"# Feature Engineering Techniques\n\n## Overview\n\nFeature engineering transforms raw data into meaningful features that improve model performance. It's often the most impactful component of machine learning. This file covers the Section 2 (Data Processing) bullets on **imputation**, **one-hot encoding**, and **log-scale transformation**.\n\n> [!abstract]\n>\n> - Impute with the **mean** (symmetric data), **median** (skewed data / outliers), or **mode** (categorical or discrete data) — after looking at the distribution\n> - Spark ML `Imputer` supports `strategy=\"mean\"` (default), `\"median\"`, and `\"mode\"` on numeric columns\n> - One-hot encoding (`StringIndexer` → `OneHotEncoder`) suits nominal features for linear / distance-based models; avoid it for high-cardinality or ordinal features and usually for tree-based models\n> - Log transforms compress right-skewed, positive features or targets that span orders of magnitude\n\n> [!tip] What the Exam Tests\n>\n> - *Compare and contrast imputing with the mean, median, or mode* — and *impute* with each\n> - *Use one-hot encoding* and *identify the model types or data sets for which it is or is not appropriate*\n> - *Identify scenarios where log-scale transformation is appropriate*\n\n---\n\n## Feature Engineering Pipeline\n\n```mermaid\nflowchart TB\n    Raw[\"Raw Data\"] --> Clean[\"Data Cleaning<br/>& Validation\"]\n    Clean --> Explore[\"Exploratory Data<br/>Analysis\"]\n    Explore --> Feat[\"Feature Creation\"]\n    Feat --> Scale[\"Scaling &<br/>Normalization\"]\n    Scale --> Encode[\"Categorical<br/>Encoding\"]\n    Encode --> Select[\"Feature<br/>Selection\"]\n    Select --> Model[\"ML Model\"]\n```\n\n## Handling Missing Values\n\n### **Removal vs Imputation**\n\n```python\nfrom pyspark.ml.feature import Imputer\nfrom pyspark.sql import functions as F\n\ndf = spark.read.table(\"data\")\n\n# Option 1: REMOVE rows with missing values\n# Use if: Missing data is rare (< 5%)\n\ndf_clean = df.dropna()\n\n# Option 2: REMOVE columns with too many missing values\n# Use if: Column has > 50% missing\n\ndf_clean = df.select([c for c in df.columns if df.filter(F.col(c).isNull()).count() / df.count() < 0.5])\n\n# Option 3: IMPUTATION - Replace missing values\n# Spark ML Imputer: strategy = \"mean\" (default) | \"median\" | \"mode\"; numeric columns only\n\nimputer = Imputer(\n    inputCols=[\"age\", \"income\", \"tenure\"],\n    outputCols=[\"age_imp\", \"income_imp\", \"tenure_imp\"],\n    strategy=\"median\"\n)\nimputer_model = imputer.fit(train_df)          # learn medians on TRAINING data only\ndf_imputed = imputer_model.transform(df)\n\n# Forward/backward fill (for time series)\n\nfrom pyspark.sql.window import Window\nwindow = Window.orderBy(\"date\").rowsBetween(-1, 0)\ndf_filled = df.withColumn(\"value_filled\", F.coalesce(\n    F.col(\"value\"),\n    F.last(F.col(\"value\"), ignorenulls=True).over(window)\n))\n\n# Domain-specific imputation\n\ndf_imputed = df.withColumn(\"category\",\n    F.when(F.col(\"category\").isNull(), \"Unknown\")\n     .otherwise(F.col(\"category\"))\n)\n```\n\n### **Mean vs Median vs Mode**\n\n| Strategy | Best for | Weakness | Spark / pandas |\n| :--- | :--- | :--- | :--- |\n| **Mean** | Continuous, roughly **symmetric** features with no strong outliers | Pulled toward outliers; distorts skewed distributions | `Imputer(strategy=\"mean\")` / `pdf[c].fillna(pdf[c].mean())` |\n| **Median** | Continuous features that are **skewed** or contain **outliers** (income, price) | Ignores the shape of the tails | `Imputer(strategy=\"median\")` / `pdf[c].fillna(pdf[c].median())` |\n| **Mode** | **Categorical** or discrete features (most frequent value) | Over-represents the dominant level | `Imputer(strategy=\"mode\")` for numeric codes; `fillna({c: most_frequent})` for strings |\n\n```python\nfrom pyspark.sql import functions as F\n\n# Mode for a STRING categorical column (Imputer only accepts numeric columns)\nmost_frequent = (train_df.groupBy(\"region\").count()\n    .orderBy(F.desc(\"count\")).first()[\"region\"])\ndf = df.fillna({\"region\": most_frequent})\n\n# Keep a missingness indicator — \"was missing\" can itself be predictive\ndf = df.withColumn(\"income_was_null\", F.col(\"income\").isNull().cast(\"int\"))\n```\n\n> [!warning] Common Mistake\n> There is no \"always correct\" imputation. A tool such as scikit-learn's `SimpleImputer` does **not** pick a strategy from the distribution — it uses whatever `strategy` you set (default mean). Examine the distribution (histogram, `summary()`), then choose: skew/outliers → median, symmetric → mean, categorical → mode. Fit the imputer on training data only.\n\nSources: [PySpark `Imputer`](https://spark.apache.org/docs/latest/api/python/reference/api/pyspark.ml.feature.Imputer.html), [scikit-learn `SimpleImputer`](https://scikit-learn.org/stable/modules/generated/sklearn.impute.SimpleImputer.html).\n\n## Categorical Encoding\n\n### **String Indexer**\n\n```python\nfrom pyspark.ml.feature import StringIndexer\n\n# Converts categories to indices (0, 1, 2, ...)\n\nindexer = StringIndexer(\n    inputCol=\"region\",\n    outputCol=\"region_idx\",\n    handleInvalid=\"keep\",            # unseen labels get an extra index instead of an error\n    stringOrderType=\"frequencyDesc\"  # default: MOST frequent category gets index 0\n)\n\n# Other orders: frequencyAsc (least frequent = 0), alphabetDesc, alphabetAsc\n# Ties under frequencyDesc/Asc are broken alphabetically\n\nindexed_df = indexer.fit(df).transform(df)\n\n# Example output (frequencyDesc):\n# region     = [\"North\", \"South\", \"North\", \"East\", \"South\", \"North\"]\n# region_idx = [0.0,     1.0,     0.0,     2.0,    1.0,     0.0]   # North (3) → 0, South (2) → 1, East (1) → 2\n\n```\n\n### **One-Hot Encoder**\n\n```python\nfrom pyspark.ml.feature import OneHotEncoder\n\n# Converts indices to binary vectors (one-hot)\n\nencoder = OneHotEncoder(\n    inputCols=[\"region_idx\"],\n    outputCols=[\"region_vec\"],\n    dropLast=True  # Drop one column to avoid multicollinearity\n)\n\nencoded_df = encoder.fit(df).transform(df)\n\n# Example (with 3 categories and dropLast=True):\n# region_idx = 0 → region_vec = [1, 0]\n# region_idx = 1 → region_vec = [0, 1]\n# region_idx = 2 → region_vec = [0, 0]\n\n```\n\n### **When One-Hot Encoding Is (and Is Not) Appropriate**\n\n| Situation | One-hot? | Why / alternative |\n| :--- | :--- | :--- |\n| Nominal feature, few levels, **linear / logistic regression, SVM, k-NN, neural nets** | ✅ Yes | These models treat numeric inputs as ordered magnitudes; an index like 0/1/2 would imply a false order |\n| **High-cardinality** feature (zip code, user ID, thousands of levels) | ❌ Usually no | Explodes dimensionality into very sparse vectors — use target/frequency encoding, hashing, or embeddings |\n| **Ordinal** feature (small < medium < large) | ❌ No | One-hot throws the order away — use an ordinal mapping |\n| **Tree-based models** (decision trees, random forest, gradient-boosted trees) | ⚠️ Often not needed | Trees split on indexed categories directly; one-hot splits a categorical feature across many sparse columns and can weaken splits |\n| Unseen categories at inference | Plan for it | `StringIndexer(handleInvalid=\"keep\")` and `OneHotEncoder(handleInvalid=\"keep\")` |\n\n> [!note]\n> `dropLast=True` (the default) drops one level so the columns are not perfectly collinear — this matters for linear models, not for trees.\n\n### **Target Encoding**\n\n```python\n\n# Replace category with target variable mean\n# Use when: High cardinality categories\n\ndf_with_target = df.select(\"region\", \"label\")\n\n# Calculate mean target value for each region\n\ntarget_encoding = (df_with_target\n    .groupBy(\"region\")\n    .agg(F.mean(\"label\").alias(\"region_target_mean\"))\n)\n\n# Join back to original data\n\ndf_target_encoded = (df\n    .join(target_encoding, \"region\")\n    .drop(\"region\")\n    .withColumnRenamed(\"region_target_mean\", \"region_encoded\")\n)\n\n# Problem: Risk of target leakage if not careful\n# Solution: Fit encoding on training set, apply to test set\n\n```\n\n### **Ordinal/Label Encoding**\n\n```python\n\n# Use when: Categories have natural order\n\n# Manual mapping for ordinal data\n\nfrom pyspark.sql.functions import when, col\n\ndf_encoded = df.withColumn(\"size_encoded\",\n    when(col(\"size\") == \"small\", 1)\n    .when(col(\"size\") == \"medium\", 2)\n    .when(col(\"size\") == \"large\", 3)\n    .otherwise(0)\n)\n\n# StringIndexer cannot follow a business order (small < medium < large):\n# frequency/alphabet ordering would scramble it, so prefer the explicit mapping above.\n```\n\n## Numerical Feature Scaling\n\n### **StandardScaler**\n\n```python\nfrom pyspark.ml.feature import VectorAssembler, StandardScaler\n\n# Standardize: (x - mean) / std → mean=0, std=1\n# Best for: Linear models, Neural Networks, KMeans\n\nassembler = VectorAssembler(inputCols=[\"age\", \"income\"], outputCol=\"features\")\nscaler = StandardScaler(\n    inputCol=\"features\",\n    outputCol=\"scaledFeatures\",\n    withMean=True,     # Center to mean=0\n    withStd=True       # Scale to std=1\n)\n\npipeline = Pipeline(stages=[assembler, scaler])\ndf_scaled = pipeline.fit(df).transform(df)\n\n# Benefits:\n# - Prevents feature dominance\n# - Speeds up convergence\n# - Better for regularization (L1, L2)\n\n```\n\n### **MinMaxScaler**\n\n```python\nfrom pyspark.ml.feature import MinMaxScaler\n\n# Scale to [min, max] range (default: [0, 1])\n\nscaler = MinMaxScaler(\n    inputCol=\"features\",\n    outputCol=\"scaledFeatures\",\n    min=0,\n    max=1\n)\n\ndf_scaled = scaler.fit(df).transform(df)\n\n# Formula: (x - min(x)) / (max(x) - min(x))\n# Best for: Tree models don't need scaling, but they use it for NN input\n# Sensitive to outliers\n\n```\n\n### **RobustScaler (Manual)**\n\n```python\n\n# Use for data with outliers\n# (x - median) / IQR\n\nfrom pyspark.sql.functions import percentile_approx, col\n\n# Calculate percentiles\n\npercentiles = df.agg(\n    percentile_approx(\"age\", 0.25).alias(\"q1\"),\n    percentile_approx(\"age\", 0.75).alias(\"q3\")\n)\n\nq1 = percentiles.collect()[0][\"q1\"]\nq3 = percentiles.collect()[0][\"q3\"]\niqr = q3 - q1\n\n# Scale using IQR\n\ndf_scaled = df.withColumn(\"age_scaled\", (col(\"age\") - q1) / iqr)\n```\n\n## Log-Scale Transformation\n\nApply a log transform when a feature or target is **positive and strongly right-skewed**, spanning several orders of magnitude (prices, incomes, counts, durations), or when effects are multiplicative. The log compresses large values and makes the distribution more symmetric, which helps linear models and distance-based methods.\n\n```python\nfrom pyspark.sql import functions as F\n\ndf_log = (df\n    .withColumn(\"log_price\", F.log(\"price\"))        # natural log; price must be > 0\n    .withColumn(\"log1p_reviews\", F.log1p(\"num_reviews\")))   # log(1 + x) handles zeros\n```\n\n| Appropriate | Not appropriate |\n| :--- | :--- |\n| Right-skewed, positive values spanning orders of magnitude | A feature that is already ~normal / centred near zero |\n| Variance that grows with the level (heteroscedastic) | Zero values (use `log1p`) or negative values (log is undefined) |\n| Multiplicative relationships you want to make additive | High-cardinality categoricals (not a cardinality-reduction tool) |\n\n> [!warning] Common Mistake\n> If you log-transform the **target**, the model predicts in log space. **Exponentiate predictions** (`exp`, or `expm1` after `log1p`) before computing RMSE/MAE in the original units or explaining predictions to the business — see [Model Evaluation & Metrics](../03-model-development/03-model-evaluation.md).\n\n## Feature Interactions\n\n### **Creating Interaction Features**\n\n```python\nfrom pyspark.sql.functions import col\n\n# Polynomial interaction\n\ndf_interactions = df.withColumn(\"age_income_interaction\", col(\"age\") * col(\"income\"))\ndf_interactions = df_interactions.withColumn(\"income_squared\", col(\"income\") ** 2)\n\n# Polynomial expansion\n\nfrom pyspark.ml.feature import PolynomialExpansion\n\npoly = PolynomialExpansion(\n    inputCol=\"features\",\n    outputCol=\"polyFeatures\",\n    degree=2  # Create degree-2 polynomials\n)\n\n# For features [a, b]:\n# Output: [a, b, a², ab, b²]\n\n```\n\n### **Feature Ratios**\n\n```python\n# Engineer domain-specific features\n\ndf_ratios = (df\n    .withColumn(\"charge_per_tenure\", col(\"monthly_charge\") / (col(\"tenure\") + 1))\n    .withColumn(\"total_charge_ratio\", col(\"total_charges\") / (col(\"monthly_charge\") + 1))\n    .withColumn(\"service_diversity\", col(\"num_services\") / col(\"account_age\"))\n)\n```\n\n## Feature Selection\n\n### **Filtering by Variance**\n\n```python\nfrom pyspark.ml.feature import VarianceThresholdSelector\n\n# Remove low-variance features (likely not predictive)\n\nselector = VarianceThresholdSelector(\n    featuresCol=\"features\",\n    outputCol=\"selectedFeatures\",\n    varianceThreshold=0.01  # Remove if variance < 0.01\n)\n\ndf_selected = selector.fit(df).transform(df)\n```\n\n### **Correlation Analysis**\n\n```python\n# Select features with high correlation to target\n\nfrom pyspark.sql.functions import corr\n\ncorrelations = {}\nfor col_name in numeric_cols:\n    corr_value = df.stat.corr(col_name, \"label\")\n    if abs(corr_value) > 0.1:  # Keep if |correlation| > 0.1\n        correlations[col_name] = corr_value\n\nprint(\"Important features:\", correlations)\n```\n\n### **Recursive Feature Elimination (Manual)**\n\n```python\n# Iteratively remove least important features\n\nfrom pyspark.ml.classification import RandomForestClassifier\n\ndef rfe_step(df, target_features):\n    \"\"\"Remove least important feature\"\"\"\n    rf = RandomForestClassifier(\n        numTrees=100,\n        labelCol=\"label\",\n        maxDepth=10\n    )\n\n    assembler = VectorAssembler(inputCols=target_features, outputCol=\"features\")\n    df_with_features = assembler.transform(df)\n\n    model = rf.fit(df_with_features)\n\n    # Get feature importance\n    feature_importance = {}\n    for i, feat in enumerate(target_features):\n        feature_importance[feat] = model.featureImportances[i]\n\n    # Remove least important\n    least_important = min(feature_importance, key=feature_importance.get)\n    return [f for f in target_features if f != least_important]\n\n# Iteratively remove until desired number reached\n\nfeatures = numeric_cols.copy()\nwhile len(features) > 10:\n    features = rfe_step(df, features)\n```\n\n## Temporal Features\n\n### **Time-Based Feature Engineering**\n\n```python\nfrom pyspark.sql.functions import col, dayofweek, dayofyear, month, year, hour\nfrom pyspark.sql.types import TimestampType\n\ndf_temporal = (df\n    # Basic temporal\n    .withColumn(\"date\", col(\"timestamp\").cast(TimestampType()))\n    .withColumn(\"year\", year(col(\"date\")))\n    .withColumn(\"month\", month(col(\"date\")))\n    .withColumn(\"day_of_week\", dayofweek(col(\"date\")))  # 1=Sunday, 7=Saturday\n    .withColumn(\"day_of_year\", dayofyear(col(\"date\")))\n    .withColumn(\"hour\", hour(col(\"date\")))\n\n    # Derived\n    .withColumn(\"is_weekend\", (col(\"day_of_week\").isin([1, 7])).cast(\"int\"))\n    .withColumn(\"is_business_hours\", ((col(\"hour\") >= 9) & (col(\"hour\") <= 17)).cast(\"int\"))\n    .withColumn(\"is_month_start\", (col(\"day_of_month\") <= 3).cast(\"int\"))\n)\n```\n\n### **Lag and Lead Features**\n\n```python\nfrom pyspark.sql.window import Window\n\n# Create lag features (previous values)\n\nwindow = Window.partitionBy(\"customer_id\").orderBy(\"date\").rowsBetween(-1, -1)\n\ndf_lag = (df\n    .withColumn(\"prev_value\", F.lag(\"value\").over(window))\n    .withColumn(\"prev_prev_value\", F.lag(\"value\", 2).over(window))\n)\n\n# Create rolling statistics\n\nwindow_rolling = Window.partitionBy(\"customer_id\").orderBy(\"date\").rowsBetween(-6, 0)\n\ndf_rolling = (df\n    .withColumn(\"rolling_mean_7\", F.mean(\"value\").over(window_rolling))\n    .withColumn(\"rolling_std_7\", F.stddev(\"value\").over(window_rolling))\n)\n```\n\n## Text Feature Extraction\n\n### **TF-IDF (Term Frequency - Inverse Document Frequency)**\n\n```python\nfrom pyspark.ml.feature import Tokenizer, CountVectorizer, IDF\n\n# Tokenize text\n\ntokenizer = Tokenizer(inputCol=\"text\", outputCol=\"words\")\n\n# Count word frequencies\n\ncv = CountVectorizer(\n    inputCol=\"words\",\n    outputCol=\"rawFeatures\",\n    vocabSize=1000,  # Top 1000 words\n    minDF=2  # Appear in at least 2 docs\n)\n\n# TF-IDF\n\nidf = IDF(inputCol=\"rawFeatures\", outputCol=\"features\")\n\n# Pipeline it\n\npipeline = Pipeline(stages=[tokenizer, cv, idf])\nfeatures = pipeline.fit(df).transform(df)\n```\n\n## Feature Engineering Checklist\n\n```python\nchecklist = {\n    \"Data Cleaning\": [\n        \"✓ Handle missing values\",\n        \"✓ Detect outliers\",\n        \"✓ Fix data type issues\",\n        \"✓ Handle duplicates\"\n    ],\n    \"Encoding\": [\n        \"✓ Encode categorical variables\",\n        \"✓ Handle high-cardinality categories\",\n        \"✓ Check for multicollinearity\",\n        \"✓ Avoid target leakage\"\n    ],\n    \"Scaling\": [\n        \"✓ Normalize/standardize numeric features\",\n        \"✓ Handle different units\",\n        \"✓ Consider outlier sensitivity\",\n        \"✓ Fit on train, apply to test\"\n    ],\n    \"Engineering\": [\n        \"✓ Create domain-specific features\",\n        \"✓ Extract temporal patterns\",\n        \"✓ Create feature interactions\",\n        \"✓ Document feature creation\"\n    ],\n    \"Selection\": [\n        \"✓ Remove low-variance features\",\n        \"✓ Check feature importance\",\n        \"✓ Handle multicollinearity\",\n        \"✓ Domain expert validation\"\n    ]\n}\n```\n\n## Real-World Example: Customer Feature Engineering\n\n```python\n%python\nfrom pyspark.sql import functions as F\nfrom pyspark.ml import Pipeline\nfrom pyspark.ml.feature import StringIndexer, OneHotEncoder, VectorAssembler, StandardScaler\n\n# Load raw customer data\n\ndf_raw = spark.read.table(\"raw.customers\")\n\n# STEP 1: Impute missing values\n\nfrom pyspark.ml.feature import Imputer\n\ndf_imputed = (Imputer(inputCols=[\"income\"], outputCols=[\"income\"], strategy=\"median\")\n    .fit(df_raw)\n    .transform(df_raw)\n    .fillna({\"region\": \"Unknown\"}))\n\n# STEP 2: Create features\n\ndf_featured = (df_imputed\n    .withColumn(\"tenure_days\", F.datediff(F.current_date(), F.col(\"signup_date\")))\n    .withColumn(\"monthly_usage_ratio\", F.col(\"monthly_usage\") / (F.col(\"historical_usage\") + 1))\n    .withColumn(\"is_high_value\", (F.col(\"annual_revenue\") > 50000).cast(\"int\"))\n)\n\n# STEP 3: Categorical encoding + scaling\n\npipeline = Pipeline(stages=[\n    StringIndexer(inputCol=\"region\", outputCol=\"region_idx\"),\n    StringIndexer(inputCol=\"segment\", outputCol=\"segment_idx\"),\n    OneHotEncoder(inputCols=[\"region_idx\", \"segment_idx\"],\n                  outputCols=[\"region_vec\", \"segment_vec\"]),\n    VectorAssembler(inputCols=[\"tenure_days\", \"monthly_usage_ratio\",\n                               \"is_high_value\", \"region_vec\", \"segment_vec\"],\n                   outputCol=\"features\"),\n    StandardScaler(inputCol=\"features\", outputCol=\"scaledFeatures\")\n])\n\ndf_engineered = pipeline.fit(df_featured).transform(df_featured)\n\n# STEP 4: Save for modeling\n\n(df_engineered.select(\"customer_id\", \"scaledFeatures\", \"label\")\n    .write.mode(\"overwrite\")\n    .saveAsTable(\"ml_ready.customer_features\"))\n```\n\n## Use Cases\n\n- **Customer Churn Prediction Pipeline**: Engineering features like tenure-to-charge ratio, rolling 7-day usage averages, and weekend activity flags from raw customer data, then assembling them into a Spark ML Pipeline for model training.\n- **High-Cardinality Categorical Handling**: Using target encoding for a `zip_code` column with 40,000 distinct values where one-hot encoding would create too many sparse features, while carefully fitting the encoding only on training data to avoid leakage.\n\n## Common Issues & Errors\n\n### Feature Leakage Causing Unrealistic Metrics\n\n**Scenario:** Model scores 99% accuracy in training but performs poorly in production.\n**Fix:** Check for target leakage -- ensure no features are derived from the target variable or future data. Fit transformers (scalers, encoders, imputers) only on training data, then apply the fitted transformer to test data.\n\n### OneHotEncoder Fails on Unseen Categories at Inference Time\n\n**Scenario:** `StringIndexer` raises an error when production data contains a category value not seen during training (e.g., a new `region` value).\n**Fix:** Set `handleInvalid=\"keep\"` on the `StringIndexer` to map unknown categories to a separate index rather than throwing an error.\n\n## Exam Tips\n\n- Rule of thumb (not a Databricks rule): drop rows when very few are missing, drop a column when most of it is missing, impute in between\n- Mean for symmetric, **median for skewed/outliers**, **mode for categorical**; `Imputer` supports all three on numeric columns\n- Log-transform right-skewed positive features/targets; exponentiate log-space predictions before reporting metrics\n- One-hot encode nominal features for linear models; avoid it for high-cardinality or ordinal features\n- The required sequence is `StringIndexer` (string to numeric index) then `OneHotEncoder` (index to binary vector) -- OHE cannot accept raw strings\n- `StandardScaler` is essential for distance-based models (logistic regression, SVM, KMeans) but unnecessary for tree-based models (Random Forest, XGBoost)\n- Target encoding risks data leakage -- always fit encoding on training data only, never on the full dataset including test\n- `VectorAssembler` combines multiple feature columns into a single `features` vector column required by Spark ML estimators\n- `dropLast=True` on `OneHotEncoder` removes one column to prevent multicollinearity in linear models\n\n## Key Takeaways\n\n- Feature engineering often more impactful than algorithm choice\n- Missing value handling depends on percentage missing\n- Categorical encoding requires careful ordering\n- Scaling essential for distance-based and linear models\n- Feature interactions capture non-linear relationships\n- Always fit transformations on training data, apply to test\n- Domain knowledge crucial for creating meaningful features\n\n## Related Topics\n\n- [Exploratory Data Analysis for ML](./01-exploratory-data-analysis.md)\n- [Spark ML Pipelines](../03-model-development/01-spark-ml-pipelines.md)\n- [Feature Store in Unity Catalog](../01-databricks-machine-learning/04-feature-store.md)\n- [Feature Engineering Basics (shared)](../../../shared/fundamentals/feature-engineering-basics.md)\n\n## Official Documentation\n\n- [Spark ML Features](https://spark.apache.org/docs/latest/ml-features.html)\n- [PySpark `Imputer`](https://spark.apache.org/docs/latest/api/python/reference/api/pyspark.ml.feature.Imputer.html)\n- [PySpark `StringIndexer`](https://spark.apache.org/docs/latest/api/python/reference/api/pyspark.ml.feature.StringIndexer.html)\n\n---\n\n**[← Previous: Exploratory Data Analysis for ML](./01-exploratory-data-analysis.md) | [↑ Back to Section](./README.md)**\n"},{"id":"02-data-processing/README","folder":"02-data-processing","group":"modulo","order":0,"isIndex":true,"title":"Data Processing","md":"# Data Processing (19 % of Exam)\n\nSection 2 of the exam guide. It covers what you do to the data before training: profiling it with summary statistics, removing outliers, visualising and comparing features, imputing missing values, one-hot encoding categorical features, and deciding when a log transform helps.\n\n> [!note] Section name: PDF vs certification page\n> The exam-guide PDF (re-issued \"August 2026\", exam version Mar 1, 2025) calls this section **\"Data Processing (19%)\"** and lists the bullets below. The certification web page still labels the 19 % domain **\"ML Workflows\"**. This guide follows the PDF, which is the source of truth. MLflow tracking — which older versions of this guide filed under \"ML Workflows\" — is a Section 1 skill in the PDF and now lives in [Databricks Machine Learning](../01-databricks-machine-learning/README.md).\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    DP[Data Processing] --> Stats[Summary statistics]\n    DP --> Out[Outlier removal]\n    DP --> Viz[Visualise + compare features]\n    DP --> Imp[Imputation]\n    DP --> OHE[One-hot encoding]\n    DP --> Log[Log transforms]\n```\n\n## Section Contents\n\n| File | Topic | Exam-guide bullets covered | Priority |\n| :--- | :--- | :--- | :--- |\n| [01-exploratory-data-analysis.md](./01-exploratory-data-analysis.md) | `summary()`, `dbutils.data.summarize`, outliers, plots, feature comparisons | Summary statistics; outliers (std dev / IQR); visualisations; compare two categorical / two continuous features | High |\n| [02-feature-engineering-techniques.md](./02-feature-engineering-techniques.md) | Imputation, encoding, scaling, log transforms | Mean vs median vs mode imputation; impute; one-hot encoding and when it is (not) appropriate; log-scale transformation | High |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **`df.summary()`** | count, mean, stddev, min, quartiles, max in one call |\n| **`dbutils.data.summarize(df)`** | Databricks' rendered data summary of a Spark or pandas DataFrame |\n| **IQR fences** | Q1 − 1.5·IQR … Q3 + 1.5·IQR — robust outlier bounds for skewed data |\n| **`Imputer(strategy=...)`** | `mean` (default), `median`, `mode` — choose after inspecting the distribution |\n| **`StringIndexer` → `OneHotEncoder`** | Index first, then encode; skip one-hot for high-cardinality / ordinal features |\n| **Log transform** | For right-skewed positive values; exponentiate log-space predictions before metrics |\n\n## Related Resources\n\n- [Feature Engineering Basics (shared)](../../../shared/fundamentals/feature-engineering-basics.md)\n- [PySpark API cheat sheet (shared)](../../../shared/cheat-sheets/pyspark-api-quick-ref.md)\n- [Spark ML feature transformers](https://spark.apache.org/docs/latest/ml-features.html)\n\n---\n\n**[← Previous: Databricks Machine Learning](../01-databricks-machine-learning/README.md) | [↑ Back to ML Associate](../README.md) | [Next: Model Development →](../03-model-development/README.md)**\n"},{"id":"03-model-development/01-spark-ml-pipelines","folder":"03-model-development","group":"modulo","order":1,"isIndex":false,"title":"Spark ML Pipelines","md":"# Spark ML Pipelines\n\n## Overview\n\nSpark ML Pipelines provide a high-level API for building reproducible machine learning workflows. They standardize the process of feature engineering, training, and prediction. Section 3 (Model Development) asks you to **compare estimators and transformers** and **develop a training pipeline**.\n\n> [!abstract]\n>\n> - A **Transformer** has `transform(df)` and returns a new DataFrame (`VectorAssembler`, `Bucketizer`, `SQLTransformer`, a fitted model)\n> - An **Estimator** has `fit(df)` and returns a fitted **Model** — which is itself a Transformer (`StringIndexer`, `OneHotEncoder`, `StandardScaler`, `Imputer`, `LogisticRegression`)\n> - A `Pipeline` is an Estimator; `pipeline.fit(train)` returns a `PipelineModel` (a Transformer) that replays every fitted stage\n> - Wrapping the whole pipeline in `CrossValidator` keeps preprocessing inside each fold, avoiding leakage\n\n> [!tip] What the Exam Tests\n>\n> - Classifying a class as Estimator vs Transformer (anything that must *learn* from data is an Estimator)\n> - What `fit()` vs `transform()` return, and stage ordering (`StringIndexer` → `OneHotEncoder` → `VectorAssembler` → model)\n> - Building a training pipeline that can be saved/logged once and reused for inference\n\n---\n\n## Pipeline Architecture\n\n```mermaid\nflowchart LR\n    subgraph Input[\"Input\"]\n        L1[\"Label Column\"]\n        F1[\"Feature Columns\"]\n    end\n\n    subgraph Pipeline[\"Pipeline Stages\"]\n        S1[\"Stage 1:<br/>StringIndexer\"]\n        S2[\"Stage 2:<br/>OneHotEncoder\"]\n        S3[\"Stage 3:<br/>VectorAssembler\"]\n        S4[\"Stage 4:<br/>StandardScaler\"]\n        S5[\"Stage 5:<br/>LogisticRegression\"]\n    end\n\n    subgraph Output[\"Output\"]\n        Predictions[\"Predictions<br/>+ Probability\"]\n    end\n\n    L1 --> S1\n    F1 --> S2\n    S1 --> S2\n    S2 --> S3\n    S3 --> S4\n    S4 --> S5\n    S5 --> Predictions\n\n    style S1 fill:#e1f5ff\n    style S2 fill:#e1f5ff\n    style S3 fill:#e1f5ff\n    style S4 fill:#f3e5f5\n    style S5 fill:#fff9c4\n```\n\n## Core Concepts\n\n### **Transformers**\n\nTransformers convert input DataFrames to output DataFrames. They have a `transform()` method and **learn nothing** from the data.\n\n```python\nfrom pyspark.ml.feature import VectorAssembler\n\n# Create a transformer — no fit() needed\n\nassembler = VectorAssembler(\n    inputCols=[\"age\", \"income\"],\n    outputCol=\"features\"\n)\n\n# Transform data\n\nassembled_df = assembler.transform(df)\n\n# Common Transformers (no fitting):\n\ntransformers = {\n    \"VectorAssembler\": \"Combine feature columns into a single vector\",\n    \"Bucketizer\": \"Discretize a continuous column with fixed split points\",\n    \"SQLTransformer\": \"Apply a SQL statement to the DataFrame\",\n    \"Tokenizer\": \"Split text into words\",\n    \"PolynomialExpansion\": \"Generate polynomial features\",\n    \"<any fitted Model>\": \"e.g. StringIndexerModel, LogisticRegressionModel, PipelineModel\"\n}\n```\n\n### **Estimators**\n\nEstimators learn from data using the `fit()` method, then produce a fitted Model (which is a Transformer).\n\n```python\nfrom pyspark.ml.classification import LogisticRegression, RandomForestClassifier\nfrom pyspark.ml.regression import LinearRegression\nfrom pyspark.ml.feature import StringIndexer\n\n# Create an estimator\n\nlr = LogisticRegression(\n    featuresCol=\"features\",\n    labelCol=\"label\",\n    maxIter=10\n)\n\n# Fit to learn parameters\n\nmodel = lr.fit(df)  # Returns a Transformer\n\n# Use the model to transform\n\npredictions = model.transform(test_df)\n\n# Common Estimators:\n\nestimators = {\n    \"LogisticRegression\": \"Binary/Multi-class classification\",\n    \"RandomForestClassifier\": \"Tree-based classification\",\n    \"LinearRegression\": \"Regression with linear modeling\",\n    \"GBTClassifier\": \"Gradient boosted trees for classification\",\n    \"StringIndexer\": \"Learn the category -> index mapping\",\n    \"OneHotEncoder\": \"Learn the number of categories per column\",\n    \"StandardScaler / MinMaxScaler\": \"Learn mean/std or min/max\",\n    \"Imputer\": \"Learn the mean/median/mode to fill\",\n    \"CountVectorizer\": \"Learn the vocabulary from text\",\n    \"Pipeline\": \"Fits every stage in order -> PipelineModel\"\n}\n```\n\n| | Transformer | Estimator |\n| :--- | :--- | :--- |\n| **Key method** | `transform(df)` → DataFrame | `fit(df)` → Model (a Transformer) |\n| **Learns from data?** | No | Yes |\n| **Examples** | `VectorAssembler`, `Bucketizer`, `SQLTransformer`, `Tokenizer`, any fitted `...Model` | `StringIndexer`, `OneHotEncoder`, `StandardScaler`, `MinMaxScaler`, `Imputer`, `LogisticRegression`, `Pipeline` |\n\nSource: [Spark ML Pipelines](https://spark.apache.org/docs/latest/ml-pipeline.html), [PySpark `pyspark.ml.feature` API](https://spark.apache.org/docs/latest/api/python/reference/pyspark.ml.html).\n\n### **Pipelines**\n\nPipelines chain multiple stages (estimators and transformers) in sequence.\n\n```python\nfrom pyspark.ml import Pipeline\n\n# Define stages\n\nstages = [\n    StringIndexer(inputCol=\"category\", outputCol=\"category_idx\"),\n    OneHotEncoder(inputCols=[\"category_idx\"], outputCols=[\"category_vec\"]),\n    VectorAssembler(inputCols=[\"category_vec\", \"numeric\"], outputCol=\"features\"),\n    StandardScaler(inputCol=\"features\", outputCol=\"scaledFeatures\"),\n    LogisticRegression(featuresCol=\"scaledFeatures\", labelCol=\"label\")\n]\n\n# Create pipeline\n\npipeline = Pipeline(stages=stages)\n\n# Fit pipeline (learns all estimators)\n\nfitted_pipeline = pipeline.fit(training_df)\n\n# Transform new data\n\npredictions = fitted_pipeline.transform(test_df)\n\n# KEY INSIGHT: Pipeline handles all transformations automatically!\n\n```\n\n## Complete ML Pipeline Example\n\n### **Binary Classification Pipeline**\n\n```python\n%python\nfrom pyspark.ml import Pipeline\nfrom pyspark.ml.feature import StringIndexer, OneHotEncoder, VectorAssembler, StandardScaler\nfrom pyspark.ml.classification import LogisticRegression\nfrom pyspark.sql import functions as F\nimport mlflow\n\n# LOAD DATA\n\ndf = spark.read.table(\"ml_catalog.data.customer_data\")\n\n# DATA PREPARATION\n# Create label: convert string to 0/1\n\ndf_processed = (df\n    .withColumn(\"label\", (F.col(\"churned\") == \"yes\").cast(\"int\"))\n    .drop(\"churned\")\n)\n\n# DEFINE PIPELINE STAGES\n\nstages = [\n    # Categorical encoding\n    StringIndexer(\n        inputCol=\"region\",\n        outputCol=\"region_idx\",\n        handleInvalid=\"keep\"\n    ),\n    StringIndexer(\n        inputCol=\"plan\",\n        outputCol=\"plan_idx\",\n        handleInvalid=\"keep\"\n    ),\n\n    # One-hot encoding\n    OneHotEncoder(\n        inputCols=[\"region_idx\", \"plan_idx\"],\n        outputCols=[\"region_vec\", \"plan_vec\"]\n    ),\n\n    # Feature assembly\n    VectorAssembler(\n        inputCols=[\n            \"region_vec\", \"plan_vec\",\n            \"age\", \"tenure\", \"monthly_charge\", \"total_charges\"\n        ],\n        outputCol=\"features\"\n    ),\n\n    # Feature scaling\n    StandardScaler(\n        inputCol=\"features\",\n        outputCol=\"scaledFeatures\"\n    ),\n\n    # Classifier\n    LogisticRegression(\n        featuresCol=\"scaledFeatures\",\n        labelCol=\"label\",\n        maxIter=10\n    )\n]\n\n# CREATE PIPELINE\n\npipeline = Pipeline(stages=stages)\n\n# SPLIT DATA\n\ntrain_df, test_df = df_processed.randomSplit([0.8, 0.2], seed=42)\n\n# FIT PIPELINE\n\nfitted_pipeline = pipeline.fit(train_df)\n\n# MAKE PREDICTIONS\n\npredictions = fitted_pipeline.transform(test_df)\n\n# EVALUATE\n\nfrom pyspark.ml.evaluation import BinaryClassificationEvaluator, MulticlassClassificationEvaluator\n\nevaluator = BinaryClassificationEvaluator(\n    labelCol=\"label\",\n    rawPredictionCol=\"rawPrediction\",\n    metricName=\"areaUnderROC\"\n)\n\nauc = evaluator.evaluate(predictions)\nprint(f\"AUC: {auc:.3f}\")\n\n# LOG TO MLFLOW\n\nwith mlflow.start_run(run_name=\"logistic_pipeline\"):\n    mlflow.log_param(\"model_type\", \"LogisticRegression\")\n    mlflow.log_metric(\"auc\", auc)\n    mlflow.spark.log_model(fitted_pipeline, \"pipeline\")\n```\n\n## Pipeline Best Practices\n\n### **Handling Missing Values**\n\n```python\nfrom pyspark.ml.feature import Imputer\n\n# Imputed stages in pipeline\n\nimputer = Imputer(\n    inputCols=[\"age\", \"income\", \"tenure\"],\n    outputCols=[\"age\", \"income\", \"tenure\"],\n    strategy=\"median\"  # or \"mean\" (default) / \"mode\"\n)\n\nstages = [imputer, *other_stages]\n```\n\n### **Categorical Encoding Order**\n\n```python\n\n# IMPORTANT: StringIndexer BEFORE OneHotEncoder\n\nstages = [\n    # Step 1: Convert strings to indices (0, 1, 2, ...)\n    StringIndexer(inputCol=\"category\", outputCol=\"category_idx\"),\n\n    # Step 2: One-hot encode indices\n    OneHotEncoder(inputCols=[\"category_idx\"], outputCols=[\"category_vec\"]),\n\n    # Step 3: Use in model\n    VectorAssembler(inputCols=[\"category_vec\", \"...\"], outputCol=\"features\")\n]\n```\n\n### **Feature Scaling Strategies**\n\n```python\nfrom pyspark.ml.feature import StandardScaler, MinMaxScaler\n\n# StandardScaler: (x - mean) / std\n# Best for: Linear models, Neural Networks, KMeans\n\nstandard_scaler = StandardScaler(inputCol=\"features\", outputCol=\"scaledFeatures\")\n\n# MinMaxScaler: (x - min) / (max - min) → [0, 1]\n# Best for: Tree models (not needed), Neural Networks\n\nminmax_scaler = MinMaxScaler(inputCol=\"features\", outputCol=\"scaledFeatures\")\n\n# RobustScaler: (x - median) / IQR  (pyspark.ml.feature.RobustScaler, an Estimator)\n# Best for: Data with outliers\n\n```\n\n### **Feature Selection in Pipeline**\n\n```python\nfrom pyspark.ml.feature import VectorSlicer\nfrom pyspark.ml.stat import ChiSquareTest, Correlation\n\n# Option 1: Manual feature selection\n\nslicer = VectorSlicer(\n    inputCol=\"features\",\n    outputCol=\"selectedFeatures\",\n    indices=[0, 1, 3, 5]  # Select indices 0, 1, 3, 5\n)\n\n# Option 2: Use only important features\n\nimportant_features = [\"age\", \"income\", \"tenure\"]\nassembler = VectorAssembler(inputCols=important_features, outputCol=\"features\")\n```\n\n## Training and Prediction Workflow\n\n```python\n# TRAINING PHASE\n\ntrain_df = spark.read.table(\"data.train_set\")\n\npipeline = Pipeline(stages=[...])\nfitted_pipeline = pipeline.fit(train_df)\n\n# Save trained pipeline\n\nfitted_pipeline.save(\"/Volumes/ml_dev/churn/models/trained_pipeline\")\n\n# PREDICTION PHASE\n\nnew_data = spark.read.table(\"data.new_customers\")\npredictions = fitted_pipeline.transform(new_data)\n\n# Display only relevant columns\n\npredictions.select(\"customer_id\", \"prediction\", \"probability\").show()\n```\n\n## Advanced Pipeline Features\n\n### **Pipeline Parameters**\n\n```python\nfrom pyspark.ml import Pipeline, Estimator\nfrom pyspark.ml.param import Params, Param\n\n# Some stages can be configured post-creation\n\nlr = LogisticRegression()\nlr.setMaxIter(20).setRegParam(0.1)\n\n# Or passed at creation\n\nlr2 = LogisticRegression(maxIter=20, regParam=0.1)\n\n# Pipeline is just a list of stages - can be modified\n\nstages = [stage1, stage2]\nstages.append(stage3)\npipeline = Pipeline(stages=stages)\n```\n\n### **Cross-Validation with Pipelines**\n\n```python\nfrom pyspark.ml.tuning import CrossValidator, ParamGridBuilder\nfrom pyspark.ml.evaluation import BinaryClassificationEvaluator\n\n# Define parameter grid\n\nparam_grid = (ParamGridBuilder()\n    .addGrid(lr.maxIter, [10, 20, 30])\n    .addGrid(lr.regParam, [0.01, 0.1, 1.0])\n    .build())\n\n# Define evaluator\n\nevaluator = BinaryClassificationEvaluator(\n    labelCol=\"label\",\n    metricName=\"areaUnderROC\"\n)\n\n# Create cross-validator\n\ncv = CrossValidator(\n    estimator=pipeline,\n    estimatorParamMaps=param_grid,\n    evaluator=evaluator,\n    numFolds=5\n)\n\n# Fit cross-validator\n\ncv_model = cv.fit(train_df)\n\n# Best model automatically selected\n\nbest_predictions = cv_model.transform(test_df)\n```\n\n### **Pipeline Persistence**\n\n```python\n# Save fitted pipeline\n\nfitted_pipeline.save(\"/Volumes/ml_dev/churn/models/production_pipeline\")\n\n# Load and use\n\nfrom pyspark.ml import PipelineModel\nloaded_pipeline = PipelineModel.load(\"/Volumes/ml_dev/churn/models/production_pipeline\")\npredictions = loaded_pipeline.transform(new_data)\n```\n\n## Comparison: DataFrame Operations vs Pipelines\n\n| Aspect | DataFrame Ops | Pipelines |\n|--------|---|---|\n| **Reusability** | Code duplication | Reproducible, shareable |\n| **Training/Inference** | Manual fit steps | Automatic via transform |\n| **Parameter Tuning** | Manual loops | Built-in CrossValidator |\n| **Debugging** | Easy to inspect | Less transparent |\n| **Production** | Hard to deploy | Easy via MLflow |\n| **Best For** | Exploration | Production ML |\n\n## Real-World Pipeline: Customer Churn\n\n```python\n%python\n\n# Complete production-ready pipeline\n\n# Load data\n\ndf = spark.read.table(\"production.customer_360.churn_data\")\n\n# Prepare\n\ndf_ready = df.select([\n    F.col(\"customer_id\"),\n    F.col(\"churned\").cast(\"int\").alias(\"label\"),\n    F.col(\"age\"), F.col(\"tenure\"),\n    F.col(\"monthly_charge\"), F.col(\"total_charges\"),\n    F.col(\"region\"), F.col(\"plan_type\")\n])\n\n# Split\n\ntrain, test = df_ready.randomSplit([0.8, 0.2], seed=42)\n\n# Build & fit pipeline\n\npipeline = Pipeline(stages=[\n    StringIndexer(inputCol=\"region\", outputCol=\"region_idx\"),\n    StringIndexer(inputCol=\"plan_type\", outputCol=\"plan_idx\"),\n    OneHotEncoder(inputCols=[\"region_idx\", \"plan_idx\"],\n                  outputCols=[\"region_vec\", \"plan_vec\"]),\n    VectorAssembler(inputCols=[\"age\", \"tenure\", \"monthly_charge\",\n                               \"total_charges\", \"region_vec\", \"plan_vec\"],\n                   outputCol=\"features\"),\n    StandardScaler(inputCol=\"features\", outputCol=\"scaledFeatures\"),\n    LogisticRegression(featuresCol=\"scaledFeatures\", labelCol=\"label\", maxIter=10)\n])\n\nfitted_pipeline = pipeline.fit(train)\n\n# Evaluate\n\npredictions = fitted_pipeline.transform(test)\nauc = BinaryClassificationEvaluator(labelCol=\"label\").evaluate(predictions)\nprint(f\"AUC: {auc:.3f}\")\n\n# Save\n\nmlflow.spark.log_model(fitted_pipeline, \"pipeline\")\nfitted_pipeline.save(\"/Volumes/ml_prod/churn/models/churn_pipeline\")\n```\n\n## Use Cases\n\n- **Large Scale Transformations**: Leveraging Spark SQL distributed execution semantics to transform multi-terabyte datasets efficiently.\n- **Reproducible Training-to-Serving Pipeline**: Packaging all preprocessing and model steps into a single pipeline so that the same transformations are applied consistently during both training and batch inference.\n\n## Common Issues & Errors\n\n### OOM Errors\n\n**Scenario:** Data skew causes an executor to run out of memory.\n**Fix:** Use Adaptive Query Execution (AQE) and review joining logic.\n\n### Pipeline `transform()` Fails on New Data\n\n**Scenario:** A fitted pipeline throws `IllegalArgumentException` when transforming new data with different column names or types.\n**Fix:** Ensure the input schema matches exactly what the pipeline was fitted on. Use `StringIndexer(handleInvalid=\"keep\")` for unseen categories.\n\n## Exam Tips\n\n- ✅ Transformer = `transform()` only (VectorAssembler, Bucketizer, SQLTransformer); Estimator = `fit()` → Model (StringIndexer, OneHotEncoder, StandardScaler, Imputer, any algorithm, Pipeline)\n- ✅ Know pipeline stages are fit in sequence\n- ✅ Recognize StringIndexer must come before OneHotEncoder\n- ✅ Understand VectorAssembler combines features\n- ✅ Know StandardScaler prevents feature dominance\n- ✅ Remember pipelines provide reproducibility\n\n## Key Takeaways\n\n- Pipelines chain transformers and estimators for reproducible workflows\n- Transformers have `transform()` method (no learning)\n- Estimators have `fit()` method (learn parameters)\n- Pipelines automatically fit all stages in sequence\n- Feature scaling prevents certain features from dominating\n- Pipelines enable easy production deployment and A/B testing\n\n## Related Topics\n\n- [Hyperparameter Tuning](./02-hyperparameter-tuning.md)\n- [Feature Engineering Techniques](../02-data-processing/02-feature-engineering-techniques.md)\n- [Feature Store in Unity Catalog](../01-databricks-machine-learning/04-feature-store.md)\n- [MLflow Tracking](../01-databricks-machine-learning/05-mlflow-tracking.md)\n\n## Official Documentation\n\n- [Spark ML Pipelines](https://spark.apache.org/docs/latest/ml-pipeline.html)\n- [Spark ML Tuning](https://spark.apache.org/docs/latest/ml-tuning.html)\n- [Databricks machine learning documentation](https://docs.databricks.com/aws/en/machine-learning/)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Hyperparameter Tuning →](./02-hyperparameter-tuning.md)**\n"},{"id":"03-model-development/02-hyperparameter-tuning","folder":"03-model-development","group":"modulo","order":2,"isIndex":false,"title":"Hyperparameter Tuning & Cross-Validation","md":"# Hyperparameter Tuning & Cross-Validation\n\n## Overview\n\nHyperparameters (tree depth, learning rate, regularisation strength) are set *before* training and are chosen by searching: try candidate values, evaluate each on held-out data, keep the best. Section 3 (Model Development, 31 %) tests the search strategies, Hyperopt's `fmin`, parallelising single-node models, cross-validation vs a train-validation split, and counting how many models a grid search trains.\n\n> [!abstract]\n>\n> - **Grid search** tries every combination; **random search** samples combinations; **Bayesian search** (Hyperopt TPE, Optuna TPE) uses past results to choose the next trial\n> - Spark ML: `ParamGridBuilder` + `CrossValidator` (k-fold) or `TrainValidationSplit` (one split); then a final refit on all training data\n> - Hyperopt: `fmin(fn, space, algo, max_evals, trials)` minimises a loss; `SparkTrials` parallelises **single-node** models (e.g. scikit-learn) across the cluster\n> - Models trained by grid + k-fold CV = **combinations × k** (plus one final refit in tools that refit)\n\n> [!tip] What the Exam Tests\n>\n> - *Use Hyperopt's `fmin` operation* and *perform random, grid, or Bayesian search*\n> - *Parallelize single-node models for hyperparameter tuning* (`SparkTrials`, not for MLlib)\n> - *Benefits and downsides of cross-validation vs a train-validation split*, *perform cross-validation*, and *count the models trained*\n\n---\n\n## Search Strategies\n\n| Strategy | How it picks the next trial | Strengths | Weaknesses |\n| :--- | :--- | :--- | :--- |\n| **Grid search** | Every combination of listed values | Exhaustive, simple, reproducible | Cost grows multiplicatively with every parameter; wastes trials on unimportant parameters |\n| **Random search** | Random samples from ranges/distributions | Covers wide ranges cheaply; often as good as grid with far fewer trials | No learning between trials |\n| **Bayesian search** (e.g. TPE) | Builds a model of \"params → loss\" from completed trials and proposes promising regions | Fewest trials to a good result | Sequential by nature — heavy parallelism reduces its advantage |\n\n```mermaid\nflowchart LR\n    Space[\"Search space\"] --> G[\"Grid:<br/>all combinations\"]\n    Space --> R[\"Random:<br/>N samples\"]\n    Space --> B[\"Bayesian (TPE):<br/>next trial informed by previous losses\"]\n    G --> Eval[\"Evaluate on validation data / CV\"]\n    R --> Eval\n    B --> Eval\n    Eval -->|loss| B\n```\n\n## Spark ML: Grid Search with Cross-Validation\n\n```python\nfrom pyspark.ml import Pipeline\nfrom pyspark.ml.classification import RandomForestClassifier\nfrom pyspark.ml.evaluation import BinaryClassificationEvaluator\nfrom pyspark.ml.tuning import CrossValidator, ParamGridBuilder, TrainValidationSplit\n\nrf = RandomForestClassifier(featuresCol=\"features\", labelCol=\"label\")\npipeline = Pipeline(stages=[indexer, encoder, assembler, rf])\n\nparam_grid = (ParamGridBuilder()\n    .addGrid(rf.maxDepth, [4, 8, 12])\n    .addGrid(rf.numTrees, [50, 100])\n    .build())                                   # 3 x 2 = 6 combinations\n\nevaluator = BinaryClassificationEvaluator(labelCol=\"label\", metricName=\"areaUnderROC\")\n\ncv = CrossValidator(\n    estimator=pipeline,                         # whole pipeline -> preprocessing refit inside each fold\n    estimatorParamMaps=param_grid,\n    evaluator=evaluator,\n    numFolds=5,                                 # default is 3\n    parallelism=4,                              # evaluate up to 4 param maps concurrently\n    seed=42,\n)\ncv_model = cv.fit(train_df)                     # 6 x 5 = 30 fits, then 1 refit on all of train_df\nbest_pipeline = cv_model.bestModel\nprint(cv_model.avgMetrics)                      # mean metric per param map\n\ntvs = TrainValidationSplit(\n    estimator=pipeline,\n    estimatorParamMaps=param_grid,\n    evaluator=evaluator,\n    trainRatio=0.8,                             # default 0.75\n)\ntvs_model = tvs.fit(train_df)                   # 6 fits, then 1 refit\n```\n\n- `CrossValidator`: \"After identifying the best `ParamMap`, `CrossValidator` finally re-fits the `Estimator` using the best `ParamMap` and the entire dataset\"\n- `TrainValidationSplit` \"only evaluates each combination of parameters once, as opposed to k times in the case of `CrossValidator`\"\n- `parallelism` defaults to 1 (serial); \"a value up to 10 should be sufficient for most clusters\"\n\nSource: [Spark ML Tuning](https://spark.apache.org/docs/latest/ml-tuning.html).\n\n### **Counting the models trained**\n\n| Setup | Fits during search | Final refit | Typical exam answer |\n| :--- | :--- | :--- | :--- |\n| Grid of 3 × 2 × 3 values, 5-fold CV | 18 × 5 = 90 | +1 (if the tool refits) | **combinations × folds** |\n| Grid of 6 combinations, `TrainValidationSplit` | 6 | +1 | combinations |\n| Hyperopt `max_evals=50`, no CV inside the objective | 50 | — | `max_evals` |\n| Hyperopt `max_evals=50`, 3-fold CV inside the objective | 50 × 3 = 150 | — | evals × folds |\n\n> [!warning] Common Mistake\n> Multiply, don't add: the grid size is the **product** of the number of values per hyperparameter, and k-fold CV trains **k** models per combination. Spark's `CrossValidator` and scikit-learn's `GridSearchCV(refit=True)` then fit one more model on all the training data; the official sample question counts only combinations × folds, so read whether the question asks about the search or \"in total including the final model\".\n\n## Cross-Validation vs Train-Validation Split\n\n| | k-fold cross-validation | Single train-validation split |\n| :--- | :--- | :--- |\n| **How** | Train on k−1 folds, validate on the held-out fold, repeat k times, average | Train once on one part, validate once on the rest |\n| **Benefits** | Every row is used for validation once → **lower-variance, more reliable estimate**; better on small datasets | **k times cheaper / faster**; fine on large datasets |\n| **Downsides** | **k times the training cost**; slower | Estimate depends on one random split → higher variance; wastes data on small datasets |\n| **Spark ML** | `CrossValidator(numFolds=k)` | `TrainValidationSplit(trainRatio=...)` |\n| **scikit-learn** | `cross_val_score`, `GridSearchCV(cv=k)` | `train_test_split` |\n\nNeither replaces a final, untouched **test set** for reporting the chosen model's performance.\n\n## Hyperopt: `fmin` for Bayesian and Random Search\n\n```python\nimport mlflow\nfrom hyperopt import fmin, tpe, rand, hp, Trials, SparkTrials, STATUS_OK, space_eval\nfrom sklearn.ensemble import GradientBoostingClassifier\nfrom sklearn.model_selection import cross_val_score\n\nsearch_space = {\n    \"n_estimators\": hp.quniform(\"n_estimators\", 50, 500, 50),\n    \"max_depth\": hp.quniform(\"max_depth\", 2, 8, 1),\n    \"learning_rate\": hp.loguniform(\"learning_rate\", -5, 0),   # e^-5 .. e^0\n    \"subsample\": hp.uniform(\"subsample\", 0.5, 1.0),\n}\n\ndef objective(params):\n    model = GradientBoostingClassifier(\n        n_estimators=int(params[\"n_estimators\"]),\n        max_depth=int(params[\"max_depth\"]),\n        learning_rate=params[\"learning_rate\"],\n        subsample=params[\"subsample\"],\n    )\n    auc = cross_val_score(model, X_train, y_train, cv=3, scoring=\"roc_auc\").mean()\n    return {\"loss\": -auc, \"status\": STATUS_OK}    # fmin MINIMISES, so negate a score\n\nwith mlflow.start_run(run_name=\"gbt_hyperopt\"):\n    best = fmin(\n        fn=objective,\n        space=search_space,\n        algo=tpe.suggest,                 # Bayesian (Tree-structured Parzen Estimator)\n        max_evals=40,                     # number of hyperparameter settings = models to fit\n        trials=SparkTrials(parallelism=8),\n    )\n\nprint(space_eval(search_space, best))     # map hp.choice indices back to values\n```\n\n| `fmin` argument | Meaning |\n| :--- | :--- |\n| `fn` | Objective; returns the loss (scalar or `{\"loss\": ..., \"status\": STATUS_OK}`) |\n| `space` | Search space built from `hp.*` expressions |\n| `algo` | `tpe.suggest` (Bayesian / adaptive) or `rand.suggest` (random search) |\n| `max_evals` | \"Number of hyperparameter settings to try (the number of models to fit)\" |\n| `trials` | `Trials()` (driver, sequential) or `SparkTrials(...)` (parallel on Spark workers) |\n\nGrid search is not an `fmin` algorithm — use `ParamGridBuilder` / `GridSearchCV`, or enumerate a grid with `hp.choice` and random/TPE sampling.\n\n### **Parallelising single-node models with `SparkTrials`**\n\n- `SparkTrials` \"is designed to parallelize computations for single-machine ML models such as scikit-learn\" — each trial trains on one worker\n- For **distributed** algorithms (Spark MLlib, Horovod) use the default `Trials` — model building is already parallelised on the cluster\n- `parallelism` trade-off: \"Because Hyperopt proposes new trials based on past results, there is a trade-off between parallelism and adaptivity\" — more parallel trials finish faster but learn less from each other\n\nSource: [Hyperopt concepts](https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/hyperopt-concepts).\n\n> [!note] Platform update (Oct 2026)\n> The Databricks docs now say \"The open-source version of Hyperopt is no longer being maintained,\" and \"Hyperopt is not included in Databricks Runtime for Machine Learning after 16.4 LTS ML.\" They recommend **Optuna** for single-node optimisation (parallelisable with Joblib, or across Spark executors with MLflow's `MlflowSparkStudy`) and **Ray Tune** for distributed tuning ([Hyperparameter tuning](https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/)). The exam guide still names Hyperopt's `fmin` — learn it, then practise the same ideas with Optuna on a current runtime.\n\n```python\n# The same idea with Optuna across Spark executors (MLflow 3 / DBR 17.0 ML+)\nimport mlflow\nfrom mlflow.optuna.storage import MlflowStorage\nfrom mlflow.pyspark.optuna.study import MlflowSparkStudy\n\nstorage = MlflowStorage(experiment_id=mlflow.get_experiment_by_name(experiment_path).experiment_id)\nstudy = MlflowSparkStudy(study_name=\"gbt-tuning\", storage=storage)   # default sampler: TPESampler\nstudy.optimize(optuna_objective, n_trials=40, n_jobs=8)\n```\n\nSource: [Hyperparameter tuning with Optuna](https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/optuna).\n\n## scikit-learn Equivalents\n\n```python\nfrom sklearn.model_selection import GridSearchCV, RandomizedSearchCV\nfrom sklearn.svm import SVC\n\ngrid = GridSearchCV(\n    SVC(),\n    param_grid={\"C\": [0.1, 1, 10], \"kernel\": [\"linear\", \"rbf\"]},   # 3 x 2 = 6 combinations\n    cv=5,                                                          # 6 x 5 = 30 fits (+1 refit)\n    scoring=\"f1\",\n)\nrand_search = RandomizedSearchCV(SVC(), param_distributions={\"C\": [0.01, 0.1, 1, 10, 100]},\n                                 n_iter=10, cv=5)                  # 10 x 5 = 50 fits (+1 refit)\n```\n\n## Use Cases\n\n- **Tuning a scikit-learn Model on a Cluster**: A gradient-boosting model that fits on one machine is tuned with Hyperopt TPE and `SparkTrials(parallelism=8)`, running eight trials at a time on workers while MLflow logs each trial as a child run.\n- **Cheaper Tuning on Big Data**: A 2-billion-row Spark ML pipeline uses `TrainValidationSplit` instead of 5-fold `CrossValidator` to cut tuning cost by roughly 5×.\n\n## Common Issues & Errors\n\n### `SparkTrials` Used with a Spark MLlib Estimator\n\n**Scenario:** Tuning a `pyspark.ml` model with `SparkTrials` fails or performs badly.\n**Fix:** MLlib training is already distributed — use `Trials()` (or Spark ML's `CrossValidator`), and reserve `SparkTrials` for single-node libraries.\n\n### Hyperopt Maximises the Wrong Thing\n\n**Scenario:** The \"best\" parameters have the *worst* AUC.\n**Fix:** `fmin` minimises. Return `-auc` (or `1 - auc`) as the loss; return RMSE/log loss as-is.\n\n## Exam Tips\n\n- ✅ Grid = exhaustive; random = sampled; Bayesian (TPE) = informed by previous trials\n- ✅ `fmin(fn, space, algo=tpe.suggest | rand.suggest, max_evals, trials)`; the objective returns a **loss** to minimise\n- ✅ `SparkTrials` → single-node models in parallel; `Trials` → distributed MLlib models\n- ✅ CV: more reliable, k× cost; train-validation split: cheaper, noisier\n- ✅ Models trained = (product of grid sizes) × folds; a final refit adds one\n- ✅ `CrossValidator` default `numFolds=3`; `TrainValidationSplit` default `trainRatio=0.75`\n\n## Key Takeaways\n\n- Choose the search strategy by budget: grid for tiny spaces, random for wide spaces, Bayesian when trials are expensive\n- Put the whole preprocessing pipeline inside the tuner so each fold is fit without leakage\n- Parallelism speeds tuning but reduces how much Bayesian search can learn between trials\n- Hyperopt is what the exam names; Optuna and Ray Tune are the platform's current recommendations\n\n## Related Topics\n\n- [Spark ML Pipelines](./01-spark-ml-pipelines.md)\n- [Model Evaluation & Metrics](./03-model-evaluation.md)\n- [Compute Clusters for ML](../01-databricks-machine-learning/02-compute-clusters-ml.md)\n- [Experiments & Runs](../01-databricks-machine-learning/06-experiments-runs.md) — nested runs for tuning trials\n\n## Official Documentation\n\n- [Hyperparameter tuning on Databricks](https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/)\n- [Hyperopt concepts](https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/hyperopt-concepts)\n- [Hyperparameter tuning with Optuna](https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/optuna)\n- [Spark ML Tuning](https://spark.apache.org/docs/latest/ml-tuning.html)\n\n---\n\n**[← Previous: Spark ML Pipelines](./01-spark-ml-pipelines.md) | [↑ Back to Section](./README.md) | [Next: Model Evaluation & Metrics →](./03-model-evaluation.md)**\n"},{"id":"03-model-development/03-model-evaluation","folder":"03-model-development","group":"modulo","order":3,"isIndex":false,"title":"Model Evaluation & Metrics","md":"# Model Evaluation & Metrics\n\n## Overview\n\nTraining a model is easy; knowing whether it is *good* — and good at the right thing — is the hard part. This file covers the Section 3 (Model Development) bullets on choosing an algorithm, handling imbalanced training data, classification and regression metrics, picking the metric that matches the objective, undoing log transforms before evaluation, and the bias-variance tradeoff.\n\n> [!abstract]\n>\n> - Classification metrics: accuracy, precision, recall, **F1**, **log loss**, **ROC AUC** (and PR AUC); regression metrics: **RMSE**, **MAE**, **R²**\n> - Imbalanced data: resample (over/under-sample), **class weights / cost-sensitive learning**, stratified splits, threshold tuning — and never judge by accuracy alone\n> - If the target was log-transformed, **exponentiate predictions** before computing RMSE/MAE or interpreting them\n> - Low training error + high validation error = **high variance (overfitting)**; high error on both = **high bias (underfitting)**\n\n> [!tip] What the Exam Tests\n>\n> - *Use ML foundations to select the appropriate algorithm* and *identify methods to mitigate data imbalance*\n> - *Use common classification and regression metrics* and *choose the most appropriate metric for a scenario*\n> - *Exponentiate log-transformed variables* and *assess model complexity and the bias-variance tradeoff*\n\n---\n\n## Selecting an Algorithm\n\n| Scenario | Good starting algorithms | Why |\n| :--- | :--- | :--- |\n| Predict a **number** (price, demand) | Linear regression (with regularisation), random forest / gradient-boosted trees | Regression task; trees capture non-linear effects |\n| Predict a **category** (churn yes/no, product type) | Logistic regression, decision tree, random forest, gradient-boosted trees | Classification task |\n| Need **interpretability** (regulated decisions) | Linear / logistic regression, shallow decision tree | Coefficients or rules are explainable |\n| Strong **non-linear** relationships and interactions | Tree ensembles (random forest, XGBoost/LightGBM, GBT) | Learn interactions without manual feature crosses |\n| **Very large** data on Spark | Spark ML `LogisticRegression`, `LinearRegression`, `RandomForest*`, `GBT*` | Distributed training |\n| Group similar records **without labels** | k-means clustering | Unsupervised |\n| Predict **future values over time** | Forecasting methods (e.g. Prophet / ARIMA via AutoML forecasting) | Time-series structure |\n\nStart simple (a linear or shallow tree baseline), then add complexity only if validation metrics improve.\n\n## Mitigating Class Imbalance\n\nWhen one class dominates (e.g. 10 % churners), a model can score high accuracy by always predicting the majority class.\n\n| Method | How | Notes |\n| :--- | :--- | :--- |\n| **Cost-sensitive learning / class weights** | Give minority-class errors a higher cost: `class_weight=\"balanced\"` (scikit-learn), `weightCol` (Spark ML) | Directly counters bias toward the majority class; no data is discarded |\n| **Oversample the minority class** | Duplicate minority rows, or synthesise them (e.g. SMOTE) | Apply to the **training** split only |\n| **Undersample the majority class** | Randomly drop majority rows | Loses information; fast on big data |\n| **Stratified splitting** | Keep the class ratio in train/validation/test | Prevents folds with almost no positives |\n| **Threshold tuning** | Move the decision threshold away from 0.5 using the PR or ROC curve | Trades precision for recall |\n| **Right metric** | F1, recall, precision, PR AUC, log loss — not accuracy | Measures minority-class performance |\n\n```python\nfrom pyspark.sql import functions as F\nfrom pyspark.ml.classification import LogisticRegression\n\n# Class weights in Spark ML: weight = (#rows / (#classes * #rows_in_class))\ncounts = {r[\"label\"]: r[\"count\"] for r in train_df.groupBy(\"label\").count().collect()}\nn, k = sum(counts.values()), len(counts)\ntrain_w = train_df.withColumn(\n    \"weight\",\n    F.when(F.col(\"label\") == 1, n / (k * counts[1])).otherwise(n / (k * counts[0])))\n\nlr = LogisticRegression(featuresCol=\"features\", labelCol=\"label\", weightCol=\"weight\")\n\n# scikit-learn equivalent\nfrom sklearn.ensemble import RandomForestClassifier\nrf = RandomForestClassifier(class_weight=\"balanced\")\n```\n\n> [!warning] Common Mistake\n> Normalising features, using a simpler model, or collecting *more majority-class* data does not fix imbalance. Resample, re-weight, or change the threshold — and evaluate on the **original** class distribution (AutoML, for example, balances only the training split).\n\n## Classification Metrics\n\n| Metric | Formula / meaning | Use when |\n| :--- | :--- | :--- |\n| **Accuracy** | (TP + TN) / all | Classes are balanced and errors cost the same |\n| **Precision** | TP / (TP + FP) — of predicted positives, how many are right | False positives are expensive (spam filter, fraud alerts that block customers) |\n| **Recall** (sensitivity) | TP / (TP + FN) — of actual positives, how many are found | False negatives are expensive (disease screening, churn you must catch) |\n| **F1** | Harmonic mean of precision and recall | Imbalanced classes; need one number balancing both |\n| **ROC AUC** | Area under TPR-vs-FPR curve; threshold-independent ranking quality | Compare models' ranking ability across thresholds |\n| **PR AUC** | Area under precision-recall curve | Heavy imbalance where positives are rare |\n| **Log loss** | Penalises confident wrong probabilities | You need well-calibrated **probabilities** |\n\n```python\nfrom pyspark.ml.evaluation import BinaryClassificationEvaluator, MulticlassClassificationEvaluator\n\nauc = BinaryClassificationEvaluator(labelCol=\"label\", metricName=\"areaUnderROC\").evaluate(preds)\npr_auc = BinaryClassificationEvaluator(labelCol=\"label\", metricName=\"areaUnderPR\").evaluate(preds)\nf1 = MulticlassClassificationEvaluator(labelCol=\"label\", metricName=\"f1\").evaluate(preds)\nlogloss = MulticlassClassificationEvaluator(labelCol=\"label\", metricName=\"logLoss\").evaluate(preds)\n\nfrom sklearn.metrics import f1_score, log_loss, roc_auc_score\nf1_score(y_true, y_pred); log_loss(y_true, y_proba); roc_auc_score(y_true, y_proba)\n```\n\n## Regression Metrics\n\n| Metric | Meaning | Notes |\n| :--- | :--- | :--- |\n| **RMSE** | √(mean squared error), in target units | Penalises large errors heavily; sensitive to outliers |\n| **MAE** | Mean absolute error, in target units | Robust to outliers; every unit of error counts equally |\n| **R²** | Share of variance explained (1 = perfect, 0 = predicts the mean, can be < 0) | Unitless; good for comparing fits on the same data |\n| **MSE** | Mean squared error | Squared units; same ranking as RMSE |\n\n```python\nfrom pyspark.ml.evaluation import RegressionEvaluator\n\nrmse = RegressionEvaluator(labelCol=\"price\", predictionCol=\"prediction\", metricName=\"rmse\").evaluate(preds)\nmae = RegressionEvaluator(labelCol=\"price\", metricName=\"mae\").evaluate(preds)\nr2 = RegressionEvaluator(labelCol=\"price\", metricName=\"r2\").evaluate(preds)\n```\n\n## Choosing the Metric for the Objective\n\n| Business objective | Metric |\n| :--- | :--- |\n| \"Catch as many fraudulent transactions as possible\" | **Recall** (with a precision floor) |\n| \"Only flag a customer when we are confident\" | **Precision** |\n| Rare positive class, balance both error types | **F1** or **PR AUC** |\n| Rank customers by risk; threshold chosen later | **ROC AUC** |\n| Probabilities feed a downstream cost model | **Log loss** |\n| Forecast error in dollars, big misses are very costly | **RMSE** |\n| Forecast error in dollars, outliers should not dominate | **MAE** |\n| How much variance the model explains | **R²** |\n\n## Exponentiating Log-Transformed Targets\n\nIf you trained on `log(price)`, the model's predictions are log-prices. RMSE computed on log values is not in dollars, and showing a \"predicted price\" of 12.3 is meaningless. Convert back first:\n\n```python\nfrom pyspark.sql import functions as F\nfrom pyspark.ml.evaluation import RegressionEvaluator\n\ntrain = train_df.withColumn(\"log_price\", F.log(\"price\"))\nmodel = rf_pipeline.fit(train)                       # label = log_price\n\npreds = (model.transform(test_df)\n    .withColumn(\"pred_price\", F.exp(F.col(\"prediction\"))))   # back to original units\n\nrmse_dollars = RegressionEvaluator(labelCol=\"price\", predictionCol=\"pred_price\",\n                                   metricName=\"rmse\").evaluate(preds)\n```\n\n```python\nimport numpy as np\ny_pred_dollars = np.expm1(model.predict(X_test))     # if you trained on np.log1p(y)\n```\n\n> [!warning] Common Mistake\n> Exponentiate **predictions**, then compare with the **original** label. Computing metrics on log-scale values (or comparing log predictions with dollar labels) gives numbers that look small but mean nothing to the business.\n\n## Bias-Variance Tradeoff and Model Complexity\n\n```mermaid\nflowchart LR\n    Simple[\"Too simple<br/>high bias\"] -->|\"add complexity\"| Sweet[\"Balanced<br/>lowest validation error\"]\n    Sweet -->|\"add more complexity\"| Complex[\"Too complex<br/>high variance\"]\n```\n\n| Symptom | Diagnosis | Remedies |\n| :--- | :--- | :--- |\n| **High** training error **and high** validation error | **High bias — underfitting** | More complex model (deeper trees, more features, less regularisation), train longer |\n| **Low** training error, **much higher** validation error | **High variance — overfitting** | Reduce complexity (shallower trees, fewer features), add regularisation, more training data, early stopping, bagging |\n| Low training error, similar low validation error | Good fit | Confirm on the untouched test set |\n\n- **Bias** = error from wrong assumptions (model too simple); **variance** = error from sensitivity to the particular training sample (model too flexible)\n- Increasing complexity lowers bias but raises variance; the goal is the complexity with the **lowest validation error**\n- Tree depth, number of features, polynomial degree, and inverse regularisation strength are all \"complexity knobs\"\n\n## Use Cases\n\n- **Churn with 10 % Positives**: The team switches from accuracy to F1 and PR AUC, adds class weights, and tunes the threshold to reach 80 % recall at acceptable precision.\n- **House Prices on a Log Scale**: A right-skewed price target is modelled as `log(price)`; predictions are exponentiated before RMSE is reported in dollars.\n\n## Common Issues & Errors\n\n### 95 % Accuracy but the Model Never Finds Fraud\n\n**Scenario:** On data with 5 % fraud, the model predicts \"not fraud\" for everything.\n**Fix:** Evaluate with recall, F1, or PR AUC; apply class weights or resampling; tune the threshold.\n\n### Validation Error Rises While Training Error Keeps Falling\n\n**Scenario:** As `maxDepth` grows, training RMSE keeps dropping but validation RMSE starts increasing.\n**Fix:** The model is overfitting — pick the depth with the lowest validation error, add regularisation, or gather more data.\n\n## Exam Tips\n\n- ✅ Imbalance → cost-sensitive learning / class weights or resampling; judge with F1 / recall / PR AUC, not accuracy\n- ✅ Precision = \"of my positives, how many are right\"; recall = \"of the real positives, how many did I find\"\n- ✅ RMSE punishes large errors; MAE is robust to outliers; R² is unitless variance explained\n- ✅ Log-transformed target → exponentiate predictions before metrics or interpretation\n- ✅ Low train error + high validation error = overfitting (high variance) → reduce complexity / regularise\n\n## Key Takeaways\n\n- The metric must match the cost of each kind of error\n- Imbalance is handled in the training data or loss, then measured on realistic data\n- Evaluation happens in the target's original units\n- Model complexity is a dial between bias and variance — validation error tells you where to stop\n\n## Related Topics\n\n- [Hyperparameter Tuning & Cross-Validation](./02-hyperparameter-tuning.md)\n- [Feature Engineering Techniques](../02-data-processing/02-feature-engineering-techniques.md) — log transforms\n- [Databricks AutoML](../01-databricks-machine-learning/03-databricks-automl.md) — automatic class balancing\n- [ML Experimentation Workflow](./04-ml-experimentation-workflow.md)\n\n## Official Documentation\n\n- [Spark ML evaluation metrics](https://spark.apache.org/docs/latest/mllib-evaluation-metrics.html)\n- [Spark ML classification and regression](https://spark.apache.org/docs/latest/ml-classification-regression.html)\n- [scikit-learn model evaluation](https://scikit-learn.org/stable/modules/model_evaluation.html)\n\n---\n\n**[← Previous: Hyperparameter Tuning & Cross-Validation](./02-hyperparameter-tuning.md) | [↑ Back to Section](./README.md) | [Next: ML Experimentation Workflow →](./04-ml-experimentation-workflow.md)**\n"},{"id":"03-model-development/04-ml-experimentation-workflow","folder":"03-model-development","group":"modulo","order":4,"isIndex":false,"title":"ML Experimentation Workflow","md":"# ML Experimentation Workflow\n\n## Overview\n\nAn effective machine learning workflow systematically explores the problem space through structured experimentation, enabling data-driven decisions for model improvement. This file ties the Section 3 skills together end-to-end: baseline, feature iterations, tuning, cross-validation, final test evaluation, and hand-off to the Unity Catalog registry.\n\n> [!abstract]\n>\n> - Define the objective and the metric first (recall vs precision vs RMSE), then build a quick baseline\n> - Iterate on features, algorithms, and hyperparameters — every iteration is an MLflow run\n> - Cross-validate the leading candidate; touch the **test set once**, at the end\n> - Register the winner in Unity Catalog and give it the `challenger` alias for promotion\n\n> [!tip] What the Exam Tests\n>\n> - *Develop a training pipeline* — the order of split → fit preprocessing on train → train → evaluate\n> - Reading train vs validation vs test results to spot over/underfitting\n> - Where tuning, cross-validation, and the final test evaluation each belong in the workflow\n\n---\n\n## Complete ML Workflow\n\n```mermaid\nflowchart TB\n    Start[\"Start New Model\"] --> 1[\"1. Define Problem<br/>& Metrics\"]\n    1 --> 2[\"2. Prepare Data\"]\n    2 --> 3[\"3. Baseline Model\"]\n    3 --> 4[\"Experiment Cycle\"]\n\n    4 --> 4.1[\"4.1 Feature<br/>Engineering\"]\n    4 --> 4.2[\"4.2 Algorithm<br/>Selection\"]\n    4 --> 4.3[\"4.3 Hyperparameter<br/>Tuning\"]\n    4 --> 4.4[\"4.4 Evaluate &<br/>Compare\"]\n\n    4.1 --> Compare{Performance<br/>Improved?}\n    4.2 --> Compare\n    4.3 --> Compare\n    4.4 --> Compare\n\n    Compare -->|Yes| 5[\"5. Cross-Validate\"]\n    Compare -->|No| 4\n\n    5 --> 6[\"6. Test Set<br/>Evaluation\"]\n    6 --> Done{Ready for<br/>Production?}\n\n    Done -->|Yes| 7[\"7. Production<br/>Deployment\"]\n    Done -->|No| 4\n\n    7 --> Monitor[\"8. Monitor &<br/>Iterate\"]\n\n    style Start fill:#c8e6c9\n    style 7 fill:#ffccbc\n    style Monitor fill:#ffe0b2\n```\n\n## Phase 1: Problem Definition\n\n### **Key Decisions**\n\n```python\n\n# Problem specification checklist\n\nproblem_spec = {\n    \"business_objective\": \"Reduce customer churn\",\n    \"ml_task\": \"Binary Classification\",\n    \"target_variable\": \"churned_in_30_days\",\n\n    \"primary_metric\": \"AUC\",\n    \"secondary_metrics\": [\"F1-score\", \"Precision\", \"Recall\"],\n\n    \"baseline_requirement\": \"Better than 0.70 AUC\",\n    \"production_requirement\": \"At least 0.85 AUC\",\n\n    \"false_positive_cost\": \"Low - send discount to potentially churning customers\",\n    \"false_negative_cost\": \"High - lose customers unexpectedly\",\n\n    \"imbalance_ratio\": 0.15  # 15% churned, 85% retained\n}\n\n# Determine whether precision or recall is critical\n# Churned: False negatives (missing churn) are expensive\n# → Prioritize RECALL (catch churners)\n\n```\n\n## Phase 2: Data Preparation\n\n### **Data Engineering for ML**\n\n```python\n%python\nimport pandas as pd\nfrom pyspark.sql import functions as F\n\n# LOAD DATA\n\ndf = spark.read.table(\"ml_catalog.raw.customer_data\")\n\n# DATA EXPLORATION\n\nprint(f\"Shape: {df.count()} rows\")\nprint(f\"Columns: {len(df.columns)}\")\nprint(f\"Missing: {df.select([F.count(F.when(F.col(c).isNull(), c)).alias(c) for c in df.columns]).collect()}\")\n\n# DATA VALIDATION\n# Check distributions, ranges, missing patterns\n\ndisplay(df.describe())\n\n# FEATURE CREATION\n# Raw features → engineered features\n\ndf_engineered = (df\n    .withColumn(\"tenure_days\", F.datediff(F.current_date(), F.col(\"signup_date\")))\n    .withColumn(\"avg_monthly_usage\", F.col(\"total_usage\") / F.greatest(F.col(\"tenure_days\"), 1))\n    .withColumn(\"is_premium\", (F.col(\"plan_type\") == \"premium\").cast(\"int\"))\n)\n\n# TRAIN/VAL/TEST SPLIT\n\ntrain, val, test = df_engineered.randomSplit([0.6, 0.2, 0.2], seed=42)\n\n# SAVE FOR ML\n\ntrain.write.mode(\"overwrite\").saveAsTable(\"ml_catalog.ml_ready.train_data\")\nval.write.mode(\"overwrite\").saveAsTable(\"ml_catalog.ml_ready.val_data\")\ntest.write.mode(\"overwrite\").saveAsTable(\"ml_catalog.ml_ready.test_data\")\n```\n\n## Phase 3: Baseline Model\n\n### **Quick Baseline for Comparison**\n\n```python\n%python\nimport mlflow\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.metrics import auc, roc_curve, roc_auc_score, f1_score\nimport pandas as pd\n\n# Load data\n\ntrain_df = spark.read.table(\"ml_catalog.ml_ready.train_data\").toPandas()\nval_df = spark.read.table(\"ml_catalog.ml_ready.val_data\").toPandas()\n\n# Create baseline experiment\n\nmlflow.set_experiment(\"/Projects/ChurnModel/Development\")\n\nwith mlflow.start_run(run_name=\"baseline_rf_default\"):\n    # Simple baseline: RF with default parameters\n    X_train = train_df.drop(\"churned\", axis=1)\n    y_train = train_df[\"churned\"]\n\n    X_val = val_df.drop(\"churned\", axis=1)\n    y_val = val_df[\"churned\"]\n\n    # Scale features\n    scaler = StandardScaler()\n    X_train_scaled = scaler.fit_transform(X_train)\n    X_val_scaled = scaler.transform(X_val)\n\n    # Train baseline\n    baseline = RandomForestClassifier(n_estimators=50, random_state=42, n_jobs=-1)\n    baseline.fit(X_train_scaled, y_train)\n\n    # Evaluate\n    y_pred = baseline.predict(X_val_scaled)\n    y_pred_proba = baseline.predict_proba(X_val_scaled)[:, 1]\n\n    fpr, tpr, _ = roc_curve(y_val, y_pred_proba)\n    auc_score = auc(fpr, tpr)                 # same value as roc_auc_score(y_val, y_pred_proba)\n    f1 = f1_score(y_val, y_pred)\n\n    # Log to MLflow\n    mlflow.log_param(\"n_estimators\", 50)\n    mlflow.log_metric(\"val_auc\", auc_score)\n    mlflow.log_metric(\"val_f1\", f1)\n    mlflow.sklearn.log_model(baseline, \"model\")\n    mlflow.set_tag(\"phase\", \"baseline\")\n    mlflow.set_tag(\"baseline\", \"yes\")\n\nprint(f\"Baseline AUC: {auc_score:.3f}\")\nprint(f\"Baseline F1: {f1:.3f}\")\n```\n\n## Phase 4: Experimentation Cycle\n\n### **Structured Iteration Process**\n\n```python\n%python\nimport mlflow\nfrom mlflow.tracking import MlflowClient\nimport json\n\nclient = MlflowClient()\nexp = mlflow.get_experiment_by_name(\"/Projects/ChurnModel/Development\")\n\n# EXPERIMENT 1: Feature Engineering\n\nprint(\"=== EXPERIMENT 1: Feature Engineering ===\")\nmlflow.set_experiment(\"/Projects/ChurnModel/Development\")\n\nfeature_sets = {\n    \"baseline_features\": [\"age\", \"tenure\", \"monthly_charge\", \"total_charges\"],\n    \"with_interactions\": [\"age\", \"tenure\", \"monthly_charge\", \"total_charges\",\n                          \"age_tenure_interaction\", \"charge_ratio\"],\n    \"with_derived\": [\"age\", \"tenure\", \"monthly_charge\", \"total_charges\",\n                     \"usage_per_day\", \"days_since_contact\", \"services_count\"]\n}\n\nresults = {}\n\nfor feature_name, features in feature_sets.items():\n    with mlflow.start_run(run_name=f\"feature_set_{feature_name}\"):\n        # Prepare data\n        X_train_subset = X_train[features]\n        X_val_subset = X_val[features]\n\n        # Train\n        model = RandomForestClassifier(n_estimators=100, random_state=42)\n        model.fit(X_train_subset, y_train)\n\n        # Evaluate\n        y_pred_proba = model.predict_proba(X_val_subset)[:, 1]\n        auc_score = roc_auc_score(y_val, y_pred_proba)\n\n        mlflow.log_param(\"feature_set\", feature_name)\n        mlflow.log_metric(\"val_auc\", auc_score)\n        mlflow.set_tag(\"experiment_type\", \"feature_engineering\")\n\n        results[feature_name] = auc_score\n        print(f\"{feature_name}: AUC = {auc_score:.4f}\")\n\nbest_features = max(results, key=results.get)\nprint(f\"\\n✓ Best feature set: {best_features} with AUC {results[best_features]:.4f}\")\n```\n\n### **Hyperparameter Tuning Example**\n\n```python\n%python\n# EXPERIMENT 2: Hyperparameter Optimization\n\nprint(\"\\n=== EXPERIMENT 2: Hyperparameter Tuning ===\")\n\nparam_grid = {\n    \"n_estimators\": [50, 100, 200],\n    \"max_depth\": [5, 10, 15],\n    \"min_samples_split\": [2, 5, 10]\n}\n\nbest_params = {}\nbest_auc = 0\n\nfor n_est in param_grid[\"n_estimators\"]:\n    for depth in param_grid[\"max_depth\"]:\n        for min_split in param_grid[\"min_samples_split\"]:\n            with mlflow.start_run(run_name=f\"hp_ne{n_est}_d{depth}_ms{min_split}\"):\n                # Train with these parameters\n                model = RandomForestClassifier(\n                    n_estimators=n_est,\n                    max_depth=depth,\n                    min_samples_split=min_split,\n                    random_state=42\n                )\n                model.fit(X_train_scaled, y_train)\n\n                # Evaluate\n                y_pred_proba = model.predict_proba(X_val_scaled)[:, 1]\n                auc_score = roc_auc_score(y_val, y_pred_proba)\n\n                # Log\n                mlflow.log_params({\n                    \"n_estimators\": n_est,\n                    \"max_depth\": depth,\n                    \"min_samples_split\": min_split\n                })\n                mlflow.log_metric(\"val_auc\", auc_score)\n                mlflow.set_tag(\"experiment_type\", \"hyperparameter_tuning\")\n\n                if auc_score > best_auc:\n                    best_auc = auc_score\n                    best_params = {\n                        \"n_estimators\": n_est,\n                        \"max_depth\": depth,\n                        \"min_samples_split\": min_split\n                    }\n                    print(f\"New best: {best_params} → AUC = {auc_score:.4f}\")\n\nprint(f\"\\n✓ Best hyperparameters: {best_params}\")\n```\n\n## Phase 5: Cross-Validation\n\n### **K-Fold Cross-Validation**\n\n```python\n%python\nfrom sklearn.model_selection import cross_validate, KFold\n\nprint(\"=== PHASE 5: Cross-Validation ===\")\n\n# Use best parameters from experimentation\n\nbest_model = RandomForestClassifier(**best_params, random_state=42)\n\n# 5-fold cross-validation\n\ncv = KFold(n_splits=5, shuffle=True, random_state=42)\nscoring_metrics = ['roc_auc', 'f1', 'precision', 'recall']\n\ncv_results = cross_validate(best_model, X_train_scaled, y_train,\n                             cv=cv, scoring=scoring_metrics)\n\n# Print results\n\nfor metric in scoring_metrics:\n    scores = cv_results[f'test_{metric}']\n    print(f\"{metric:12s}: {scores.mean():.4f} (+/- {scores.std():.4f})\")\n\n# Log to MLflow\n\nwith mlflow.start_run(run_name=\"cross_validation\"):\n    mlflow.log_params(best_params)\n    for metric in scoring_metrics:\n        scores = cv_results[f'test_{metric}']\n        mlflow.log_metric(f\"cv_mean_{metric}\", scores.mean())\n        mlflow.log_metric(f\"cv_std_{metric}\", scores.std())\n    mlflow.set_tag(\"phase\", \"cross_validation\")\n```\n\n## Phase 6: Test Set Evaluation\n\n### **Final Holdout Test**\n\n```python\n%python\ntest_df = spark.read.table(\"ml_catalog.ml_ready.test_data\").toPandas()\n\nX_test = test_df[best_features]\ny_test = test_df[\"churned\"]\n\nX_test_scaled = scaler.transform(X_test)\n\n# Final model with the selected hyperparameters (optionally refit on train + val)\n\nfinal_model = RandomForestClassifier(**best_params, random_state=42)\nfinal_model.fit(X_train_scaled, y_train)\n\n# Test set performance\n\ny_test_pred = final_model.predict(X_test_scaled)\ny_test_pred_proba = final_model.predict_proba(X_test_scaled)[:, 1]\n\ntest_auc = roc_auc_score(y_test, y_test_pred_proba)\ntest_f1 = f1_score(y_test, y_test_pred)\n\nprint(f\"TEST AUC: {test_auc:.4f}\")\nprint(f\"TEST F1:  {test_f1:.4f}\")\n\n# Compare train/val/test performance\n\nprint(\"\\nPerformance Summary:\")\nprint(f\"Train AUC: {train_auc:.4f}\")\nprint(f\"Val AUC:   {val_auc:.4f}\")\nprint(f\"Test AUC:  {test_auc:.4f}\")\n\n# Check for overfitting\n\nif train_auc - test_auc > 0.05:\n    print(\"⚠ Warning: Potential overfitting detected\")\n```\n\n## Phase 7: Production Deployment\n\n### **Model Registry & Promotion**\n\n```python\n%python\nimport mlflow\nfrom mlflow import MlflowClient\n\nmlflow.set_registry_uri(\"databricks-uc\")\nmodel_name = \"ml_dev.churn.customer_churn_predictor\"\n\n# Log the final model (input_example -> signature, required by Unity Catalog)\n\nwith mlflow.start_run(run_name=\"production_candidate\") as run:\n    mlflow.log_params(best_params)\n    mlflow.log_metrics({\n        \"test_auc\": test_auc,\n        \"test_f1\": test_f1,\n        \"cv_mean_auc\": cv_mean_auc\n    })\n    mlflow.sklearn.log_model(final_model, \"model\", input_example=X_test.head(5))\n    mlflow.set_tag(\"phase\", \"production_candidate\")\n\n    run_id = run.info.run_id\n\n# Register in Unity Catalog and mark it as the challenger\n\nmv = mlflow.register_model(f\"runs:/{run_id}/model\", model_name)\n\nclient = MlflowClient()\nclient.set_registered_model_alias(model_name, \"challenger\", mv.version)\n\nprint(f\"Model {mv.name} v{mv.version} registered with alias @challenger\")\n```\n\n## Phase 8: Monitoring & Iteration\n\n### **Production Monitoring**\n\n```python\n%python\n\n# After deployment: continuously monitor performance\n\nmonitoring_tasks = {\n    \"Data Drift\": \"Compare feature distributions in production vs training\",\n    \"Model Drift\": \"Track prediction distribution changes\",\n    \"Performance Degradation\": \"Monitor AUC/F1 on new data\",\n    \"Predictions\": \"Log all predictions for audit\"\n}\n\n# Example: Monitor data drift\n\nfrom scipy.stats import ks_2samp\n\ndef check_feature_drift(new_data, train_data, threshold=0.05):\n    drift_features = []\n    for col in train_data.columns:\n        stat, pvalue = ks_2samp(train_data[col], new_data[col])\n        if pvalue < threshold:\n            drift_features.append(col)\n    return drift_features\n\n# If drift detected → retrain or investigate\n\n```\n\n## Experimentation Best Practices\n\n### **Experiment Tracking Guidelines**\n\n```python\n# Track EVERYTHING\n\nguidelines = {\n    \"Log\": [\n        \"All hyperparameters\",\n        \"All metrics (train, val, test)\",\n        \"Feature list used\",\n        \"Data preprocessing steps\",\n        \"Train/val/test split ratios\",\n        \"Model artifacts\",\n        \"Feature importance\"\n    ],\n    \"Tag\": [\n        \"experiment_type (feature_eng, hp_tuning, etc.)\",\n        \"phase (exploration, validation, production)\",\n        \"baseline (yes/no)\",\n        \"production_ready (yes/no)\"\n    ],\n    \"Name\": [\n        \"Descriptive run names\",\n        \"Include key differentiator\",\n        \"Examples: rf_depth_10, with_derived_features\"\n    ]\n}\n```\n\n### **Experiment Design Checklist**\n\n```python\nchecklist = {\n    \"Before Experiment\": [\n        \"✓ Clear hypothesis\",\n        \"✓ Metric to optimize\",\n        \"✓ Expected improvement\",\n        \"✓ Baseline for comparison\"\n    ],\n    \"During Experiment\": [\n        \"✓ Log parameters & metrics\",\n        \"✓ Use meaningful names\",\n        \"✓ Set relevant tags\",\n        \"✓ Log artifacts (metrics, plots)\"\n    ],\n    \"After Experiment\": [\n        \"✓ Document findings\",\n        \"✓ Compare with baseline\",\n        \"✓ Decide on next iteration\",\n        \"✓ Archive if not continuing\"\n    ]\n}\n```\n\n## Real-World Decision Tree\n\n```text\nStart ML Project\n    ↓\nDefine Problem & Metrics\n    ↓\nPrepare Data (80% of time!)\n    ↓\nCreate Baseline (usually ~70% accuracy)\n    ↓\nTry 3-5 Feature Engineering approaches\n    ↓\nDid any improve baseline? → No → Accept baseline\n    ↓ Yes\nSelect best features\n    ↓\nTry 3-5 Algorithms\n    ↓\nTune best algorithm's hyperparameters\n    ↓\nCross-validate final model\n    ↓\nEvaluate on held-out test set\n    ↓\nMeet production requirements? → No → Iterate\n    ↓ Yes\nDeploy & Monitor\n```\n\n## Use Cases\n\n- **ML Experimentation Workflow Implementation**: Incorporating ML Experimentation Workflow principles to build scalable and maintainable solutions in Databricks environments.\n- **Iterative Model Improvement**: Following a structured experiment cycle of feature engineering, algorithm selection, and hyperparameter tuning to systematically improve model performance from a baseline.\n\n## Common Issues & Errors\n\n### Test Set Used for Tuning\n\n**Scenario:** Hyperparameters are chosen by comparing scores on the test set, and production performance is lower than reported.\n**Fix:** Tune on validation data or cross-validation; evaluate the final model on the untouched test set exactly once.\n\n### Experiment Reproducibility Issues\n\n**Scenario:** Re-running the same notebook produces different model metrics.\n**Fix:** Set random seeds (`random_state`, `np.random.seed`, `torch.manual_seed`), pin library versions, and log the full environment with `mlflow.log_artifact()`.\n\n## Exam Tips\n\n- ✅ Understand full ML workflow phases\n- ✅ Know when to evaluate on train/val/test\n- ✅ Recognize signs of overfitting/underfitting\n- ✅ Understand proper experimentation structure\n- ✅ Know cross-validation for generalization\n- ✅ Remember holdout test set is sacred (don't use for tuning)\n\n## Key Takeaways\n\n- Systematic experimentation beats random tweaking\n- Baseline establishes comparison point\n- Feature engineering usually most impactful\n- Cross-validation validates generalization\n- Test set remains untouched until final evaluation\n- Proper tracking enables reproducibility and collaboration\n- Phase gates ensure quality models reach production\n\n## Related Topics\n\n- [Model Evaluation & Metrics](./03-model-evaluation.md)\n- [Hyperparameter Tuning & Cross-Validation](./02-hyperparameter-tuning.md)\n- [MLflow Tracking](../01-databricks-machine-learning/05-mlflow-tracking.md)\n- [Model Registry in Unity Catalog](../01-databricks-machine-learning/07-model-registry.md)\n\n## Official Documentation\n\n- [Organize training runs with MLflow experiments](https://docs.databricks.com/aws/en/mlflow/experiments)\n- [MLOps workflows on Databricks](https://docs.databricks.com/aws/en/machine-learning/mlops/mlops-workflow)\n\n---\n\n**[← Previous: Model Evaluation & Metrics](./03-model-evaluation.md) | [↑ Back to Section](./README.md)**\n"},{"id":"03-model-development/README","folder":"03-model-development","group":"modulo","order":0,"isIndex":true,"title":"Model Development","md":"# Model Development (31 % of Exam)\n\nSection 3 of the exam guide and the second-largest domain. It covers choosing an algorithm, building training pipelines with estimators and transformers, handling class imbalance, tuning hyperparameters (grid, random, Bayesian; Hyperopt `fmin`; parallel single-node tuning), cross-validation, evaluation metrics, log-target handling, and the bias-variance tradeoff.\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    MD[Model Development] --> Pipe[Pipelines:<br/>estimators + transformers]\n    MD --> Tune[Tuning + cross-validation]\n    MD --> Eval[Metrics, imbalance,<br/>bias-variance]\n    MD --> Flow[End-to-end experimentation]\n```\n\n## Section Contents\n\n| File | Topic | Exam-guide bullets covered | Priority |\n| :--- | :--- | :--- | :--- |\n| [01-spark-ml-pipelines.md](./01-spark-ml-pipelines.md) | `Pipeline`, Estimator vs Transformer, `PipelineModel` | Compare estimators and transformers; develop a training pipeline | High |\n| [02-hyperparameter-tuning.md](./02-hyperparameter-tuning.md) | Grid / random / Bayesian search, Hyperopt `fmin`, `SparkTrials`, CV vs train-validation split | Hyperopt `fmin`; random/grid/Bayesian search; parallelise single-node models; CV benefits/downsides; perform CV; number of models trained | High |\n| [03-model-evaluation.md](./03-model-evaluation.md) | Algorithm choice, imbalance, metrics, log targets, bias-variance | Select algorithm; mitigate imbalance; classification and regression metrics; choose metric; exponentiate log-transformed variables; bias-variance tradeoff | High |\n| [04-ml-experimentation-workflow.md](./04-ml-experimentation-workflow.md) | Baseline → iterate → CV → test → register | Develop a training pipeline (end-to-end) | Medium |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **Estimator vs Transformer** | `fit()` → Model vs `transform()` → DataFrame; anything that learns from data is an Estimator |\n| **`CrossValidator` / `TrainValidationSplit`** | k-fold (reliable, k× cost) vs one split (cheap, noisier); both refit the best model |\n| **Hyperopt `fmin` + `SparkTrials`** | Bayesian (`tpe.suggest`) or random (`rand.suggest`) search; parallel trials for single-node models |\n| **Models trained** | (product of grid sizes) × folds (+1 final refit) |\n| **F1 / log loss / ROC AUC; RMSE / MAE / R²** | Pick the metric that matches the cost of errors |\n| **Bias-variance** | Low train + high validation error = overfitting; high on both = underfitting |\n\n## Related Resources\n\n- [PySpark API cheat sheet (shared)](../../../shared/cheat-sheets/pyspark-api-quick-ref.md)\n- [Spark ML Pipelines guide](https://spark.apache.org/docs/latest/ml-pipeline.html)\n- [Hyperparameter tuning on Databricks](https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/)\n\n---\n\n**[← Previous: Data Processing](../02-data-processing/README.md) | [↑ Back to ML Associate](../README.md) | [Next: Model Deployment →](../04-model-deployment/README.md)**\n"},{"id":"04-model-deployment/01-model-deployment-serving","folder":"04-model-deployment","group":"modulo","order":1,"isIndex":false,"title":"Model Deployment & Serving","md":"# Model Deployment & Serving\n\n## Overview\n\nSection 4 of the exam guide (**Model Deployment, 12 %**) asks you to choose between **batch, streaming, and real-time** serving, run **batch inference with pandas**, **deploy a custom model** to a Model Serving endpoint, **query** it, and **split traffic** between models. Streaming inference with Delta Live Tables has its own page: [Streaming Inference](./02-streaming-inference.md).\n\n> [!abstract]\n>\n> - **Batch**: score a whole table on a schedule (pandas for small data; `mlflow.pyfunc.spark_udf` / `fe.score_batch` at scale) — cheapest, highest latency\n> - **Streaming**: score records continuously as they arrive (Structured Streaming / Delta Live Tables) — seconds of latency\n> - **Real-time**: a **Model Serving** REST endpoint answers individual requests in milliseconds — most infrastructure per prediction\n> - One endpoint can serve several model versions with a **`traffic_config`** split (A/B, canary, gradual rollout)\n\n> [!tip] What the Exam Tests\n>\n> - *Identify the differences and advantages of batch, real-time, and streaming serving* for a scenario\n> - *Use pandas to perform batch inference*; *deploy a custom model to a model endpoint*; *deploy and query a model for real-time inference*\n> - *Split data between endpoints for real-time inference* (traffic percentages across served models)\n\n---\n\n## Choosing a Serving Approach\n\n| | **Batch** | **Streaming** | **Real-time** |\n| :--- | :--- | :--- | :--- |\n| **Trigger** | Schedule (hourly / nightly job) | Continuous arrival of events | Each client request |\n| **Latency** | Minutes–hours | Seconds | Milliseconds |\n| **Throughput** | Very high (whole tables) | High, sustained | Per-request |\n| **Cost per prediction** | Lowest | Medium | Highest (always-ready endpoint) |\n| **Databricks tools** | Lakeflow Jobs + pandas / `spark_udf` / `fe.score_batch` / `ai_query` | Structured Streaming or Delta Live Tables + `spark_udf` | Model Serving endpoint (REST) |\n| **Example** | Nightly marketing segments for every customer | Fraud score per card swipe written to a Delta table | Product recommendation when a page loads |\n\n```mermaid\nflowchart TD\n    Q1{\"Does a caller need the answer<br/>inside the request (ms)?\"} -->|Yes| RT[\"Real-time:<br/>Model Serving endpoint\"]\n    Q1 -->|No| Q2{\"Does data arrive continuously and<br/>need scoring within seconds?\"}\n    Q2 -->|Yes| ST[\"Streaming:<br/>Structured Streaming / Delta Live Tables\"]\n    Q2 -->|No| BA[\"Batch:<br/>scheduled job\"]\n```\n\n![Set up model inference dialog with batch, real-time, and streaming tabs](../../../images/databricks-ui/mlflow/model_serving_endpoint.png)\n\n*The legacy \"Set up model inference\" dialog offered the same three choices the exam compares — batch, real-time, and streaming via Delta Live Tables (older workspace-registry UI showing a stage and a DBFS output path).*\n\nRule of thumb: pick the **least-real-time approach that meets the latency requirement** — batch is simplest and most cost-effective when no one waits for a single prediction.\n\n## Batch Inference with pandas\n\nFor data that fits on the driver, load the registered model as a generic `pyfunc` and call `predict` on a pandas DataFrame:\n\n```python\nimport mlflow\n\nmlflow.set_registry_uri(\"databricks-uc\")\nmodel = mlflow.pyfunc.load_model(\"models:/ml_prod.churn.churn_classifier@champion\")\n\npdf = spark.read.table(\"ml_prod.churn.customers_today\").toPandas()   # small enough for the driver\npdf[\"churn_prediction\"] = model.predict(pdf[feature_columns])\n\nspark.createDataFrame(pdf).write.mode(\"overwrite\").saveAsTable(\"ml_prod.churn.daily_scores\")\n```\n\n### **Scaling the same model out with Spark**\n\n```python\nimport mlflow\nfrom pyspark.sql import functions as F\n\n# Option 1 — MLflow wraps the model as a Spark UDF (pandas batches on every worker)\npredict_udf = mlflow.pyfunc.spark_udf(\n    spark, \"models:/ml_prod.churn.churn_classifier@champion\", result_type=\"double\")\nscored = (spark.read.table(\"ml_prod.churn.customers_today\")\n    .withColumn(\"churn_prediction\", predict_udf(*feature_columns)))\n\n# Option 2 — explicit pandas function over partitions\nmodel_uri = \"models:/ml_prod.churn.churn_classifier@champion\"\n\ndef predict_batches(iterator):\n    model = mlflow.pyfunc.load_model(model_uri)        # loaded once per task\n    for pdf in iterator:\n        pdf[\"churn_prediction\"] = model.predict(pdf[feature_columns])\n        yield pdf\n\nscored2 = (spark.read.table(\"ml_prod.churn.customers_today\")\n    .mapInPandas(predict_batches, schema=\"customer_id long, churn_prediction double\"))\n```\n\n| Tool | Use when |\n| :--- | :--- |\n| `pyfunc.load_model(...).predict(pandas_df)` | Small data; single machine |\n| `mlflow.pyfunc.spark_udf(spark, model_uri)` | Large Spark DataFrames — distributed pandas batches |\n| `fe.score_batch(model_uri, df)` | The model was logged with `fe.log_model` (features looked up automatically) |\n| `ai_query(...)` in SQL | Batch inference against a serving endpoint from SQL |\n\n> [!warning] Common Mistake\n> `df.toPandas()` on tens of millions of rows collects everything to the driver and can run out of memory. Use pandas inference only when the data fits on one machine; otherwise use `spark_udf`.\n\n## Deploying a Custom Model to an Endpoint\n\nA **custom model** is any MLflow model with your own Python logic — typically a subclass of `mlflow.pyfunc.PythonModel` that wraps preprocessing, post-processing, or a library MLflow has no built-in flavor for. Model Serving \"can deploy any Python model or custom code as a production-grade API using CPU or GPU compute resources.\"\n\n### **1. Log and register the custom model**\n\n```python\nimport mlflow\nimport mlflow.pyfunc\nimport pandas as pd\n\nclass ChurnWithThreshold(mlflow.pyfunc.PythonModel):\n    \"\"\"Wraps a trained scikit-learn classifier and applies a business threshold.\"\"\"\n\n    def __init__(self, sk_model, threshold=0.4):\n        self.sk_model = sk_model          # serialized with the pyfunc model by MLflow\n        self.threshold = threshold\n\n    def predict(self, context, model_input: pd.DataFrame):\n        proba = self.sk_model.predict_proba(model_input)[:, 1]\n        return pd.DataFrame({\"churn_probability\": proba,\n                             \"churn_flag\": (proba >= self.threshold).astype(int)})\n\nmlflow.set_registry_uri(\"databricks-uc\")\nwith mlflow.start_run():\n    mlflow.pyfunc.log_model(\n        artifact_path=\"model\",\n        python_model=ChurnWithThreshold(trained_classifier, threshold=0.4),\n        input_example=X_sample,                          # signature is required in UC\n        registered_model_name=\"ml_prod.churn.churn_custom\",\n    )\n```\n\n### **2. Create the serving endpoint**\n\n**UI:** *Serving* → *Create serving endpoint* → choose the Unity Catalog model and version → compute size and scale-to-zero → *Create*.\n\n**MLflow Deployments SDK:**\n\n```python\nfrom mlflow.deployments import get_deploy_client\n\nclient = get_deploy_client(\"databricks\")\nendpoint = client.create_endpoint(\n    config={                                   # full API request payload\n        \"name\": \"churn-custom\",\n        \"config\": {\n            \"served_entities\": [{\n                \"name\": \"churn-custom-3\",\n                \"entity_name\": \"ml_prod.churn.churn_custom\",\n                \"entity_version\": \"3\",\n                \"workload_size\": \"Small\",\n                \"scale_to_zero_enabled\": True,\n            }]\n        },\n    },\n)\n```\n\n**Databricks SDK:**\n\n```python\nfrom databricks.sdk import WorkspaceClient\nfrom databricks.sdk.service.serving import EndpointCoreConfigInput, ServedEntityInput\n\nw = WorkspaceClient()\nw.serving_endpoints.create(\n    name=\"churn-custom\",\n    config=EndpointCoreConfigInput(\n        served_entities=[ServedEntityInput(\n            entity_name=\"ml_prod.churn.churn_custom\",\n            entity_version=\"3\",\n            workload_size=\"Small\",\n            scale_to_zero_enabled=True,\n        )]\n    ),\n)\n```\n\n| Setting | Effect |\n| :--- | :--- |\n| `workload_size` | Concurrency capacity (`Small`, `Medium`, `Large`); GPU workload types exist for GPU models |\n| `scale_to_zero_enabled` | Scales to zero when idle — saves cost, adds cold-start latency on the next request |\n| `served_entities` | One or more model versions behind the endpoint (older code uses `served_models`) |\n\nSources: [Deploy custom models](https://docs.databricks.com/aws/en/machine-learning/model-serving/custom-models), [Create custom model serving endpoints](https://docs.databricks.com/aws/en/machine-learning/model-serving/create-manage-serving-endpoints).\n\n## Querying a Real-Time Endpoint\n\nThe REST invocation URL is `https://<databricks-instance>/serving-endpoints/<endpoint-name>/invocations`.\n\n```bash\ncurl -X POST -u token:$DATABRICKS_TOKEN \\\n  https://<databricks-instance>/serving-endpoints/churn-custom/invocations \\\n  -H 'Content-Type: application/json' \\\n  -d '{\"dataframe_split\": {\"columns\": [\"tenure\", \"monthly_charge\"], \"data\": [[12, 65.5], [3, 45.0]]}}'\n```\n\n```python\nimport mlflow.deployments\n\nclient = mlflow.deployments.get_deploy_client(\"databricks\")\nresponse = client.predict(\n    endpoint=\"churn-custom\",\n    inputs={\"dataframe_records\": [{\"tenure\": 12, \"monthly_charge\": 65.5}]},\n)\nprint(response)\n```\n\n| Input key | Shape |\n| :--- | :--- |\n| `dataframe_split` (recommended) | `{\"columns\": [...], \"data\": [[...], ...]}` — pandas `split` orientation |\n| `dataframe_records` | `[{\"col\": value, ...}, ...]` — pandas `records` orientation (column order not guaranteed) |\n| `instances` / `inputs` | Tensor input (row / columnar) |\n\nFrom SQL, the same endpoint can be called with the `ai_query` function. Source: [Query serving endpoints for custom models](https://docs.databricks.com/aws/en/machine-learning/model-serving/score-custom-model-endpoints).\n\n## Splitting Traffic Between Models\n\nServe several versions behind **one** endpoint and route a percentage of requests to each — for A/B tests, canary releases, or gradual champion → challenger rollouts:\n\n```python\nfrom mlflow.deployments import get_deploy_client\n\nclient = get_deploy_client(\"databricks\")\nclient.update_endpoint_config(\n    endpoint=\"churn-custom\",\n    config={\n        \"served_entities\": [\n            {\"name\": \"champion-v3\", \"entity_name\": \"ml_prod.churn.churn_custom\",\n             \"entity_version\": \"3\", \"workload_size\": \"Small\", \"scale_to_zero_enabled\": False},\n            {\"name\": \"challenger-v4\", \"entity_name\": \"ml_prod.churn.churn_custom\",\n             \"entity_version\": \"4\", \"workload_size\": \"Small\", \"scale_to_zero_enabled\": False},\n        ],\n        \"traffic_config\": {\n            \"routes\": [\n                {\"served_model_name\": \"champion-v3\", \"traffic_percentage\": 90},\n                {\"served_model_name\": \"challenger-v4\", \"traffic_percentage\": 10},\n            ]\n        },\n    },\n)\n```\n\n- Percentages across routes must add up to **100**\n- Shift gradually (90/10 → 50/50 → 0/100) while monitoring; move the `champion` alias when the challenger wins\n- The UI exposes the same split: each served entity gets a traffic percentage\n\n## Monitoring Served Models\n\nRequest/response logging to a Unity Catalog Delta table lets you monitor latency, errors, and prediction drift and join predictions to ground-truth labels later.\n\n> [!note] Platform update (Oct 2026)\n>\n> - The docs now call the product simply **Model Serving** (older material: \"Mosaic AI Model Serving\").\n> - The legacy custom-model inference-table docs (`auto_capture_config`) are marked retired; Databricks recommends **AI Gateway-enabled inference tables** for custom model, foundation model, and agent endpoints ([Inference tables (legacy)](https://docs.databricks.com/aws/en/machine-learning/model-serving/inference-tables)).\n> - **Free Edition** (for hands-on practice; Community Edition was retired on January 1, 2026) has limits on active endpoints and no GPU serving endpoints, no provisioned throughput, and no custom models on GPU or batch inference ([Free Edition limitations](https://docs.databricks.com/aws/en/getting-started/free-edition-limitations)).\n\n## Use Cases\n\n- **Nightly Batch Scoring**: A Lakeflow Job runs at 02:00, loads `@champion` with `spark_udf`, and overwrites a predictions table for the marketing team — no endpoint is needed.\n- **Real-Time Recommendations**: A web app calls a Model Serving endpoint for each page view; a 90/10 traffic split tests a new model version on live traffic.\n\n## Common Issues & Errors\n\n### Endpoint Returns 400 for Valid-Looking Requests\n\n**Scenario:** Requests fail with a schema or input error.\n**Fix:** Send one of the accepted formats (`dataframe_split`, `dataframe_records`, `instances`, `inputs`) with column names that match the model signature.\n\n### First Request After Idle Time Is Very Slow\n\n**Scenario:** The first call after a quiet period takes far longer than later calls.\n**Fix:** The endpoint scaled to zero. Disable `scale_to_zero_enabled` (or keep provisioned concurrency) for latency-critical production endpoints.\n\n## Exam Tips\n\n- ✅ No low-latency requirement + whole dataset on a schedule → **batch** (cheapest)\n- ✅ Continuously arriving events scored within seconds → **streaming** (see [Streaming Inference](./02-streaming-inference.md))\n- ✅ A caller waits for each prediction → **real-time Model Serving endpoint**\n- ✅ Custom logic = subclass `mlflow.pyfunc.PythonModel`, log with `mlflow.pyfunc.log_model`, register in UC, serve\n- ✅ Query URL: `/serving-endpoints/<name>/invocations` with `dataframe_split` / `dataframe_records`\n- ✅ Traffic split = multiple `served_entities` + `traffic_config.routes` percentages summing to 100\n\n## Key Takeaways\n\n- Match the serving approach to the latency requirement, not to what is most sophisticated\n- The same registered model can be used for batch (`spark_udf`), streaming, and real-time serving\n- Custom `pyfunc` models package preprocessing and business rules with the model\n- Traffic splitting enables safe, measurable rollouts of new versions\n\n## Related Topics\n\n- [Streaming Inference](./02-streaming-inference.md)\n- [Model Registry in Unity Catalog](../01-databricks-machine-learning/07-model-registry.md)\n- [Feature Store in Unity Catalog](../01-databricks-machine-learning/04-feature-store.md) — `score_batch` and online lookups\n- [MLOps Strategy](../01-databricks-machine-learning/08-mlops-strategy.md)\n\n## Official Documentation\n\n- [Model Serving](https://docs.databricks.com/aws/en/machine-learning/model-serving/)\n- [Deploy custom models](https://docs.databricks.com/aws/en/machine-learning/model-serving/custom-models)\n- [Create custom model serving endpoints](https://docs.databricks.com/aws/en/machine-learning/model-serving/create-manage-serving-endpoints)\n- [Query serving endpoints for custom models](https://docs.databricks.com/aws/en/machine-learning/model-serving/score-custom-model-endpoints)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Streaming Inference →](./02-streaming-inference.md)**\n"},{"id":"04-model-deployment/02-streaming-inference","folder":"04-model-deployment","group":"modulo","order":2,"isIndex":false,"title":"Streaming Inference","md":"# Streaming Inference\n\n## Overview\n\nStreaming inference scores records **continuously as they arrive** — clickstream events, card transactions, sensor readings — and writes predictions to a table within seconds. The exam guide bullet is *\"Identify how streaming inference is performed with Delta Live Tables\"*: load the registered model as a Spark UDF and apply it inside a pipeline's streaming table, letting the pipeline manage state, checkpoints, and autoscaling.\n\n> [!abstract]\n>\n> - Pattern: `mlflow.pyfunc.spark_udf(spark, \"models:/<uc_model>@champion\")` applied to `spark.readStream` inside a **Delta Live Tables** streaming table\n> - The pipeline handles checkpoints, retries, data-quality expectations, lineage, and **enhanced autoscaling** of compute as event volume changes\n> - A plain **Structured Streaming** job with the same UDF also works, but you manage compute sizing, checkpoints, and orchestration yourself\n> - Calling a Model Serving endpoint from a streaming UDF adds a network round-trip per batch — avoid it for high-throughput scoring\n\n> [!tip] What the Exam Tests\n>\n> - That streaming inference with Delta Live Tables means **applying the model as a Spark UDF inside the pipeline**\n> - Why a Delta Live Tables pipeline suits fluctuating, high-volume streams (managed, dynamically resized compute)\n> - Telling streaming apart from batch and real-time serving\n\n---\n\n> [!note] Platform update (Oct 2026)\n> The exam guide says **Delta Live Tables**. The product was renamed Lakeflow Declarative Pipelines and then, per the release notes, \"Lakeflow Declarative Pipelines has been renamed to Lakeflow Spark Declarative Pipelines\" on November 12, 2025 ([November 2025 release notes](https://docs.databricks.com/aws/en/release-notes/product/2025/november)). The Python API is now `from pyspark import pipelines as dp`; the docs say you \"may still use `dlt`, but Databricks recommends using `pipelines`\" ([Python language reference](https://docs.databricks.com/aws/en/ldp/developer/python-ref)). Answer exam questions in Delta Live Tables terms.\n\n## How It Works\n\n```mermaid\nflowchart LR\n    Src[\"Event source<br/>(Kafka / Auto Loader / Delta)\"] --> Bronze[\"Streaming table<br/>raw events\"]\n    Bronze --> Feat[\"Streaming table<br/>features (e.g. 10-min windows)\"]\n    Reg[(\"UC registry<br/>model@champion\")] -.->|spark_udf| Score\n    Feat --> Score[\"Streaming table<br/>scored events\"]\n    Score --> Out[\"Alerts / dashboards /<br/>downstream jobs\"]\n    Pipe[\"Pipeline: checkpoints, expectations,<br/>enhanced autoscaling\"] -.-> Bronze\n    Pipe -.-> Score\n```\n\n## Streaming Inference in a Pipeline\n\n### **Current API (`pyspark.pipelines`)**\n\n```python\nimport mlflow\nfrom pyspark import pipelines as dp\nfrom pyspark.sql import functions as F\n\nmlflow.set_registry_uri(\"databricks-uc\")\nmodel_uri = \"models:/ml_prod.podcast.low_engagement_detector@champion\"\nscore_udf = mlflow.pyfunc.spark_udf(spark, model_uri, result_type=\"double\")\n\nfeature_cols = [\"listen_seconds\", \"pause_count\", \"skip_count\"]\n\n@dp.table(comment=\"Podcast events scored for low engagement\")\ndef scored_events():\n    return (spark.readStream.table(\"ml_prod.podcast.engagement_features\")\n        .withColumn(\"low_engagement_score\", score_udf(*feature_cols))\n        .withColumn(\"scored_at\", F.current_timestamp()))\n```\n\n### **Exam-era syntax (`dlt`)**\n\n```python\nimport dlt\nimport mlflow\n\nscore_udf = mlflow.pyfunc.spark_udf(\n    spark, \"models:/ml_prod.podcast.low_engagement_detector@champion\", result_type=\"double\")\n\n@dlt.table(comment=\"Podcast events scored for low engagement\")\n@dlt.expect_or_drop(\"has_features\", \"listen_seconds IS NOT NULL\")\ndef scored_events():\n    return (spark.readStream.table(\"ml_prod.podcast.engagement_features\")\n        .withColumn(\"low_engagement_score\", score_udf(\"listen_seconds\", \"pause_count\", \"skip_count\")))\n```\n\nKey points:\n\n- The model is loaded **once per worker** by `spark_udf` and applied to micro-batches in pandas batches — no per-record network calls\n- Because the alias is resolved when the pipeline starts, promoting a new `@champion` takes effect on the next pipeline update/restart\n- Data-quality **expectations** (`expect`, `expect_or_drop`, `expect_or_fail`) can guard the features before scoring\n\n## Why a Pipeline Suits Fluctuating Streams\n\n\"Enhanced autoscaling implements optimization of streaming workloads\" by adding and removing machines as load changes; it \"is enabled by default for all new pipelines,\" and \"for serverless pipelines, enhanced autoscaling is always on\" ([Optimize pipeline cluster utilization with autoscaling](https://docs.databricks.com/aws/en/ldp/auto-scaling)).\n\n| Option | Throughput | Compute sizing | Operational burden | Verdict for high-volume, fluctuating streams |\n| :--- | :--- | :--- | :--- | :--- |\n| **Delta Live Tables pipeline + model as Spark UDF** | High — model runs next to the data | **Managed, dynamically resized** (enhanced autoscaling) | Low: checkpoints, retries, lineage, expectations built in | ✅ Best fit |\n| **Structured Streaming job + model as Spark UDF** | High | You size the cluster — the docs say \"Don't enable autoscaling for Structured Streaming jobs\" | Higher: you manage checkpoints, restarts, monitoring | Works, more to manage |\n| **Pipeline or streaming job calling a Model Serving endpoint per batch** | Limited by HTTP round-trips and endpoint capacity | Two systems to scale | Highest | ❌ Extra latency and overhead |\n\nSources: [Optimize pipeline cluster utilization with autoscaling](https://docs.databricks.com/aws/en/ldp/auto-scaling), [Production considerations for Structured Streaming](https://docs.databricks.com/aws/en/structured-streaming/production).\n\n## Plain Structured Streaming Alternative\n\n```python\nimport mlflow\n\nscore_udf = mlflow.pyfunc.spark_udf(\n    spark, \"models:/ml_prod.podcast.low_engagement_detector@champion\", result_type=\"double\")\n\n(spark.readStream.table(\"ml_prod.podcast.engagement_features\")\n    .withColumn(\"low_engagement_score\", score_udf(\"listen_seconds\", \"pause_count\", \"skip_count\"))\n    .writeStream\n    .option(\"checkpointLocation\", \"/Volumes/ml_prod/podcast/checkpoints/scored_events\")\n    .trigger(processingTime=\"30 seconds\")\n    .toTable(\"ml_prod.podcast.scored_events\"))\n```\n\n## Streaming vs Batch vs Real-Time\n\n| Requirement | Choose |\n| :--- | :--- |\n| Score the full customer base once a night | Batch |\n| Score every event within seconds and store the result | **Streaming** |\n| Return a prediction inside a user's request | Real-time (Model Serving) |\n\n## Use Cases\n\n- **Low-Engagement Detection**: Listening events (play, pause, exit) are aggregated into 10-minute windows and scored by an anomaly model inside a pipeline whose compute grows and shrinks with traffic through the day.\n- **Card Fraud Flags**: Transactions are scored as they land and high scores are written to an alerts table consumed by an investigations dashboard.\n\n## Common Issues & Errors\n\n### New Champion Not Picked Up\n\n**Scenario:** The `champion` alias was moved, but the streaming table still uses the old model.\n**Fix:** The UDF resolved the alias when the pipeline started — run a new pipeline update (or restart the stream) after promotion.\n\n### Streaming Scoring Falls Behind at Peak Hours\n\n**Scenario:** Processing lag grows when event volume spikes.\n**Fix:** Run the scoring in a pipeline with enhanced autoscaling (or serverless), avoid per-record calls to external endpoints, and keep the model in-process with `spark_udf`.\n\n## Exam Tips\n\n- ✅ Streaming inference with Delta Live Tables = **model loaded as a Spark UDF and applied in a streaming table** of the pipeline\n- ✅ \"High throughput + compute must resize as volume fluctuates\" → Delta Live Tables pipeline (enhanced autoscaling)\n- ✅ Routing a stream through a serving endpoint adds overhead — not the best answer for high-volume streams\n- ✅ Load the model by alias (`@champion`) so promotion needs no code change\n\n## Key Takeaways\n\n- Streaming inference reuses the same registered model as batch scoring — only the input is a stream\n- Pipelines add managed state, quality checks, lineage, and autoscaling around the scoring step\n- Keep the model in-process (`spark_udf`) for throughput; reserve endpoints for request/response use cases\n- Delta Live Tables is now Lakeflow Spark Declarative Pipelines — same idea, new name and import\n\n## Related Topics\n\n- [Model Deployment & Serving](./01-model-deployment-serving.md)\n- [Model Registry in Unity Catalog](../01-databricks-machine-learning/07-model-registry.md)\n- [Streaming Fundamentals (shared)](../../../shared/fundamentals/streaming-fundamentals.md)\n- [Lakeflow Declarative Pipelines quick reference (shared)](../../../shared/cheat-sheets/lakeflow-declarative-pipelines-quick-ref.md)\n\n## Official Documentation\n\n- [Lakeflow Spark Declarative Pipelines Python reference](https://docs.databricks.com/aws/en/ldp/developer/python-ref)\n- [Optimize pipeline cluster utilization with autoscaling](https://docs.databricks.com/aws/en/ldp/auto-scaling)\n- [`mlflow.pyfunc.spark_udf`](https://mlflow.org/docs/latest/api_reference/python_api/mlflow.pyfunc.html)\n\n---\n\n**[← Previous: Model Deployment & Serving](./01-model-deployment-serving.md) | [↑ Back to Section](./README.md)**\n"},{"id":"04-model-deployment/README","folder":"04-model-deployment","group":"modulo","order":0,"isIndex":true,"title":"Model Deployment","md":"# Model Deployment (12 % of Exam)\n\nSection 4 of the exam guide. It covers choosing between batch, streaming, and real-time serving; batch inference with pandas (and its Spark scale-out); streaming inference with Delta Live Tables; deploying a custom model to a Model Serving endpoint; querying it; and splitting traffic between served models. Registering and promoting models (aliases, tags) is a Section 1 skill — see [Model Registry in Unity Catalog](../01-databricks-machine-learning/07-model-registry.md).\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    MD[Model Deployment] --> Choose[Batch vs streaming vs real-time]\n    MD --> Batch[Batch inference:<br/>pandas, spark_udf]\n    MD --> Stream[Streaming inference:<br/>Delta Live Tables]\n    MD --> RT[Real-time:<br/>Model Serving endpoints]\n    RT --> Split[Traffic split]\n```\n\n## Section Contents\n\n| File | Topic | Exam-guide bullets covered | Priority |\n| :--- | :--- | :--- | :--- |\n| [01-model-deployment-serving.md](./01-model-deployment-serving.md) | Serving approaches, pandas batch inference, custom model endpoints, querying, traffic split | Batch vs real-time vs streaming; deploy a custom model; pandas batch inference; deploy and query real-time; split traffic between endpoints | High |\n| [02-streaming-inference.md](./02-streaming-inference.md) | Model as Spark UDF inside a pipeline | Streaming inference with Delta Live Tables | High |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **Batch inference** | Cheapest; scheduled scoring of whole tables (`pyfunc` + pandas, `spark_udf`, `fe.score_batch`) |\n| **Streaming inference** | `spark_udf` applied to `spark.readStream` in a Delta Live Tables (now Lakeflow Spark Declarative Pipelines) streaming table |\n| **Model Serving endpoint** | REST API at `/serving-endpoints/<name>/invocations`; `served_entities`, `workload_size`, `scale_to_zero_enabled` |\n| **Custom model** | `mlflow.pyfunc.PythonModel` subclass logged with `mlflow.pyfunc.log_model` |\n| **Traffic split** | `traffic_config.routes` percentages across served entities (sum = 100) |\n\n## Related Resources\n\n- [MLflow cheat sheet (shared)](../../../shared/cheat-sheets/mlflow-quick-ref.md)\n- [Model Serving documentation](https://docs.databricks.com/aws/en/machine-learning/model-serving/)\n- [Hands-on Lab 04 — MLflow tracking and Model Registry in UC](../../../labs/04-mlflow-tracking.md)\n\n---\n\n**[← Previous: Model Development](../03-model-development/README.md) | [↑ Back to ML Associate](../README.md)**\n"},{"id":"README","folder":"","group":"geral","order":0,"isIndex":false,"title":"ML Associate","md":"# Databricks Machine Learning Associate\n\n> [!important]\n> **What changed in the latest exam guide (re-issued \"August 2026\"; exam version Mar 1, 2025)**\n>\n> - **Same exam, new document.** The PDF's Update Information table still says *Exam Published: March 1, 2025* and *Exam Guide Updated: March 1, 2025*. Weights are unchanged: **38 / 19 / 31 / 12 %**.\n> - **This guide is now realigned 1 : 1 to the PDF sections.** Section 2 is **Data Processing** (summary statistics, outliers, imputation, one-hot encoding, log transforms) and all **MLflow + feature-table + registry** skills sit in **Section 1**. The previous layout followed the certification web page, which labels the 19 % domain \"ML Workflows\"; the folders `02-model-development/` and `03-ml-workflows/` were replaced by `02-data-processing/` and `03-model-development/`.\n> - **Question format:** 48 scored *multiple-choice and multiple-selection* questions (plus up to 10 unscored items) in 90 minutes.\n> - **New study pages** for bullets that had no coverage: [Exploratory Data Analysis](./02-data-processing/01-exploratory-data-analysis.md), [Hyperparameter Tuning](./03-model-development/02-hyperparameter-tuning.md), [Model Evaluation](./03-model-development/03-model-evaluation.md), [MLOps Strategy](./01-databricks-machine-learning/08-mlops-strategy.md), [Streaming Inference](./04-model-deployment/02-streaming-inference.md).\n> - **Platform names have moved on since the exam was written** — the guide still says *Delta Live Tables* (now Lakeflow Spark Declarative Pipelines) and tests *Hyperopt* (no longer in Databricks Runtime ML after 16.4 LTS ML). Topic pages keep the exam wording and add `Platform update (Oct 2026)` notes.\n> - For hands-on practice the guide now points to **Databricks Free Edition** (Community Edition retired January 1, 2026).\n>\n> Source of truth: [exam guide PDF](https://www.databricks.com/sites/default/files/2026-10/Databricks-Certified-Machine-Learning-Associate-Exam-Guide-August-2026.pdf) · [certification page](https://www.databricks.com/learn/certification/machine-learning-associate).\n\n> [!note] Section 2 name: PDF vs certification page\n> The PDF names Section 2 **\"Data Processing (19%)\"**; the certification web page lists the same 19 % domain as **\"ML Workflows\"**. The PDF's bullets (summary statistics, outliers, imputation, one-hot encoding, log transforms) are what this guide follows.\n\n## Exam Overview\n\n| Detail              | Information                                     |\n| ------------------- | ----------------------------------------------- |\n| **Certification**   | Databricks Certified Machine Learning Associate |\n| **Exam guide**      | Re-issued \"August 2026\" PDF — exam published and guide updated **March 1, 2025** |\n| **Scored questions**| 48 multiple-choice and multiple-selection       |\n| **Unscored items**  | Up to 10 (time already included)                |\n| **Duration**        | 90 minutes                                      |\n| **Result**          | Pass / fail (the exam guide does not publish a numeric passing score) |\n| **Languages**       | English, Japanese, Portuguese (BR), Korean      |\n| **Code in stems**   | Python (ML); SQL possible for non-ML data manipulation |\n| **Experience**      | 6+ months hands-on with Databricks for the listed tasks (recommended) |\n| **Recertification** | Every 2 years — see [Renewal Guide](../../shared/appendix/renewal-guide.md) |\n| **Cost**            | USD 200 (plus applicable taxes)                 |\n| **Delivery**        | Online proctored or test center                 |\n| **Hands-on practice** | [Databricks Free Edition](https://docs.databricks.com/aws/en/getting-started/free-edition) |\n\n## Exam Domain Weights (official — exam version March 1, 2025)\n\n```mermaid\npie title Exam Topic Distribution (4 sections)\n    \"Databricks Machine Learning\" : 38\n    \"Model Development\" : 31\n    \"Data Processing\" : 19\n    \"Model Deployment\" : 12\n```\n\n## Study Topics\n\n| Section | Weight | Focus |\n| :--- | :---: | :--- |\n| [01 — Databricks Machine Learning](./01-databricks-machine-learning/README.md) | 38 % | MLOps strategy, ML runtimes, AutoML, feature tables in UC, MLflow tracking + Client API, UC model registry (aliases, tags) |\n| [02 — Data Processing](./02-data-processing/README.md) | 19 % | Summary statistics, outliers (std dev / IQR), visualisations, feature comparisons, imputation, one-hot encoding, log transforms |\n| [03 — Model Development](./03-model-development/README.md) | 31 % | Algorithm choice, imbalance, estimators vs transformers, pipelines, Hyperopt / grid / random / Bayesian search, cross-validation, metrics, bias-variance |\n| [04 — Model Deployment](./04-model-deployment/README.md) | 12 % | Batch vs streaming vs real-time, pandas batch inference, streaming with Delta Live Tables, custom model endpoints, querying, traffic split |\n\n### Practice & Resources\n\n| Resource                                                        | Description                              |\n| --------------------------------------------------------------- | ---------------------------------------- |\n| [Practice Questions](./resources/practice-questions/README.md)  | Topic-specific practice questions mapped to the four sections |\n| [Mock Exam 1](./resources/mock-exam/README.md)                  | Full-length 48-question practice exam    |\n| [Mock Exam 2](./resources/mock-exam-2/README.md)                | Alternative 48-question practice exam    |\n| [Exam Tips](./resources/exam-tips.md)                           | Exam strategies and tips                 |\n| [Final Review](./resources/final-review.md)                     | 20-minute exam-morning scan              |\n| [Official Links](./resources/official-links.md)                 | Documentation and resources              |\n\n## Interview Preparation\n\nAfter completing this certification, explore:\n\n- [Interview Prep Resource](../../shared/interview-prep/README.md) - System design, feature engineering, and model architecture questions\n\n## Prerequisites\n\nReview these shared fundamentals:\n\n- [Spark Fundamentals](../../shared/fundamentals/spark-fundamentals.md)\n- [MLflow Basics](../../shared/fundamentals/mlflow-basics.md)\n- [Feature Engineering Basics](../../shared/fundamentals/feature-engineering-basics.md)\n\n## Study Progress Tracker\n\n- [ ] Section 1 — Databricks Machine Learning (MLOps, ML runtimes, AutoML, feature tables, MLflow, UC registry)\n- [ ] Section 2 — Data Processing (summary stats, outliers, imputation, one-hot encoding, log transforms)\n- [ ] Section 3 — Model Development (pipelines, tuning, cross-validation, metrics, bias-variance)\n- [ ] Section 4 — Model Deployment (batch, streaming, real-time, custom endpoints, traffic split)\n- [ ] Run Hands-on Lab 04 (MLflow + Model Registry in UC)\n- [ ] Take Mock Exam 1 and Mock Exam 2\n\n## Official Resources\n\n- [Databricks Certification Page](https://www.databricks.com/learn/certification/machine-learning-associate)\n- [Exam Guide PDF (re-issued August 2026)](https://www.databricks.com/sites/default/files/2026-10/Databricks-Certified-Machine-Learning-Associate-Exam-Guide-August-2026.pdf)\n- [Databricks machine learning documentation](https://docs.databricks.com/aws/en/machine-learning/)\n\n## Recommended Path\n\nComplete this certification before attempting [ML Professional](../ml-professional/README.md).\n"},{"id":"resources/exam-tips","folder":"resources","group":"recursos","order":0,"isIndex":false,"title":"ML Associate Exam Tips","md":"# ML Associate Exam Tips and Strategies\n\nPractical strategies for passing the Databricks Certified Machine Learning Associate exam on your first attempt. Facts below come from the exam guide PDF (re-issued \"August 2026\"; exam version March 1, 2025).\n\n## Exam Format\n\n| Detail | Value |\n| :--- | :--- |\n| Scored questions | 48 multiple-choice **and multiple-selection** questions |\n| Unscored items | Up to 10, not identified (extra time is already included) |\n| Duration | 90 minutes |\n| Passing score | Not published — treat the exam as pass/fail and aim to be solid in every section |\n| Code | Python for ML code; non-ML data manipulation may appear in SQL |\n| Delivery | Online proctored or test center |\n| Fee | USD 200 plus applicable taxes |\n\n## Section Weights and Study Time\n\n| Section | Weight | ≈ Scored questions | Suggested study time |\n| :--- | :---: | :---: | :--- |\n| 1 — Databricks Machine Learning | 38 % | ~18 | 8–10 hours |\n| 3 — Model Development | 31 % | ~15 | 7–9 hours |\n| 2 — Data Processing | 19 % | ~9 | 4–5 hours |\n| 4 — Model Deployment | 12 % | ~6 | 3–4 hours |\n\nSection 1 is the largest: MLOps strategy, ML runtimes, AutoML, feature tables in Unity Catalog, MLflow tracking and the Client API, and the Unity Catalog model registry all live there.\n\n> [!note]\n> The certification web page labels the 19 % section \"ML Workflows\"; the exam-guide PDF calls it **Data Processing** and lists summary statistics, outliers, imputation, one-hot encoding, and log transforms. Study the PDF's bullets.\n\n## Time Management\n\nUp to 58 items in 90 minutes is about **1.5 minutes per item**.\n\n| Phase | Time | Target |\n| :--- | :--- | :--- |\n| First pass (answer all) | 65 min | ~1 min per question; flag anything uncertain |\n| Review flagged questions | 20 min | Revisit uncertain answers |\n| Final check | 5 min | Make sure nothing is blank |\n\nFor **multiple-selection** questions, read how many answers are required and judge each option on its own.\n\n## Key Topics to Master\n\n### Must Know (High Frequency)\n\n- [ ] Feature tables in Unity Catalog: `FeatureEngineeringClient.create_table(name, primary_keys, df)`, `write_table(..., mode=\"merge\")`, `FeatureLookup` + `create_training_set`, `fe.log_model`, `fe.score_batch`\n- [ ] MLflow manual logging: `log_param(s)`, `log_metric(s)` (with `step`), `log_artifact` vs `log_artifacts`, `<flavor>.log_model`\n- [ ] Best run with the Client API: `MlflowClient().search_runs([exp_id], order_by=[\"metrics.m DESC\"], max_results=1)[0]`\n- [ ] UC registry: `mlflow.set_registry_uri(\"databricks-uc\")`, `create_registered_model` / `create_model_version`, aliases (`set_registered_model_alias`), tags (`set_/delete_model_version_tag`)\n- [ ] Spark ML: Estimator (`fit`) vs Transformer (`transform`), `Pipeline` → `PipelineModel`, `StringIndexer` → `OneHotEncoder` → `VectorAssembler`\n- [ ] Tuning: grid / random / Bayesian; Hyperopt `fmin(fn, space, algo, max_evals, trials)`; `SparkTrials` for single-node models; models trained = combinations × folds\n- [ ] Metrics: F1, log loss, ROC AUC, precision vs recall; RMSE vs MAE vs R²; choosing the metric for a scenario\n- [ ] Serving choice: batch vs streaming vs real-time; `spark_udf`; Model Serving endpoints and traffic splits\n\n### Should Know (Medium Frequency)\n\n- [ ] `df.summary()` vs `describe()`; `dbutils.data.summarize(df)`\n- [ ] Outlier rules: μ ± 3σ vs Q1 − 1.5·IQR … Q3 + 1.5·IQR\n- [ ] Imputation: mean (symmetric), median (skewed/outliers), mode (categorical); `Imputer(strategy=...)`\n- [ ] When one-hot encoding is / is not appropriate (high cardinality, ordinal, tree models)\n- [ ] Log transforms for right-skewed positive data; exponentiate log-space predictions before metrics\n- [ ] Class imbalance: class weights / cost-sensitive learning, resampling the training split, stratified splits\n- [ ] Bias-variance diagnosis from training vs validation error\n- [ ] Deploy code vs deploy models (and when each is preferred)\n- [ ] AutoML outputs: MLflow experiment, best-trial + data exploration notebooks, SHAP importance (off by default)\n\n### Good to Know (Lower Frequency)\n\n- [ ] ML runtime advantages: pre-installed, version-tested ML/DL libraries, MLflow, AutoML, GPU variants\n- [ ] Online vs offline feature tables; point-in-time lookups with `timestamp_lookup_key`\n- [ ] Custom `mlflow.pyfunc.PythonModel` for endpoints with custom logic\n- [ ] Endpoint URL `/serving-endpoints/<name>/invocations`; `dataframe_split` / `dataframe_records`\n- [ ] Streaming inference with Delta Live Tables: model as a Spark UDF inside a streaming table\n\n## Common Exam Traps\n\n| Trap | What the Exam Tests | Correct Understanding |\n| :--- | :--- | :--- |\n| Promoting a model | Stages or aliases? | In Unity Catalog, move an **alias** (`set_registered_model_alias`). Stages / `transition_model_version_stage` are legacy workspace-registry features. |\n| Creating a feature table in UC | Which API? | `FeatureEngineeringClient.create_table` (or a Delta table with a `PRIMARY KEY` constraint). No `AS FEATURE STORE` clause. |\n| Tag vs alias | Does a `champion` tag change what is served? | No — tags are metadata; only aliases are resolved by `models:/name@alias`. |\n| `autolog()` vs custom metrics | Does autolog capture custom metrics? | No — log custom values with `mlflow.log_metric()`. |\n| `fmin` direction | Maximise accuracy? | `fmin` minimises the loss — return `-accuracy`. |\n| `SparkTrials` with MLlib | Parallelise everything? | `SparkTrials` is for single-machine models; use `Trials` for distributed MLlib. |\n| Counting models | Grid 3 × 2 × 3, 5-fold CV | 18 × 5 = 90 during the search (a final refit adds one). |\n| Imbalanced data | Is 95 % accuracy good? | Not when 95 % of rows are one class — use F1 / recall / PR AUC and class weights or resampling. |\n| Log-transformed target | Evaluate directly? | Exponentiate predictions first, then compute RMSE/MAE in original units. |\n| Overfitting vs underfitting | Low train error, high validation error? | High variance → reduce complexity / regularise. High error on both → high bias. |\n| Serving approach | Real-time for everything? | No — nightly full-population scoring is batch; continuous events within seconds are streaming. |\n\n## Quick Reference Numbers\n\n| Item | Value |\n| :--- | :--- |\n| Scored questions / time | 48 / 90 minutes (+ up to 10 unscored items) |\n| `CrossValidator` default `numFolds` | 3 |\n| `TrainValidationSplit` default `trainRatio` | 0.75 |\n| `Imputer` strategies | `mean` (default), `median`, `mode` |\n| AutoML problem types | Classification, regression, forecasting |\n| AutoML default split | 60 / 20 / 20 train / validation / test |\n| IQR fences | Q1 − 1.5·IQR, Q3 + 1.5·IQR |\n\n## Platform Names You May See\n\nThe exam guide was written for the March 2025 exam. As of October 2026:\n\n| Exam wording | Current name / status |\n| :--- | :--- |\n| Delta Live Tables | Lakeflow Spark Declarative Pipelines (renamed November 12, 2025) |\n| Hyperopt | Not included in Databricks Runtime ML after 16.4 LTS ML; Optuna / Ray Tune recommended |\n| Databricks Repos | Git folders |\n| Databricks Asset Bundles | Declarative Automation Bundles (renamed March 16, 2026) |\n| Community Edition | Retired January 1, 2026 — use Databricks Free Edition for hands-on practice |\n\nAnswer exam questions using the exam's wording.\n\n## Day Before the Exam\n\n- [ ] Re-read the exam-guide bullet list and tick off each one\n- [ ] Review Estimator vs Transformer and the `Pipeline` fit/transform flow\n- [ ] Rehearse the feature-table and UC-registry API calls\n- [ ] Review the metric-choice and bias-variance tables\n- [ ] Run the system check for online proctoring\n- [ ] Get a full night's sleep\n\n## During the Exam\n\n- [ ] Read each question fully and identify the key constraint (latency, cost, data access, interpretability)\n- [ ] For multiple-selection questions, confirm how many answers are required\n- [ ] Eliminate clearly wrong answers first\n- [ ] For API questions, check exact names (`inputCols` vs `inputCol`, `log_artifacts` vs `log_artifact`)\n- [ ] Prefer the recommended, governed Databricks approach (Unity Catalog, aliases, deploy code) when two answers seem plausible\n- [ ] Flag uncertain questions and move on\n\n---\n\n[← Back to Resources](./README.md)\n"},{"id":"resources/final-review","folder":"resources","group":"recursos","order":0,"isIndex":false,"title":"Final Review — ML Associate","md":"# Final Review — ML Associate (20-minute exam-morning scan)\n\n> [!important]\n> Four sections: **Databricks ML 38 %**, **Model Development 31 %**, **Data Processing 19 %**, **Model Deployment 12 %**. 48 scored multiple-choice and multiple-selection questions, plus up to 10 unscored items, in 90 minutes.\n\n## 2-minute facts that show up *most often*\n\n- **Feature tables in UC**: `FeatureEngineeringClient().create_table(name=\"cat.sch.t\", primary_keys=[...], df=...)`; `write_table(..., mode=\"merge\")`; train with `FeatureLookup` + `create_training_set` + `fe.log_model`; score with `fe.score_batch`\n- **UC registry**: `mlflow.set_registry_uri(\"databricks-uc\")`; promote by moving an **alias** (`set_registered_model_alias(name, \"champion\", v)`); load `models:/cat.sch.m@champion`; **no stages in UC**\n- **Best run**: `MlflowClient().search_runs([exp_id], order_by=[\"metrics.rmse ASC\"], max_results=1)[0]`\n- **Estimator vs Transformer**: `fit()` → Model vs `transform()` → DataFrame; `StringIndexer`, `OneHotEncoder`, `StandardScaler`, `Imputer`, every algorithm and `Pipeline` are Estimators\n- **Tuning**: Hyperopt `fmin` minimises the loss; `tpe.suggest` = Bayesian, `rand.suggest` = random; `SparkTrials` for single-node models; models trained = combinations × folds\n- **Deploy code** is the default MLOps recommendation; **deploy models** when training is very expensive, single workspace, or no CI/CD\n\n## 5-minute per-domain quick-fire (4 sections)\n\n### 1 — Databricks Machine Learning (38 %)\n\n- ML runtime = pre-installed, version-tested ML/DL libraries + MLflow + AutoML (+ GPU variants)\n- AutoML: classification / regression / forecasting; one MLflow run per trial; best-trial + data exploration notebooks; SHAP importance off by default\n- UC feature tables: account-level → shared across workspaces, UC governance, lineage; offline (Delta) vs online store (low-latency serving)\n- Manual logging: `log_param(s)`, `log_metric(s)` (`step`), `log_artifact` (file) vs `log_artifacts` (folder), `<flavor>.log_model`\n- Tags: `set_/delete_registered_model_tag`, `set_/delete_model_version_tag` — metadata only\n\n### 2 — Data Processing (19 %)\n\n- `df.summary()` adds quartiles to `describe()`; `dbutils.data.summarize(df)` renders a profile\n- Outliers: μ ± 3σ (symmetric data) or Q1 − 1.5·IQR … Q3 + 1.5·IQR (skewed data)\n- Continuous × continuous → scatter + correlation; categorical × categorical → cross-tab + chi-square\n- Impute: mean (symmetric), median (skewed), mode (categorical); look at the distribution first\n- One-hot: nominal, low cardinality, linear/distance models — not for high-cardinality or ordinal features\n- Log transform: positive, right-skewed, orders of magnitude (`log1p` if zeros)\n\n### 3 — Model Development (31 %)\n\n- Imbalance: class weights / cost-sensitive learning, resample the **training** split; judge with F1 / recall / PR AUC\n- CV: more reliable, k× cost; train-validation split: cheaper, noisier; `CrossValidator` default 3 folds\n- Precision = few false positives; recall = few false negatives; log loss = calibrated probabilities; RMSE punishes big misses, MAE is robust\n- Log target → exponentiate predictions before metrics\n- Low train / high validation error = overfitting (high variance); high both = underfitting (high bias)\n\n### 4 — Model Deployment (12 %)\n\n- Batch (scheduled, cheapest) vs streaming (continuous, seconds) vs real-time (endpoint, milliseconds)\n- pandas: `pyfunc.load_model(uri).predict(pdf)`; at scale: `mlflow.pyfunc.spark_udf`\n- Streaming with Delta Live Tables: model as a Spark UDF inside a streaming table\n- Custom model: `mlflow.pyfunc.PythonModel` → `pyfunc.log_model` → register in UC → endpoint\n- Query `/serving-endpoints/<name>/invocations` with `dataframe_split`; split traffic with `traffic_config` routes summing to 100\n\n## Common-trap reminders\n\n| Trap | Right answer |\n| :--- | :--- |\n| \"Promote to Production stage\" | UC has no stages — move the `champion` alias |\n| \"`AS FEATURE STORE` clause\" | Does not exist — use `create_table` or a `PRIMARY KEY` constraint |\n| \"Tag the version as champion\" | Tags don't change what is served; aliases do |\n| \"`fmin` returns the best accuracy\" | Only if the objective returns `-accuracy` as the loss |\n| \"Oversample before splitting\" | Resample the training split only |\n| \"RMSE on log predictions in dollars\" | Exponentiate first |\n| \"Stream through a serving endpoint\" | Apply the model as a Spark UDF in the pipeline |\n| \"Delta Live Tables\" in a question | Same thing as Lakeflow Spark Declarative Pipelines — answer in exam terms |\n\n## Today's exam — 90-minute time budget\n\n- **Up to 58 items ÷ 90 minutes ≈ 1.5 minutes each** — keep moving and flag uncertain questions\n- For multiple-selection items, check how many answers are required\n- When two answers look plausible, prefer the governed, recommended Databricks approach (Unity Catalog, aliases, deploy code, the least-real-time serving that meets the latency need)\n\n## Eat. Hydrate. Breathe.\n\nYou're ready. Go pass it.\n\n---\n\n**[← Back to Resources](./README.md)** | **[↑ Back to ML Associate](../README.md)**\n"},{"id":"resources/official-links","folder":"resources","group":"recursos","order":0,"isIndex":false,"title":"Official Resources — ML Associate","md":"# Official Resources and Documentation Links\n\nCurated list of official Databricks, MLflow, and Spark documentation for the ML Associate exam, grouped by exam-guide section.\n\n## Certification\n\n| Resource | URL |\n| :--- | :--- |\n| ML Associate certification page | <https://www.databricks.com/learn/certification/machine-learning-associate> |\n| Exam guide PDF (re-issued \"August 2026\"; exam version March 1, 2025) | <https://www.databricks.com/sites/default/files/2026-10/Databricks-Certified-Machine-Learning-Associate-Exam-Guide-August-2026.pdf> |\n| AI Prep Guide (any Databricks exam) | <https://www.databricks.com/sites/default/files/2026-06/ai-prep-guide-any-databricks-certification.pdf> |\n| Certification overview and FAQ | <https://www.databricks.com/learn/certification> |\n\n## Section 1 — Databricks Machine Learning\n\n| Resource | URL |\n| :--- | :--- |\n| MLOps workflows on Databricks | <https://docs.databricks.com/aws/en/machine-learning/mlops/mlops-workflow> |\n| Model deployment patterns (deploy code vs deploy models) | <https://docs.databricks.com/aws/en/machine-learning/mlops/deployment-patterns> |\n| Databricks Runtime for Machine Learning | <https://docs.databricks.com/aws/en/machine-learning/databricks-runtime-ml> |\n| What is AutoML? | <https://docs.databricks.com/aws/en/machine-learning/automl/> |\n| AutoML Python API reference | <https://docs.databricks.com/aws/en/machine-learning/automl/automl-api-reference> |\n| Feature management (Feature Store) | <https://docs.databricks.com/aws/en/machine-learning/feature-store/> |\n| Work with feature tables in Unity Catalog | <https://docs.databricks.com/aws/en/machine-learning/feature-store/uc/feature-tables-uc> |\n| Use features to train models | <https://docs.databricks.com/aws/en/machine-learning/feature-store/train-models-with-feature-store> |\n| Online Feature Stores | <https://docs.databricks.com/aws/en/machine-learning/feature-store/online-feature-store> |\n| Feature Engineering Python API | <https://api-docs.databricks.com/python/feature-engineering/latest/feature_engineering.client.html> |\n| MLflow on Databricks | <https://docs.databricks.com/aws/en/mlflow/> |\n| Manage training code with MLflow runs | <https://docs.databricks.com/aws/en/mlflow/runs> |\n| Databricks Autologging | <https://docs.databricks.com/aws/en/mlflow/databricks-autologging> |\n| Manage model lifecycle in Unity Catalog | <https://docs.databricks.com/aws/en/machine-learning/manage-model-lifecycle/> |\n| MLflow Python API (`MlflowClient`) | <https://mlflow.org/docs/latest/api_reference/python_api/mlflow.client.html> |\n\n## Section 2 — Data Processing\n\n| Resource | URL |\n| :--- | :--- |\n| Databricks Utilities (`dbutils.data.summarize`) | <https://docs.databricks.com/aws/en/dev-tools/databricks-utils> |\n| PySpark `DataFrame.summary` | <https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.summary.html> |\n| Spark ML basic statistics (correlation, chi-square) | <https://spark.apache.org/docs/latest/ml-statistics.html> |\n| Spark ML feature transformers (`Imputer`, `StringIndexer`, `OneHotEncoder`) | <https://spark.apache.org/docs/latest/ml-features.html> |\n| Visualizations in Databricks notebooks | <https://docs.databricks.com/aws/en/visualizations/> |\n\n## Section 3 — Model Development\n\n| Resource | URL |\n| :--- | :--- |\n| Spark ML Pipelines | <https://spark.apache.org/docs/latest/ml-pipeline.html> |\n| Spark ML Tuning (`CrossValidator`, `TrainValidationSplit`) | <https://spark.apache.org/docs/latest/ml-tuning.html> |\n| Spark ML classification and regression | <https://spark.apache.org/docs/latest/ml-classification-regression.html> |\n| Hyperparameter tuning on Databricks | <https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/> |\n| Hyperopt concepts | <https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/hyperopt-concepts> |\n| Hyperparameter tuning with Optuna | <https://docs.databricks.com/aws/en/machine-learning/automl-hyperparam-tuning/optuna> |\n| scikit-learn model evaluation | <https://scikit-learn.org/stable/modules/model_evaluation.html> |\n\n## Section 4 — Model Deployment\n\n| Resource | URL |\n| :--- | :--- |\n| Model Serving | <https://docs.databricks.com/aws/en/machine-learning/model-serving/> |\n| Deploy custom models | <https://docs.databricks.com/aws/en/machine-learning/model-serving/custom-models> |\n| Create custom model serving endpoints | <https://docs.databricks.com/aws/en/machine-learning/model-serving/create-manage-serving-endpoints> |\n| Query serving endpoints for custom models | <https://docs.databricks.com/aws/en/machine-learning/model-serving/score-custom-model-endpoints> |\n| Lakeflow Spark Declarative Pipelines Python reference (formerly Delta Live Tables) | <https://docs.databricks.com/aws/en/ldp/developer/python-ref> |\n| Pipeline autoscaling | <https://docs.databricks.com/aws/en/ldp/auto-scaling> |\n| `mlflow.pyfunc` (incl. `spark_udf`) | <https://mlflow.org/docs/latest/api_reference/python_api/mlflow.pyfunc.html> |\n\n## Practice Resources\n\n| Resource | URL |\n| :--- | :--- |\n| Databricks Academy / training | <https://www.databricks.com/learn/training> |\n| Databricks Free Edition (hands-on practice) | <https://docs.databricks.com/aws/en/getting-started/free-edition> |\n| Free Edition limitations | <https://docs.databricks.com/aws/en/getting-started/free-edition-limitations> |\n\n> [!note] Platform update (Oct 2026)\n> Databricks **Community Edition** was retired on January 1, 2026; the exam guide now points to **Free Edition** for hands-on practice ([Databricks Community announcement](https://community.databricks.com/t5/announcements/psa-community-edition-retires-on-january-1-2026-move-to-the-free/m-p/141888)). Free Edition is serverless-only and lists limits relevant to this exam: no GPU serving endpoints, no provisioned throughput, no custom models on GPU or batch inference, and no online tables.\n\n---\n\n[← Back to Resources](./README.md)\n"},{"id":"resources/README","folder":"resources","group":"recursos","order":0,"isIndex":false,"title":"Exam Resources","md":"# Machine Learning Associate - Exam Resources\n\nPreparation materials for the Databricks Certified Machine Learning Associate exam.\n\n## Available Resources\n\n| Resource | Description |\n| -------- | ----------- |\n| [Practice Questions](./practice-questions/README.md) | Topic-specific practice questions |\n| [Mock Exam](./mock-exam/README.md) | Full-length practice exam (48 questions, by exam section) |\n| [Mock Exam 2](./mock-exam-2/README.md) | Alternative practice exam (48 questions, by exam section) |\n| [Exam Tips](./exam-tips.md) | Strategies, time management, common pitfalls |\n| [Final Review](./final-review.md) | 20-minute exam-morning cram scan |\n| [Official Links](./official-links.md) | Databricks documentation and registration |\n\n---\n\n**[← Back to Certification](../README.md)**\n"}]};
